var DATA = window.DATA = window.DATA = {"meta": {"title": "Hoá 11–12 · Ôn tập cả chương trình", "tagline": "Lật thẻ nhớ, làm bài tập có lời giải từng bước, chấm đề trọn vẹn cùng lý thuyết đầy đủ."}, "grades": [{"id": "g11", "label": "Hoá 11 · Học kì 2", "desc": "Anken–Ankin, Arene, dẫn xuất halogen, Ancol, Phenol, Aldehyde–Ketone, Carboxylic acid."}, {"id": "g12", "label": "Hoá 12 · Học kì 1", "desc": "Chương 1: Ester – Lipit, xà phòng và chất giặt rửa. Chương 2: Carbohydrate – glucose, fructose, saccharose, maltose, tinh bột, cellulose."}], "chapters": [{"id": "g11c1", "grade": "g11", "num": "1", "title": "Chương 1 · Anken – Ankin", "tagline": "Quy tắc Markovnikov · Trùng hợp · KMnO4", "color": "#2f81f7", "icon": "⚗️", "count": 10}, {"id": "g11c2", "grade": "g11", "num": "2", "title": "Chương 2 · Arene", "tagline": "Nitro hoá · Halogen hoá · Quy tắc thế", "color": "#f78166", "icon": "☕", "count": 7}, {"id": "g11c3", "grade": "g11", "num": "3", "title": "Chương 3 · Dẫn xuất halogen", "tagline": "Thuỷ phân · Quy tắc Zaitsev", "color": "#d2a8ff", "icon": "🧪", "count": 5}, {"id": "g11c4", "grade": "g11", "num": "4", "title": "Chương 4 · Ancol", "tagline": "Na · CuO · H2SO4 · Liên kết hydrogen", "color": "#7ee787", "icon": "🍶", "count": 10}, {"id": "g11c5", "grade": "g11", "num": "5", "title": "Chương 5 · Phenol", "tagline": "Tính acid · Br2 kết tủa trắng", "color": "#46c18c", "icon": "🧴", "count": 9}, {"id": "g11c6", "grade": "g11", "num": "6", "title": "Chương 6 · Aldehyde – Ketone", "tagline": "Tráng bạc · Iodoform · Cu(OH)2", "color": "#ffa657", "icon": "🍬", "count": 10}, {"id": "g11c7", "grade": "g11", "num": "7", "title": "Chương 7 · Carboxylic acid", "tagline": "Tính acid · Ester hoá · Điều chế", "color": "#ff7b72", "icon": "🍋", "count": 9}, {"id": "g11on", "grade": "g11", "num": "8", "title": "Ôn tập tổng hợp", "tagline": "Sơ đồ phản ứng · Nhận biết · Chương 1–7", "color": "#e3b341", "icon": "📚", "count": 7}, {"id": "g11cq", "grade": "g11", "num": "9", "title": "Câu hỏi tổng hợp", "tagline": "130 câu trắc nghiệm · đúng/sai · tự luận", "color": "#2dd4bf", "icon": "🎯", "count": 130}, {"id": "g12c1", "grade": "g12", "num": "1", "title": "Chương 1 · Ester – Lipit · Xà phòng", "tagline": "Thuỷ phân · Xà phòng hoá · Chất giặt rửa", "color": "#14b8a6", "icon": "🧈", "count": 16}, {"id": "g12c2", "grade": "g12", "num": "2", "title": "Chương 2 · Carbohydrate", "tagline": "Glucose · Saccharose · Tinh bột · Cellulose", "color": "#e2557c"}, {"id": "g12c3", "grade": "g12", "num": "3", "title": "Chương 3 · Hợp chất chứa Nitrogen · Amine", "tagline": "Khái niệm · Bậc amine · Đồng phân & danh pháp · Tính base & Aniline", "color": "#8b5cf6", "icon": "🧬", "count": 12}], "qb": {"g11a": [{"k": "m", "ch": "g11c1", "q": "Hàn xì là một trong những công nghệ hàn rất phổ biến, nhiệt lượng tỏa ra để hàn, cắt kim loại dựa trên phản ứng cháy của khí nào sau đây?", "o": "A=C₂H₄;B=C₂H₆;C=CH₄;D=C₂H₂", "a": "D", "e": "Acetylene (C₂H₂) cháy trong O₂ cho nhiệt độ ngọn lửa ~3000°C — đủ nóng để cắt kim loại."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây không làm mất màu dung dịch bromine ở điều kiện thường?", "o": "A=propane;B=propylene;C=propyne;D=styrene", "a": "A", "e": "Propane là alkane (chỉ có liên kết đơn) → không cộng Br₂. Còn lại đều có liên kết bội (C=C hoặc C≡C)."}, {"k": "m", "ch": "g11c1", "q": "Phát biểu nào sau đây về tính chất vật lý của các chất (ở điều kiện thường) không đúng?", "o": "A=Acetylene là chất khí, không màu, nặng hơn không khí;B=Hexane nhẹ hơn nước và không tan trong nước;C=Nhiệt độ sôi của methane nhỏ hơn ethane;D=Hex-1-ene là chất lỏng, không tan trong nước", "a": "A", "e": "M(C₂H₂) = 26 < M(không khí) ≈ 29 → acetylene NHẸ hơn không khí, không phải nặng hơn."}, {"k": "m", "ch": "g11c1", "q": "Khi cho propene (CH₂=CH–CH₃) tác dụng với HCl, theo qui tắc Markovnikov thì sản phẩm chính là", "o": "A=CH₃-CHCl-CH₃;B=CH₃-CH₂-CH₂Cl;C=CH₃-CH₂-CHCl₂;D=CH₃-CCl₂-CH₃", "a": "A", "e": "Quy tắc Markovnikov: H gắn vào C có nhiều H hơn (CH₂ có 2H), Cl gắn vào C ít H hơn (CH có 1H) → 2-chloropropane."}, {"k": "m", "ch": "g11c1", "q": "Khí dầu mỏ hóa lỏng (LPG: Liquefied Petroleum Gas) chứa chủ yếu hai khí nào sau đây?", "o": "A=Methane và ethane;B=Propane và pentane;C=Ethane và propane;D=Propane và butane", "a": "D", "e": "LPG (gas bình) là hỗn hợp propane (C₃H₈) và butane (C₄H₁₀) — hai alkane dễ hóa lỏng dưới áp suất."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây là đồng phân của CH₂=CHCH₂CH₂CH₃?", "o": "A=(CH₃)₂C=CHCH₃;B=CH₂=CHCH₂CH₃;C=CH≡CCH₂CH₂CH₃;D=CH₂=CHCH₂CH=CH₂", "a": "A", "e": "Pent-1-ene có CTPT C₅H₁₀. (CH₃)₂C=CHCH₃ (2-methylbut-2-ene) cũng C₅H₁₀ → đồng phân. B là C₄H₈, C là C₅H₈, D là C₅H₈."}, {"k": "m", "ch": "g11c1", "q": "Công thức phân tử của styrene là", "o": "A=C₇H₁₄;B=C₈H₈;C=C₆H₆;D=C₇H₈", "a": "B", "e": "Styrene = C₆H₅–CH=CH₂ → 6C+5H (vòng) + 2C+3H (nhánh) = 8C+8H = C₈H₈."}, {"k": "m", "ch": "g11c1", "q": "Chất nào trong 4 chất dưới đây có thể tham gia cả 4 phản ứng: Phản ứng cháy trong oxi, phản ứng cộng bromine, phản ứng cộng hydrogen (Ni, t°), phản ứng thế với dung dịch AgNO₃/NH₃?", "o": "A=ethane;B=ethylene;C=acetylene;D=cyclopropane", "a": "C", "e": "Phản ứng với AgNO₃/NH₃ chỉ xảy ra với alk-1-yne (có H gắn C≡C đầu mạch). Acetylene HC≡CH thoả mãn điều kiện này."}, {"k": "m", "ch": "g11c1", "q": "Để phân biệt ethane và ethene, dùng phản ứng nào là thuận tiện nhất?", "o": "A=Phản ứng đốt cháy;B=Phản ứng với hydrogen;C=Phản ứng với nước bromine;D=Phản ứng trùng hợp", "a": "C", "e": "Nước bromine cho hiện tượng trực quan ngay (mất màu nâu đỏ) — chỉ ethene (alkene) phản ứng, ethane (alkane) không."}, {"k": "m", "ch": "g11c1", "q": "Phát biểu nào sau đây không đúng?", "o": "A=Trong phân tử hydrocarbon, số nguyên tử hydrogen luôn là số chẵn;B=Trong phân tử alkene, liên kết đôi gồm một liên kết σ và một liên kết π;C=Hydrocarbon không no là hydrocarbon mà trong phân tử chứa liên kết bội;D=Công thức chung của hydrocarbon no, mạch hở có dạng CₙH₂ₙ", "a": "D", "e": "Alkane (no, mạch hở) có CTTQ CₙH₂ₙ₊₂. CₙH₂ₙ là CT của alkene mạch hở hoặc cycloalkane."}, {"k": "m", "ch": "g11c1", "q": "Alkene X có tên gọi 2,3-dimethylhept-2-ene. Công thức phân tử của X là", "o": "A=C₇H₁₄;B=C₈H₁₆;C=C₉H₁₈;D=C₉H₁₆", "a": "C", "e": "Hept = 7C, thêm 2 nhánh methyl = 2C → tổng 9C. Là alkene → CₙH₂ₙ → C₉H₁₈."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây có khả năng tác dụng với dung dịch AgNO₃/NH₃?", "o": "A=but-2-yne;B=ethylene;C=but-1-yne;D=but-2-ene", "a": "C", "e": "Chỉ alk-1-yne (C≡CH ở đầu mạch) phản ứng tạo kết tủa vàng với AgNO₃/NH₃. But-1-yne CH≡C-CH₂-CH₃ thoả mãn."}, {"k": "m", "ch": "g11c1", "q": "Hyđrocarbon chỉ có liên kết đơn trong phân tử là", "o": "A=alkene;B=alkyne;C=arene;D=alkane", "a": "D", "e": "Alkane là hydrocarbon NO — chỉ có liên kết đơn C-C và C-H."}, {"k": "m", "ch": "g11c1", "q": "Alkyne CH₃C≡CCH₃ có tên gọi là", "o": "A=but-1-yne;B=but-2-yne;C=pent-2-yne;D=but-3-yne", "a": "B", "e": "4C, liên kết ba ở C2-C3 → đánh số từ đầu nào cũng cho vị trí 2 → but-2-yne."}, {"k": "m", "ch": "g11c1", "q": "Alkene là các hidrocarbon không no, mạch hở, có công thức chung là", "o": "A=CₙH₂ₙ₊₂ (n≥1);B=CₙH₂ₙ (n≥2);C=CₙH₂ₙ₋₂ (n≥2);D=CₙH₂ₙ₋₆ (n≥6)", "a": "B", "e": "Alkene mạch hở có 1 liên kết đôi → CTTQ CₙH₂ₙ với n≥2 (cần ít nhất 2C để có C=C)."}, {"k": "m", "ch": "g11c1", "q": "Hợp chất nào dưới đây được dùng để tổng hợp PVC?", "o": "A=vinyl chloride (CH₂=CHCl);B=ethylene;C=acetylene;D=propene", "a": "A", "e": "PVC = poly(vinyl chloride) → trùng hợp từ monomer vinyl chloride CH₂=CHCl."}, {"k": "m", "ch": "g11c1", "q": "Hợp chất gây ra lỗ thủng tầng ozone là", "o": "A=CO₂;B=CFC (freon);C=CH₄;D=SO₂", "a": "B", "e": "CFC (chlorofluorocarbon) phân huỷ trong khí quyển → giải phóng Cl• tự do, phá huỷ O₃."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nW: Một diol chứa hai nhóm alcohol bậc một", "a": "false", "e": "Sai. But-1-ene CH₂=CH-CH₂-CH₃ + KMnO₄ → HOCH₂-CHOH-CH₂-CH₃ (1 OH bậc 1, 1 OH bậc 2)."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nX: Một diol chứa một nhóm alcohol bậc một và một nhóm alcohol bậc hai", "a": "true", "e": "Đúng. Đây chính là sản phẩm từ but-1-ene."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nY: Một diol chứa hai nhóm alcohol bậc hai", "a": "true", "e": "Đúng. But-2-ene CH₃-CH=CH-CH₃ + KMnO₄ → CH₃-CHOH-CHOH-CH₃ (cả 2 OH đều bậc 2)."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nZ: Cả hai alkene đều có đồng phân cis-trans", "a": "false", "e": "Sai. But-1-ene KHÔNG có đp cis-trans (1 đầu C có 2H giống nhau). Chỉ but-2-ene có cis-trans."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nAcetylene + H₂ (xt Lindlar) thu được ethane", "a": "false", "e": "Sai. Lindlar là xúc tác BÁN TÍNH (Pd/PbCO₃) → chỉ cộng 1 H₂ → tạo ETHYLENE chứ không phải ethane."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nPhản ứng cộng H₂ của propylene: CH₂=CH-CH₃ + H₂ → CH₃-CH₂-CH₃", "a": "true", "e": "Đúng. Propene cộng H₂ (Ni, t°) → propane."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nPhản ứng cộng H₂ vào liên kết bội luôn cần xúc tác kim loại", "a": "true", "e": "Đúng. Cần Ni/Pt/Pd để hoạt hoá H₂ thành H nguyên tử."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nSản phẩm cộng H₂ của ethylene là methane", "a": "false", "e": "Sai. CH₂=CH₂ + H₂ → CH₃-CH₃ (ethane), không phải methane."}, {"k": "n", "ch": "g11c1", "q": "Cho hợp chất HC≡C–CH₂OH lần lượt tác dụng với các chất sau: Cu(OH)₂; dd AgNO₃/NH₃; H₂ (Ni, t°); Na; nước bromine; dd KMnO₄; dd NaOH. Có bao nhiêu chất phản ứng được với hợp chất này?", "a": "5", "e": "Phản ứng được với 5 chất: AgNO₃/NH₃ (do C≡C đầu mạch), H₂ (cộng vào C≡C), Na (do –OH), Br₂ (cộng vào C≡C), KMnO₄ (oxi hoá). KHÔNG phản ứng với Cu(OH)₂ (chỉ poly-OH) và NaOH (alcohol không có tính acid).", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c1", "q": "Muốn điều chế 33,6 lít C₂H₂ (đktc) để hàn cắt kim loại, cần m gam đất đèn (chứa 80% CaC₂). Tính m (gam).", "a": "120", "e": "n(C₂H₂) = 33,6/22,4 = 1,5 mol. CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂ → n(CaC₂) = 1,5 mol → m(CaC₂) = 1,5×64 = 96 g. Đất đèn 80% → m = 96/0,8 = 120 g.", "u": "g", "tol": "0.5"}, {"k": "n", "ch": "g11c1", "q": "Cho 7,8 gam acetylene tác dụng với lượng dư AgNO₃/NH₃, thu được m gam kết tủa vàng nhạt (Ag₂C₂). Tính m (gam).", "a": "72", "e": "n(C₂H₂) = 7,8/26 = 0,3 mol. C₂H₂ + 2AgNO₃/NH₃ → AgC≡CAg↓ + 2NH₄NO₃. M(Ag₂C₂) = 240 → m = 0,3 × 240 = 72 g.", "u": "g", "tol": "0.5"}, {"k": "n", "ch": "g11c1", "q": "Da nhân tạo (PVC) được điều chế từ khí thiên nhiên (chứa 80% CH₄) qua sơ đồ: 2CH₄ → C₂H₂ → CH₂=CHCl → PVC. Hiệu suất toàn quá trình 20%. Để điều chế 1 tấn PVC, cần thể tích khí thiên nhiên ở điều kiện chuẩn (24,79 L/mol) là bao nhiêu m³?", "a": "4958", "e": "n(monomer CH₂=CHCl) = 10⁶/62,5 = 16000 mol. Cần 2 mol CH₄ cho 1 mol monomer (theo stoichiometry) → n(CH₄ cần lý thuyết) = 32000 mol. H = 20% → n(CH₄ thực tế) = 32000/0,2 = 160000 mol. V(CH₄) = 160000 × 24,79 = 3,9664×10⁶ L = 3966,4 m³. Khí thiên nhiên 80% CH₄ → V = 3966,4/0,8 ≈ 4958 m³.", "u": "m³", "tol": "5", "ac": "4958.0|4957.5|4960|4959"}, {"k": "n", "ch": "g11c1", "q": "Khi dùng biogas (giả sử chỉ chứa CH₄, ΔH = –890 kJ/mol) để thay khí gas (40% C₃H₈ ΔH=–2220 kJ/mol và 60% C₄H₁₀ ΔH=–2850 kJ/mol theo thể tích), với cùng năng lượng cần dùng thì lượng CO₂ thải ra giảm bao nhiêu %?", "a": "18,9", "e": "Cùng E (kJ): n(CO₂) từ CH₄ = E/890; n(CO₂) từ gas hh = E×3,6/(0,4×2220+0,6×2850) = E×3,6/2598 = E/721,67. % giảm = 1 − 721,67/890 ≈ 18,9%.", "u": "%", "tol": "0.5", "ac": "18.9|19|18,93|18.93"}, {"k": "n", "ch": "g11c1", "q": "Một bình gas 12 kg chứa propane:butane = 1:2 (theo mol). Biết ΔH cháy: C₃H₈ = –2220 kJ/mol, C₄H₁₀ = –2874 kJ/mol. Mỗi ngày hộ gia đình cần 10 000 kJ nhiệt (hiệu suất hấp thu 80%). Hỏi sử dụng được bao nhiêu ngày? (Làm tròn xuống số nguyên)", "a": "47", "e": "Gọi n(C₃H₈) = x, n(C₄H₁₀) = 2x. m = 44x + 116x = 160x = 12000 → x = 75 mol. Q = 75×2220 + 150×2874 = 597600 kJ. Hữu ích = 597600 × 0,8 = 478080 kJ. Số ngày = 478080/10000 ≈ 47,8 → 47 ngày trọn.", "u": "ngày", "tol": "1", "ac": "47,8|47.8|48"}, {"k": "m", "ch": "g11c2", "q": "Nitro hoá benzene bằng hỗn hợp HNO₃ đặc và H₂SO₄ đặc ở nhiệt độ ≤ 50°C, tạo thành chất hữu cơ X. Phát biểu nào sau đây về X không đúng?", "o": "A=X là nitrobenzene;B=X là chất lỏng, sánh như dầu;C=X có màu vàng;D=Công thức phân tử của X là C₆H₅NO₃", "a": "D", "e": "Phản ứng thế: C₆H₆ + HNO₃ → C₆H₅NO₂ + H₂O. CTPT đúng là C₆H₅NO₂ (chứ không phải C₆H₅NO₃)."}, {"k": "m", "ch": "g11c2", "q": "Arene hay còn gọi là hydrocarbon thơm là những hydrocarbon trong phân tử có chứa một hay nhiều", "o": "A=vòng benzene;B=liên kết đôi;C=liên kết ba;D=vòng không bão hoà", "a": "A", "e": "Định nghĩa: Arene là hydrocarbon chứa vòng benzene."}, {"k": "m", "ch": "g11c2", "q": "Cho sơ đồ: C₆H₆ (benzene) → X → Y → Z. Hai chất hữu cơ Y, Z lần lượt là", "o": "A=C₆H₅Cl, C₆H₄(NO₂)Cl;B=C₆H₅NO₂, C₆H₅NH₂;C=C₆H₅Cl, C₆H₄(OH)Cl;D=C₆H₅Br, C₆H₄(OH)Br", "a": "A", "e": "Quy trình điển hình: benzene → nitrobenzene → chloronitrobenzene. Tuy nhiên dạng câu phụ thuộc sơ đồ — đáp án ưu tiên A theo dãy halogen hoá → tiếp tục thế."}, {"k": "m", "ch": "g11c2", "q": "Trong các chất sau đây, chất nào có nhiệt độ sôi cao nhất?", "o": "A=benzene;B=toluene;C=ethylbenzene;D=xylene", "a": "C", "e": "Trong dãy đồng đẳng arene, M càng lớn → t°s càng cao. Ethylbenzene (M=106) > toluene (92) > benzene (78). Xylene cũng M=106 nhưng đẳng phương — gần ngang ethylbenzene."}, {"k": "tf", "ch": "g11c2", "q": "Hợp chất X chứa vòng benzene có công thức phân tử là C₈H₈O₂. Biết X tác dụng được với dung dịch NaOH theo sơ đồ: X + 2NaOH → Y + 2H₂O.\nX có 5 liên kết π trong phân tử", "a": "true", "e": "Đúng. C₈H₈O₂ có k = (2×8+2-8)/2 = 5 → 5 liên kết π+vòng. Có 1 vòng + 3π trong vòng + 1 π trong COOH/C=O = 5."}, {"k": "tf", "ch": "g11c2", "q": "Hợp chất X chứa vòng benzene có công thức phân tử là C₈H₈O₂. Biết X tác dụng được với dung dịch NaOH theo sơ đồ: X + 2NaOH → Y + 2H₂O.\nY là phenol đa chức", "a": "true", "e": "Đúng. Vì X + 2NaOH → muối → X có 2 nhóm phản ứng được NaOH (cả -OH phenol và -COOH). Một dạng X là HOC₆H₄CH₂COOH hoặc CH₃COOC₆H₄... → Y có 2 nhóm phenol."}, {"k": "tf", "ch": "g11c2", "q": "Hợp chất X chứa vòng benzene có công thức phân tử là C₈H₈O₂. Biết X tác dụng được với dung dịch NaOH theo sơ đồ: X + 2NaOH → Y + 2H₂O.\nTrong phân tử Y có 6 nguyên tử hydrogen", "a": "false", "e": "Sai. Tuỳ cấu trúc Y. Cần phân tích cụ thể CTCT."}, {"k": "tf", "ch": "g11c2", "q": "Hợp chất X chứa vòng benzene có công thức phân tử là C₈H₈O₂. Biết X tác dụng được với dung dịch NaOH theo sơ đồ: X + 2NaOH → Y + 2H₂O.\nX có khả năng làm mất màu dung dịch bromine", "a": "true", "e": "Đúng. X có nhóm -OH phenol → dễ thế Br ở vòng → nước Br₂ mất màu, tạo kết tủa trắng."}, {"k": "n", "ch": "g11c2", "q": "Từ 1 tấn toluene có thể điều chế được bao nhiêu kg 2,4,6-trinitrotoluene (TNT), biết hiệu suất phản ứng là 62%?", "a": "1530", "e": "M(toluene) = 92, M(TNT) = 227. n(toluene) = 10⁶/92 ≈ 10869,57 mol. n(TNT) = 10869,57 × 0,62 ≈ 6739,13 mol. m = 6739,13 × 227 ≈ 1.529.782 g ≈ 1530 kg.", "u": "kg", "tol": "5", "ac": "1529,8|1529.8|1530.0|1529"}, {"k": "n", "ch": "g11c2", "q": "Methyl eugenol (phân tích nguyên tố: %C = 74,16%, %H = 7,86%, %O ≈ 17,98%) có phổ khối M⁺ = 178. Hỏi phân tử methyl eugenol có bao nhiêu nguyên tử carbon?", "a": "11", "e": "Số C = M × %C/12 = 178 × 0,7416/12 ≈ 11. CTPT: C₁₁H₁₄O₂.", "u": "nguyên tử C", "tol": "0"}, {"k": "m", "ch": "g11c3", "q": "Trong thể thao, khi các vận động viên bị chấn thương do va chạm, không gây vết thương hở, gãy xương, ... thường được nhân viên y tế dùng loại thuốc xịt, xịt vào chỗ bị thương để gây tê cục bộ. Hợp chất chính có trong thuốc xịt là", "o": "A=carbon dioxide;B=hydrogen chloride;C=chloromethane;D=chloroethane", "a": "D", "e": "Chloroethane (C₂H₅Cl) bay hơi rất nhanh ở nhiệt độ cơ thể → hấp thu nhiệt → làm lạnh tức thì → gây tê."}, {"k": "m", "ch": "g11c3", "q": "Sự tách hydrogen halide của dẫn xuất halogen X có CTPT C₄H₉Cl cho 3 alkene đồng phân, X là", "o": "A=butyl chloride (n-butyl);B=sec-butyl chloride;C=iso-butyl chloride;D=tert-butyl chloride", "a": "B", "e": "sec-butyl chloride CH₃-CHCl-CH₂-CH₃: tách được but-1-ene + cis-but-2-ene + trans-but-2-ene = 3 alkene đp."}, {"k": "m", "ch": "g11c3", "q": "Khi đun nóng CH₃-CH(Br)-CH₂-CH₃ với sodium hydroxide trong ethanol, thu được sản phẩm chính là", "o": "A=but-1-ene;B=but-2-ene;C=butan-2-ol;D=butane", "a": "B", "e": "NaOH/ethanol → tách HBr (theo Zaitsev: ưu tiên tạo alkene có nhiều nhánh hơn ở C=C) → but-2-ene."}, {"k": "m", "ch": "g11c3", "q": "Chất nào là dẫn xuất halogen của hydrocarbon?", "o": "A=CH₃-CH₂-OH;B=CH₃-CHCl-CH₃;C=CH₃-COOH;D=CH₃-O-CH₃", "a": "B", "e": "Dẫn xuất halogen có nhóm thế là halogen (F/Cl/Br/I) gắn trực tiếp vào hydrocarbon."}, {"k": "m", "ch": "g11c3", "q": "Có bao nhiêu alkane là chất khí ở điều kiện thường khi phản ứng với chlorine (ánh sáng) cho 1 sản phẩm thế monohalogen duy nhất?", "o": "A=1;B=2;C=3;D=4", "a": "B", "e": "Alkane khí (≤4C) cho 1 sản phẩm duy nhất khi mọi H tương đương: CH₄ và C(CH₃)₄ (không khí, lỏng)... thực tế là 2: CH₄ và C₂H₆."}, {"k": "n", "ch": "g11c3", "q": "Cho 2-methylbutane phản ứng với chlorine (1:1, ánh sáng) thu được tối đa bao nhiêu đồng phân cấu tạo dẫn xuất monochlorine?", "a": "4", "e": "2-methylbutane CH₃-CH(CH₃)-CH₂-CH₃ có 4 vị trí H khác nhau (do 2 nhóm CH₃ ở C2 đối xứng): C1, C2, C3, C4 → 4 sản phẩm thế khác nhau.", "u": "đồng phân", "tol": "0"}, {"k": "n", "ch": "g11c3", "q": "Đun sôi 12,9 gam C₂H₅Cl với KOH/C₂H₅OH dư, sau đó dẫn khí sinh ra qua dung dịch Br₂ dư. Biết hiệu suất phản ứng tách HCl là 80%, phản ứng cộng Br₂ là 100%. Tính khối lượng Br₂ đã phản ứng (g).", "a": "25,6", "e": "n(C₂H₅Cl) = 12,9/64,5 = 0,2 mol. C₂H₅Cl + KOH → C₂H₄ + KCl + H₂O. n(C₂H₄) = 0,2 × 0,80 = 0,16 mol. C₂H₄ + Br₂ → C₂H₄Br₂ → n(Br₂) = 0,16 mol → m = 0,16 × 160 = 25,6 g.", "u": "g", "tol": "0.1", "ac": "25.6"}, {"k": "m", "ch": "g11c4", "q": "Việc sử dụng bia rượu ở Việt Nam hiện nay đang ở mức báo động. Thành phần gây say chính trong bia rượu là chất nào sau đây?", "o": "A=C₆H₅OH;B=CH₃CHO;C=CH₃CH₂OH;D=CH₃OH", "a": "C", "e": "Ethanol (CH₃CH₂OH) là cồn trong bia rượu. Methanol (CH₃OH) cực độc, có thể gây mù và tử vong."}, {"k": "m", "ch": "g11c4", "q": "Propan-1-ol không tác dụng được với chất nào sau đây?", "o": "A=NaOH;B=O₂ (t°);C=Na;D=CuO (t°)", "a": "A", "e": "Alcohol KHÔNG phản ứng với NaOH (vì alcohol không có tính acid như phenol). Có phản ứng với Na, CuO, đốt cháy."}, {"k": "m", "ch": "g11c4", "q": "Chất nào sau đây tác dụng với Cu(OH)₂ trong môi trường base tạo dung dịch màu xanh lam đặc trưng?", "o": "A=Ethyl alcohol;B=Isopropyl alcohol;C=Phenol;D=Glycerol", "a": "D", "e": "Phản ứng đặc trưng của polyalcohol có ít nhất 2 nhóm -OH liền kề (vicinal diol) → tạo phức xanh lam với Cu(OH)₂. Glycerol C₃H₅(OH)₃ thoả mãn."}, {"k": "m", "ch": "g11c4", "q": "Cho phản ứng dạng: X + CuO → H–CHO + Cu + H₂O. X là chất nào sau đây?", "o": "A=methanol;B=ethanol;C=glycerol;D=propyl alcohol", "a": "A", "e": "HCHO (formaldehyde) chỉ tạo ra từ methanol bậc 1 đặc biệt: CH₃OH + CuO → HCHO + Cu + H₂O."}, {"k": "m", "ch": "g11c4", "q": "Phản ứng nào sau đây đúng?", "o": "A=C₂H₅OH + HBr → C₂H₅Br + H₂O;B=C₂H₅OH + HBr → C₂H₅OBr + H₂;C=C₂H₅OH + NaOH → C₂H₅ONa + H₂O;D=C₂H₅OH + Na → C₂H₅Na + H₂O", "a": "A", "e": "Alcohol + HBr → ethyl bromide + nước (thay -OH bằng -Br). Lưu ý alcohol KHÔNG phản ứng với NaOH."}, {"k": "m", "ch": "g11c4", "q": "Alcohol là những hợp chất hữu cơ mà phân tử có chứa nhóm OH liên kết trực tiếp với", "o": "A=nguyên tử carbon;B=nguyên tử carbon không no;C=nguyên tử carbon no;D=nguyên tử oxygen", "a": "C", "e": "Định nghĩa alcohol: -OH gắn vào C no (C sp³). Nếu -OH gắn vào C của vòng benzene → đó là phenol, không phải alcohol."}, {"k": "m", "ch": "g11c4", "q": "Cho 4,6 gam một alcohol no, đơn chức, mạch hở X tác dụng với Na dư, thu được 1,2395 lít H₂ (đkc, 24,79 L/mol). CTPT của X là", "o": "A=C₂H₆O;B=CH₄O;C=C₃H₈O;D=C₄H₁₀O", "a": "A", "e": "n(H₂) = 1,2395/24,79 = 0,05 mol → n(X) = 2×0,05 = 0,1 mol → M(X) = 4,6/0,1 = 46 → C₂H₆O (ethanol)."}, {"k": "m", "ch": "g11c4", "q": "Phương pháp điều chế ethanol bằng cách lên men chất nào sau đây là phương pháp sinh hóa?", "o": "A=tinh bột (gạo);B=ethylene;C=acetaldehyde;D=methane", "a": "A", "e": "Phương pháp sinh hoá = dùng enzyme/vi sinh: tinh bột → glucose → ethanol (men rượu). B là pp hoá học."}, {"k": "m", "ch": "g11c4", "q": "Ứng với CTPT C₃H₈O có bao nhiêu alcohol là đồng phân cấu tạo của nhau?", "o": "A=1;B=2;C=3;D=4", "a": "B", "e": "C₃H₈O có 2 alcohol đồng phân: propan-1-ol (CH₃CH₂CH₂OH) và propan-2-ol (CH₃CHOHCH₃)."}, {"k": "m", "ch": "g11c4", "q": "Nhiều vụ ngộ độc rượu do sử dụng rượu pha chế từ cồn công nghiệp có lẫn methanol. Công thức của methanol là", "o": "A=CH₃OH;B=C₂H₅OH;C=C₃H₇OH;D=HCHO", "a": "A", "e": "Methanol = CH₃OH. Cực độc, gây mù mắt và tử vong. Đừng nhầm với ethanol C₂H₅OH (uống được)."}, {"k": "m", "ch": "g11c4", "q": "Cồn 70° là dung dịch ethyl alcohol, dùng để sát trùng. Mô tả nào sau đây đúng?", "o": "A=70 mL nước trong 100 mL dd;B=70 g ethanol trong 100 g dd;C=70 mL ethanol trong 100 mL dd;D=70 g ethanol trong 100 mL dd", "a": "C", "e": "Độ rượu = thể tích ethanol nguyên chất / thể tích dd × 100. Cồn 70° = 70 mL ethanol / 100 mL dd."}, {"k": "m", "ch": "g11c4", "q": "Xăng E5 RON 92 chứa hàm lượng ethanol là bao nhiêu?", "o": "A=5%;B=10%;C=15%;D=92%", "a": "A", "e": "E5 = 5% ethanol theo thể tích. (E10 = 10%, RON 92 chỉ chỉ số octan của xăng)."}, {"k": "m", "ch": "g11c4", "q": "Hợp chất nào sau đây là alcohol đa chức?", "o": "A=methanol;B=ethanol;C=ethylene glycol;D=phenol", "a": "C", "e": "Alcohol đa chức = nhiều nhóm -OH. Ethylene glycol HOCH₂-CH₂OH có 2 -OH. Phenol có -OH nhưng gắn vòng → là phenol, không phải alcohol."}, {"k": "m", "ch": "g11c4", "q": "Alcohol nào sau đây không có phản ứng tách nước tạo ra alkene?", "o": "A=ethanol;B=propan-2-ol;C=methanol;D=butan-2-ol", "a": "C", "e": "Methanol CH₃OH chỉ có 1C → không thể tạo C=C → không tách nước thành alkene."}, {"k": "tf", "ch": "g11c4", "q": "Menthol là hợp chất hữu cơ tìm thấy trong cây bạc hà, dùng làm hương liệu trong kem đánh răng, kẹo cao su, xi-rô ho.\nMenthol là alcohol no, đơn chức", "a": "true", "e": "Đúng. Menthol C₁₀H₂₀O — alcohol no đơn chức, có vòng cyclohexane."}, {"k": "tf", "ch": "g11c4", "q": "Menthol là hợp chất hữu cơ tìm thấy trong cây bạc hà, dùng làm hương liệu trong kem đánh răng, kẹo cao su, xi-rô ho.\nCông thức phân tử của menthol là C₁₀H₂₀O", "a": "true", "e": "Đúng. Đây là CTPT của menthol."}, {"k": "tf", "ch": "g11c4", "q": "Menthol là hợp chất hữu cơ tìm thấy trong cây bạc hà, dùng làm hương liệu trong kem đánh răng, kẹo cao su, xi-rô ho.\nMenthol là alcohol bậc 3", "a": "false", "e": "Sai. Menthol là alcohol bậc 2 — nhóm -OH gắn vào C có 1H (chứ không phải 0H như bậc 3)."}], "g11b": [{"k": "tf", "ch": "g11c4", "q": "Menthol là hợp chất hữu cơ tìm thấy trong cây bạc hà, dùng làm hương liệu trong kem đánh răng, kẹo cao su, xi-rô ho.\nThành phần % khối lượng của O trong menthol là 10,256%", "a": "true", "e": "Đúng. M(C₁₀H₂₀O) = 156 → %O = 16/156 × 100 ≈ 10,26%."}, {"k": "n", "ch": "g11c4", "q": "Số đồng phân alcohol có CTPT C₃H₈O là bao nhiêu?", "a": "2", "e": "C₃H₈O có 2 đp alcohol: propan-1-ol (CH₃CH₂CH₂OH) và propan-2-ol (CH₃CHOHCH₃). (Đồng phân thứ 3 là dimethyl ether CH₃OCH₃ — không phải alcohol).", "u": "đồng phân", "tol": "0"}, {"k": "n", "ch": "g11c4", "q": "Ứng với CTPT C₄H₁₀O có bao nhiêu đồng phân alcohol?", "a": "4", "e": "4 đp: butan-1-ol, butan-2-ol, 2-methylpropan-1-ol (isobutyl alcohol), 2-methylpropan-2-ol (tert-butyl alcohol).", "u": "đồng phân", "tol": "0"}, {"k": "n", "ch": "g11c4", "q": "Xăng sinh học E5 chứa bao nhiêu % ethanol theo thể tích?", "a": "5", "e": "Ký hiệu E5 = 5% ethanol theo thể tích, 95% xăng truyền thống. (E10 = 10%, E85 = 85%.)", "u": "%", "tol": "0", "ac": "5%|5.0|5,0"}, {"k": "n", "ch": "g11c4", "q": "Để thu được 460 mL ethanol 50° (d = 0,8 g/mL) ở hiệu suất 50% (toàn quá trình tinh bột → glucose → ethanol), cần dùng bao nhiêu gam nếp (chứa 80% tinh bột)?", "a": "810", "e": "V(C₂H₅OH nguyên chất) = 460×50/100 = 230 mL → m = 184 g → n = 4 mol. (C₆H₁₀O₅)ₙ → nC₆H₁₂O₆ → 2nC₂H₅OH. n(tinh bột) = 4/2 = 2 mol đơn vị → m lý thuyết = 324 g. H=50% → m thực tế = 648 g. Nếp 80% tinh bột → m(nếp) = 648/0,8 = 810 g.", "u": "g", "tol": "5"}, {"k": "n", "ch": "g11c4", "q": "Xăng E10 chứa 10% ethanol và 90% octan theo khối lượng. Nhiệt cháy: ethanol 29,6 kJ/g, octan 47,9 kJ/g. Cần đốt bao nhiêu TẤN xăng E10 để sinh ra 3 502 000 kJ?", "a": "0,076", "e": "Năng lượng/g E10 = 0,1×29,6 + 0,9×47,9 = 46,07 kJ/g. m = 3 502 000/46,07 ≈ 76 013 g ≈ 76 kg ≈ 0,076 tấn.", "u": "tấn", "tol": "0.002", "ac": "0.076|0,0760|76|76,0"}, {"k": "n", "ch": "g11c4", "q": "Chuẩn độ 5 mL huyết tương người lái xe bằng K₂Cr₂O₇ 0,01 M, cần 2 mL (Cr₂O₇²⁻ + 3 C₂H₅OH + 8H⁺ → 2Cr³⁺ + 3 CH₃CHO + 7H₂O). Tính nồng độ C₂H₅OH (mg/100 mL) trong máu?", "a": "55,2", "e": "n(K₂Cr₂O₇) = 2×10⁻³ × 0,01 = 2×10⁻⁵ mol → n(C₂H₅OH) = 3 × 2×10⁻⁵ = 6×10⁻⁵ mol. m = 6×10⁻⁵ × 46 = 2,76×10⁻³ g = 2,76 mg trong 5 mL → trong 100 mL = 2,76 × 20 = 55,2 mg/100 mL. Vi phạm Nghị định 100 (vì > 0).", "u": "mg/100mL", "tol": "0.5", "ac": "55.2"}, {"k": "m", "ch": "g11c5", "q": "Phenol và ethanol đều tác dụng được với chất nào sau đây?", "o": "A=dung dịch NaCl;B=dung dịch NaOH;C=nước bromine;D=Na", "a": "D", "e": "Cả phenol và ethanol đều có -OH → tác dụng với Na giải phóng H₂. NaOH chỉ phản ứng với phenol, Br₂ chỉ phản ứng với phenol (vòng)."}, {"k": "m", "ch": "g11c5", "q": "Cho m gam phenol (C₆H₅OH) tác dụng với NaOH thu được 23,2 gam muối C₆H₅ONa. Giá trị của m là", "o": "A=21,2 gam;B=16,51 gam;C=23,5 gam;D=18,8 gam", "a": "D", "e": "n(C₆H₅ONa) = 23,2/116 = 0,2 mol → n(phenol) = 0,2 mol → m = 0,2 × 94 = 18,8 g."}, {"k": "m", "ch": "g11c5", "q": "Nguyên nhân phản ứng thế bromine vào vòng thơm của phenol xảy ra dễ dàng hơn so với benzene là do", "o": "A=phenol có khối lượng phân tử nhỏ hơn;B=cặp e tự do của O liên hợp với vòng → tăng mật độ e ở vòng;C=phenol tan trong nước;D=phenol có nhiệt độ sôi cao hơn", "a": "B", "e": "Cặp e chưa dùng của O liên hợp π vào vòng → đẩy e vào vòng → vị trí o, p giàu e → dễ thế electrophile (Br⁺)."}, {"k": "m", "ch": "g11c5", "q": "Phenol không phản ứng với chất nào sau đây?", "o": "A=Na;B=NaOH;C=Br₂ (nước);D=NaHCO₃", "a": "D", "e": "Phenol có tính acid YẾU hơn H₂CO₃ → KHÔNG đẩy được CO₂ ra khỏi muối carbonate → không phản ứng với NaHCO₃."}, {"k": "m", "ch": "g11c5", "q": "Số hợp chất đồng phân cấu tạo có CTPT C₈H₁₀O, trong phân tử có vòng benzene và tác dụng được với NaOH là", "o": "A=3;B=4;C=5;D=6", "a": "A", "e": "Tác dụng với NaOH → có -OH gắn trực tiếp vào vòng (phenol). C₈H₁₀O với vòng benzene + 1 phenolic-OH = methylphenol có 3 đp ortho/meta/para của ethyl... thực tế: 3 cresol bậc 2 (xylenol)."}, {"k": "m", "ch": "g11c5", "q": "Chất X không phải là phenol. Vậy X là", "o": "A=C₆H₅-OH;B=p-CH₃-C₆H₄-OH;C=C₆H₅-CH₂-OH;D=p-OH-C₆H₄-OH", "a": "C", "e": "Benzyl alcohol C₆H₅-CH₂-OH có -OH gắn vào C no (CH₂), không gắn trực tiếp vào vòng → đó là alcohol thơm, không phải phenol."}, {"k": "m", "ch": "g11c5", "q": "Phát biểu không đúng khi nói về tính chất vật lí của phenol là", "o": "A=Phenol là chất rắn ở điều kiện thường;B=Phenol tan vô hạn trong nước lạnh;C=Phenol có mùi đặc trưng;D=Phenol để lâu ngoài không khí có màu hồng", "a": "B", "e": "Phenol ÍT tan trong nước lạnh (chỉ tan ~8,3 g/100mL ở 25°C), tan tốt trong nước nóng. Không tan vô hạn."}, {"k": "m", "ch": "g11c5", "q": "Để loại bỏ nhanh muối phenolate, người ta thường tái tạo phenol từ C₆H₅ONa bằng cách", "o": "A=cho tác dụng với HCl;B=đun nóng dung dịch;C=cho vào nước;D=thêm NaOH", "a": "A", "e": "C₆H₅ONa + HCl → C₆H₅OH + NaCl. Phản ứng này dùng để tách phenol từ muối."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPhản ứng chứng minh ảnh hưởng của -OH lên gốc phenyl", "a": "true", "e": "Đúng. -OH hoạt hoá vòng → dễ thế ở vị trí 2,4,6."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid kết tủa màu trắng", "a": "false", "e": "Sai. Picric acid có MÀU VÀNG (do 3 nhóm NO₂)."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid có tính acid mạnh hơn phenol", "a": "true", "e": "Đúng. 3 nhóm NO₂ hút e mạnh → H trong -OH linh động hơn → acid mạnh hơn ~10⁹ lần."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid được dùng làm thuốc nổ, thuộc da, phẩm nhuộm", "a": "true", "e": "Đúng. Đây là 3 ứng dụng kinh điển của picric acid."}, {"k": "n", "ch": "g11c5", "q": "Cho dãy các chất sau: phenol, ethanol, ethyl chloride, o-cresol, glycerol. Có bao nhiêu chất phản ứng được với sodium kim loại (Na)?", "a": "4", "e": "Phản ứng với Na cần –OH (alcohol/phenol). 4 chất: phenol, ethanol, o-cresol, glycerol. Ethyl chloride C₂H₅Cl KHÔNG có –OH → không phản ứng.", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c5", "q": "Cho 4,02 g hỗn hợp X gồm phenol và propan-1-ol tác dụng với nước Br₂ dư, thu được 9,93 g kết tủa trắng (2,4,6-tribromophenol). Tính %m của phenol trong X (%).", "a": "70,15", "e": "M(C₆H₂Br₃OH) = 331. n(kết tủa) = 9,93/331 = 0,03 mol = n(phenol). m(phenol) = 0,03 × 94 = 2,82 g. %m = 2,82/4,02 × 100 ≈ 70,15%. (Propan-1-ol không phản ứng Br₂).", "u": "%", "tol": "0.2", "ac": "70.15"}, {"k": "n", "ch": "g11c5", "q": "Hỗn hợp ethanol + phenol + Na dư → 3,7185 L H₂ (đkc, 24,79 L/mol). Cùng hỗn hợp + Br₂ vừa đủ → 19,86 g kết tủa trắng. Tính %m phenol trong hỗn hợp (%).", "a": "33,81", "e": "n(H₂) = 0,15 mol → n(ROH tổng) = 0,3 mol. n(C₆H₂Br₃OH) = 19,86/331 = 0,06 mol = n(phenol). n(ethanol) = 0,24 mol. m(phenol) = 5,64 g, m(ethanol) = 11,04 g, tổng 16,68 g. %phenol = 5,64/16,68 × 100 ≈ 33,81%.", "u": "%", "tol": "0.2", "ac": "33.81|33,8|33.8"}, {"k": "n", "ch": "g11c5", "q": "Để định lượng vanillin (HO-C₆H₃(OCH₃)-CHO, M=152) trong mẫu 0,120 g, hoà mẫu trong dung môi rồi chuẩn độ vừa đủ với 7,82 mL NaOH 0,1 M. Tính %m vanillin trong mẫu (%).", "a": "99,05", "e": "Vanillin có 1 –OH phenol → 1:1 với NaOH. n(vanillin) = 7,82×10⁻³ × 0,1 = 7,82×10⁻⁴ mol → m = 7,82×10⁻⁴ × 152 = 0,11886 g. %m = 0,11886/0,120 × 100 ≈ 99,05% → đủ tiêu chuẩn (>99%).", "u": "%", "tol": "0.3", "ac": "99.05|99|99.0|99,0"}, {"k": "m", "ch": "g11c6", "q": "Hợp chất nào sau đây tham gia phản ứng tráng bạc?", "o": "A=CH₃OH;B=CH₃CHO;C=CH≡C-CH₂-CH₃;D=CH₃COCH₃", "a": "B", "e": "Phản ứng tráng bạc cần nhóm -CHO (aldehyde). CH₃CHO (acetaldehyde) thoả. Ketone (CH₃COCH₃) không phản ứng."}, {"k": "m", "ch": "g11c6", "q": "Cho CH₃CHO phản ứng với H₂ (xt Ni, đun nóng) thu được sản phẩm là", "o": "A=CH₃COOH;B=HCOOH;C=CH₃CH₂OH;D=CH₃OH", "a": "C", "e": "Aldehyde + H₂ → alcohol bậc 1: CH₃CHO + H₂ → CH₃CH₂OH (ethanol). Đây là phản ứng khử."}, {"k": "m", "ch": "g11c6", "q": "Trong số các hợp chất sau, chất nào dùng để ngâm xác động vật?", "o": "A=dd HCHO (formalin);B=dd CH₃CHO;C=dd CH₃COOH;D=dd CH₃OH", "a": "A", "e": "Formalin = dd HCHO 37-40% → diệt khuẩn, làm cứng protein → bảo quản mẫu sinh học, ướp xác."}, {"k": "m", "ch": "g11c6", "q": "Khối lượng Ag thu được khi cho 0,1 mol CH₃CHO phản ứng hoàn toàn với AgNO₃/NH₃ dư là", "o": "A=16,2 g;B=43,2 g;C=21,6 g;D=10,8 g", "a": "C", "e": "RCHO + 2AgNO₃/NH₃ → 2Ag. n(Ag) = 2 × 0,1 = 0,2 mol → m = 0,2 × 108 = 21,6 g."}, {"k": "m", "ch": "g11c6", "q": "Hợp chất chứa nhóm C=O liên kết với nguyên tử carbon hoặc nguyên tử hydrogen được gọi là", "o": "A=alcohol;B=phenol;C=hợp chất carbonyl;D=carboxylic acid", "a": "C", "e": "Hợp chất carbonyl = chứa nhóm C=O. Bao gồm aldehyde (R-CHO) và ketone (R-CO-R')."}, {"k": "m", "ch": "g11c6", "q": "Hợp chất nào sau đây là aldehyde?", "o": "A=CH₃COCH₃;B=CH₃CHO;C=CH₃COOH;D=CH₃OH", "a": "B", "e": "Aldehyde có nhóm -CHO ở đầu mạch. CH₃CHO = acetaldehyde."}, {"k": "m", "ch": "g11c6", "q": "Tên gọi của hợp chất CH₃-CH(C₂H₅)-CH₂-CHO là", "o": "A=3-ethylbutanal;B=3-methylpentanal;C=2-ethylbutanal;D=2-methylpentanal", "a": "B", "e": "Mạch chính dài nhất chứa CHO: CHO-CH₂-CH(C₂H₅)-CH₃. Đếm từ CHO: C1(CHO)-C2(CH₂)-C3(CH-có ethyl)-C4-C5 = pentanal. Nhánh methyl ở C3 → 3-methylpentanal."}, {"k": "m", "ch": "g11c6", "q": "Cho 1,97 gam dung dịch formalin tác dụng với lượng dư AgNO₃/NH₃, thu được 10,8 gam Ag. Nồng độ % của HCHO trong dung dịch là (HCHO + 4AgNO₃/NH₃ → 4Ag)", "o": "A=38,07%;B=76,15%;C=19,03%;D=57,11%", "a": "A", "e": "n(Ag) = 10,8/108 = 0,1 mol → n(HCHO) = 0,1/4 = 0,025 mol → m(HCHO) = 0,025 × 30 = 0,75 g → C% = 0,75/1,97 × 100 ≈ 38,07%."}, {"k": "m", "ch": "g11c6", "q": "Dãy nào sau đây gồm các chất đều tác dụng với dung dịch AgNO₃/NH₃?", "o": "A=HCHO, CH₃CHO, HCOOH;B=CH₃COCH₃, CH₃CHO, HCHO;C=CH₃OH, HCHO, HCOOH;D=CH₃COOH, HCHO, CH₃CHO", "a": "A", "e": "AgNO₃/NH₃ oxi hoá nhóm -CHO. HCHO, CH₃CHO có -CHO; HCOOH có H-C(=O)-OH cũng tráng bạc được (chứa -CHO ẩn)."}, {"k": "tf", "ch": "g11c6", "q": "Cho hợp chất X có công thức cấu tạo (CH₃)₂CH-CH₂-CO-CH₃. Cho các phát biểu về X:\nCông thức phân tử của X là C₇H₁₆O", "a": "false", "e": "Sai. (CH₃)₂CH-CH₂-CO-CH₃ = 6C + 12H + 1O = C₆H₁₂O, không phải C₇H₁₆O."}, {"k": "tf", "ch": "g11c6", "q": "Cho hợp chất X có công thức cấu tạo (CH₃)₂CH-CH₂-CO-CH₃. Cho các phát biểu về X:\nTên gọi của X là 2-methylhexan-5-one", "a": "false", "e": "Sai. Đánh số ưu tiên C=O nhỏ → 4-methylpentan-2-one, không phải 2-methylhexan-5-one."}, {"k": "tf", "ch": "g11c6", "q": "Cho hợp chất X có công thức cấu tạo (CH₃)₂CH-CH₂-CO-CH₃. Cho các phát biểu về X:\nX phản ứng được với thuốc thử Tollens (AgNO₃/NH₃)", "a": "false", "e": "Sai. X là KETONE (C=O ở giữa mạch) → KHÔNG tráng bạc."}, {"k": "tf", "ch": "g11c6", "q": "Cho hợp chất X có công thức cấu tạo (CH₃)₂CH-CH₂-CO-CH₃. Cho các phát biểu về X:\nTrong phân tử X có nhóm chức carbonyl", "a": "true", "e": "Đúng. X có nhóm C=O → là hợp chất carbonyl."}, {"k": "n", "ch": "g11c6", "q": "Cho các chất: CH₃CH₂CHO, CH₃COCH₃, CH₃CH₂CH₂OH, CH₃COOH. Có bao nhiêu chất tác dụng được với I₂/NaOH tạo iodoform?", "a": "1", "e": "Iodoform yêu cầu nhóm CH₃-CO- hoặc CH₃-CH(OH)-. Chỉ CH₃COCH₃ (acetone) thoả mãn → 1 chất. CH₃CH₂CHO không có CH₃-CO-, propan-1-ol không có CH₃-CHOH-, acid không tạo iodoform.", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c6", "q": "Cho dãy: HCHO, CH₃COOH, CH₂=CH-CHO, C₂H₅OH, CH₃CHO, CH₃COCH₃. Có bao nhiêu chất phản ứng được với thuốc thử Tollens (AgNO₃/NH₃)?", "a": "3", "e": "Cần nhóm –CHO. 3 chất: HCHO, CH₂=CH-CHO, CH₃CHO. Acid (CH₃COOH), alcohol (C₂H₅OH), ketone (CH₃COCH₃) đều không tráng bạc.", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c6", "q": "Cho các chất hữu cơ: (CHO)₂, C₄H₂ (HC≡C–C≡CH, mạch hở), CH₃OH, HCHO, CH₃OCH₃, CH₃CHO. Có bao nhiêu chất phản ứng với AgNO₃/NH₃?", "a": "4", "e": "4 chất: (CHO)₂ (2 –CHO), HC≡C-C≡CH (2 H đầu ankin), HCHO, CH₃CHO. Methanol CH₃OH và ether CH₃OCH₃ không phản ứng.", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c6", "q": "Cho 4,5 gam HCHO phản ứng hoàn toàn với AgNO₃/NH₃ dư. Tính khối lượng Ag thu được (gam). (Lưu ý: HCHO là aldehyde đặc biệt → 4Ag).", "a": "64,8", "e": "HCHO + 4AgNO₃/NH₃ → 4Ag + (NH₄)₂CO₃ + 4NH₄NO₃. n(HCHO) = 4,5/30 = 0,15 mol → n(Ag) = 4 × 0,15 = 0,6 mol → m = 0,6 × 108 = 64,8 g. (Khác với CH₃CHO chỉ cho 2Ag.)", "u": "g", "tol": "0.2", "ac": "64.8"}, {"k": "n", "ch": "g11c6", "q": "Oxi hoá không hoàn toàn ethylene để điều chế ethanal, thu được hỗn hợp X (gồm CH₂=CH₂ dư + CH₃CHO). Dẫn 2,479 L X (đkc, 24,79 L/mol) qua AgNO₃/NH₃ dư, thu được 16,2 g Ag. Hiệu suất phản ứng oxi hoá ethylene = ?", "a": "75", "e": "n(X) = 2,479/24,79 = 0,1 mol. n(Ag) = 16,2/108 = 0,15 mol → n(CH₃CHO) = 0,15/2 = 0,075 mol. n(C₂H₄ dư) = 0,1 − 0,075 = 0,025 mol. H = 0,075/(0,075+0,025) × 100 = 75%.", "u": "%", "tol": "0.5", "ac": "75%|75.0|75,0"}, {"k": "n", "ch": "g11c6", "q": "Cho 0,1 mol aldehyde X phản ứng tối đa với 0,3 mol H₂ thu được 9 g alcohol Y. Mặt khác 2,1 g X + AgNO₃/NH₃ dư → m gam Ag. Tính m (g).", "a": "10,8", "e": "0,1 mol X cộng 0,3 mol H₂ → mỗi X cộng 3H₂ → X có 3 liên kết π. m(Y)/n = 9/0,1 = 90 g/mol → M(Y) = 90 → M(X) = 90 − 6 = 84 → X là OHC-CH=CH-CHO (C₄H₄O₂). 2,1 g X → 0,025 mol → có 2 nhóm CHO → n(Ag) = 4×0,025 = 0,1 mol → m = 10,8 g.", "u": "g", "tol": "0.2", "ac": "10.8"}, {"k": "m", "ch": "g11c7", "q": "Trong các chất sau đây, chất nào có nhiệt độ sôi cao nhất?", "o": "A=acetone;B=ethyl chloride;C=ethanol;D=acetic acid", "a": "D", "e": "Acid có liên kết hydrogen MẠNH NHẤT (dimer 2 liên kết H) → t°s cao nhất. Thứ tự: acid > alcohol > ketone > halide."}, {"k": "m", "ch": "g11c7", "q": "Propanoic acid không tác dụng với chất nào sau đây?", "o": "A=kim loại Cu;B=dung dịch NaOH;C=ethanol (xt H₂SO₄ đặc);D=đá vôi (CaCO₃)", "a": "A", "e": "Cu đứng SAU H trong dãy hoạt động → không phản ứng với acid carboxylic. Phản ứng với NaOH (trung hoà), ethanol (ester hoá), CaCO₃ (giải phóng CO₂)."}, {"k": "m", "ch": "g11c7", "q": "Công thức chung của carboxylic acid no, đơn chức, mạch hở là", "o": "A=CₙH₂ₙO₂ (n≥1);B=CₙH₂ₙ₊₂O₂ (n≥2);C=CₙH₂ₙ₋₂O (n≥2);D=CₙH₂ₙ₋₂O₂ (n≥3)", "a": "A", "e": "Acid no đơn chức mạch hở: CₙH₂ₙ₊₁COOH = CₙH₂ₙO₂ với n≥1 (HCOOH là n=1)."}, {"k": "m", "ch": "g11c7", "q": "Chất nào sau đây không phản ứng được với acetic acid?", "o": "A=Zn;B=Cu;C=NaOH;D=CaCO₃", "a": "B", "e": "Cu không phản ứng với acid yếu (đứng sau H). Zn (trước H) → tạo H₂; NaOH trung hoà; CaCO₃ → CO₂."}, {"k": "m", "ch": "g11c7", "q": "Một số carboxylic acid (oxalic, tartaric...) gây vị chua của quả sấu xanh. Khi làm sấu ngâm đường, người ta dùng dung dịch nào để giảm độ chua?", "o": "A=Vôi tôi (Ca(OH)₂);B=Muối ăn;C=Giấm ăn;D=Nước", "a": "A", "e": "Vôi tôi là base → trung hoà acid trong sấu → giảm chua."}, {"k": "m", "ch": "g11c7", "q": "Tên gọi của HCOOH là", "o": "A=formic acid (methanoic acid);B=acetic acid;C=propanoic acid;D=oxalic acid", "a": "A", "e": "HCOOH = formic acid (kiến) hoặc methanoic acid theo IUPAC."}, {"k": "m", "ch": "g11c7", "q": "Để trung hòa 0,2 mol hỗn hợp X gồm 2 carboxylic acid cần 0,3 mol NaOH. Tỉ lệ acid đơn chức và đa chức (2-COOH) trong X là", "o": "A=đơn:đa = 1:1;B=đơn:đa = 2:1;C=đơn:đa = 1:2;D=Đều là đơn chức", "a": "A", "e": "Gọi a mol đơn (1 COOH), b mol đa (2 COOH). a+b=0,2; a+2b=0,3 → b=0,1; a=0,1 → 1:1."}, {"k": "m", "ch": "g11c7", "q": "CH₃CH(CH₃)CH₂COOH có tên gọi là", "o": "A=3-methylbutanoic acid;B=2-methylpropanoic acid;C=isobutyric acid;D=isopentanoic acid", "a": "A", "e": "Mạch chính có 4C (butanoic), nhánh methyl ở C3 (đếm từ COOH) → 3-methylbutanoic acid (= isovaleric acid)."}, {"k": "m", "ch": "g11c7", "q": "Để loại bỏ lớp cặn màu trắng (CaCO₃) trong ấm đun nước, người ta có thể dùng dung dịch nào?", "o": "A=Giấm ăn (CH₃COOH);B=Nước muối;C=Nước vôi;D=Nước javen", "a": "A", "e": "2CH₃COOH + CaCO₃ → (CH₃COO)₂Ca + H₂O + CO₂. Acid yếu trong giấm hoà tan cặn vôi."}, {"k": "m", "ch": "g11c7", "q": "Hợp chất X có khối lượng phân tử là 60 amu, có công thức thực nghiệm là CH₂O. Công thức phân tử của X là", "o": "A=CH₂O;B=C₂H₄O₂;C=C₃H₆O₃;D=C₄H₈O₄", "a": "B", "e": "(CH₂O)ₙ = 60 → 30n = 60 → n=2 → C₂H₄O₂ (acetic acid CH₃COOH)."}, {"k": "tf", "ch": "g11c7", "q": "Phản ứng của acetic acid với sodium carbonate. Chuẩn bị: dd CH₃COOH 1M, dd Na₂CO₃ 1M. Thực hiện: cho 5 mL acid vào ống nghiệm, thêm từ từ 5 mL Na₂CO₃.\nCó khí không màu thoát ra", "a": "true", "e": "Đúng. 2CH₃COOH + Na₂CO₃ → 2CH₃COONa + H₂O + CO₂ (khí không màu)."}, {"k": "tf", "ch": "g11c7", "q": "Phản ứng của acetic acid với sodium carbonate. Chuẩn bị: dd CH₃COOH 1M, dd Na₂CO₃ 1M. Thực hiện: cho 5 mL acid vào ống nghiệm, thêm từ từ 5 mL Na₂CO₃.\nKhí thoát ra làm đục nước vôi trong", "a": "true", "e": "Đúng. CO₂ + Ca(OH)₂ → CaCO₃ (kết tủa trắng) → đục."}, {"k": "tf", "ch": "g11c7", "q": "Phản ứng của acetic acid với sodium carbonate. Chuẩn bị: dd CH₃COOH 1M, dd Na₂CO₃ 1M. Thực hiện: cho 5 mL acid vào ống nghiệm, thêm từ từ 5 mL Na₂CO₃.\nPhản ứng chứng tỏ acetic acid mạnh hơn carbonic acid", "a": "true", "e": "Đúng. Acid mạnh đẩy được acid yếu ra khỏi muối → CH₃COOH > H₂CO₃ về lực acid."}, {"k": "tf", "ch": "g11c7", "q": "Phản ứng của acetic acid với sodium carbonate. Chuẩn bị: dd CH₃COOH 1M, dd Na₂CO₃ 1M. Thực hiện: cho 5 mL acid vào ống nghiệm, thêm từ từ 5 mL Na₂CO₃.\nSau phản ứng, dung dịch có pH < 7", "a": "false", "e": "Sai. Sản phẩm CH₃COONa thuỷ phân tạo môi trường BASE → pH > 7."}, {"k": "n", "ch": "g11c7", "q": "Citric acid (HOOC-CH₂-C(OH)(COOH)-CH₂-COOH, 3 nhóm –COOH) trung hoà với NaOH 0,4 M. Tính thể tích NaOH (mL) cần dùng để trung hoà 0,005 mol citric acid.", "a": "37,5", "e": "n(NaOH) = 3 × 0,005 = 0,015 mol. V = 0,015/0,4 = 0,0375 L = 37,5 mL.", "u": "mL", "tol": "0.2", "ac": "37.5"}, {"k": "n", "ch": "g11c7", "q": "Để trung hoà 40 mL giấm ăn cần 25 mL dung dịch NaOH 1 M. Biết khối lượng riêng giấm là 1 g/mL. Tính nồng độ % của acetic acid trong giấm (%).", "a": "3,75", "e": "n(NaOH) = 0,025 mol = n(CH₃COOH) → m(CH₃COOH) = 1,5 g. m(giấm) = 40 g. C% = 1,5/40 × 100 = 3,75%.", "u": "%", "tol": "0.05", "ac": "3.75"}, {"k": "n", "ch": "g11c7", "q": "Trung hoà 6,72 g một carboxylic acid no, đơn chức, mạch hở X cần 200 g dung dịch NaOH 2,24%. Tính phân tử khối M của X (đvC).", "a": "60", "e": "m(NaOH) = 200 × 0,0224 = 4,48 g → n(NaOH) = 0,112 mol = n(X) (đơn chức). M(X) = 6,72/0,112 = 60 → X là CH₃COOH (acetic acid).", "u": "đvC", "tol": "1"}, {"k": "n", "ch": "g11c7", "q": "Chuẩn độ 6,0 mL dung dịch acetic acid bằng NaOH 0,15 M, cần trung bình 20,0 mL NaOH. Tính nồng độ mol của acetic acid (mol/L).", "a": "0,5", "e": "n(NaOH) = 0,02 × 0,15 = 0,003 mol = n(CH₃COOH). C(acid) = 0,003/0,006 = 0,5 M.", "u": "M", "tol": "0.02", "ac": "0.5|0,50|0.50"}, {"k": "n", "ch": "g11c7", "q": "Lên men 5 lít dung dịch ethanol 9,2° (d ethanol = 0,8 g/mL) với hiệu suất quá trình lên men giấm là 80%. Tính khối lượng acetic acid thu được (g).", "a": "384", "e": "V(C₂H₅OH nguyên chất) = 5×9,2/100 = 0,46 L = 460 mL → m = 460×0,8 = 368 g → n = 8 mol. C₂H₅OH + O₂ → CH₃COOH + H₂O. n(acid thực tế) = 8 × 0,8 = 6,4 mol → m = 6,4 × 60 = 384 g.", "u": "g", "tol": "2"}, {"k": "n", "ch": "g11c7", "q": "Methyl salicylate (CH₃OOC–C₆H₄–OH, có 1 nhóm ester + 1 nhóm phenol) cho 0,1 mol phản ứng với NaOH dư. Tính số mol NaOH đã tham gia phản ứng (mol).", "a": "0,2", "e": "Mỗi mol methyl salicylate cần 2 mol NaOH: 1 thuỷ phân ester + 1 trung hoà –OH phenol → 0,1 × 2 = 0,2 mol.", "u": "mol", "tol": "0.01", "ac": "0.2|0,20|0.20"}, {"k": "n", "ch": "g11c7", "q": "Citric acid (3 nhóm -COOH, có cấu trúc đối xứng quanh C ở giữa) + CH₃OH/H₂SO₄ đặc → tối đa bao nhiêu loại ester chứa nhóm –COOCH₃ khác nhau (gồm mono-, di-, tri-)?", "a": "5", "e": "Hai nhóm –COOH ở 2 đầu giống nhau (đối xứng), nhóm –COOH ở giữa khác. Mono: 2 đp (đầu / giữa). Di: 2 đp (2 đầu / 1 đầu+1 giữa). Tri: 1 đp. Tổng: 2+2+1 = 5.", "u": "ester", "tol": "0"}, {"k": "n", "ch": "g11c7", "q": "Cho 30 g hỗn hợp 3 acid: HCOOH, CH₃COOH, CH₂=CH-COOH tác dụng vừa hết với NaHCO₃ thu được 14,874 L CO₂ (đkc 25°C, 1 bar; 24,79 L/mol). Tính khối lượng muối khan thu được (g).", "a": "43,2", "e": "n(CO₂) = 14,874/24,79 = 0,6 mol = n(acid) (acid + NaHCO₃ → muối + CO₂ + H₂O, 1:1). m(NaHCO₃) = 0,6 × 84 = 50,4 g; m(H₂O) = 0,6×18 = 10,8 g; m(CO₂) = 26,4 g. m(muối) = 30 + 50,4 − 10,8 − 26,4 = 43,2 g.", "u": "g", "tol": "0.3", "ac": "43.2"}, {"k": "n", "ch": "g11c7", "q": "Tổng hợp methacrylic acid (CH₂=C(CH₃)COOH, M=86, D=1,015 g/mL) từ 10 m³ acetone (CH₃COCH₃, M=58, D=0,7844 g/mL) qua sơ đồ 2 giai đoạn, mỗi giai đoạn H = 80%. Tính thể tích methacrylic acid thu được (m³).", "a": "7,33", "e": "m(acetone) = 10⁷ × 0,7844 = 7,844×10⁶ g → n = 1,3524×10⁵ mol. H tổng = 0,8 × 0,8 = 0,64 → n(MA) = 8,6555×10⁴ mol → m(MA) = 7,4438×10⁶ g → V = 7,4438×10⁶/1,015 = 7,3338×10⁶ mL ≈ 7,33 m³.", "u": "m³", "tol": "0.1", "ac": "7.33|7,3|7.3"}], "g12": [{"k": "m", "ch": "g12c1", "q": "Hợp chất nào dưới đây thuộc loại ester?", "o": "A=HOCH2CH2CHO;B=CH3CH2CH2COOH;C=HOCH2COCH3;D=CH3CH2COOCH3", "a": "D", "e": "Ester chứa nhóm -COO-. Chỉ D có -COO-; A là aldehyde, B là acid, C là ketone.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Ester no, đơn chức, mạch hở có công thức tổng quát là", "o": "A=CnH2nO2 (n >= 2);B=CnH2n-2O2 (n >= 2);C=CnH2n+2O2 (n >= 2);D=CnH2nO (n >= 2)", "a": "A", "e": "Ester đơn chức có 2 O; no mạch hở có k = 1 nên H = 2n, suy ra CnH2nO2.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề MH – 2019) Ethyl propionate là ester có mùi thơm của dứa. Công thức của ethyl propionate là", "o": "A=HCOOC2H5;B=C2H5COOC2H5;C=C2H5COOCH3;D=CH3COOCH3", "a": "B", "e": "ethyl => gốc -C2H5, propionate => gốc C2H5COO- nên công thức là C2H5COOC2H5.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "So với các acid, alcohol có cùng số nguyên tử carbon thì ester có nhiệt độ sôi", "o": "A=thấp hơn do khối lượng phân tử ester nhỏ hơn nhiều;B=thấp hơn do giữa các phân tử ester không tồn tại liên kết hydrogen;C=cao hơn do giữa các phân tử ester có liên kết hydrogen bền vững;D=cao hơn do khối lượng phân tử ester lớn hơn nhiều", "a": "B", "e": "Các phân tử ester không tạo liên kết hydrogen với nhau nên nhiệt độ sôi thấp hơn alcohol và acid.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Ester nào sau đây tác dụng với NaOH thu được ethyl alcohol?", "o": "A=CH3COOC2H5;B=CH3COOC3H7;C=C2H5COOCH3;D=HCOOCH3", "a": "A", "e": "Alcohol sinh ra ứng với gốc -OR'; muốn thu C2H5OH thì ester phải có gốc -OC2H5.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TSĐH A – 2007) Một ester có CTPT C4H6O2, khi thủy phân trong acid thu được acetaldehyde. Công thức cấu tạo thu gọn của ester là", "o": "A=CH2=CHCOOCH3;B=CH3COOCH=CH2;C=HCOOC(CH3)=CH2;D=HCOOCH=CH-CH3", "a": "B", "e": "Ester cho aldehyde khi thủy phân phải có gốc alcohol dạng vinyl -O-CH=CH2; CH3COOCH=CH2 cho CH3COOH và CH3CHO.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Thủy phân hoàn toàn hỗn hợp ethyl propionate và ethyl formate trong dung dịch NaOH, thu được sản phẩm gồm", "o": "A=1 muối và 1 alcohol;B=2 muối và 2 alcohol;C=1 muối và 2 alcohol;D=2 muối và 1 alcohol", "a": "D", "e": "Hai gốc acid khác nhau (propionate, formate) tạo 2 muối; cùng gốc -OC2H5 nên chỉ có 1 alcohol C2H5OH.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TN THPT QG – 2021) Ester X có CTPT C4H8O2. Thủy phân X trong H2SO4 loãng, đun nóng, thu được ethyl alcohol và chất hữu cơ Y. Công thức của Y là", "o": "A=CH3OH;B=CH3COOH;C=C2H5COOH;D=HCOOH", "a": "B", "e": "X = RCOOC2H5, M = 88 => R = 15 (CH3-) nên Y là CH3COOH.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TN THPT QG – 2022) Phát biểu nào sau đây sai?", "o": "A=Ethyl formate có khả năng tham gia phản ứng tráng bạc;B=Phân tử methyl methacrylate có một liên kết pi;C=Ethyl acetate có công thức phân tử là C4H8O2;D=Methyl acrylate có khả năng tham gia phản ứng cộng Br2", "a": "B", "e": "Methyl methacrylate CH2=C(CH3)COOCH3 có 2 liên kết pi (1 C=C + 1 C=O), không phải 1.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TSCĐ – 2014) Đun nóng 24 gam acetic acid với dư ethyl alcohol (H2SO4 đặc) thu được 26,4 gam ester. Hiệu suất ester hóa là", "o": "A=75%;B=55%;C=60%;D=44%", "a": "A", "e": "n(acid) = 0,4 mol, n(ester) = 26,4/88 = 0,3 mol nên H = 0,3/0,4 = 75%.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TSCĐ – 2011) Cho m gam chất hữu cơ đơn chức X tác dụng vừa đủ với 50 gam dung dịch NaOH 8%, thu được 9,6 gam muối của acid hữu cơ và 3,2 gam alcohol. Công thức của X là", "o": "A=CH3COOCH=CH2;B=CH3COOC2H5;C=C2H5COOCH3;D=CH2=CHCOOCH3", "a": "C", "e": "n(NaOH) = 0,1 mol; M(alcohol) = 32 (CH3OH), M(muối) = 96 (C2H5COONa) nên X = C2H5COOCH3.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề THPT QG – 2019) Công thức của triolein là", "o": "A=(C17H33COO)3C3H5;B=(HCOO)3C3H5;C=(C2H5COO)3C3H5;D=(CH3COO)3C3H5", "a": "A", "e": "Triolein là triester của glycerol với oleic acid C17H33COOH.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Chất béo động vật hầu hết ở thể rắn do chứa", "o": "A=chủ yếu gốc acid béo không no;B=glycerol trong phân tử;C=chủ yếu gốc acid béo no;D=gốc acid béo", "a": "C", "e": "Gốc no có mạch thẳng, phân tử xếp khít nên nhiệt độ nóng chảy cao, chất béo rắn.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(Đề TN THPT QG – 2020) Thủy phân tristearin ((C17H35COO)3C3H5) trong NaOH, thu được muối có công thức là", "o": "A=C2H3COONa;B=HCOONa;C=C17H33COONa;D=C17H35COONa", "a": "D", "e": "Gốc acid giữ nguyên, muối là sodium stearate C17H35COONa.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Cho sơ đồ chuyển hóa: Triolein ->(+H2 dư, t°)-> E ->(+NaOH, t°)-> T ->(+HCl)-> G. Tên gọi của G là", "o": "A=oleic acid;B=linoleic acid;C=stearic acid;D=palmitic acid", "a": "C", "e": "Triolein + 3H2 -> tristearin; thủy phân -> C17H35COONa; + HCl -> C17H35COOH là stearic acid.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SBT Hóa học 12 CB) Phát biểu nào sau đây không đúng?", "o": "A=Chất béo là triester của glycerol và các monocarboxylic acid mạch dài không phân nhánh;B=Chất béo chứa chủ yếu gốc no thường là chất rắn ở nhiệt độ phòng;C=Chất béo chứa chủ yếu gốc không no thường là chất lỏng, gọi là dầu;D=Phản ứng thủy phân chất béo trong môi trường kiềm là phản ứng thuận nghịch", "a": "D", "e": "Xà phòng hóa tạo muối RCOONa không tác dụng ngược với glycerol nên là phản ứng một chiều.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Đun sôi a gam một triglyceride X với KOH đến phản ứng hoàn toàn, thu được 0,92 gam glycerol và 9,58 gam muối. Giá trị của a là", "o": "A=8,82 gam;B=9,94 gam;C=10,90 gam;D=8,92 gam", "a": "A", "e": "n(glycerol) = 0,01 => n(KOH) = 0,03; bảo toàn khối lượng: a = 9,58 + 0,92 - 0,03 x 56 = 8,82 gam.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SGK – KNTT) Cho các phát biểu: (1) Một số ester có mùi thơm dùng làm chất tạo hương; (2) Chất béo là triester của glycerol với acid béo; (3) Chất béo tan tốt trong nước; (4) Mỡ động vật, dầu thực vật làm nguyên liệu sản xuất xà phòng; (5) Thủy phân ester trong acid luôn là phản ứng một chiều. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "B", "e": "(1), (2), (4) đúng; (3) sai vì chất béo kị nước; (5) sai vì thủy phân trong acid là thuận nghịch.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\na. Tên gọi của các ester trên là: (1) methyl propionate; (2) ethyl butyrate; (3) methyl acetate; (4) ethyl propionate.", "o": "", "a": "true", "e": "Các tên đều đúng theo quy tắc tên gốc R' + tên gốc acid.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nb. Ester (2) và (4) có mùi dứa chín.", "o": "", "a": "true", "e": "Ethyl butyrate và ethyl propionate đều được dùng làm hương dứa.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nc. Độ tan trong nước giảm dần theo thứ tự: (2) > (1) > (3) > (4).", "o": "", "a": "false", "e": "Độ tan giảm khi M tăng; M(3) = 74 < M(1) = 88 < M(4) = 102 < M(2) = 116 nên thứ tự đúng là (3) > (1) > (4) > (2).", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nd. Các ester tạo liên kết hydrogen với nước nên tan nhiều hơn hẳn alcohol và carboxylic acid cùng số C hoặc cùng M.", "o": "", "a": "false", "e": "Ester không tạo liên kết hydrogen giữa các phân tử và tương tác yếu với nước nên tan kém hơn alcohol và acid.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho vào hai ống nghiệm mỗi ống 1,0 mL ethyl acetate. Bước 2: thêm 2 mL H2SO4 20% vào ống (1), 2 mL NaOH 30% vào ống (2). Bước 3: đun cách thủy 60-70°C.\na. Sau bước 2: chất lỏng trong cả hai ống nghiệm đồng nhất.", "o": "", "a": "false", "e": "Chưa đun, ester chưa phản ứng và không tan trong nước nên chất lỏng tách thành hai lớp.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho vào hai ống nghiệm mỗi ống 1,0 mL ethyl acetate. Bước 2: thêm 2 mL H2SO4 20% vào ống (1), 2 mL NaOH 30% vào ống (2). Bước 3: đun cách thủy 60-70°C.\nb. Sau bước 3: sản phẩm thu được ở cả hai ống nghiệm là CH3COOH.", "o": "", "a": "false", "e": "Ống (1) thủy phân thuận nghịch cho CH3COOH còn ester dư (phân lớp); ống (2) xà phòng hóa cho CH3COONa tan, không phải CH3COOH.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho vào hai ống nghiệm mỗi ống 1,0 mL ethyl acetate. Bước 2: thêm 2 mL H2SO4 20% vào ống (1), 2 mL NaOH 30% vào ống (2). Bước 3: đun cách thủy 60-70°C.\nc. Sau bước 3: ống (1) thể tích lớp chất lỏng phía trên giảm; ống (2) tạo thành hỗn hợp đồng nhất.", "o": "", "a": "true", "e": "Ống (1) ester bị thủy phân một phần nên lớp trên giảm; ống (2) phản ứng một chiều, sản phẩm đều tan nên đồng nhất.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho vào hai ống nghiệm mỗi ống 1,0 mL ethyl acetate. Bước 2: thêm 2 mL H2SO4 20% vào ống (1), 2 mL NaOH 30% vào ống (2). Bước 3: đun cách thủy 60-70°C.\nd. Phản ứng xảy ra ở ống (1) là thuận nghịch, ống (2) là một chiều.", "o": "", "a": "true", "e": "Môi trường acid cho phản ứng thuận nghịch; môi trường kiềm (xà phòng hóa) là một chiều.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho salicylic acid phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3).\na. Công thức của salicylic acid là o-HO-C6H4-COOH.", "o": "", "a": "true", "e": "Salicylic acid có nhóm -OH ở vị trí ortho (số 2) so với -COOH.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho salicylic acid phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3).\nb. Phản ứng giữa salicylic acid với methyl alcohol có sulfuric acid xúc tác là phản ứng thuận nghịch.", "o": "", "a": "true", "e": "Phản ứng ester hóa giữa acid và alcohol luôn là phản ứng thuận nghịch.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho salicylic acid phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3).\nc. 1 mol methyl salicylate tác dụng với Na dư thu được 1 mol khí H2.", "o": "", "a": "false", "e": "Methyl salicylate HO-C6H4-COOCH3 chỉ còn 1 nhóm -OH phenol nên 1 mol chất với Na dư cho 0,5 mol H2.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Cho salicylic acid phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3).\nd. 1 mol methyl salicylate tác dụng tối đa với 1 mol NaOH.", "o": "", "a": "false", "e": "Tối đa 2 mol NaOH: 1 mol thủy phân nhóm ester và 1 mol trung hòa -OH phenol.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thủy phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\na. X là triolein có công thức (C17H33COO)3C3H5.", "o": "", "a": "true", "e": "Chỉ thu được một muối C17H33COONa nên ba gốc acid giống nhau, X là triolein.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thủy phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nb. 1 mol X tác dụng với NaOH dư thu được 3 mol C17H33COONa.", "o": "", "a": "true", "e": "Tỉ lệ phản ứng 1 mol triglyceride với 3 mol NaOH tạo 3 mol muối.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thủy phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nc. X là chất béo no ở trạng thái rắn (điều kiện thường).", "o": "", "a": "false", "e": "Gốc oleate C17H33COO- chứa 1 liên kết C=C nên X là chất béo không no, thể lỏng.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thủy phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nd. 1 mol X + 3 mol H2 (Ni, t°) thu được Y. Y tác dụng với NaOH dư thu được muối C17H33COOH.", "o": "", "a": "false", "e": "Y là tristearin; Y + NaOH dư cho muối C17H35COONa, sai cả loại chất (muối, không phải acid) lẫn gốc.", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "Cho các ester: HCOOCH3; CH3COOCH3; (COOCH3)2; (HCOO)2C2H4; CH2=CHCOOCH3; C2H5COOC2H5; CH3COOC6H5. Có bao nhiêu ester no, đơn chức, mạch hở?", "o": "", "a": "3", "e": "Loại 2 chất hai chức, chất không no CH2=CHCOOCH3 và ester của phenol CH3COOC6H5; còn 3 chất.", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "(Đề TSCĐ – 2007) Số hợp chất đơn chức, đồng phân cấu tạo của nhau cùng CTPT C4H8O2, đều tác dụng với NaOH là bao nhiêu?", "o": "", "a": "6", "e": "Gồm 4 ester (HCOOC3H7, HCOOCH(CH3)2, CH3COOC2H5, C2H5COOCH3) và 2 acid (butanoic, 2-methylpropanoic).", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "(Đề THPT QG – 2017) Cho a mol ester X (C9H10O2) tác dụng vừa đủ với 2a mol NaOH, thu được dung dịch không tráng bạc. Số công thức cấu tạo phù hợp với X?", "o": "", "a": "4", "e": "Tỉ lệ 1:2 => ester của phenol; không tráng bạc => không có gốc HCOO-. Gồm CH3COOC6H4CH3 (o, m, p: 3) và C2H5COOC6H5 (1).", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "Hydrogen hóa hoàn toàn triolein thu được Y. Thủy phân Y bằng NaOH thu được glycerol và Z. Tính phần trăm khối lượng oxygen trong Z?", "o": "", "a": "10,46", "e": "Triolein + 3H2 -> tristearin; Z = C17H35COONa (M = 306); %O = 32/306 = 10,46%.", "u": "%", "tol": "0.1"}, {"k": "n", "ch": "g12c1", "q": "(Đề MH – 2020) Hỗn hợp X gồm hai ester C8H8O2 chứa vòng benzene. Để phản ứng hết 0,25 mol X cần tối đa 0,35 mol NaOH, thu được m gam hỗn hợp hai muối. Tính m?", "o": "", "a": "30", "e": "Ester thường (0,15 mol) + ester phenol (0,1 mol); hai muối HCOONa 17 g và CH3C6H4ONa 13 g nên m = 30 g.", "u": "g", "tol": "0.1"}, {"k": "n", "ch": "g12c1", "q": "Hydrogen hóa hoàn toàn 0,1 mol triglyceride X cần 0,3 mol H2 thu được Y. Y + NaOH vừa đủ thu được sodium stearate và 27,8 gam sodium palmitate. Số nguyên tử H trong X?", "o": "", "a": "100", "e": "n(palmitate) = 0,1; tổng muối 0,3 => 2 gốc stearate + 1 gốc palmitate; Y = C55H106O6, X cộng 3 H2 nên X = C55H100O6 có 100 H.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Thành phần chính của chất giặt rửa tổng hợp là", "o": "A=C15H31COONa;B=(C17H35COO)2Ca;C=CH3[CH2]11-C6H4-SO3Na;D=C17H35COOK", "a": "C", "e": "Chất giặt rửa tổng hợp là muối alkylsulfate/alkylbenzenesulfonate chứa S; A và D là xà phòng, B là kết tủa với nước cứng.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Hợp chất nào dưới đây được sử dụng làm xà phòng?", "o": "A=CH3COONa;B=CH3(CH2)14COONa;C=CH3(CH2)12COOCH3;D=CH3(CH2)5O(CH2)5CH3", "a": "B", "e": "Xà phòng là muối Na/K của acid béo mạch dài; CH3(CH2)14COONa = C15H31COONa (16 C).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SBT Hóa học 12 CB) Trong thành phần của xà phòng và chất giặt rửa thường có một số ester. Vai trò của các ester này là", "o": "A=làm tăng khả năng giặt rửa;B=tạo hương thơm mát, dễ chịu;C=tạo màu sắc hấp dẫn;D=làm giảm giá thành", "a": "B", "e": "Ester có mùi thơm nên được thêm vào với vai trò chất tạo hương cho xà phòng, chất giặt rửa.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SBT Hóa học 12 CB) Xà phòng và chất giặt rửa có điểm chung là", "o": "A=chứa muối sodium có khả năng làm giảm sức căng bề mặt chất bẩn;B=các muối được lấy từ phản ứng xà phòng hóa chất béo;C=sản phẩm của công nghệ hóa dầu;D=có nguồn gốc từ động vật hoặc thực vật", "a": "A", "e": "Cả hai đều có đầu ưa nước - đuôi kị nước nên làm giảm sức căng bề mặt, nhũ hóa vết bẩn.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Nguyên nhân làm cho bồ kết có khả năng giặt rửa là", "o": "A=trong bồ kết có chất khử mạnh;B=bồ kết có thành phần là ester của glycerol;C=trong bồ kết có những chất oxi hóa mạnh;D=bồ kết có những chất có cấu tạo kiểu đầu phân cực gắn với đuôi dài không phân cực", "a": "D", "e": "Bồ kết chứa saponin có đầu ưa nước gắn đuôi dài kị nước, giống cấu tạo xà phòng nên giặt rửa được.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SGK – Cánh Diều) Để tẩy vết dầu, mỡ bám trên quần áo, sử dụng chất nào sau đây là phù hợp nhất?", "o": "A=Nước cất;B=Dung dịch sodium hydroxide;C=Dung dịch nước Javel;D=Dung dịch xà phòng", "a": "D", "e": "Xà phòng nhũ hóa dầu mỡ thành hạt nhỏ rửa trôi; NaOH ăn mòn vải, Javel chỉ tẩy màu.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Từ tristearin, người ta dùng phản ứng nào để điều chế ra xà phòng?", "o": "A=Phản ứng ester hóa;B=Phản ứng thủy phân ester trong môi trường acid;C=Phản ứng cộng hydrogen;D=Phản ứng thủy phân ester trong môi trường kiềm", "a": "D", "e": "Xà phòng hóa (thủy phân trong kiềm) tạo muối C17H35COONa chính là xà phòng.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SGK – CTST) Hóa chất chủ đạo trong ngành công nghiệp sản xuất xà phòng là", "o": "A=K2SO4;B=NaCl;C=Mg(NO3)2;D=NaOH", "a": "D", "e": "Xà phòng hóa chất béo cần kiềm mạnh là NaOH (hoặc KOH).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Xà phòng được điều chế bằng cách nào trong các cách sau đây?", "o": "A=Thủy phân saccharose;B=Thủy phân mỡ trong kiềm;C=Phản ứng của acid với kim loại;D=Dehydrogen hóa mỡ tự nhiên", "a": "B", "e": "Mỡ (chất béo) + NaOH đun nóng tạo muối acid béo (xà phòng) và glycerol - phản ứng xà phòng hóa.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SBT Hóa học 12 CB) Không nên dùng xô, chậu bằng nhôm để đựng quần áo ngâm xà phòng vì", "o": "A=quần áo bị mục nhanh;B=xô chậu nhanh hỏng do trong xà phòng có kiềm;C=quần áo bị bạc màu nhanh;D=quần áo không sạch", "a": "B", "e": "Xà phòng thường dư kiềm: 2Al + 2NaOH + 2H2O -> 2NaAlO2 + 3H2, nhôm bị ăn mòn.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Không nên dùng xà phòng khi giặt rửa với nước cứng vì", "o": "A=xuất hiện kết tủa làm giảm tác dụng giặt rửa và ảnh hưởng đến chất lượng sợi vải;B=gây ô nhiễm môi trường;C=tạo ra kết tủa CaCO3, MgCO3 bám lên sợi vải;D=gây hại cho da tay", "a": "A", "e": "Ca2+, Mg2+ tạo kết tủa muối stearate/palmitate (không phải CaCO3, MgCO3) làm mất tác dụng và bám trên vải.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SBT Hóa học 12 NC) Chất giặt rửa tổng hợp có ưu điểm", "o": "A=dễ kiếm;B=rẻ tiền hơn xà phòng;C=có thể dùng để giặt rửa cả trong nước cứng;D=có khả năng hòa tan tốt trong nước", "a": "C", "e": "Muối sulfate/sulfonate của Ca2+, Mg2+ đều tan nên không bị kết tủa, dùng được với nước cứng.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SGK Hóa học 12 NC) Phát biểu nào sau đây đúng?", "o": "A=Chất giặt rửa là chất có tác dụng giống như xà phòng nhưng được tổng hợp từ dầu mỏ;B=Chất giặt rửa là chất có tác dụng làm sạch vết bẩn trên bề mặt vật rắn;C=Chất giặt rửa là chất khi dùng cùng với nước có tác dụng làm sạch vết bẩn bám trên vật rắn;D=Chất giặt rửa là chất khi dùng cùng với nước làm sạch vết bẩn trên vật rắn mà không gây ra phản ứng hóa học với các chất đó", "a": "D", "e": "Định nghĩa đầy đủ gồm: dùng cùng nước, làm sạch vết bẩn trên vật rắn và không gây phản ứng hóa học với vết bẩn.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "(SGK Hóa học 12 CB) Cho các phát biểu: (a) Xà phòng là sản phẩm của phản ứng xà phòng hóa chất béo với NaOH hoặc KOH; (b) Muối sodium/potassium của acid hữu cơ là thành phần chính của xà phòng; (c) Đun nóng chất béo với NaOH hoặc KOH ta được xà phòng; (d) Từ dầu mỏ sản xuất được chất giặt rửa tổng hợp. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(a), (c), (d) đúng; (b) sai vì phải là muối của acid BÉO, không phải acid hữu cơ bất kỳ.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Cho các phát biểu: (1) Chất giặt rửa tổng hợp dùng được cả trong nước cứng; (2) Các triglyceride đều có phản ứng cộng hydrogen; (3) Thủy phân chất béo trong môi trường kiềm là phản ứng một chiều; (4) Có thể dùng nước và quỳ tím phân biệt glycerol, formic acid, triolein. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(1), (3), (4) đúng; (2) sai vì chỉ triglyceride không no mới cộng H2 (tristearin không cộng).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Cho các phát biểu: (a) Xà phòng là muối sodium hoặc potassium của acid béo; (b) Các triglyceride đều có phản ứng cộng hydrogen; (c) Thủy phân chất béo trong môi trường kiềm là phản ứng một chiều; (d) Chất béo nhẹ hơn nước và không tan trong nước. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(a), (c), (d) đúng; (b) sai vì không phải mọi triglyceride đều cộng H2.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Cho các phát biểu: (a) Chất ưa nước tan tốt trong nước như methanol, sodium acetate; (b) Chất kị nước không tan trong dầu mỡ, dung môi hữu cơ; (c) Xà phòng là hỗn hợp muối sodium/potassium của acid béo; (d) Chất tẩy rửa tổng hợp là muối sodium của acid béo; (e) Phân tử chất giặt rửa gồm 1 đầu ưa dầu mỡ gắn với 1 đầu dài ưa nước; (f) Ưu điểm của xà phòng là dùng được với nước cứng. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "A", "e": "Chỉ (a) và (c) đúng; các ý còn lại đảo sai: chất kị nước tan trong dầu mỡ, đầu ưa nước gắn với đuôi kị nước, xà phòng kém tác dụng với nước cứng.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c1", "q": "Cho các phát biểu: (a) Xà phòng bị giảm hoặc mất tác dụng khi dùng nước cứng vì tạo muối kết tủa với Ca2+, Mg2+; (b) Bột giặt tổng hợp dùng được với nước cứng vì muối sulfonate tan, không kết tủa với Ca2+, Mg2+; (c) Các chế phẩm giặt rửa có thể chứa chất tẩy trắng như sodium hypochlorite; (d) Chất giặt rửa có gốc hydrocarbon phân nhánh không gây ô nhiễm vì dễ bị vi sinh vật phân hủy; (e) Chất ưa nước là chất tan tốt trong dầu mỏ, alkane. Số phát biểu SAI là", "o": "A=1;B=2;C=3;D=4", "a": "B", "e": "(a), (b), (c) đúng; (d) và (e) sai - gốc phân nhánh khó phân hủy gây ô nhiễm, chất ưa nước tan tốt trong nước.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Chất giặt rửa tổng hợp là chất được tổng hợp hóa học, thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\na. Các muối CH3[CH2]14COONa và CH3[CH2]10CH2OSO3Na là thành phần chính của chất giặt rửa tổng hợp.", "o": "", "a": "false", "e": "CH3[CH2]14COONa có -COO- là xà phòng, không phải thành phần chất giặt rửa tổng hợp.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Chất giặt rửa tổng hợp là chất được tổng hợp hóa học, thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nb. Thành phần chính của chất giặt rửa tổng hợp điển hình là CH3[CH2]10CH2OSO3Na hoặc CH3[CH2]11-C6H4-SO3Na.", "o": "", "a": "true", "e": "Đây là muối alkylsulfate và alkylbenzenesulfonate điển hình.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Chất giặt rửa tổng hợp là chất được tổng hợp hóa học, thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nc. Saponin trong bồ hòn và quả bồ kết là chất giặt rửa tự nhiên, khi tiếp xúc với nước tạo lớp bọt nhẹ tương tự xà phòng.", "o": "", "a": "true", "e": "Saponin là chất giặt rửa tự nhiên, có khả năng tạo bọt và nhũ hóa như xà phòng.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Chất giặt rửa tổng hợp là chất được tổng hợp hóa học, thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nd. Cấu tạo gồm phần ưa nước và kị nước; phần ưa nước của xà phòng và chất giặt rửa là gốc hydrocarbon mạch dài R, tan nhiều trong nước.", "o": "", "a": "false", "e": "Gốc R mạch dài là phần KỊ nước; phần ưa nước là -COO-, -SO3Na, -OSO3Na.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Trong công nghiệp sản xuất xà phòng, người ta đun chất béo với dung dịch kiềm đặc: (RCOO)3C3H5 + 3NaOH -> 3RCOONa + C3H5(OH)3.\na. Thành phần chủ yếu muối RCOONa là sodium palmitate và sodium stearate.", "o": "", "a": "true", "e": "Chất béo tự nhiên chủ yếu chứa gốc palmitate và stearate.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Trong công nghiệp sản xuất xà phòng, người ta đun chất béo với dung dịch kiềm đặc: (RCOO)3C3H5 + 3NaOH -> 3RCOONa + C3H5(OH)3.\nb. Để tách hỗn hợp muối acid béo, cho dung dịch NaCl bão hòa vào thì các muối acid béo nổi lên trên.", "o": "", "a": "true", "e": "NaCl bão hòa làm giảm độ tan (hiệu ứng muối kết) nên xà phòng tách ra và nổi lên.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Trong công nghiệp sản xuất xà phòng, người ta đun chất béo với dung dịch kiềm đặc: (RCOO)3C3H5 + 3NaOH -> 3RCOONa + C3H5(OH)3.\nc. Trong phòng thí nghiệm, có thể đựng hỗn hợp chất béo và NaOH vào bát nhôm (hoặc xoong nhôm) để điều chế lượng nhỏ xà phòng.", "o": "", "a": "false", "e": "NaOH ăn mòn nhôm; phải dùng bát sứ hoặc thủy tinh chịu nhiệt.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Trong công nghiệp sản xuất xà phòng, người ta đun chất béo với dung dịch kiềm đặc: (RCOO)3C3H5 + 3NaOH -> 3RCOONa + C3H5(OH)3.\nd. Xà phòng còn được sản xuất từ dầu mỏ theo sơ đồ: alkane -> acid béo -> muối sodium/potassium của acid béo.", "o": "", "a": "true", "e": "Oxi hóa alkane thành acid béo rồi trung hòa bằng NaOH/KOH tạo muối (xà phòng).", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL dung dịch NaCl bão hòa, khuấy nhẹ, để nguội.\na. Sau bước 2 thấy có lớp chất rắn màu trắng chứa muối sodium của acid béo nổi lên.", "o": "", "a": "true", "e": "Xà phòng có khối lượng riêng nhỏ và bị muối kết nên nổi lên trên.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL dung dịch NaCl bão hòa, khuấy nhẹ, để nguội.\nb. Vai trò của dung dịch NaCl bão hòa ở bước 2 là để tách muối sodium của acid béo ra khỏi hỗn hợp.", "o": "", "a": "true", "e": "NaCl bão hòa làm giảm độ tan của muối acid béo, glycerol vẫn ở lại trong dung dịch.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL dung dịch NaCl bão hòa, khuấy nhẹ, để nguội.\nc. Nếu thay mỡ lợn bằng dầu nhớt thì hiện tượng thí nghiệm sau bước 2 vẫn xảy ra tương tự.", "o": "", "a": "false", "e": "Dầu nhớt là hydrocarbon, không phải ester nên không bị thủy phân, không tạo xà phòng.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL dung dịch NaCl bão hòa, khuấy nhẹ, để nguội.\nd. Phản ứng ở thí nghiệm trên được ứng dụng trong công nghiệp để sản xuất xà phòng và glycerol.", "o": "", "a": "true", "e": "Đây là phản ứng xà phòng hóa, ứng dụng sản xuất đồng thời xà phòng và glycerol.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thành phần chính của chất giặt rửa tổng hợp điển hình là CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11-C6H4-SO3Na (2).\na. Chất giặt rửa tổng hợp được sản xuất từ paraffin dầu mỏ: dầu mỏ -> [R-SO3H; R-OSO3H] -> [R-SO3Na; R-OSO3Na].", "o": "", "a": "true", "e": "Sơ đồ đúng: sulfo hóa paraffin thành acid sulfonic rồi trung hòa bằng NaOH.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thành phần chính của chất giặt rửa tổng hợp điển hình là CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11-C6H4-SO3Na (2).\nb. Phần ưa nước trong phân tử chất giặt rửa tổng hợp (1) và (2) là -SO3Na và -OSO3Na.", "o": "", "a": "true", "e": "Đầu phân cực ưa nước chính là các nhóm sulfate/sulfonate; gốc hydrocarbon dài là phần kị nước.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thành phần chính của chất giặt rửa tổng hợp điển hình là CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11-C6H4-SO3Na (2).\nc. Ưu điểm của chất giặt rửa tổng hợp là dùng được với nước cứng (không bị kết tủa bởi Ca2+, Mg2+) và giá thành thấp.", "o": "", "a": "true", "e": "Muối sulfate/sulfonate của Ca2+, Mg2+ đều tan nên không kết tủa; nguyên liệu từ dầu mỏ giá rẻ.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c1", "q": "Thành phần chính của chất giặt rửa tổng hợp điển hình là CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11-C6H4-SO3Na (2).\nd. Các chất giặt rửa tổng hợp có gốc hydrocarbon phân nhánh hoặc chứa vòng benzene ít gây ô nhiễm môi trường do chúng bị vi sinh vật phân hủy.", "o": "", "a": "false", "e": "Ngược lại: gốc phân nhánh hoặc vòng benzene rất khó bị vi sinh vật phân hủy nên gây ô nhiễm môi trường.", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "Cho các chất: CH3[CH2]10CH2OSO3Na; CH3[CH2]14COONa; CH3[CH2]11-C6H4-SO3Na; CH3CH2COONa; CH3[CH2]16COOK. Số chất có thể là thành phần chính của xà phòng là bao nhiêu?", "o": "", "a": "2", "e": "Xà phòng là muối Na/K của acid béo: CH3[CH2]14COONa và CH3[CH2]16COOK; loại 2 chất chứa S và CH3CH2COONa (mạch quá ngắn).", "u": "", "tol": ""}, {"k": "n", "ch": "g12c1", "q": "Xà phòng hóa hoàn toàn 0,1 mol tristearin (C17H35COO)3C3H5 bằng dung dịch NaOH dư, đun nóng, thu được m gam glycerol. Tính giá trị của m?", "o": "", "a": "9,2", "e": "n(glycerol) = n(tristearin) = 0,1 mol; m = 0,1 x 92 = 9,2 gam.", "u": "g", "tol": "0.1"}, {"k": "n", "ch": "g12c1", "q": "Xà phòng hóa hoàn toàn 17,8 gam chất béo X cần vừa đủ dung dịch chứa 0,06 mol NaOH. Cô cạn dung dịch sau phản ứng thu được m gam muối khan. Tính m?", "o": "", "a": "18,36", "e": "n(glycerol) = 0,02 mol; bảo toàn khối lượng: m = 17,8 + 0,06 x 40 - 0,02 x 92 = 18,36 gam.", "u": "g", "tol": "0.1"}, {"k": "n", "ch": "g12c1", "q": "Thủy phân hoàn toàn m gam chất béo bằng dung dịch NaOH, đun nóng, thu được 9,2 gam glycerol và 91,8 gam muối. Tính giá trị của m?", "o": "", "a": "89", "e": "n(glycerol) = 0,1 mol => n(NaOH) = 0,3 mol; m = 91,8 + 9,2 - 0,3 x 40 = 89 gam.", "u": "g", "tol": "1"}, {"k": "n", "ch": "g12c1", "q": "(SCĐ – CTST) Lượng NaOH cần dùng trong một thí nghiệm điều chế xà phòng là 60 gam. Nếu thay NaOH bằng KOH thì khối lượng KOH cần dùng là bao nhiêu?", "o": "", "a": "84", "e": "Cùng hóa trị I nên cùng số mol: n = 60/40 = 1,5 mol; m(KOH) = 1,5 x 56 = 84 gam.", "u": "g", "tol": "1"}, {"k": "n", "ch": "g12c1", "q": "(SBT Hóa học 12 CB) Tính khối lượng muối thu được khi cho 100 kg mỡ chứa 50% tristearin, 30% triolein, 20% tripalmitin tác dụng với sodium hydroxide vừa đủ (H = 100%).", "o": "", "a": "103,22", "e": "Tổng n chất béo = 0,11493 kmol; m(NaOH) = 13,79 kg, m(glycerol) = 10,57 kg; bảo toàn khối lượng: m(muối) = 100 + 13,79 - 10,57 = 103,22 kg.", "u": "kg", "tol": "0.5"}, {"k": "m", "ch": "g12c2", "q": "Carbohydrate nào sau đây thuộc loại polysaccharide?", "o": "A=Fructose;B=Glucose;C=Tinh bột;D=Saccharose", "a": "C", "e": "Tinh bột là polysaccharide (C₆H₁₀O₅)ₙ; fructose, glucose là monosaccharide; saccharose là disaccharide.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề THPT QG - 2018) Công thức phân tử của saccharose là", "o": "A=C6H12O6;B=(C6H10O5)n;C=C12H22O11;D=C2H4O2", "a": "C", "e": "Saccharose là disaccharide: C₁₂H₂₂O₁₁ (M = 342).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Phân tử maltose được tạo bởi", "o": "A=một gốc glucose và một gốc maltose;B=hai gốc fructose;C=một gốc glucose và một gốc fructose;D=hai gốc glucose", "a": "D", "e": "Maltose = 2 gốc α-glucose nối qua liên kết α-1,4-glycoside.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Saccharose tham gia phản ứng hóa học nào sau đây?", "o": "A=Phản ứng tráng gương;B=Phản ứng thủy phân;C=Phản ứng xà phòng hóa;D=Phản ứng ester hóa", "a": "B", "e": "Saccharose không có –OH hemiacetal tự do nên không tráng bạc; chỉ thủy phân được (→ glucose + fructose).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Carbohydrate chứa đồng thời liên kết α–1,4–glycoside và liên kết α–1,6–glycoside trong phân tử là", "o": "A=tinh bột;B=cellulose;C=saccharose;D=fructose", "a": "A", "e": "Amylose chỉ có α-1,4; amylopectin có α-1,4 và α-1,6 (nơi phân nhánh). Cellulose là β-1,4.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Ở nhiệt độ thường, nhỏ vài giọt dung dịch iodine vào hồ tinh bột thấy xuất hiện màu", "o": "A=vàng;B=xanh tím;C=hồng;D=nâu đỏ", "a": "B", "e": "Hồ tinh bột + I₂ → màu xanh tím (đun nóng mất màu, để nguội có lại).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề TSĐH A - 2007) Để chứng minh trong phân tử của glucose có nhiều nhóm hydroxyl, người ta cho dung dịch glucose phản ứng với", "o": "A=Cu(OH)2 ở nhiệt độ thường;B=Cu(OH)2 trong NaOH, đun nóng;C=kim loại Na;D=AgNO3 trong dung dịch NH3, đun nóng", "a": "A", "e": "Cu(OH)₂ ở t° thường cho dung dịch xanh lam — phản ứng đặc trưng của ≥ 2 nhóm –OH kề nhau. B và D chứng minh tính khử (nhóm CHO), Na phản ứng với mọi –OH.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề MH – 2022) Phát biểu nào sau đây đúng?", "o": "A=Glucose bị thủy phân trong môi trường acid;B=Tinh bột là chất lỏng ở nhiệt độ thường;C=Cellulose thuộc loại disaccharide;D=Dung dịch saccharose hòa tan được Cu(OH)2", "a": "D", "e": "Saccharose có nhiều –OH kề nhau nên hòa tan Cu(OH)₂ ở t° thường. Glucose, fructose là monosaccharide không bị thủy phân; tinh bột là chất rắn; cellulose là polysaccharide.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề TNTHPT – 2023) Phát biểu nào sau đây sai?", "o": "A=Thủy phân saccharose chỉ thu được glucose;B=Glucose có khả năng tham gia phản ứng tráng bạc;C=Cellulose và tinh bột đều thuộc loại polysaccharide;D=Cellulose có cấu tạo mạch không phân nhánh", "a": "A", "e": "Thủy phân saccharose thu được glucose VÀ fructose.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề MH – 2024) Phát biểu nào sau đây đúng?", "o": "A=Dung dịch saccharose có phản ứng tráng bạc;B=Tinh bột và cellulose là đồng phân của nhau;C=Saccharose thuộc loại polysaccharide;D=Glucose là hợp chất hữu cơ tạp chức", "a": "D", "e": "Glucose chứa nhiều –OH và nhóm CHO => tạp chức. A sai (không có –OH hemiacetal tự do); B sai (n khác nhau); C sai (disaccharide).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề MH – 2023) Chất X được tạo thành trong cây xanh nhờ quang hợp. Thủy phân hoàn toàn X (xúc tác acid) thu được chất Y (đường nho). Hai chất X và Y lần lượt là", "o": "A=tinh bột và glucose;B=cellulose và saccharose;C=cellulose và fructose;D=tinh bột và saccharose", "a": "A", "e": "Tinh bột tạo trong quang hợp, thủy phân cho glucose (đường nho).", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Đường mía là loại đường nào sau đây?", "o": "A=Maltose;B=Glucose;C=Fructose;D=Saccharose", "a": "D", "e": "Saccharose còn gọi là đường mía, đường củ cải, đường thốt nốt.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "Để phân biệt saccharose và glucose người ta dùng dung dịch", "o": "A=H2SO4 loãng;B=NaOH;C=AgNO3 trong NH3;D=Na kim loại", "a": "C", "e": "Glucose tráng bạc (tạo Ag), saccharose thì không => dùng thuốc thử Tollens.", "u": "", "tol": ""}, {"k": "m", "ch": "g12c2", "q": "(Đề TNTHPT – 2022) Cho dãy: glucose, fructose, saccharose, cellulose. Số chất trong dãy có khả năng tham gia phản ứng tráng bạc là", "o": "A=4;B=2;C=1;D=3", "a": "B", "e": "Glucose và fructose (chuyển hóa trong base) => 2 chất.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c2", "q": "Ở dạng mạch hở, phân tử glucose có năm nhóm hydroxy và một nhóm aldehyde, với công thức cấu tạo HOCH2[CHOH]4CH=O.", "o": "", "a": "true", "e": "Đúng: 5 nhóm –OH trên 5 carbon liên tiếp + 1 nhóm CHO => polyalcohol-aldehyde.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c2", "q": "Nhóm –OH ở vị trí carbon số 6 trong glucose dạng mạch vòng gọi là –OH hemiacetal.", "o": "", "a": "false", "e": "Sai: –OH hemiacetal ở vị trí C1 (α, β phân biệt nhau ở vị trí này).", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c2", "q": "Saccharose là một polysaccharide có công thức phân tử là C12H22O11.", "o": "", "a": "false", "e": "Sai: C₁₂H₂₂O₁₁ là disaccharide (thủy phân cho 2 monosaccharide).", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c2", "q": "Cellulose và tinh bột là đồng phân cấu tạo của nhau vì có cùng công thức phân tử (C6H10O5)n.", "o": "", "a": "false", "e": "Sai: polymers khác nhau, n khác nhau => không phải đồng phân.", "u": "", "tol": ""}, {"k": "tf", "ch": "g12c2", "q": "Phân tử amylopectin gồm các chuỗi α-glucose liên kết bằng α-1,4-glycoside và α-1,6-glycoside tạo thành mạch phân nhánh.", "o": "", "a": "true", "e": "Đúng: amylopectin phân nhánh nhờ liên kết α-1,6 ở chỗ phân nhánh (amylose thì chỉ α-1,4, không nhánh).", "u": "", "tol": ""}, {"k": "n", "ch": "g12c2", "q": "Cho 6 carbohydrate: glucose, fructose, maltose, saccharose, tinh bột và cellulose. Có bao nhiêu carbohydrate thuộc nhóm monosaccharide?", "o": "", "a": "2", "e": "Glucose và fructose là monosaccharide; maltose, saccharose là disaccharide; tinh bột, cellulose là polysaccharide.", "u": "", "tol": ""}, {"k": "n", "ch": "g12c2", "q": "(Đề THPT QG - 2019) Đun nóng 100 mL dung dịch glucose a mol/L với lượng dư dung dịch AgNO3 trong NH3. Sau khi phản ứng hoàn toàn thu được 21,6 gam kết tủa. Tính giá trị của a?", "o": "", "a": "1", "e": "n(Ag) = 21,6/108 = 0,2 mol → n(glucose) = 0,1 mol (1 glucose → 2 Ag). a = 0,1/0,1 = 1 mol/L.", "u": "mol/L", "tol": "0.01"}, {"k": "n", "ch": "g12c2", "q": "(Đề MH - 2020) Thủy phân 68,4 gam saccharose với hiệu suất 75%, thu được m gam glucose. Giá trị của m là bao nhiêu?", "o": "", "a": "27", "e": "n(saccharose) = 68,4/342 = 0,2 mol; n(thực) = 0,2 × 75% = 0,15 mol → m(glucose) = 0,15 × 180 = 27 gam.", "u": "g", "tol": "0.1"}], "g12c3": [{"k": "m", "ch": "g12c3", "q": "Chất nào sau đây là amine bậc hai?", "o": "A=CH3CH(NH2)CH3;B=(C2H5)2NH;C=(C2H5)3N;D=C2H5NH2", "a": "B", "e": "Amine bậc 2 có 2 gốc hydrocarbon gắn vào N, có dạng R-NH-R'. (C2H5)2NH là diethylamine bậc 2."}, {"k": "m", "ch": "g12c3", "q": "Dung dịch chất nào sau đây KHÔNG làm đổi màu quỳ tím?", "o": "A=Methylamine;B=Ethylamine;C=Aniline;D=Dimethylamine", "a": "C", "e": "Aniline (C6H5NH2) có tính base rất yếu do gốc phenyl hút electron, không làm đổi màu quỳ tím và phenolphthalein."}, {"k": "m", "ch": "g12c3", "q": "Khi nhỏ dung dịch nước bromine vào ống nghiệm chứa dung dịch aniline, hiện tượng quan sát được là", "o": "A=Có sủi bọt khí;B=Xuất hiện kết tủa màu trắng;C=Xuất hiện kết tủa màu vàng;D=Dung dịch chuyển sang màu xanh lam", "a": "B", "e": "Aniline phản ứng thế dễ dàng với nước Br2 tạo kết tủa trắng 2,4,6-tribromoaniline."}, {"k": "m", "ch": "g12c3", "q": "Số đồng phân amine có cùng công thức phân tử C3H9N là", "o": "A=2;B=3;C=4;D=5", "a": "C", "e": "C3H9N có 4 đồng phân: 2 bậc 1 (propan-1-amine, propan-2-amine), 1 bậc 2 (ethylmethylamine), 1 bậc 3 (trimethylamine)."}, {"k": "m", "ch": "g12c3", "q": "Chất nào sau đây ở thể khí ở điều kiện thường?", "o": "A=Aniline;B=Methylamine;C=Benzylamine;D=Hexan-1-amine", "a": "B", "e": "4 amine ở thể khí ở điều kiện thường: methylamine, dimethylamine, trimethylamine và ethylamine."}, {"k": "m", "ch": "g12c3", "q": "Để khử mùi tanh của cá (chủ yếu do trimethylamine gây ra), trong nấu ăn người ta thường dùng", "o": "A=Nước vôi trong;B=Giấm ăn hoặc chanh;C=Dung dịch muối ăn NaCl;D=Dung dịch baking soda", "a": "B", "e": "Giấm ăn (chứa CH3COOH) hoặc chanh (chứa citric acid) tác dụng với trimethylamine tạo muối không bay hơi, làm mất mùi tanh."}, {"k": "tf", "ch": "g12c3", "q": "Cho các phát biểu về amine:\nAniline tác dụng với nước bromine tạo kết tủa màu trắng", "a": "true", "e": "Đúng. Tạo kết tủa trắng 2,4,6-tribromoaniline."}, {"k": "tf", "ch": "g12c3", "q": "Cho các phát biểu về amine:\nBậc của amine (CH3)3C-NH2 là bậc ba", "a": "false", "e": "Sai. Đây là amine bậc một vì chỉ có 1 gốc hydrocarbon gắn vào N (dù gốc đó có C bậc ba)."}, {"k": "tf", "ch": "g12c3", "q": "Cho các phát biểu về amine:\nLực base của methylamine mạnh hơn ammonia (NH3)", "a": "true", "e": "Đúng. Nhóm methyl đẩy e làm tăng mật độ e trên N -> tăng lực base."}, {"k": "n", "ch": "g12c3", "q": "Ứng với công thức phân tử C4H11N có bao nhiêu đồng phân amine bậc một?", "a": "4", "e": "Có 4 đồng phân bậc 1: butan-1-amine, butan-2-amine, 2-methylpropan-1-amine, 2-methylpropan-2-amine.", "u": "đồng phân", "tol": "0"}]}, "tests": [{"id": "g12t1", "ch": "g12c1", "title": "Đề ôn tập chương 1 · số 1", "timeMin": 30, "qs": [{"k": "m", "q": "(Đề MH – 2023) Công thức của ethyl acetate là", "o": "A=CH3COOCH3;B=CH3COOC2H5;C=HCOOCH3;D=HCOOC2H5", "a": "B", "e": "ethyl => -C2H5, acetate => CH3COO- nên CH3COOC2H5."}, {"k": "m", "q": "(Đề THPT QG – 2016) Chất X có công thức cấu tạo CH3CH2COOCH3. Tên gọi của X là", "o": "A=propyl acetate;B=methyl propionate;C=methyl acetate;D=ethyl acetate", "a": "B", "e": "Gốc acid C2H5COO- (propionate) + gốc -OCH3 (methyl) nên là methyl propionate."}, {"k": "m", "q": "(SGK – Cánh Diều) Cho các ester: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4). Thứ tự tăng dần độ tan trong nước là", "o": "A=(1);(2);(3);(4);B=(3);(1);(2);(4);C=(2);(4);(1);(3);D=(2);(1);(3);(4)", "a": "C", "e": "Độ tan giảm khi M tăng; M(2) = 116 > M(4) = 102 > M(1) = 88 > M(3) = 74 nên thứ tự tăng dần là (2);(4);(1);(3)."}, {"k": "m", "q": "(Đề TN THPT QG – 2022) Thủy phân ester nào sau đây trong dung dịch NaOH thu được sodium formate?", "o": "A=CH3COOCH3;B=CH3COOC2H5;C=HCOOC2H5;D=CH3COOC3H7", "a": "C", "e": "Sodium formate là HCOONa nên ester phải có gốc HCOO-; chỉ HCOOC2H5 thỏa mãn."}, {"k": "m", "q": "(Đề MH lần I – 2017) Thủy phân ester X (C4H6O2) trong môi trường acid, thu được aldehyde. Công thức của X là", "o": "A=CH3COOCH3;B=CH3COOCH=CH2;C=CH2=CHCOOCH3;D=HCOOCH2CH=CH2", "a": "B", "e": "Ester cho aldehyde phải có gốc alcohol dạng vinyl; CH3COOCH=CH2 + H2O -> CH3COOH + CH3CHO."}, {"k": "m", "q": "(Đề TN THPT QG – 2021) Ester X được tạo bởi ethyl alcohol và acetic acid. Công thức của X là", "o": "A=CH3COOCH3;B=HCOOC2H5;C=HCOOCH3;D=CH3COOC2H5", "a": "D", "e": "CH3COOH + C2H5OH -> CH3COOC2H5 + H2O (H2SO4 đặc, t°)."}, {"k": "m", "q": "(Đề MH – 2023) Xà phòng hóa ester X có CTPT C4H8O2 bằng NaOH dư thu được muối Y và alcohol Z bậc II. Công thức cấu tạo thu gọn của X là", "o": "A=HCOOCH(CH3)2;B=CH3CH2COOCH3;C=CH3COOC2H5;D=HCOOCH2CH2CH3", "a": "A", "e": "Alcohol bậc II duy nhất phù hợp là (CH3)2CHOH; phần acid còn lại là HCOO- nên X = HCOOCH(CH3)2."}, {"k": "m", "q": "(SBT Hóa học 12 NC) Để phân biệt các chất lỏng acetic acid, glycerol, triolein, có thể chỉ cần dùng", "o": "A=nước và quỳ tím;B=nước và dung dịch NaOH;C=dung dịch NaOH;D=nước brom", "a": "A", "e": "Thêm nước: triolein không tan; quỳ tím nhận acetic acid (hóa đỏ), glycerol không đổi màu."}, {"k": "m", "q": "(Đề MH – 2022) Palmitic acid là acid béo có trong mỡ động vật và dầu cọ. Công thức của palmitic acid là", "o": "A=C3H5(OH)3;B=CH3COOH;C=C15H31COOH;D=C17H35COOH", "a": "C", "e": "Palmitic acid có 16 C no nên công thức là C15H31COOH (M = 256)."}, {"k": "m", "q": "Chất nào sau đây có trạng thái lỏng ở điều kiện thường?", "o": "A=(C17H33COO)3C3H5;B=(C17H35COO)3C3H5;C=C6H5OH (phenol);D=(C15H31COO)3C3H5", "a": "A", "e": "Triolein có gốc acid không no nên lỏng; tristearin, tripalmitin no và phenol đều rắn."}, {"k": "m", "q": "(Đề TN THPT QG – 2022) Đun nóng triglyceride trong dung dịch NaOH dư đến phản ứng hoàn toàn luôn thu được chất nào sau đây?", "o": "A=Glycerol;B=Ethylene glycol;C=Ethanol;D=Methanol", "a": "A", "e": "Mọi triglyceride đều là triester của glycerol nên luôn thu được glycerol."}, {"k": "m", "q": "Triolein tác dụng với H2 dư (Ni, t°) thu được chất X. Thủy phân triolein thu được alcohol Y. X và Y lần lượt là", "o": "A=tripalmitin và ethylene glycol;B=tripalmitin và glycerol;C=tristearin và ethylene glycol;D=tristearin và glycerol", "a": "D", "e": "Cộng H2 chỉ no hóa C=C giữ nguyên số C (C17H33 -> C17H35) nên X là tristearin; alcohol luôn là glycerol."}, {"k": "m", "q": "(SBT Hóa học 12 CB) Xà phòng và chất giặt rửa có điểm chung là", "o": "A=chứa muối sodium có khả năng làm giảm sức căng bề mặt của các chất bẩn;B=các muối được lấy từ phản ứng xà phòng hóa chất béo;C=sản phẩm của công nghệ hóa dầu;D=có nguồn gốc từ động vật hoặc thực vật", "a": "A", "e": "Cả hai đều có đầu ưa nước - đuôi kị nước giúp làm giảm sức căng bề mặt, nhũ hóa vết bẩn."}, {"k": "m", "q": "(Đề TSĐH B – 2010) Hợp chất hữu cơ mạch hở X có CTPT C6H10O4. Thủy phân X tạo ra hai alcohol đơn chức có số C trong phân tử gấp đôi nhau. Công thức của X là", "o": "A=CH3OCO-CH2-COOC2H5;B=C2H5OCO-COOCH3;C=CH3OCO-COOC3H7;D=CH3OCO-CH2-CH2-COOC2H5", "a": "A", "e": "Hai alcohol là CH3OH (1C) và C2H5OH (2C); gốc acid 2 chức còn 3 C là -OCO-CH2-CO- nên X = CH3OCO-CH2-COOC2H5."}, {"k": "m", "q": "(Đề MH – 2018) Phát biểu nào sau đây sai?", "o": "A=Ethyl formate có phản ứng tráng bạc;B=Thủy phân ethyl acetate thu được methyl alcohol;C=Triolein phản ứng được với nước bromine;D=Ở điều kiện thường tristearin là chất rắn", "a": "B", "e": "Ethyl acetate CH3COOC2H5 thủy phân cho ethyl alcohol C2H5OH, không phải methyl alcohol."}, {"k": "m", "q": "(SBT Hóa học 12 NC) Cho các phát biểu: (a) Chất béo là triester của glycerol với monocarboxylic acid có số chẵn C (12-24), mạch dài không phân nhánh; (b) Lipid gồm chất béo, sáp, steroid, phospholipid; (c) Chất béo là các chất lỏng; (d) Chất béo chứa chủ yếu gốc không no thường là chất lỏng, gọi là dầu; (e) Thủy phân chất béo trong kiềm là phản ứng thuận nghịch; (f) Chất béo là thành phần chính của dầu, mỡ. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "C", "e": "(a), (b), (d), (f) đúng; (c) sai vì chất béo có thể rắn; (e) sai vì xà phòng hóa là một chiều."}, {"k": "m", "q": "(Đề THPT QG – 2017) Thủy phân hoàn toàn m gam chất béo bằng dung dịch NaOH, đun nóng, thu được 9,2 gam glycerol và 91,8 gam muối. Giá trị của m là", "o": "A=89;B=101;C=85;D=93", "a": "A", "e": "n(glycerol) = 0,1 => n(NaOH) = 0,3; m = 91,8 + 9,2 - 0,3 x 40 = 89 gam."}, {"k": "m", "q": "(Đề THPT QG – 2023) Cho 8,8 gam ester X đơn chức phản ứng hoàn toàn với dung dịch NaOH, thu được 3,2 gam CH3OH. Tên của X là", "o": "A=ethyl acetate;B=methyl acetate;C=propyl formate;D=methyl propionate", "a": "D", "e": "n(CH3OH) = 0,1 mol = n(X) nên M(X) = 88; gốc -OCH3 và M muối 96 => C2H5COOCH3 (methyl propionate)."}, {"k": "tf", "q": "(SGK – CTST) Methyl methacrylate dùng điều chế poly(methyl methacrylate) trong răng giả, kính áp tròng, xi măng sinh học.\na. Công thức cấu tạo của methyl methacrylate là CH2=C(CH3)COOCH3.", "o": "", "a": "true", "e": "Đúng công thức cấu tạo."}, {"k": "tf", "q": "(SGK – CTST) Methyl methacrylate dùng điều chế poly(methyl methacrylate) trong răng giả, kính áp tròng, xi măng sinh học.\nb. Methyl methacrylate được điều chế từ methacrylic acid và ethyl alcohol.", "o": "", "a": "false", "e": "Phải điều chế từ methyl alcohol (CH3OH); dùng ethyl alcohol sẽ được ethyl methacrylate."}, {"k": "tf", "q": "(SGK – CTST) Methyl methacrylate dùng điều chế poly(methyl methacrylate) trong răng giả, kính áp tròng, xi măng sinh học.\nc. Thủy phân hoàn toàn methyl methacrylate trong NaOH thu được 1 muối và 1 aldehyde.", "o": "", "a": "false", "e": "Thu được 1 muối CH2=C(CH3)COONa và 1 alcohol CH3OH, không phải aldehyde."}, {"k": "tf", "q": "(SGK – CTST) Methyl methacrylate dùng điều chế poly(methyl methacrylate) trong răng giả, kính áp tròng, xi măng sinh học.\nd. 1 mol methyl methacrylate tác dụng tối đa với 1 mol Br2.", "o": "", "a": "true", "e": "Chỉ 1 liên kết C=C cộng Br2; nhóm C=O của ester không cộng Br2."}, {"k": "tf", "q": "(TSCĐ – 2013) Xà phòng hóa triglyceride X bằng NaOH dư thu được glycerol, sodium oleate, sodium stearate và sodium palmitate.\na. Phản ứng trên gọi là phản ứng xà phòng hóa.", "o": "", "a": "true", "e": "Thủy phân chất béo trong môi trường kiềm là phản ứng xà phòng hóa."}, {"k": "tf", "q": "(TSCĐ – 2013) Xà phòng hóa triglyceride X bằng NaOH dư thu được glycerol, sodium oleate, sodium stearate và sodium palmitate.\nb. 1 mol X phản ứng tối đa với 3 mol NaOH.", "o": "", "a": "true", "e": "X là triester của glycerol nên tỉ lệ mol 1:3."}, {"k": "tf", "q": "(TSCĐ – 2013) Xà phòng hóa triglyceride X bằng NaOH dư thu được glycerol, sodium oleate, sodium stearate và sodium palmitate.\nc. Có ba đồng phân thỏa mãn tính chất của X.", "o": "", "a": "true", "e": "Ba gốc acid khác nhau gắn vào glycerol; cố định gốc ở vị trí giữa nên có 3 đồng phân cấu tạo."}, {"k": "tf", "q": "(TSCĐ – 2013) Xà phòng hóa triglyceride X bằng NaOH dư thu được glycerol, sodium oleate, sodium stearate và sodium palmitate.\nd. Phân tử X có 5 liên kết pi.", "o": "", "a": "false", "e": "3 pi của ba C=O + 1 pi của C=C trong gốc oleate = 4 pi (stearate và palmitate đều no), không phải 5."}, {"k": "tf", "q": "(SGK – KNTT) Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL NaCl bão hòa, khuấy nhẹ, để nguội.\na. Sau bước 2 thấy có lớp chất rắn màu trắng nổi lên là glycerol.", "o": "", "a": "false", "e": "Lớp chất rắn trắng là xà phòng (muối sodium của acid béo); glycerol tan trong nước nằm ở lớp dưới."}, {"k": "tf", "q": "(SGK – KNTT) Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL NaCl bão hòa, khuấy nhẹ, để nguội.\nb. Vai trò của dung dịch NaCl bão hòa là để tách muối sodium của acid béo ra khỏi hỗn hợp.", "o": "", "a": "true", "e": "NaCl bão hòa làm giảm độ tan của muối acid béo nên xà phòng tách ra và nổi lên."}, {"k": "tf", "q": "(SGK – KNTT) Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL NaCl bão hòa, khuấy nhẹ, để nguội.\nc. Ở bước 1, nếu không thêm nước cất, hỗn hợp bị cạn khô thì phản ứng thủy phân không xảy ra.", "o": "", "a": "true", "e": "Phản ứng thủy phân cần môi trường nước nên cạn khô thì không xảy ra."}, {"k": "tf", "q": "(SGK – KNTT) Bước 1: cho 2 gam chất béo và 4 mL dung dịch NaCl 40% vào bát sứ, đun 10 phút khuấy liên tục. Bước 2: đổ hỗn hợp vào 30 mL NaCl bão hòa, khuấy nhẹ, để nguội.\nd. Ở bước 1, nếu thay mỡ lợn bằng dầu dừa thì hiện tượng thí nghiệm sau bước 2 vẫn xảy ra tương tự.", "o": "", "a": "true", "e": "Dầu dừa cũng là chất béo (triester của glycerol) nên vẫn bị xà phòng hóa."}, {"k": "tf", "q": "(SGK – CTST) Isopropyl formate là một ester có trong cà phê Arabica.\na. Công thức của isopropyl formate là HCOOCH(CH3)2.", "o": "", "a": "true", "e": "Gốc isopropyl -CH(CH3)2 ghép với gốc formate HCOO-."}, {"k": "tf", "q": "(SGK – CTST) Isopropyl formate là một ester có trong cà phê Arabica.\nb. Isopropyl formate là ester không no (có 1 C=C), đơn chức, mạch hở.", "o": "", "a": "false", "e": "Isopropyl formate C4H8O2 là ester no, không có liên kết C=C."}, {"k": "tf", "q": "(SGK – CTST) Isopropyl formate là một ester có trong cà phê Arabica.\nc. Phần trăm khối lượng oxygen trong isopropyl formate là 37,5%.", "o": "", "a": "false", "e": "M = 88 nên %O = 32/88 = 36,36%, không phải 37,5%."}, {"k": "tf", "q": "(SGK – CTST) Isopropyl formate là một ester có trong cà phê Arabica.\nd. Isopropyl formate được điều chế từ propyl alcohol và formic acid.", "o": "", "a": "false", "e": "Phải điều chế từ isopropyl alcohol (propan-2-ol); propyl alcohol sẽ cho propyl formate."}, {"k": "n", "q": "Cho các chất: CH3[CH2]10CH2OSO3Na; CH3[CH2]14COONa; CH3[CH2]11-C6H4-SO3Na; CH3CH2COONa; CH3[CH2]16COOK. Số chất có thể là thành phần chính của xà phòng là bao nhiêu?", "o": "", "a": "2", "u": "", "tol": "", "e": "Xà phòng là muối Na/K của acid béo: CH3[CH2]14COONa và CH3[CH2]16COOK."}, {"k": "n", "q": "(SBT Hóa học 12 NC) Từ các alcohol C3H8O và các acid C4H8O2 có thể tạo ra bao nhiêu ester là đồng phân cấu tạo của nhau?", "o": "", "a": "4", "u": "", "tol": "", "e": "Alcohol có 2 đồng phân, acid có 2 đồng phân => 2 x 2 = 4 ester, đều có CTPT C7H14O2."}, {"k": "n", "q": "Ester X có CTPT C9H10O2 (chứa vòng benzene). X tác dụng với NaOH dư thu được C2H5COONa và chất hữu cơ Y. Xác định phân tử khối của Y?", "o": "", "a": "116", "u": "", "tol": "", "e": "X = C2H5COOC6H5 (ester của phenol); X + 2NaOH -> C2H5COONa + C6H5ONa + H2O; Y = C6H5ONa có M = 116."}, {"k": "n", "q": "Khi xà phòng hóa 1 mol triglyceride X bằng NaOH dư, đun nóng, thu được glycerol, 2 mol sodium oleate và 1 mol sodium palmitate. Hydrogen hóa hoàn toàn 1 mol X cần tối đa a mol H2 (Ni, t°). Tính a?", "o": "", "a": "2", "u": "", "tol": "", "e": "X có 2 gốc oleate, mỗi gốc 1 C=C nên 1 mol X cần 2 mol H2."}, {"k": "n", "q": "(SGK – KNTT) Isoamyl acetate (dầu chuối) được điều chế từ 16,2 gam acetic acid và 15,2 gam isoamyl alcohol với H2SO4 đặc; thu được 14,16 gam dầu chuối. Tính hiệu suất phản ứng?", "o": "", "a": "63,06", "u": "%", "tol": "0.1", "e": "n(alcohol) = 15,2/88 = 0,1727 mol (chất hết); n(ester) = 14,16/130 = 0,1089 mol; H = 0,1089/0,1727 = 63,06%."}, {"k": "n", "q": "Đun sôi a gam một triglyceride X với dung dịch KOH đến phản ứng hoàn toàn, thu được 0,92 gam glycerol và 9,58 gam hỗn hợp muối của linoleic acid và oleic acid. Tính giá trị của a?", "o": "", "a": "8,82", "u": "g", "tol": "0.1", "e": "n(glycerol) = 0,01 => n(KOH) = 0,03; a = 9,58 + 0,92 - 0,03 x 56 = 8,82 gam."}], "grade": "g12"}, {"id": "g12t2", "ch": "g12c1", "title": "Đề ôn tập chương 1 · số 2", "timeMin": 30, "qs": [{"k": "m", "q": "CTPT của ester X mạch hở là C4H6O2. X thuộc loại ester", "o": "A=no, đa chức;B=không no, đơn chức;C=no, đơn chức;D=không no, có một nối đôi C=C, đơn chức", "a": "D", "e": "k = (2.4 + 2 - 6)/2 = 2; đơn chức có 1 pi của C=O nên còn 1 pi là C=C; X không no, 1 C=C, đơn chức."}, {"k": "m", "q": "(Đề TN THPT QG – 2020) Tên gọi của ester CH3COOC2H5 là", "o": "A=ethyl formate;B=ethyl acetate;C=methyl acetate;D=methyl formate", "a": "B", "e": "CH3COO- là acetate, -OC2H5 là ethyl nên tên ethyl acetate."}, {"k": "m", "q": "(SGK – Cánh Diều) Cho các chất mạch không phân nhánh: C4H9OH (1), C3H7COOH (2), CH3COOC2H5 (3). Thứ tự nhiệt độ sôi tăng dần là", "o": "A=(1);(2);(3);B=(3);(1);(2);C=(2);(3);(1);D=(2);(1);(3)", "a": "B", "e": "Ester không có liên kết hydrogen nên sôi thấp nhất; liên kết hydrogen của acid bền hơn alcohol nên thứ tự ester < alcohol < acid."}, {"k": "m", "q": "(Đề MH – 2021) Thủy phân ester X trong dung dịch NaOH, thu được CH3COONa và C2H5OH. Công thức cấu tạo của X là", "o": "A=C2H5COOCH3;B=C2H5COOC2H5;C=CH3COOCH3;D=CH3COOC2H5", "a": "D", "e": "Ghép ngược sản phẩm: gốc acid CH3COO- + gốc alcohol -OC2H5 nên X = CH3COOC2H5."}, {"k": "m", "q": "(Đề THPT QG – 2017) Xà phòng hóa CH3COOC2H5 trong dung dịch NaOH đun nóng, thu được muối có công thức là", "o": "A=C2H5ONa;B=C2H5COONa;C=CH3COONa;D=HCOONa", "a": "C", "e": "CH3COOC2H5 + NaOH -> CH3COONa + C2H5OH; muối giữ nguyên gốc acid CH3COO-."}, {"k": "m", "q": "Thủy phân hỗn hợp methyl formate và ethyl formate trong dung dịch H2SO4, thu được sản phẩm gồm", "o": "A=1 muối và 1 alcohol;B=1 muối và 2 alcohol;C=1 acid và 2 alcohol;D=2 acid và 1 alcohol", "a": "C", "e": "Môi trường acid cho acid, không phải muối; hai ester cùng gốc HCOO- cho 1 acid HCOOH và hai gốc alcohol khác nhau cho 2 alcohol."}, {"k": "m", "q": "(Đề TN THPT QG – 2021) Ester X có CTPT C4H8O2. Thủy phân X trong H2SO4 loãng, đun nóng, thu được methyl alcohol và chất hữu cơ Y. Công thức của Y là", "o": "A=C2H5COOH;B=HCOOH;C=C2H5OH;D=CH3COOH", "a": "A", "e": "X = RCOOCH3, M = 88 => R = 29 (C2H5-) nên Y = C2H5COOH."}, {"k": "m", "q": "Dầu thực vật hầu hết là lipid ở trạng thái lỏng do", "o": "A=chứa chủ yếu gốc acid béo no;B=trong phân tử có chứa gốc glycerol;C=chứa chủ yếu gốc acid béo không no;D=chứa acid béo tự do", "a": "C", "e": "Gốc không no cấu hình cis làm mạch gấp khúc, phân tử khó xếp khít nên nóng chảy thấp, thể lỏng."}, {"k": "m", "q": "(Đề TN THPT QG – 2020) Thủy phân tripalmitin ((C15H31COO)3C3H5) trong dung dịch NaOH, thu được muối có công thức là", "o": "A=C15H31COONa;B=C17H33COONa;C=HCOONa;D=CH3COONa", "a": "A", "e": "Gốc acid giữ nguyên nên muối là sodium palmitate C15H31COONa."}, {"k": "m", "q": "Hợp chất nào dưới đây được sử dụng làm xà phòng?", "o": "A=CH3COONa;B=CH3(CH2)14COONa;C=CH3(CH2)12COOCH3;D=CH3(CH2)5O(CH2)5CH3", "a": "B", "e": "Xà phòng là muối Na/K của acid béo mạch dài; CH3(CH2)14COONa = C15H31COONa (16 C)."}, {"k": "m", "q": "(SBT Hóa học 12 CB) Không nên dùng xô, chậu bằng nhôm để đựng quần áo ngâm xà phòng vì", "o": "A=quần áo bị mục nhanh;B=xô chậu nhanh hỏng do trong xà phòng có kiềm;C=quần áo bị bạc màu nhanh;D=quần áo không sạch", "a": "B", "e": "Xà phòng dư kiềm ăn mòn nhôm (2Al + 2NaOH + 2H2O -> 2NaAlO2 + 3H2)."}, {"k": "m", "q": "(SGK Hóa học 12 CB) Cho các phát biểu: (a) Xà phòng là sản phẩm của phản ứng xà phòng hóa chất béo với NaOH hoặc KOH; (b) Muối sodium/potassium của acid hữu cơ là thành phần chính của xà phòng; (c) Đun nóng chất béo với NaOH hoặc KOH ta được xà phòng; (d) Từ dầu mỏ sản xuất được chất giặt rửa tổng hợp. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(a), (c), (d) đúng; (b) sai vì phải là muối của acid BÉO."}, {"k": "m", "q": "(Đề TN THPT QG – 2022) Phát biểu nào sau đây sai?", "o": "A=Ethyl acetate có công thức phân tử là C4H8O2;B=Phân tử methyl methacrylate có 1 liên kết pi;C=Methyl acrylate có khả năng cộng Br2 trong dung dịch;D=Ethyl formate có khả năng tráng bạc", "a": "B", "e": "Methyl methacrylate CH2=C(CH3)COOCH3 có 2 pi (1 C=C + 1 C=O)."}, {"k": "m", "q": "(SBT Hóa học 12 CB) Cho các phát biểu: (a) Chất béo thuộc loại hợp chất ester; (b) Ester không tan trong nước do nhẹ hơn nước; (c) Ester không tan và nổi trên mặt nước do không tạo liên kết hydrogen với nước và nhẹ hơn nước; (d) Đun chất béo lỏng + H2 (xt Ni) chuyển thành chất béo rắn; (e) Chất béo lỏng là triglyceride chứa gốc acid không no. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "C", "e": "(a), (c), (d), (e) đúng; (b) sai vì 'nhẹ hơn nước' chỉ giải thích sự nổi, không phải nguyên nhân không tan."}, {"k": "m", "q": "(Đề THPT QG – 2017) Chất X tác dụng vừa đủ với dung dịch NaOH, thu được hai chất Y và Z. Cho Z tác dụng với AgNO3 trong NH3 thu được chất hữu cơ T. Cho T tác dụng với NaOH lại thu được Y. Chất X là", "o": "A=CH3COOCH=CH2;B=HCOOCH3;C=CH3COOCH=CH-CH3;D=HCOOCH=CH2", "a": "A", "e": "X = CH3COOCH=CH2: Y = CH3COONa, Z = CH3CHO; CH3CHO + AgNO3/NH3 -> CH3COONH4, T + NaOH -> CH3COONa = Y."}, {"k": "m", "q": "(Đề TSĐH B – 2007) X là ester no đơn chức, có tỉ khối hơi so với CH4 là 5,5. Đun 2,2 gam X với NaOH dư thu được 2,05 gam muối. Công thức cấu tạo thu gọn của X là", "o": "A=CH3COOC2H5;B=HCOOCH2CH2CH3;C=C2H5COOCH3;D=HCOOCH(CH3)3", "a": "A", "e": "M(X) = 88 (C4H8O2); n = 0,025 mol; M(muối) = 82 = CH3COONa nên X = CH3COOC2H5."}, {"k": "m", "q": "(Đề THPT QG – 2017) Hydrogen hóa hoàn toàn 17,68 gam triolein cần vừa đủ a mol khí H2. Giá trị của a là", "o": "A=0,03;B=0,02;C=0,06;D=0,04", "a": "C", "e": "n(triolein) = 17,68/884 = 0,02 mol; mỗi phân tử có 3 C=C nên a = 3 x 0,02 = 0,06 mol."}, {"k": "m", "q": "(Đề MH – 2024) Methyl salicylate được điều chế: HOC6H4COOH + CH3OH -> HOC6H4COOCH3 + H2O. Để sản xuất 3,8 triệu tuýp thuốc (mỗi tuýp 2,7 gam methyl salicylate), hiệu suất 75%, cần tối thiểu m tấn salicylic acid. Giá trị của m là", "o": "A=9,315;B=12,420;C=6,986;D=15,068", "a": "B", "e": "m(methyl salicylate) = 10,26 tấn; n = 10,26/152 = 0,0675; n(salicylic acid) = 0,0675/0,75 = 0,09; m = 0,09 x 138 = 12,420 tấn."}, {"k": "tf", "q": "(SGK – KNTT) Cho ba hợp chất butan-1-ol, propanoic acid, methyl acetate và các giá trị nhiệt độ sôi (không theo thứ tự): 57°C; 118°C; 141°C.\na. Nhiệt độ sôi của các chất trên là: butan-1-ol (141), propanoic acid (118), methyl acetate (57).", "o": "", "a": "false", "e": "Gán ngược: propanoic acid 141°C (cao nhất), butan-1-ol 118°C, methyl acetate 57°C."}, {"k": "tf", "q": "(SGK – KNTT) Cho ba hợp chất butan-1-ol, propanoic acid, methyl acetate và các giá trị nhiệt độ sôi (không theo thứ tự): 57°C; 118°C; 141°C.\nb. Nhiệt độ sôi methyl acetate thấp nhất do không có liên kết hydrogen giữa các phân tử.", "o": "", "a": "true", "e": "Ester không tạo liên kết hydrogen nên sôi thấp nhất."}, {"k": "tf", "q": "(SGK – KNTT) Cho ba hợp chất butan-1-ol, propanoic acid, methyl acetate và các giá trị nhiệt độ sôi (không theo thứ tự): 57°C; 118°C; 141°C.\nc. Butan-1-ol có nhiệt độ sôi cao nhất do liên kết hydrogen giữa các phân tử bền hơn của carboxylic acid.", "o": "", "a": "false", "e": "Liên kết hydrogen của carboxylic acid (dạng dimer) bền hơn của alcohol nên acid sôi cao nhất."}, {"k": "tf", "q": "(SGK – KNTT) Cho ba hợp chất butan-1-ol, propanoic acid, methyl acetate và các giá trị nhiệt độ sôi (không theo thứ tự): 57°C; 118°C; 141°C.\nd. Với khối lượng phân tử tương đương, nhiệt độ sôi tăng dần: hydrocarbon < aldehyde/ketone/ester < alcohol < carboxylic acid.", "o": "", "a": "true", "e": "Đúng quy luật về lực liên phân tử."}, {"k": "tf", "q": "(SGK – CTST) Ester bị thủy phân khi đun nóng với dung dịch kiềm như NaOH, KOH (phản ứng xà phòng hóa) và xảy ra một chiều.\na. Phản ứng thủy phân ester trong môi trường base luôn thu được muối của carboxylic acid và alcohol.", "o": "", "a": "false", "e": "Không phải luôn: ester của phenol cho 2 muối; ester của alcohol dạng vinyl cho muối + aldehyde."}, {"k": "tf", "q": "(SGK – CTST) Ester bị thủy phân khi đun nóng với dung dịch kiềm như NaOH, KOH (phản ứng xà phòng hóa) và xảy ra một chiều.\nb. Thủy phân ester methyl propionate trong dung dịch NaOH thu được muối C2H5COONa.", "o": "", "a": "true", "e": "CH3CH2COOCH3 + NaOH -> C2H5COONa + CH3OH."}, {"k": "tf", "q": "(SGK – CTST) Ester bị thủy phân khi đun nóng với dung dịch kiềm như NaOH, KOH (phản ứng xà phòng hóa) và xảy ra một chiều.\nc. Ester CH3COOC6H5 (C6H5- là phenyl) trong dung dịch NaOH thu được một muối và một alcohol.", "o": "", "a": "false", "e": "CH3COOC6H5 + 2NaOH -> CH3COONa + C6H5ONa + H2O, thu được hai muối, không có alcohol."}, {"k": "tf", "q": "(SGK – CTST) Ester bị thủy phân khi đun nóng với dung dịch kiềm như NaOH, KOH (phản ứng xà phòng hóa) và xảy ra một chiều.\nd. Thủy phân ester X trong dung dịch NaOH thu được HCOONa và CH3CHO. Tên gọi của X là vinyl formate.", "o": "", "a": "true", "e": "X = HCOOCH=CH2 (vinyl formate) nên thủy phân cho HCOONa và CH3CHO."}, {"k": "tf", "q": "(SGK – CTST) Chất béo X gồm ba gốc: CH2-O-CO-[CH2]14CH3; CH-O-CO-[CH2]7CH=CH[CH2]7CH3; CH2-O-CO-[CH2]7CH=CH-CH2-CH=CH-[CH2]4CH3.\na. Thủy phân X trong KOH thu được 3 muối: C15H31COOK; C17H33COOK; C17H31COOK.", "o": "", "a": "true", "e": "Các gốc là palmitate (16C, no), oleate (18C, 1 C=C) và linoleate (18C, 2 C=C) nên tạo ba muối tương ứng."}, {"k": "tf", "q": "(SGK – CTST) Chất béo X gồm ba gốc: CH2-O-CO-[CH2]14CH3; CH-O-CO-[CH2]7CH=CH[CH2]7CH3; CH2-O-CO-[CH2]7CH=CH-CH2-CH=CH-[CH2]4CH3.\nb. Số liên kết pi trong X là 3.", "o": "", "a": "false", "e": "3 pi của ba C=O + 3 pi của C=C (1 oleate + 2 linoleate) = 6 pi, không phải 3."}, {"k": "tf", "q": "(SGK – CTST) Chất béo X gồm ba gốc: CH2-O-CO-[CH2]14CH3; CH-O-CO-[CH2]7CH=CH[CH2]7CH3; CH2-O-CO-[CH2]7CH=CH-CH2-CH=CH-[CH2]4CH3.\nc. Hydrogen hóa 1 mol X cần tối đa 3 mol H2 (Ni, t°).", "o": "", "a": "true", "e": "Tổng số C=C là 3 nên 1 mol X cần 3 mol H2."}, {"k": "tf", "q": "(SGK – CTST) Chất béo X gồm ba gốc: CH2-O-CO-[CH2]14CH3; CH-O-CO-[CH2]7CH=CH[CH2]7CH3; CH2-O-CO-[CH2]7CH=CH-CH2-CH=CH-[CH2]4CH3.\nd. Phần trăm về khối lượng của oxygen trong X là 46%.", "o": "", "a": "false", "e": "M(X) = 856 nên %O = 96/856 = 11,21%, khác xa 46%."}, {"k": "tf", "q": "(SBT Hóa học 12 CB) Cho tristearin vào dung dịch NaOH dư, đun sôi khuấy đều đến khi chất lỏng đồng nhất; để nguội, thêm muối ăn, hỗn hợp tách hai lớp.\na. Lớp chất rắn màu trắng phía trên chứa sodium stearate, lớp chất lỏng dưới chứa glycerol.", "o": "", "a": "true", "e": "Sodium stearate (xà phòng) bị muối kết nổi lên; glycerol tan trong nước ở phía dưới."}, {"k": "tf", "q": "(SBT Hóa học 12 CB) Cho tristearin vào dung dịch NaOH dư, đun sôi khuấy đều đến khi chất lỏng đồng nhất; để nguội, thêm muối ăn, hỗn hợp tách hai lớp.\nb. Vai trò của muối ăn là để tách muối sodium của acid béo ra khỏi hỗn hợp.", "o": "", "a": "true", "e": "Muối bão hòa làm giảm độ tan của muối acid béo nên xà phòng tách ra."}, {"k": "tf", "q": "(SBT Hóa học 12 CB) Cho tristearin vào dung dịch NaOH dư, đun sôi khuấy đều đến khi chất lỏng đồng nhất; để nguội, thêm muối ăn, hỗn hợp tách hai lớp.\nc. Phản ứng ở thí nghiệm trên là phản ứng xà phòng hóa, ứng dụng để sản xuất xà phòng và glycerol.", "o": "", "a": "true", "e": "Đúng, đây là phản ứng xà phòng hóa."}, {"k": "tf", "q": "(SBT Hóa học 12 CB) Cho tristearin vào dung dịch NaOH dư, đun sôi khuấy đều đến khi chất lỏng đồng nhất; để nguội, thêm muối ăn, hỗn hợp tách hai lớp.\nd. Trong thí nghiệm trên, có thể thay cốc thủy tinh bằng cốc nhôm.", "o": "", "a": "false", "e": "NaOH dư ăn mòn nhôm nên không được thay cốc thủy tinh bằng cốc nhôm."}, {"k": "n", "q": "(Đề MH – 2024) Hydrogen hóa hoàn toàn 17,68 gam triolein cần vừa đủ b mol H2. Tính giá trị của b?", "o": "", "a": "0,06", "u": "mol", "tol": "0.001", "e": "n(triolein) = 17,68/884 = 0,02 mol; 3 C=C nên b = 3 x 0,02 = 0,06 mol."}, {"k": "n", "q": "(Đề THPT QG – 2017) Ester X có CTPT C8H8O2. Cho X tác dụng với NaOH, thu được sản phẩm có hai muối. Số công thức cấu tạo của X thỏa mãn là bao nhiêu?", "o": "", "a": "4", "u": "", "tol": "", "e": "X là ester của phenol: HCOOC6H4CH3 (3 vị trí o, m, p) và CH3COOC6H5 (1) = 4 công thức."}, {"k": "n", "q": "Cho sơ đồ phản ứng: Ester X (C4HnO2) ->(+NaOH, t°)-> Y ->(+AgNO3/NH3, t°)-> Z ->(+NaOH, t°)-> C2H3O2Na. Xác định giá trị của n?", "o": "", "a": "6", "u": "", "tol": "", "e": "C2H3O2Na = CH3COONa; Y tráng bạc là CH3CHO nên X = CH3COOCH=CH2 (C4H6O2), vậy n = 6."}, {"k": "n", "q": "Xà phòng hóa hoàn toàn triglyceride X trong NaOH dư thu được glycerol, sodium oleate, sodium stearate và sodium palmitate. Phân tử khối của X là bao nhiêu?", "o": "", "a": "860", "u": "", "tol": "", "e": "X = (C17H33COO)(C17H35COO)(C15H31COO)C3H5; M = 41 + 281 + 283 + 255 = 860."}, {"k": "n", "q": "Thủy phân hoàn toàn m gam chất béo bằng dung dịch NaOH, đun nóng, thu được 9,2 gam glycerol và 91,8 gam muối. Tính giá trị của m?", "o": "", "a": "89", "u": "g", "tol": "1", "e": "m = 91,8 + 9,2 - 0,3 x 40 = 89 gam."}, {"k": "n", "q": "(Đề MH – 2023) Thủy phân hoàn toàn 14,8 gam ester đơn chức X bằng NaOH dư, đun nóng, thu được 16,4 gam muối Y và m gam alcohol Z. Tính giá trị của m?", "o": "", "a": "6,4", "u": "g", "tol": "0.1", "e": "X = CH3COOCH3 (M = 74), n = 0,2 mol; Z = CH3OH nên m = 0,2 x 32 = 6,4 gam."}], "grade": "g12"}, {"id": "g12t3", "ch": "g12c1", "grade": "g12", "title": "Đề BÀI 1 · Ester – Lipid", "timeMin": 30, "qs": [{"k": "m", "q": "(SGK – Cánh Diều) Hợp chất nào dưới đây thuộc loại ester?", "o": "A=HOCH2CH2CHO;B=CH3CH2CH2COOH;C=HOCH2COCH3;D=CH3CH2COOCH3", "a": "D", "e": "D chứa nhóm chức –COO– nối giữa hai gốc hydrocarbon nên là ester. A có nhóm –CHO (aldehyde), B có nhóm –COOH (acid), C có nhóm C=O giữa mạch (ketone)."}, {"k": "m", "q": "Ester no, đơn chức, mạch hở có công thức tổng quát là", "o": "A=CnH2nO2 (n ≥ 2);B=CnH2n-2O2 (n ≥ 2);C=CnH2n+2O2 (n ≥ 2);D=CnH2nO (n ≥ 2)", "a": "A", "e": "Ester no, đơn chức, mạch hở có 1 nhóm –COO– và không còn liên kết π khác nên có độ bất bão hoà k = 1, công thức là CnH2nO2 (n ≥ 2)."}, {"k": "m", "q": "(Đề MH – 2019) Ethyl propionate là ester có mùi thơm của dứa. Công thức của ethyl propionate là", "o": "A=HCOOC2H5;B=C2H5COOC2H5;C=C2H5COOCH3;D=CH3COOCH3", "a": "B", "e": "ethyl ⇒ gốc alcohol –C2H5; propionate ⇒ gốc acid C2H5COO–. Ghép lại: C2H5COOC2H5."}, {"k": "m", "q": "So với các acid, alcohol có cùng số nguyên tử carbon thì ester có nhiệt độ sôi", "o": "A=thấp hơn do khối lượng phân tử của ester nhỏ hơn nhiều;B=thấp hơn do giữa các phân tử ester không tồn tại liên kết hydrogen;C=cao hơn do giữa các phân tử ester có liên kết hydrogen bền vững;D=cao hơn do khối lượng phân tử của ester lớn hơn nhiều", "a": "B", "e": "Phân tử ester không có nguyên tử H linh động nên không tạo được liên kết hydrogen giữa các phân tử, làm lực liên phân tử yếu nên nhiệt độ sôi thấp hơn acid và alcohol tương ứng."}, {"k": "m", "q": "(Đề THPT QG – 2019) Ester nào sau đây tác dụng với NaOH thu được ethyl alcohol?", "o": "A=CH3COOC2H5;B=CH3COOC3H7;C=C2H5COOCH3;D=HCOOCH3", "a": "A", "e": "RCOOR' + NaOH → RCOONa + R'OH. Muốn thu C2H5OH thì ester phải có gốc –OC2H5; chỉ CH3COOC2H5 thoả mãn."}, {"k": "m", "q": "(Đề TSĐH A – 2007) Một ester có công thức phân tử C4H6O2, khi thuỷ phân trong môi trường acid thu được acetaldehyde. Công thức cấu tạo thu gọn của ester đó là", "o": "A=CH2=CHCOOCH3;B=CH3COOCH=CH2;C=HCOOC(CH3)=CH2;D=HCOOCH=CH-CH3", "a": "B", "e": "Gốc alcohol dạng vinyl –O–CH=CH2 khi thuỷ phân tạo ra aldehyde tương ứng. CH3COOCH=CH2 + H2O → CH3COOH + CH3CHO (acetaldehyde)."}, {"k": "m", "q": "(Đề MH – 2021) Thuỷ phân hoàn toàn hỗn hợp ethyl propionate và ethyl formate trong dung dịch NaOH, thu được sản phẩm gồm", "o": "A=1 muối và 1 alcohol;B=2 muối và 2 alcohol;C=1 muối và 2 alcohol;D=2 muối và 1 alcohol", "a": "D", "e": "C2H5COOC2H5 → C2H5COONa + C2H5OH; HCOOC2H5 → HCOONa + C2H5OH. Hai gốc acid khác nhau ⇒ 2 muối, hai gốc alcohol giống nhau (đều ethyl) ⇒ 1 alcohol C2H5OH."}, {"k": "m", "q": "(Đề TN THPT QG – 2021) Ester X có công thức phân tử C4H8O2. Thuỷ phân X trong dung dịch H2SO4 loãng, đun nóng, thu được sản phẩm gồm ethyl alcohol và chất hữu cơ Y. Công thức của Y là", "o": "A=CH3OH;B=CH3COOH;C=C2H5COOH;D=HCOOH", "a": "B", "e": "Thu được C2H5OH ⇒ X có gốc –OC2H5. M(X) = 88 ⇒ R + 44 + 29 = 88 ⇒ R = 15 (CH3–). Vậy X = CH3COOC2H5, thuỷ phân trong acid cho Y = CH3COOH."}, {"k": "m", "q": "(Đề TN THPT QG – 2022) Phát biểu nào sau đây sai?", "o": "A=Ethyl formate có khả năng tham gia phản ứng tráng bạc;B=Phân tử methyl methacrylate có một liên kết π trong phân tử;C=Ethyl acetate có công thức phân tử là C4H8O2;D=Methyl acrylate có khả năng tham gia phản ứng cộng Br2 trong dung dịch", "a": "B", "e": "Methyl methacrylate CH2=C(CH3)COOCH3 có 2 liên kết π (1 của C=C và 1 của C=O), không phải một. Các ý còn lại đều đúng."}, {"k": "m", "q": "(Đề TSCĐ – 2014) Đun nóng 24 gam acetic acid với lượng dư ethyl alcohol (xúc tác H2SO4 đặc), thu được 26,4 gam ester. Hiệu suất của phản ứng ester hoá là", "o": "A=75%;B=55%;C=60%;D=44%", "a": "A", "e": "n(CH3COOH) = 24/60 = 0,4 mol. n(CH3COOC2H5) = 26,4/88 = 0,3 mol. H = 0,3/0,4 × 100% = 75%."}, {"k": "m", "q": "(Đề TSCĐ – 2011) Cho m gam chất hữu cơ đơn chức X tác dụng vừa đủ với 50 gam dung dịch NaOH 8%, sau khi phản ứng hoàn toàn thu được 9,6 gam muối của một acid hữu cơ và 3,2 gam một alcohol. Công thức của X là", "o": "A=CH3COOCH=CH2;B=CH3COOC2H5;C=C2H5COOCH3;D=CH2=CHCOOCH3", "a": "C", "e": "m(NaOH) = 50×8% = 4 gam ⇒ n = 0,1 mol. M alcohol = 3,2/0,1 = 32 (CH3OH); M muối = 9,6/0,1 = 96 (C2H5COONa). Vậy X = C2H5COOCH3."}, {"k": "m", "q": "(Đề THPT QG – 2019) Công thức của triolein là", "o": "A=(C17H33COO)3C3H5;B=(HCOO)3C3H5;C=(C2H5COO)3C3H5;D=(CH3COO)3C3H5", "a": "A", "e": "Triolein là triester của glycerol với oleic acid C17H33COOH nên công thức là (C17H33COO)3C3H5."}, {"k": "m", "q": "Chất béo động vật hầu hết ở thể rắn do chứa", "o": "A=chủ yếu gốc acid béo không no;B=glycerol trong phân tử;C=chủ yếu gốc acid béo no;D=gốc acid béo", "a": "C", "e": "Gốc acid béo no có mạch thẳng, các phân tử xếp khít tạo lực tương tác lớn ⇒ nhiệt độ nóng chảy cao ⇒ thể rắn."}, {"k": "m", "q": "(Đề TN THPT QG – 2020) Thuỷ phân tristearin ((C17H35COO)3C3H5) trong dung dịch NaOH, thu được muối có công thức là", "o": "A=C2H3COONa;B=HCOONa;C=C17H33COONa;D=C17H35COONa", "a": "D", "e": "(C17H35COO)3C3H5 + 3NaOH → 3C17H35COONa + C3H5(OH)3, muối là C17H35COONa."}, {"k": "m", "q": "Cho sơ đồ chuyển hoá: Triolein → E → T → G. Tên gọi của G là", "o": "A=oleic acid;B=linoleic acid;C=stearic acid;D=palmitic acid", "a": "C", "e": "Triolein + H2 dư → tristearin (E); tristearin + NaOH → C17H35COONa (T); T + HCl → C17H35COOH là stearic acid."}, {"k": "m", "q": "(SBT Hoá học 12 CB) Phát biểu nào sau đây không đúng?", "o": "A=Chất béo là triester của glycerol và các monocarboxylic acid có mạch carbon dài, không phân nhánh;B=Chất béo chứa chủ yếu các gốc no của acid thường là chất rắn ở nhiệt độ phòng;C=Chất béo chứa chủ yếu các gốc không no của acid thường là chất lỏng ở nhiệt độ phòng và được gọi là dầu;D=Phản ứng thuỷ phân chất béo trong môi trường kiềm là phản ứng thuận nghịch", "a": "D", "e": "Thuỷ phân chất béo trong môi trường kiềm là phản ứng xà phòng hoá, xảy ra một chiều. Chỉ thuỷ phân trong môi trường acid mới thuận nghịch."}, {"k": "m", "q": "Đun sôi a gam một triglyceride X với dung dịch KOH cho đến khi phản ứng hoàn toàn, thu được 0,92 gam glycerol và 9,58 gam hỗn hợp Y gồm muối của linoleic acid và oleic acid. Giá trị của a là", "o": "A=8,82 gam;B=9,94 gam;C=10,90 gam;D=8,92 gam", "a": "A", "e": "n(glycerol) = 0,92/92 = 0,01 mol ⇒ n(KOH) = 0,03 mol. Bảo toàn khối lượng: a = 9,58 + 0,92 − 0,03×56 = 8,82 gam."}, {"k": "m", "q": "(SGK – KNTT) Cho các phát biểu: (1) Một số ester có mùi thơm nên được dùng làm chất tạo hương trong công nghiệp thực phẩm và mĩ phẩm. (2) Chất béo là triester của glycerol với acid béo. (3) Chất béo tan tốt trong nước. (4) Mỡ động vật, dầu thực vật có thể được dùng làm nguyên liệu để sản xuất xà phòng. (5) Phản ứng thuỷ phân ester trong môi trường acid luôn là phản ứng một chiều. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "B", "e": "Đúng: (1), (2), (4). Sai: (3) chất béo kị nước, không tan trong nước; (5) thuỷ phân ester trong acid là thuận nghịch. Vậy có 3 phát biểu đúng."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Cho các ester có công thức như sau: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\na. Tên gọi của các ester trên là: (1) methyl propionate; (2) ethyl butyrate; (3) methyl acetate; (4) ethyl propionate.", "o": "", "a": "true", "e": "Đúng quy tắc: gốc alcohol + tên gốc acid + ate. (1) mạch C2H5COO– + CH3; (2) CH3CH2CH2COO– + C2H5; (3) CH3COO– + CH3; (4) C2H5COO– + C2H5."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Cho các ester có công thức như sau: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nb. Ester (2) và (4) có mùi dứa chín.", "o": "", "a": "true", "e": "Ethyl butyrate (2) và ethyl propionate (4) đều được dùng làm hương dứa chín."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Cho các ester có công thức như sau: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nc. Độ tan trong nước của các ester giảm dần theo thứ tự: (2) > (1) > (3) > (4).", "o": "", "a": "false", "e": "Độ tan giảm khi phân tử khối tăng: M(3)=74 < M(1)=88 < M(4)=102 < M(2)=116, nên thứ tự giảm dần phải là (3) > (1) > (4) > (2)."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Cho các ester có công thức như sau: C2H5COOCH3 (1); CH3CH2CH2COOC2H5 (2); CH3COOCH3 (3); C2H5COOC2H5 (4).\nd. Các ester tạo liên kết hydrogen với nước nên chúng tan nhiều trong nước hơn hẳn so với các alcohol và carboxylic acid có cùng số nguyên tử carbon hoặc khối lượng phân tử.", "o": "", "a": "false", "e": "Ester không tạo được liên kết hydrogen giữa các phân tử, khả năng tạo liên kết hydrogen với nước yếu ⇒ tan kém hơn hẳn alcohol và acid cùng số C hoặc cùng M."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho vào hai ống nghiệm (1) và (2) mỗi ống khoảng 1,0 mL ethyl acetate. Bước 2: thêm khoảng 2 mL dung dịch H2SO4 20% vào ống (1) và khoảng 2 mL dung dịch NaOH 30% vào ống (2). Bước 3: đun cách thuỷ hai ống trong cốc thuỷ tinh ở 60 – 70 °C.\na. Sau bước 2: Chất lỏng trong cả hai ống nghiệm đồng nhất.", "o": "", "a": "false", "e": "Ester không tan trong nước nên cả hai ống đều tách thành 2 lớp, chất lỏng không đồng nhất."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho vào hai ống nghiệm (1) và (2) mỗi ống khoảng 1,0 mL ethyl acetate. Bước 2: thêm khoảng 2 mL dung dịch H2SO4 20% vào ống (1) và khoảng 2 mL dung dịch NaOH 30% vào ống (2). Bước 3: đun cách thuỷ hai ống trong cốc thuỷ tinh ở 60 – 70 °C.\nb. Sau bước 3: Sản phẩm thu được ở cả ống nghiệm là CH3COOH.", "o": "", "a": "false", "e": "Chỉ ống (1) thuỷ phân trong acid cho CH3COOH; ống (2) trong NaOH cho muối CH3COONa tan tốt nên dung dịch đồng nhất."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho vào hai ống nghiệm (1) và (2) mỗi ống khoảng 1,0 mL ethyl acetate. Bước 2: thêm khoảng 2 mL dung dịch H2SO4 20% vào ống (1) và khoảng 2 mL dung dịch NaOH 30% vào ống (2). Bước 3: đun cách thuỷ hai ống trong cốc thuỷ tinh ở 60 – 70 °C.\nc. Sau bước 3: Ống nghiệm (1) thể tích lớp chất lỏng phía trên giảm. Ống nghiệm (2) tạo thành hỗn hợp đồng nhất.", "o": "", "a": "true", "e": "Ống (1) ester thuỷ phân một phần trong acid nên lớp ester phía trên giảm thể tích. Ống (2) xà phòng hoá một chiều, sản phẩm đều tan ⇒ đồng nhất."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho vào hai ống nghiệm (1) và (2) mỗi ống khoảng 1,0 mL ethyl acetate. Bước 2: thêm khoảng 2 mL dung dịch H2SO4 20% vào ống (1) và khoảng 2 mL dung dịch NaOH 30% vào ống (2). Bước 3: đun cách thuỷ hai ống trong cốc thuỷ tinh ở 60 – 70 °C.\nd. Phản ứng xảy ra ở ống nghiệm (1) là thuận nghịch, ở ống nghiệm (2) là một chiều.", "o": "", "a": "true", "e": "Môi trường acid cho phản ứng thuận nghịch; môi trường kiềm (xà phòng hoá) cho phản ứng một chiều."}, {"k": "tf", "q": "(SGK – Cánh Diều) Cho salicylic acid (hay 2-hydroxybenzoic acid) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3) dùng làm chất giảm đau (có trong miếng dán giảm đau khi vận động hoặc chơi thể thao).\na. Công thức của salicylic acid là o–HO–C6H4–COOH.", "o": "", "a": "true", "e": "Salicylic acid có nhóm –OH phenol ở vị trí ortho (số 2) so với –COOH, công thức o–HO–C6H4–COOH."}, {"k": "tf", "q": "(SGK – Cánh Diều) Cho salicylic acid (hay 2-hydroxybenzoic acid) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3) dùng làm chất giảm đau (có trong miếng dán giảm đau khi vận động hoặc chơi thể thao).\nb. Phản ứng giữa salicylic acid với methyl alcohol có mặt sulfuric acid làm xúc tác là phản ứng thuận nghịch.", "o": "", "a": "true", "e": "Phản ứng ester hoá giữa acid và alcohol có xúc tác H2SO4 đặc luôn thuận nghịch."}, {"k": "tf", "q": "(SGK – Cánh Diều) Cho salicylic acid (hay 2-hydroxybenzoic acid) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3) dùng làm chất giảm đau (có trong miếng dán giảm đau khi vận động hoặc chơi thể thao).\nc. 1 mol methyl salicylate tác dụng với Na dư thu được 1 mol khí H2.", "o": "", "a": "false", "e": "Methyl salicylate HO–C6H4–COOCH3 chỉ còn 1 nhóm –OH phenol ⇒ 1 mol chất này + Na dư giải phóng 0,5 mol H2."}, {"k": "tf", "q": "(SGK – Cánh Diều) Cho salicylic acid (hay 2-hydroxybenzoic acid) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salicylate (C8H8O3) dùng làm chất giảm đau (có trong miếng dán giảm đau khi vận động hoặc chơi thể thao).\nd. 1 mol methyl salicylate tác dụng tối đa với 1 mol NaOH.", "o": "", "a": "false", "e": "Methyl salicylate tác dụng tối đa với 2 mol NaOH: 1 mol thuỷ phân nhóm ester –COOCH3 và 1 mol phản ứng với nhóm –OH phenol."}, {"k": "tf", "q": "(Đề TN THPT QG – 2023) Thuỷ phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\na. X là triolein có công thức (C17H33COO)3C3H5.", "o": "", "a": "true", "e": "Chỉ thu được một muối C17H33COONa ⇒ ba gốc acid giống nhau ⇒ X là triolein (C17H33COO)3C3H5."}, {"k": "tf", "q": "(Đề TN THPT QG – 2023) Thuỷ phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nb. 1 mol X tác dụng với NaOH dư thu được 3 mol C17H33COONa.", "o": "", "a": "true", "e": "1 mol X + 3 mol NaOH → 3 mol C17H33COONa + 1 mol glycerol."}, {"k": "tf", "q": "(Đề TN THPT QG – 2023) Thuỷ phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nc. X là chất béo no ở trạng thái rắn (điều kiện thường).", "o": "", "a": "false", "e": "Gốc oleate C17H33COO– chứa 1 liên kết C=C ⇒ X là chất béo không no, ở thể lỏng trong điều kiện thường."}, {"k": "tf", "q": "(Đề TN THPT QG – 2023) Thuỷ phân hoàn toàn triglyceride X trong dung dịch NaOH thu được C17H33COONa và C3H5(OH)3.\nd. 1 mol X tác dụng tối đa với 3 mol H2 (Ni, to) thu được Y. Y tác dụng với NaOH dư thu được muối C17H33COOH.", "o": "", "a": "false", "e": "X + 3H2 → Y là tristearin (các gốc đều no C17H35COO–). Y + NaOH dư cho muối C17H35COONa, không phải acid C17H33COOH."}, {"k": "n", "q": "Cho các ester sau: HCOOCH3; CH3COOCH3; (COOCH3)2; (HCOO)2C2H4; CH2=CHCOOCH3; C2H5COOC2H5; CH3COOC6H5. Có bao nhiêu ester no, đơn chức, mạch hở?", "o": "", "a": "3", "u": "", "tol": "", "e": "Loại (COOCH3)2 và (HCOO)2C2H4 (hai chức), CH2=CHCOOCH3 (không no), CH3COOC6H5 (chứa vòng benzene). Còn lại HCOOCH3; CH3COOCH3; C2H5COOC2H5 ⇒ 3 chất."}, {"k": "n", "q": "(Đề TSCĐ – 2007) Số hợp chất đơn chức, đồng phân cấu tạo của nhau có cùng công thức phân tử C4H8O2, đều tác dụng với dung dịch NaOH là bao nhiêu?", "o": "", "a": "6", "u": "", "tol": "", "e": "C4H8O2 có k = 1; đơn chức tác dụng NaOH gồm ester và acid: 4 ester (HCOOCH2CH2CH3; HCOOCH(CH3)2; CH3COOC2H5; C2H5COOCH3) và 2 acid (CH3CH2CH2COOH; (CH3)2CHCOOH) ⇒ 6 chất."}, {"k": "n", "q": "(Đề THPT QG – 2017) Cho a mol ester X (C9H10O2) tác dụng vừa đủ với 2a mol NaOH, thu được dung dịch không có phản ứng tráng bạc. Có bao nhiêu công thức cấu tạo phù hợp với tính chất của X?", "o": "", "a": "4", "u": "", "tol": "", "e": "n(X) : n(NaOH) = 1 : 2 ⇒ X là ester của phenol (RCOOC6H4R'). Không tráng bạc ⇒ loại gốc HCOO–. Trường hợp CH3COOC6H4CH3 có 3 vị trí o, m, p và C2H5COOC6H5 ⇒ tổng 4 công thức."}, {"k": "n", "q": "Hydrogen hoá hoàn toàn triolein thu được chất hữu cơ Y. Thuỷ phân hoàn toàn Y bằng dung dịch NaOH, đun nóng thu được glycerol và chất hữu cơ Z. Tính phần trăm khối lượng oxygen trong Z?", "o": "", "a": "10,46", "u": "%", "tol": "0.1", "e": "Triolein + 3H2 → tristearin (Y); Y + 3NaOH → glycerol + 3C17H35COONa (Z). M(Z) = 17×12 + 35 + 12 + 32 + 23 = 306; %O = 32/306 ≈ 10,46%."}, {"k": "n", "q": "(Đề MH – 2020) Hỗn hợp X gồm hai ester có cùng công thức phân tử C8H8O2 và đều chứa vòng benzene. Để phản ứng hết với 0,25 mol X cần tối đa 0,35 mol NaOH trong dung dịch, thu được m gam hỗn hợp hai muối. Tính giá trị của m?", "o": "", "a": "30", "u": "g", "tol": "0.1", "e": "Gọi x là mol ester thường (dùng 1 NaOH), y là mol ester của phenol (dùng 2 NaOH): x + y = 0,25; x + 2y = 0,35 ⇒ y = 0,1; x = 0,15. Đúng hai muối ⇒ HCOOCH2C6H5 và HCOOC6H4CH3. m = 0,25×68 (HCOONa) + 0,1×130 (CH3C6H4ONa) = 30,0 gam."}, {"k": "n", "q": "Hydrogen hoá hoàn toàn 0,1 mol triglyceride X cần dùng 0,3 mol H2 (Ni, to) thu được chất hữu cơ Y. Đun nóng Y với dung dịch NaOH vừa đủ, thu được hỗn hợp muối gồm sodium stearate và 27,8 gam sodium palmitate. Số nguyên tử hydrogen (H) trong X là bao nhiêu?", "o": "", "a": "100", "u": "", "tol": "", "e": "n(C15H31COONa) = 27,8/278 = 0,1 mol ⇒ Y có 1 gốc palmitate và 2 gốc stearate ⇒ Y = C55H106O6. X cộng 3 H2 (mất 6 H) ⇒ X = C55H100O6, số H là 100."}]}, {"id": "g12t4", "ch": "g12c1", "grade": "g12", "title": "Đề BÀI 2 · Xà phòng và chất giặt rửa", "timeMin": 30, "qs": [{"k": "m", "q": "Thành phần chính của chất giặt rửa tổng hợp là", "o": "A=C15H31COONa;B=(C17H35COO)2Ca;C=CH3[CH2]11-C6H4-SO3Na;D=C17H35COOK", "a": "C", "e": "Chất giặt rửa tổng hợp là muối alkylsulfate (R–OSO3Na) hoặc alkylbenzenesulfonate (R–C6H4–SO3Na) với dấu hiệu có nguyên tử S, không có nhóm –COO–. C là sodium alkylbenzenesulfonate."}, {"k": "m", "q": "Hợp chất nào dưới đây được sử dụng làm xà phòng?", "o": "A=CH3COONa;B=CH3(CH2)14COONa;C=CH3(CH2)12COOCH3;D=CH3(CH2)5O(CH2)5CH3", "a": "B", "e": "Xà phòng là muối sodium/potassium của acid béo (mạch carbon dài 12–24 C). CH3(CH2)14COONa chính là sodium palmitate C15H31COONa. A mạch quá ngắn, C là ester, D là ether."}, {"k": "m", "q": "(SBT Hoá học 12 CB) Trong thành phần của xà phòng và của chất giặt rửa thường có một số ester. Vai trò của các ester này là", "o": "A=làm tăng khả năng giặt rửa;B=tạo hương thơm mát, dễ chịu;C=tạo màu sắc hấp dẫn;D=làm giảm giá thành của xà phòng và chất giặt rửa", "a": "B", "e": "Ester có mùi thơm đặc trưng của hoa quả, được thêm vào xà phòng, bột giặt với vai trò chất tạo hương."}, {"k": "m", "q": "(SBT Hoá học 12 CB) Xà phòng và chất giặt rửa có điểm chung là", "o": "A=chứa muối sodium có khả năng làm giảm sức căng bề mặt của các chất bẩn;B=các muối được lấy từ phản ứng xà phòng hoá chất béo;C=sản phẩm của công nghệ hoá dầu;D=có nguồn gốc từ động vật hoặc thực vật", "a": "A", "e": "Cả hai đều là muối sodium có cấu tạo đầu ưa nước – đuôi dài kị nước, giúp giảm sức căng bề mặt và nhũ hoá vết bẩn dầu mỡ – đó là điểm chung. B, D chỉ đúng với xà phòng; C chỉ đúng với chất giặt rửa tổng hợp."}, {"k": "m", "q": "Nguyên nhân nào làm cho bồ kết có khả năng giặt rửa?", "o": "A=trong bồ kết có chất khử mạnh;B=bồ kết có thành phần là ester của glycerol;C=trong bồ kết có những chất oxi hoá mạnh;D=bồ kết có những chất có cấu tạo kiểu đầu phân cực gắn với đuôi dài không phân cực", "a": "D", "e": "Bồ kết chứa saponin – chất giặt rửa tự nhiên có cấu tạo đầu phân cực (ưa nước) gắn với đuôi dài không phân cực (kị nước), tương tự xà phòng."}, {"k": "m", "q": "(SGK – Cánh Diều) Để tẩy vết dầu, mỡ bám trên quần áo, sử dụng chất nào sau đây là phù hợp nhất?", "o": "A=Nước cất;B=Dung dịch sodium hydroxide;C=Dung dịch nước Javel;D=Dung dịch xà phòng", "a": "D", "e": "Xà phòng có đuôi kị nước bám vào dầu mỡ, đầu ưa nước hướng ra ngoài, nhũ hoá vết dầu trôi đi mà không hại vải. NaOH ăn mòn vải, nước Javel chỉ tẩy màu."}, {"k": "m", "q": "Từ tristearin, người ta dùng phản ứng nào để điều chế ra xà phòng?", "o": "A=Phản ứng ester hoá;B=Phản ứng thuỷ phân ester trong môi trường acid;C=Phản ứng cộng hydrogen;D=Phản ứng thuỷ phân ester trong môi trường kiềm", "a": "D", "e": "(C17H35COO)3C3H5 + 3NaOH → 3C17H35COONa + C3H5(OH)3; muối C17H35COONa chính là xà phòng ⇒ dùng phản ứng xà phòng hoá (thuỷ phân trong kiềm)."}, {"k": "m", "q": "(SGK – CTST) Hoá chất chủ đạo trong ngành công nghiệp sản xuất xà phòng là", "o": "A=K2SO4;B=NaCl;C=Mg(NO3)2;D=NaOH", "a": "D", "e": "Để xà phòng hoá chất béo cần kiềm mạnh là NaOH (hoặc KOH). NaCl chỉ dùng ở khâu tách xà phòng ra khỏi hỗn hợp."}, {"k": "m", "q": "Xà phòng được điều chế bằng cách nào trong các cách sau đây?", "o": "A=Thuỷ phân saccharose;B=Thuỷ phân mỡ trong kiềm;C=Phản ứng của acid với kim loại;D=Đề hydrogen hoá mỡ tự nhiên", "a": "B", "e": "Mỡ (chất béo) + NaOH đun nóng → muối của acid béo (xà phòng) + glycerol, đây chính là phản ứng xà phòng hoá."}, {"k": "m", "q": "(SBT Hoá học 12 CB) Không nên dùng xô, chậu bằng nhôm để đựng quần áo ngâm xà phòng vì", "o": "A=quần áo bị mục nhanh;B=xô chậu nhanh hỏng do trong xà phòng có kiềm;C=quần áo bị bạc màu nhanh;D=quần áo không sạch", "a": "B", "e": "Xà phòng còn dư NaOH/KOH tạo môi trường base; nhôm là kim loại lưỡng tính: 2Al + 2NaOH + 2H2O → 2NaAlO2 + 3H2↑, bị ăn mòn nên xô chậu nhanh hỏng."}, {"k": "m", "q": "Không nên dùng xà phòng khi giặt rửa với nước cứng vì", "o": "A=xuất hiện kết tủa làm giảm tác dụng giặt rửa và ảnh hưởng đến chất lượng sợi vải;B=gây ô nhiễm môi trường;C=tạo ra kết tủa CaCO3, MgCO3 bám lên sợi vải;D=gây hại cho da tay", "a": "A", "e": "Nước cứng chứa Ca2+, Mg2+ tạo kết tủa không tan với muối của acid béo: 2C17H35COONa + Ca2+ → (C17H35COO)2Ca↓, làm giảm tác dụng giặt rửa và bám vào sợi vải."}, {"k": "m", "q": "(SBT Hoá học 12 NC) Chất giặt rửa tổng hợp có ưu điểm", "o": "A=dễ kiếm;B=rẻ tiền hơn xà phòng;C=có thể dùng để giặt rửa cả trong nước cứng;D=có khả năng hoà tan tốt trong nước", "a": "C", "e": "Muối sulfate/sulfonate của Ca2+, Mg2+ đều tan nên không bị kết tủa trong nước cứng – ưu điểm nổi bật so với xà phòng."}, {"k": "m", "q": "(SGK Hoá học 12 NC) Phát biểu nào sau đây đúng?", "o": "A=Chất giặt rửa là những chất có tác dụng giống như xà phòng nhưng được tổng hợp từ dầu mỏ;B=Chất giặt rửa là những chất có tác dụng làm sạch các vết bẩn trên bề mặt vật rắn;C=Chất giặt rửa là những chất khi dùng cùng với nước thì có tác dụng làm sạch các vết bẩn bám trên các vật rắn;D=Chất giặt rửa là những chất khi dùng cùng với nước thì có tác dụng làm sạch các vết bẩn bám trên các vật rắn mà không gây ra phản ứng hoá học với các chất đó", "a": "D", "e": "Định nghĩa đầy đủ gồm 3 ý: dùng cùng với nước, làm sạch vết bẩn trên vật rắn, và không gây phản ứng hoá học với vết bẩn (chỉ nhũ hoá – tác dụng vật lí)."}, {"k": "m", "q": "(SGK Hoá học 12 CB) Cho các phát biểu: (a) Xà phòng là sản phẩm của phản ứng xà phòng hoá chất béo với dung dịch NaOH hoặc KOH. (b) Muối sodium hoặc potassium của acid hữu cơ là thành phần chính của xà phòng. (c) Khi đun nóng chất béo với dung dịch NaOH hoặc KOH ta được xà phòng. (d) Từ dầu mỏ có thể sản xuất được chất giặt rửa tổng hợp. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(a), (c), (d) đúng. (b) sai vì thành phần chính của xà phòng là muối của acid béo (mạch dài), không phải acid hữu cơ nói chung (CH3COONa cũng là muối sodium của acid hữu cơ nhưng không phải xà phòng)."}, {"k": "m", "q": "Cho các phát biểu: (1) Chất giặt rửa tổng hợp có thể dùng để giặt rửa cả trong nước cứng. (2) Các triglyceride đều có phản ứng cộng hydrogen. (3) Phản ứng thuỷ phân chất béo trong môi trường kiềm là phản ứng một chiều. (4) Có thể dùng nước và quỳ tím để phân biệt các chất lỏng glycerol, formic acid, triolein. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(1), (3), (4) đúng. (2) sai vì chỉ triglyceride chứa gốc acid béo không no mới cộng H2; tristearin, tripalmitin thì không."}, {"k": "m", "q": "Cho các phát biểu: (a) Xà phòng là muối sodium hoặc potassium của các acid béo. (b) Các triglyceride đều có phản ứng cộng hydrogen. (c) Phản ứng thuỷ phân chất béo trong môi trường kiềm là phản ứng một chiều. (d) Chất béo nhẹ hơn nước và không tan trong nước. Số phát biểu đúng là", "o": "A=1;B=2;C=3;D=4", "a": "C", "e": "(a), (c), (d) đúng. (b) sai vì chỉ triglyceride không no mới cộng H2. Lưu ý ý (a) ở đây ghi là acid béo nên đúng (khác câu hỏi ghi acid hữu cơ)."}, {"k": "m", "q": "Cho các phát biểu: (a) Chất ưa nước là những chất tan tốt trong nước như methanol, muối sodium acetate,… (b) Chất kị nước là những chất không tan trong dầu mỡ, dung môi hữu cơ,… (c) Xà phòng là hỗn hợp các muối sodium hoặc potassium của các acid béo. (d) Chất tẩy rửa tổng hợp là muối sodium của acid béo. (e) Phân tử chất giặt rửa gồm 1 đầu ưa dầu mỡ gắn với 1 đầu dài ưa nước. (f) Ưu điểm của xà phòng là dùng được với nước cứng. Số phát biểu đúng là", "o": "A=2;B=3;C=4;D=5", "a": "A", "e": "Đúng: (a) và (c). Sai: (b) chất kị nước tan tốt trong dầu mỡ; (d) chất tẩy rửa tổng hợp là muối alkylsulfate/alkylbenzenesulfonate; (e) trong phân tử chất giặt rửa là đầu ưa nước gắn với đuôi dài kị nước; (f) điều đó là nhược điểm của xà phòng."}, {"k": "m", "q": "Cho các phát biểu: (a) Xà phòng bị giảm hoặc mất tác dụng tẩy rửa khi dùng nước cứng vì tạo các muối kết tủa với cation Ca2+, Mg2+. (b) Bột giặt tổng hợp vẫn có thể sử dụng với nước cứng vì muối sulfonate có độ tan lớn nên không bị kết tủa với ion Ca2+, Mg2+. (c) Các chế phẩm như bột giặt, kem giặt,… bao gồm các thành phần chất giặt rửa tổng hợp, các phụ gia chất thơm, chất tạo màu, còn có thể có chất tẩy trắng như sodium hypochlorite. (d) Những chất giặt rửa tổng hợp có chứa gốc hydrocarbon phân nhánh không gây ô nhiễm môi trường vì chúng dễ bị các vi sinh vật phân huỷ. (e) Chất ưa nước là những chất tan tốt trong dầu mỏ, alkane,… Số phát biểu SAI là", "o": "A=1;B=2;C=3;D=4", "a": "B", "e": "Sai: (d) gốc hydrocarbon phân nhánh rất khó bị vi sinh vật phân huỷ nên gây ô nhiễm môi trường; (e) chất ưa nước tan tốt trong nước, tan tốt trong dầu mỏ là chất kị nước. (a), (b), (c) đúng ⇒ 2 phát biểu sai."}, {"k": "tf", "q": "(SGK – KNTT) Chất giặt rửa tổng hợp là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\na. Các muối CH3[CH2]14COONa và CH3[CH2]10CH2OSO3Na là thành phần chính của chất giặt rửa tổng hợp.", "o": "", "a": "false", "e": "CH3[CH2]10CH2OSO3Na là chất giặt rửa tổng hợp, nhưng CH3[CH2]14COONa (sodium palmitate) có nhóm –COO– là xà phòng. Ghép chung hai chất là sai."}, {"k": "tf", "q": "(SGK – KNTT) Chất giặt rửa tổng hợp là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nb. Thành phần chính của chất giặt rửa tổng hợp điển hình là các muối: CH3[CH2]10CH2OSO3Na hoặc CH3[CH2]11–C6H4–SO3Na.", "o": "", "a": "true", "e": "Hai muối điển hình của chất giặt rửa tổng hợp là sodium alkylsulfate và sodium alkylbenzenesulfonate."}, {"k": "tf", "q": "(SGK – KNTT) Chất giặt rửa tổng hợp là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nc. Saponin trong bồ hòn và quả bồ kết là chất giặt rửa tự nhiên. Khi tiếp xúc với nước, saponin tạo ra lớp bọt nhẹ tương tự xà phòng.", "o": "", "a": "true", "e": "Saponin là chất giặt rửa tự nhiên có trong bồ hòn, bồ kết, tạo bọt và nhũ hoá tương tự xà phòng."}, {"k": "tf", "q": "(SGK – KNTT) Chất giặt rửa tổng hợp là các chất được tổng hợp hoá học, có tác dụng giặt rửa như xà phòng nhưng không phải muối sodium, potassium của các acid béo. Những chất này thường là muối sodium alkylsulfate hoặc alkylbenzene sulfonate.\nd. Cấu tạo chung của xà phòng và chất giặt rửa phổ biến gồm hai phần: phần ưa nước và phần kị nước. Trong đó phần ưa nước của xà phòng và chất giặt rửa tổng hợp là các gốc hydrocarbon mạch dài (R), phần này tan nhiều trong nước.", "o": "", "a": "false", "e": "Gốc hydrocarbon mạch dài (R) là phần kị nước (tan trong dầu mỡ). Phần ưa nước là –COO–Na+, –SO3Na hoặc –OSO3Na."}, {"k": "tf", "q": "(SGK – Cánh Diều) Trong công nghiệp, để sản xuất xà phòng, người ta thường đun chất béo (mỡ động vật, dầu thực vật) với dung dịch kiềm đặc ở nhiệt độ cao: (RCOO)3C3H5 + 3NaOH → 3RCOONa + C3H5(OH)3.\na. Thành phần chủ yếu muối RCOONa là sodium palmitate và sodium stearate.", "o": "", "a": "true", "e": "Chất béo tự nhiên chủ yếu chứa gốc palmitate và stearate nên muối thu được chủ yếu là sodium palmitate và sodium stearate."}, {"k": "tf", "q": "(SGK – Cánh Diều) Trong công nghiệp, để sản xuất xà phòng, người ta thường đun chất béo (mỡ động vật, dầu thực vật) với dung dịch kiềm đặc ở nhiệt độ cao: (RCOO)3C3H5 + 3NaOH → 3RCOONa + C3H5(OH)3.\nb. Để tách hỗn hợp muối của các acid béo, người ta cho vào hỗn hợp sản phẩm dung dịch muối NaCl bão hoà, các muối của acid béo nổi lên.", "o": "", "a": "true", "e": "NaCl bão hoà làm giảm độ tan của muối acid béo (hiệu ứng muối kết), giúp xà phòng tách ra và nổi lên trên."}, {"k": "tf", "q": "(SGK – Cánh Diều) Trong công nghiệp, để sản xuất xà phòng, người ta thường đun chất béo (mỡ động vật, dầu thực vật) với dung dịch kiềm đặc ở nhiệt độ cao: (RCOO)3C3H5 + 3NaOH → 3RCOONa + C3H5(OH)3.\nc. Trong phòng thí nghiệm, để điều chế lượng nhỏ xà phòng, người ta có thể đựng hỗn hợp chất béo và NaOH vào bát nhôm (hoặc xoong nhôm) để làm thí nghiệm.", "o": "", "a": "false", "e": "NaOH ăn mòn nhôm: 2Al + 2NaOH + 2H2O → 2NaAlO2 + 3H2↑. Phải dùng bát sứ hoặc thuỷ tinh chịu nhiệt, không dùng bát nhôm."}, {"k": "tf", "q": "(SGK – Cánh Diều) Trong công nghiệp, để sản xuất xà phòng, người ta thường đun chất béo (mỡ động vật, dầu thực vật) với dung dịch kiềm đặc ở nhiệt độ cao: (RCOO)3C3H5 + 3NaOH → 3RCOONa + C3H5(OH)3.\nd. Xà phòng còn được sản xuất từ dầu mỏ theo sơ đồ: Alkane → acid béo → muối sodium/potassium của acid béo.", "o": "", "a": "true", "e": "Từ dầu mỏ, người ta oxi hoá alkane thành acid béo rồi trung hoà bằng NaOH/KOH tạo muối (xà phòng)."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho khoảng 2 gam chất béo và khoảng 4 mL dung dịch NaCl 40% vào bát sứ, đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh, bổ sung nước nếu cạn. Bước 2: kết thúc, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ và để nguội.\na. Sau bước 2 thấy có lớp chất rắn màu trắng chứa muối sodium của acid béo nổi lên.", "o": "", "a": "true", "e": "Lớp chất rắn màu trắng nổi lên chính là muối sodium của acid béo (xà phòng), do khối lượng riêng nhỏ và bị muối kết nên nổi."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho khoảng 2 gam chất béo và khoảng 4 mL dung dịch NaCl 40% vào bát sứ, đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh, bổ sung nước nếu cạn. Bước 2: kết thúc, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ và để nguội.\nb. Vai trò của dung dịch NaCl bão hoà ở bước 2 là để tách muối sodium của acid béo ra khỏi hỗn hợp.", "o": "", "a": "true", "e": "NaCl bão hoà làm giảm độ tan của muối acid béo nên tách được xà phòng ra khỏi hỗn hợp, glycerol vẫn ở lại trong dung dịch."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho khoảng 2 gam chất béo và khoảng 4 mL dung dịch NaCl 40% vào bát sứ, đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh, bổ sung nước nếu cạn. Bước 2: kết thúc, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ và để nguội.\nc. Ở bước 1, nếu thay mỡ lợn bằng dầu nhớt thì hiện tượng thí nghiệm sau bước 2 vẫn xảy ra tương tự.", "o": "", "a": "false", "e": "Dầu nhớt là hỗn hợp hydrocarbon từ dầu mỏ, không phải ester nên không bị thuỷ phân, không tạo xà phòng – hiện tượng sẽ khác hẳn."}, {"k": "tf", "q": "(SGK Hoá học 12 – KNTT) Tiến hành thí nghiệm theo các bước: Bước 1: cho khoảng 2 gam chất béo và khoảng 4 mL dung dịch NaCl 40% vào bát sứ, đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh, bổ sung nước nếu cạn. Bước 2: kết thúc, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ và để nguội.\nd. Trong công nghiệp, phản ứng ở thí nghiệm trên được ứng dụng để sản xuất xà phòng và glycerol.", "o": "", "a": "true", "e": "Đây chính là phản ứng xà phòng hoá, được ứng dụng để sản xuất đồng thời xà phòng và glycerol."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Thành phần chính của chất giặt rửa tổng hợp điển hình là các muối: CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11–C6H4–SO3Na (2).\na. Chất giặt rửa tổng hợp được sản xuất từ paraffin dầu mỏ theo sơ đồ: Dầu mỏ → [R–SO3H; R–OSO3H] → [R–SO3Na; R–OSO3Na].", "o": "", "a": "true", "e": "Từ paraffin dầu mỏ, sulfo hoá tạo R–SO3H hoặc R–OSO3H, sau đó trung hoà bằng NaOH tạo R–SO3Na, R–OSO3Na."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Thành phần chính của chất giặt rửa tổng hợp điển hình là các muối: CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11–C6H4–SO3Na (2).\nb. Phần ưa nước trong phân tử chất giặt rửa tổng hợp (1) và (2) là: –SO3Na và –OSO3Na.", "o": "", "a": "true", "e": "Phần ưa nước của (1) là –OSO3Na, của (2) là –SO3Na; phần kị nước là gốc hydrocarbon mạch dài."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Thành phần chính của chất giặt rửa tổng hợp điển hình là các muối: CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11–C6H4–SO3Na (2).\nc. Ưu điểm của chất giặt rửa tổng hợp là dùng được với nước cứng vì không bị kết tủa bởi các ion Ca2+ và Mg2+, và giá thành thấp.", "o": "", "a": "true", "e": "Muối sulfate/sulfonate của Ca2+, Mg2+ đều tan nên không bị kết tủa; nguyên liệu từ dầu mỏ nên giá thành thấp."}, {"k": "tf", "q": "(SGK Hoá học 12 – Cánh Diều) Thành phần chính của chất giặt rửa tổng hợp điển hình là các muối: CH3[CH2]10CH2OSO3Na (1) hoặc CH3[CH2]11–C6H4–SO3Na (2).\nd. Các chất giặt rửa tổng hợp có gốc hydrocarbon phân nhánh hoặc chứa vòng benzene ít gây ô nhiễm môi trường do chúng bị vi sinh vật phân huỷ.", "o": "", "a": "false", "e": "Ngược lại: gốc hydrocarbon phân nhánh hoặc có vòng benzene rất khó bị vi sinh vật phân huỷ, tồn lưu lâu trong nước nên GÂY ô nhiễm môi trường."}, {"k": "n", "q": "Cho các chất sau: CH3[CH2]10CH2OSO3Na; CH3[CH2]14COONa; CH3[CH2]11–C6H4–SO3Na; CH3CH2COONa; CH3[CH2]16COOK. Số chất có thể là thành phần chính của xà phòng là bao nhiêu?", "o": "", "a": "2", "u": "", "tol": "", "e": "Xà phòng là muối Na/K của acid béo nên phải có nhóm –COO– và mạch carbon dài: CH3[CH2]14COONa (palmitate) và CH3[CH2]16COOK (stearate) ⇒ 2 chất. Hai muối chứa S là chất giặt rửa tổng hợp; CH3CH2COONa mạch quá ngắn."}, {"k": "n", "q": "Xà phòng hoá hoàn toàn 0,1 mol tristearin (C17H35COO)3C3H5 bằng dung dịch NaOH dư, đun nóng, thu được m gam glycerol. Tính giá trị của m?", "o": "", "a": "9,2", "u": "g", "tol": "0.1", "e": "(C17H35COO)3C3H5 + 3NaOH → 3C17H35COONa + C3H5(OH)3. Tỉ lệ 1 : 1 ⇒ n(glycerol) = 0,1 mol; m = 0,1 × 92 = 9,2 gam."}, {"k": "n", "q": "Xà phòng hoá hoàn toàn 17,8 gam chất béo X cần vừa đủ dung dịch chứa 0,06 mol NaOH. Cô cạn dung dịch sau phản ứng, thu được m gam muối khan. Tính giá trị của m?", "o": "", "a": "18,36", "u": "g", "tol": "0.01", "e": "n(glycerol) = 0,06 : 3 = 0,02 mol. Bảo toàn khối lượng: m = 17,8 + 0,06×40 − 0,02×92 = 17,8 + 2,4 − 1,84 = 18,36 gam."}, {"k": "n", "q": "Thuỷ phân hoàn toàn m gam chất béo bằng dung dịch NaOH, đun nóng, thu được 9,2 gam glycerol và 91,8 gam muối. Tính giá trị của m?", "o": "", "a": "89", "u": "g", "tol": "1", "e": "n(glycerol) = 9,2 : 92 = 0,1 mol ⇒ n(NaOH) = 0,3 mol. Bảo toàn khối lượng: m = 91,8 + 9,2 − 0,3×40 = 101 − 12 = 89 gam."}, {"k": "n", "q": "(SCĐ Hoá học 11 – CTST) Lượng NaOH cần dùng trong một thí nghiệm điều chế xà phòng là 60 gam. Nếu thay NaOH bằng KOH thì khối lượng KOH cần dùng là bao nhiêu?", "o": "", "a": "84", "u": "g", "tol": "1", "e": "NaOH và KOH đều hoá trị I nên số mol cần dùng bằng nhau: n = 60 : 40 = 1,5 mol; m(KOH) = 1,5 × 56 = 84 gam."}, {"k": "n", "q": "(SBT Hoá học 12 CB) Tính khối lượng muối thu được khi cho 100 kg một loại mỡ chứa 50% tristearin; 30% triolein và 20% tripalmitin tác dụng với sodium hydroxide vừa đủ (giả thiết hiệu suất phản ứng đạt 100%).", "o": "", "a": "103,22", "u": "kg", "tol": "0.01", "e": "n(tristearin) = 50/890; n(triolein) = 30/884; n(tripalmitin) = 20/806 (kmol). m(NaOH) = 3×(50/890 + 30/884 + 20/806)×40 ≈ 13,79 kg; m(glycerol) = (50/890 + 30/884 + 20/806)×92 ≈ 10,57 kg. Bảo toàn: m(muối) = 100 + 13,79 − 10,57 ≈ 103,22 kg."}]}, {"id": "g12t5", "ch": "g12c2", "grade": "g12", "title": "Đề ôn tập chương 2 · Carbohydrate", "timeMin": 30, "qs": [{"k": "m", "q": "(Đề TSĐH B - 2013) Carbohydrate nào sau đây thuộc loại disaccharide?", "o": "A=Amylose;B=Saccharose;C=Glucose;D=Cellulose", "a": "B", "e": "Saccharose thủy phân cho 2 monosaccharide => disaccharide."}, {"k": "m", "q": "(Đề TN THPT QG - 2020) Số nguyên tử hydrogen trong phân tử fructose là", "o": "A=10;B=12;C=22;D=6", "a": "B", "e": "Fructose có công thức C₆H₁₂O₆ → 12 hydrogen."}, {"k": "m", "q": "(Đề MH – 2023) Chất nào sau đây có phản ứng tráng bạc?", "o": "A=Saccharose;B=Cellulose;C=Tinh bột;D=Glucose", "a": "D", "e": "Chỉ glucose có nhóm CHO tự do trong 4 chất trên."}, {"k": "m", "q": "(Đề TNTHPT – 2022) Cho dãy: glucose, fructose, saccharose, cellulose. Số chất tham gia tráng bạc là", "o": "A=4;B=2;C=1;D=3", "a": "B", "e": "Glucose và fructose (chuyển hóa trong base) → 2 chất."}, {"k": "m", "q": "(SGK) Carbohydrate nào không có nhóm –OH hemiacetal hoặc –OH hemiketal?", "o": "A=Maltose;B=Fructose;C=Saccharose;D=Glucose", "a": "C", "e": "Cả 2 –OH hemiacetal của saccharose đều tham gia liên kết α-1,2-glycoside."}, {"k": "m", "q": "(Đề TN THPT QG - 2021) Chất nào bị thủy phân khi đun nóng trong môi trường acid?", "o": "A=Saccharose;B=Glycerol;C=Glucose;D=Fructose", "a": "A", "e": "Chỉ disaccharide/polysaccharide mới có liên kết glycoside để thủy phân."}, {"k": "m", "q": "(Đề MH lần I - 2017) Polymer X sinh ra trong quang hợp, cho với I₂ màu xanh tím. Polymer X là", "o": "A=tinh bột;B=cellulose;C=saccharose;D=glicogen", "a": "A", "e": "Màu xanh tím là phản ứng đặc trưng của tinh bột."}, {"k": "m", "q": "(Đề TSĐH A - 2013) Dãy nào đều tham gia phản ứng thủy phân trong H₂SO₄ đun nóng?", "o": "A=glucose, tinh bột và cellulose;B=saccharose, tinh bột và cellulose;C=glucose, saccharose và fructose;D=fructose, saccharose và tinh bột", "a": "B", "e": "Glucose, fructose là monosaccharide nên không bị thủy phân."}, {"k": "m", "q": "(Đề TNTHPT – 2023) Phát biểu nào SAI?", "o": "A=Thủy phân saccharose chỉ thu được glucose;B=Glucose có khả năng tráng bạc;C=Cellulose và tinh bột đều là polysaccharide;D=Cellulose mạch không phân nhánh", "a": "A", "e": "Saccharose thủy phân cho glucose VÀ fructose."}, {"k": "m", "q": "(Đề MH – 2022) Carbohydrate chứa đồng thời α-1,4 và α-1,6-glycoside là", "o": "A=tinh bột;B=cellulose;C=saccharose;D=fructose", "a": "A", "e": "Amylopectin trong tinh bột có cả hai liên kết (nơi phân nhánh là α-1,6)."}, {"k": "tf", "q": "Nhóm –OH ở vị trí carbon số 1 trong glucose dạng mạch vòng là –OH hemiacetal, phân biệt α-glucose và β-glucose.", "o": "", "a": "true", "e": "Đúng: vị trí C1 là vị trí anomeric – khác nhau ở α và β."}, {"k": "tf", "q": "Tinh bột và cellulose là đồng phân cấu tạo của nhau vì cùng công thức (C6H10O5)n.", "o": "", "a": "false", "e": "Sai: n khác nhau nên không phải đồng phân."}, {"k": "tf", "q": "Fructose không có phản ứng tráng bạc vì có nhóm chức ketone.", "o": "", "a": "false", "e": "Sai: trong môi trường base fructose chuyển thành glucose nên vẫn tráng bạc được (chỉ không làm mất màu Br₂)."}, {"k": "n", "q": "Cho các chất: glucose, fructose, saccharose và maltose. Số carbohydrate có khả năng mở vòng trong dung dịch nước là bao nhiêu?", "o": "", "a": "3", "e": "Glucose, fructose, maltose có –OH hemiacetal/hemiketal tự do (maltose 1 gốc còn tự do); saccharose thì không → 3 chất.", "u": "", "tol": ""}, {"k": "n", "q": "(Đề TSCĐ - 2008) Cho dãy: glucose, cellulose, saccharose, tinh bột và fructose. Số chất tham gia phản ứng tráng gương là?", "o": "", "a": "2", "e": "Chỉ glucose và fructose.", "u": "", "tol": ""}, {"k": "n", "q": "Thủy phân hoàn toàn 0,5 mol saccharose thu được dung dịch X. Cho X tác dụng hoàn toàn với dung dịch AgNO3 trong NH3 dư thu được a mol Ag. Tính a?", "o": "", "a": "2", "e": "0,5 mol saccharose → 0,5 glucose + 0,5 fructose; mỗi chất cho 2 Ag → a = 0,5×2 + 0,5×2 = 2 mol.", "u": "mol", "tol": "0.01"}]}, {"id": "g12t6", "title": "Đề 06 · GHK1 Hoá 12 — THPT Bùi Bích Ngọc (Phú Yên) 2024–2025", "grade": "g12", "timeMin": 45, "qs": [{"k": "m", "ch": "g12c1", "q": "Ester ethyl formate có mùi thơm của đào và có thành phần trong hương vị của quả mâm xôi, đôi khi nó còn được tìm thấy trong táo, ester này có công thức cấu tạo rút gọn là", "o": "A=CH3COOCH3;B=HCOOC2H5;C=HCOOCH=CH2;D=HCOOCH3", "a": "B", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Chất béo là trieste của acid béo với", "o": "A=ethylene glycol;B=glycerol;C=ethanol;D=phenol", "a": "B", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Cho 6 carbohydrate sau: glucose, fructose, maltose, saccharose, tinh bột và cellulose. Có bao nhiêu carbohydrate đã cho thuộc nhóm polysaccharide?", "o": "A=1;B=2;C=3;D=4", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c2", "q": "Nhận xét nào dưới đây là không đúng khi nói về glucose và fructose?", "o": "A=Đều tạo dược dung dịch màu xanh lam khi tác dụng với Cu(OH)2 trong môi trường kiềm;B=Đều tạo được kết tủa đỏ gạch Cu2O khi tác dụng với Cu(OH)2, đun nóng trong môi trường kiềm;C=Đều làm mất màu nước bromine;D=Đều xảy ra phản ứng tráng bạc khi tác dụng với thuốc thử Tollens", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Phản ứng giữa C2H5OH với CH3COOH (xúc tác H2SO4 đặc, đun nóng) là phản ứng", "o": "A=xà phòng hóa;B=ester hóa.          \tC.trùng hợp.        \tD. trùng ngưng", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Phát biểu nào sau đây sai?", "o": "A=Amylopectin có cấu trúc mạch phân nhánh;B=Fructose là sản phẩm của phản ứng thủy phân tinh bột;C=Thủy phân hoàn toàn cellulose thu được glucose;D=Fructose và glucose là đồng phân của nhau", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "n", "ch": "g12c2", "q": "(biết) Công thức cấu tạo dạng mạch vòng - glucose là", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "m", "ch": "g12c1", "q": "Điều chế xà phòng bằng thí nghiệm nào sau đây?", "o": "A=Cho chất béo tác dụng với acid;B=Cho chất béo tác dụng với dung dịch base;C=Cho chất béo tác dụng với muối;D=Cho chất béo tác dụng với ammonia", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Hợp chất  có tên là thay thế là", "o": "A=N-methylethanamine;B=dimethylamine;C=N-ethylmethanamine;D=diethylamine", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Amino acid là hợp chất hữu cơ trong phân tử", "o": "A=chứa nhóm carboxyl và nhóm amino;B=chỉ chứa nhóm amino;C=chỉ chứa nhóm carboxyl;D=chỉ chứa nitrogen hoặc carbon", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Tripeptide là hợp chất mà phân tử có", "o": "A=hai liên kết peptide, ba gốc β-amino acid;B=hai liên kết peptide, ba gốc α- amino acid;C=ba liên kết peptide, hai gốc α- amino acid;D=ba liên kết peptide, ba gốc α- amino acid", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Ở pH thấp, amino acid tồn tại chủ yếu dưới dạng", "o": "A=ion lưỡng cực;B=phân tử;C=anion;D=cation", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Trong cây thuốc lá tự nhiên và khói thuốc lá chứa một amine rất độc, đó là nicotin với công thức cấu tạo như sau:\nNicotin làm tăng huyết áp và nhịp tim, có khả năng gây sơ vữa động mạnh vành và suy giảm trí nhớ. Số nguyên tử carbon trong một phân tử nicotin là", "o": "A=11;B=9;C=10;D=8", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c2", "q": "Glucose có thể lên tạo lactic acid có trong sữa chua qua phản ứng nào sao đây?", "o": "A=2C6H12O6 + Cu(OH)2 (C6H11O6)2Cu + 2H2O;B=C6H12O6  2 C2H5OH  + 2 CO2;C=C6H12O6  2 CH3CH(OH)COOH;D=CH2OH-[CHOH]4-CHO + Br2 +H2O CH2OH-[CHOH]4-COOH + 2HBr", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c3", "q": "Cho một số đặc điểm và tính chất của saccharose:\n(1) là polysaccharide.\n(2) là chất kết tinh, không màu.\n(3) khi thủy phân tạo thành sản phẩm trong đó có glucose.\n(4) tham gia phản ứng tráng bạc.\n(5) phản ứng được với Cu(OH)2.\nSố nhận định đúng là:", "o": "A=(2), (4), (5);B=(1), (3), (5);C=(1), (2), (3);D=(2), (3), (5)", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "n", "ch": "g12c1", "q": "(vận dụng) Thực hiện phản ứng ester hoá sau: cho 0,1 mol alcohol tác dụng với 0,1 mol carboxylic acid, có mặt H2SO4 đặc làm xúc tác.\nĐồ thị nào sau đây biểu diễn sự thay đổi số mol (n) alcohol theo thời gian (t)?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "m", "ch": "g12c3", "q": "Aniline tác dụng với (HNO2 +HCl) ở 0 – 5oC tạo muối diazonium để tổng hợp phẩm nhuộm azo và dược phẩm.\nC6H5NH2 + HONO + HCl X + 2H2O\nChất X có công thức cấu tạo là", "o": "A=[C6H5N2]+Cl-;B=[C6H5NH2]+Cl-;C=[C6H5NH3]+Cl-;D=[C6H5N2H]+Cl-", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c2", "q": "Cho m gam cellulose tác dụng vừa đủ với 56,7 gam HNO3 có trong hỗn hợp HNO3 đặc và H2SO4 đặc, tạo thành 97,2 gam hỗn hợp X gồm cellulose dinitrate và cellulose trinitrate. Giá trị m và thành phần phần trăm về khối lượng của cellulose dinitrate trong X lần lượt là:", "o": "A=40,5 và 61,11%;B=56,7 và 38,89%;C=56,7 và 61,11%;D=57,6 và 38,89%", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "n", "ch": "g12c3", "q": "Thí nghiệm: Phản ứng xà phòng hoá chất béo\nChuẩn bị:\nHoá chất: chất béo (dầu thực vật hoặc mỡ động vật), dung dịch NaOH 40%, dung dịch NaCl bão hoà.\nDụng cụ: bát sứ, cốc thuỷ tinh, đũa thuỷ tinh, kiềng sắt, đèn cồn.\nTiến hành:\nCho khoảng 2 g chất béo và khoảng 4 mL dung dịch NaOH 40% vào bát sứ. Đun hỗn hợp trong khoảng 10 phút và liên tục khuấy bằng đũa thuỷ tinh. Nếu thể tích nước giảm cần bổ sung thêm nước.\nKết thúc phản ứng, đổ hỗn hợp vào cốc thuỷ tinh chứa khoảng 30 mL dung dịch NaCl bão hoà, khuấy nhẹ. Để nguội hỗn hợp, tách lấy khối xà phòng nổi lên ở trên.\na. (biết) Phải dùng đũa thủy tinh khuấy đều hỗn hợp trong bát sứ để phản ứng xảy ra nhanh hơn; có cho thêm vài giọt nước để hỗn hợp không cạn đi (thể tích không đổi) thì phản ứng mới thực hiện được.\nb. (hiểu) Việc thêm NaCl bão hòa để tách xà phòng ra khỏi glycerol do xà phòng tan nhiều trong NaCl bão hòa và nhẹ hơn nên nổi lên trên.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c2", "q": "Glucose và fructose thuộc nhóm monosaccharide, không bị thủy phân.\na. (biết) Glucose là chất rắn, vị ngọt, dễ tan trong nước, glucose có trong nhiều loại trái cây chín.\nb. (hiểu) Ở người trưởng thành, khoẻ mạnh thì lượng glucose trong máu trước khi ăn khoảng 4,4 – 7,2 mmol/L.\nc. (hiểu) Fructose là chất rắn, dễ tan trong nước, có vị ngọt hơn glucose, fructose có nhiều trong mật ong.\nd. (vận dụng) Trong dung dịch, glucose tồn tại chủ yếu ở dạng vòng 6 cạnh và fructose tồn tại chủ yếu ở dạng mạch hở.", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c2", "q": "Một học sinh tiến hành làm thí nghiệm tráng bạc của glucose theo hai bước sau:\nBước 1: Cho vào một ống nghiệm sạch 1 ml dung dịch AgNO3 1%, sau đó nhỏ tiếp từng giọt dung dịch NH3 vào cho đến khi kết tủa vừa xuất hiện lại tan hết.\nBước 2: Thêm tiếp 1 ml dung dịch glucose 1% vào ống nghiệm trên rồi đun nóng nhẹ.\na. (hiểu) Phản ứng hóa học xảy ra ở bước 2 là\nCH2OH-[CHOH]4-CHO+2AgNO3 +3NH3+H2O  CH2OH-[CHOH]4-COONH4+2Ag + 3NH4NO3\nb. (hiểu) Hiện tượng hóa học quan sát được ở bước 2 là có xuất hiện kết tủa màu đen.\nc.  (vận dụng) Ở bước 2, chất oxi hóa là glucose, chất khử là AgNO3\nd. (vận dụng) Trong công nghiệp, người ta dùng sucrose làm nguyên liệu để tráng ruột phích mà không dùng glucose là vì sucrose có lượng nhiều trong tự nhiên, giá thành thấp đồng thời khi thủy phân sinh ra glucose và Fructose đều có phản ứng tráng bạc còn glucose có lượng ít trong tự nhiên, giá thành cao.", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Papain là enzyme có tác dụng thuỷ phân protein, có nhiều trong quả đu đủ. Papain được tách từ nhựa đu đủ xanh, là một enzyme thực vật. Enzym papain rất tốt cho hệ tiêu hóa, giúp tiêu hóa các thức ăn giàu protein một cách dễ dàng hơn. Papain là enzyme có thể sản xuất thuốc điều trị các tác dụng phụ của xạ trị, hoặc nó có thể được sử dụng kết hợp với các liệu pháp khác để điều trị khối u,…\nPapain\na. (vận dụng) Thịt được ướp với nước ép đu đủ thì khi nấu sẽ nhanh mềm hơn.\nb. (vận dụng) Do enzyme có nhiều trong quả đu đủ có tác dụng phân giải protein có trong thịt nên khiến cho thịt khi nấu cùng sẽ nhanh mềm hơn.\nc. (hiểu)Từ quả đu đủ xanh có thể chiết xuất được Bromelain.\nd. (hiểu)Papain có công thức phân tử C9H15N4O3", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c2", "q": "(hiểu) Trong công thức cấu tạo dạng mạch vòng - glucose như sau:\n- glucose\nNhóm –OH hemiacetal là –OH gắn ở carbon số mấy?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "(hiểu) Cho ethylamine lần lượt vào: dung dịch FeCl3; dung dịch HCl; Cu(OH)2; dung dịch NaCl; dung dịch Br2. Ethylamine phản ứng được với bao nhiêu chất?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c2", "q": "(hiểu) Cho các chất: saccharose, glucose, fructose, ethyl formate, formic acid và acetic aldehyde. Trong các chất trên, có bao nhiêu chất vừa có khả năng tham gia phản ứng tráng bạc vừa có khả năng phản ứng với Cu(OH)2 ở điều kiện thường?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "(vận dụng) Valine là một loại amino acid thiết yếu, cần được cung cấp từ nguồn thực phẩm bên ngoài,  cơ thể không tự tổng hợp được. Khi cho 1,404 gam valine hòa tan trong nước được dung dịch. Dung dịch này phản ứng vừa đủ với 12 mL dung dịch NaOH có nồng độ C (mol/L), thu được 1,668 gam muối. Tính giá trị của C?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "(hiểu) Now Ultra Omega-3 Fish Oil 90 là sản phẩm dầu cá được ưa chuộng nhất trên thị trường thực phẩm bổ sung hiện nay. Now Omega-3 phù hợp với đối tượng người cao tuổi, người có nhu cầu giảm cân, người thiếu hụt dinh dưỡng, những gymer, vận động viên, người tập luyện thể thao. Mỗi viên dầu cá chứa 180 mg EPA và 120 mg DHA. Hãy tính tổng số mol EPA và DHA có trong một lọ Now Ultra Omega-3 Fish Oil 90, biết trong một lọ có chứa 90 viên dầu cá trên?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "(vận dụng) Phản ứng quang hợp tạo ra glucose cần được cung cấp năng lượng:\n6 CO2 + 6 H2O + 673 kcal  C6H12O6 + 6 O2\nNếu có một cây xanh với tổng diện tích lá 100 dm2, mỗi dm2 nhận được 3000 cal năng lượng mặt trời trong 1 giờ và chỉ có 10% năng lượng đó tham gia phản ứng tổng hợp glucose, thì trong 10 giờ có bao x gam glucose được tạo thành. Xác định giá trị của x (làm tròn một chữ số thập phân).\n================ Hết đề ===============", "a": "1", "e": "Bài toán định lượng G12C2."}]}, {"id": "g12t7", "title": "Đề 07 · GHK1 Hoá 12 — Đề số 52 (Bạch Hữu Hạnh) 2024–2025", "grade": "g12", "timeMin": 45, "qs": [{"k": "m", "ch": "g12c1", "q": "Chất nào sau đây là ester?", "o": "A=HCOOH;B=CH3CHO;C=CH3OH;D=CH3COOC2H5", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Chất thuộc loại disaccharide là", "o": "A=glucose;B=saccarose;C=cellulose;D=fructose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Acid nào sau đây là acid béo?", "o": "A=formic acid;B=oleic acid;C=acrylic acid;D=Acetic acid", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Carbohydrate nào sau đây thuộc loại polysaccharide?", "o": "A=Glucose;B=Tinh bột;C=Fructose;D=Saccharose", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Một số  ester được dùng trong hương liệu, mĩ phẩm, bột giặt là nhờ các ester", "o": "A=là chất lỏng dễ bay hơi;B=có mùi thơm, an toàn với người;C=có thể bay hơi nhanh sau khi sử dụng;D=đều có nguồn gốc từ thiên nhiên", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Đồng phân của glucose là", "o": "A=fructose;B=tinh bột;C=saccharose;D=cellulose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Công thức của tristearin là", "o": "A=(C2H5COO)3C3H5;B=(C17H35COO)3C3H5;C=(CH3COO)3C3H5;D=(HCOO)3C3H5", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Ester ethyl formate có mùi thơm của đào và có thành phần trong hương vị của quả mâm xôi, đôi khi nó còn được tìm thấy trong táo, ester này công thức là", "o": "A=CH3COOCH3;B=HCOOC2H5;C=HCOOCH=CH2;D=HCOOCH3", "a": "B", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Ester X được tạo bởi methyl alcohol và acetic acid. Công thức của X là", "o": "A=HCOOC2H5;B=CH3COOC2H5;C=CH3COOCH3;D=HCOOCH3", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Trong phân tử của carbohydrate luôn có", "o": "A=nhóm chức aldehyde;B=nhóm chức ketone;C=nhóm chức alcohol;D=nhóm chức acid", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Dầu chuối là ester có tên isoamyl acetate, được điều chế từ", "o": "A=CH3OH, CH3COOH;B=(CH3)2CH-CH2OH, CH3COOH;C=C2H5COOH, C2H5OH;D=CH3COOH, (CH3)2CH-CH2-CH2OH", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Cho 6 carbohydrate sau: glucose, fructose, maltose, saccharose, tinh bột và cellulose. Có bao nhiêu  carbohydrate đã cho thuộc nhóm polysaccharide?", "o": "A=1;B=2;C=3;D=4", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Chất nào sau đây phản ứng với dung dịch NaOH tạo thành HCOONa và C2H5OH?", "o": "B=CH3COOC2H5;C=CH3COOCH3;D=HCOOCH3", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Ở nhiệt độ thường, nhỏ vài giọt dung dịch iodine vào hồ tinh bột thấy xuất hiện màu", "o": "A=vàng;B=nâu đỏ;C=xanh tím;D=hồng", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Chất phản ứng được với AgNO3 trong dung dịch NH3, đun nóng tạo ra kim loại Ag là", "o": "A=glucose;B=saccharose;C=cellulose;D=tinh bột", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Loại glucide không có tính khử là", "o": "A=Glucose;B=Fructose;C=Saccharose;D=Maltose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Phản ứng điều chế xà phòng từ chất béo được gọi là phản ứng", "o": "A=ester hóa;B=xà phòng hóa;C=trung hòa;D=hydrate hóa", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Cho dãy các dung dịch: glucose, saccharose, ethanol, glycerol. Số dung dịch trong dãy phản ứng được với Cu(OH)2 ở nhiệt độ thường tạo thành dung dịch có màu xanh lam là", "o": "A=4;B=1;C=2;D=3", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý a): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nPhản ứng thủy phân trong môi trường acid H+ là phản ứng một chiều.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý b): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nPhản ứng thủy phân trong môi trường base (Phản ứng xà phòng hóa) là phản ứng một chiều.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý c): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nThủy phân chất béo trong môi trường acid hay base thì luôn thu được glycerol.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý d): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nMuối của các acid béo như sodium palmitate, sodium stearate,… được dùng để sản xuất xà phòng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý a): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nGlucose và fructose đều có công thức phân tử là C6H12O6.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý b): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nPhân tử glucose và fructose đều có chứa nhóm chức hydroxy và nhóm chức carbonyl.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý c): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nỞ dạng mạch hở, trong phân tử glucose và phân tử fructose đều chức nhóm aldehyde.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý d): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nCả hai hợp chất glucose và fructose đều tổn tại chủ yếu ở dạng mạch vòng 6 cạnh.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý a): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 2, chất lỏng trong cả hai ống nghiệm đều phân thành hai lớp.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý b): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 2, chất lỏng trong cả hai ống nghiệm đều đồng nhất.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý c): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 3, ở hai ống nghiệm đều thu được sản phẩm giống nhau.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý d): Tiến hành các thí nghiệm theo các bước sau:\nỞ bước 3, có thể thay việc đun sôi nhẹ bằng đun cách thủy (ngâm trong nước nóng).", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý a): Tiến hành thí nghiệm sau:\nKết thúc bước 1, ống nghiệm xuất hiện kết tủa màu xanh.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý b): Tiến hành thí nghiệm sau:\nKết thúc bước 2, ống nghiệm xuất hiện dung dịch màu xanh lam.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý c): Tiến hành thí nghiệm sau:\nPhản ứng xảy ra ở bước 1 là phản ứng trao đổi, ở bước 2 là phản ứng oxi hóa – khử.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý d): Tiến hành thí nghiệm sau:\nThí nghiệm trên chứng tỏ saccharose có tính chất của polyalcohol.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "n", "ch": "g12c3", "q": "Khi xà phòng hóa triglyceride X bằng dung dịch NaOH dư, đun nóng, thu được sản phẩm gồm glycerol, sodium oleate, sodium stearate và sodium palmitate. Có bao nhiêu đồng phân cấu tạo thỏa mãn tính chất trên của X?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho các ester: vinyl acetate, vinyl benzoate, ethyl acetate, isoamyl acetate, phenyl acetate, allyl acetate. Có bao nhiêu ester có thể điều chế trực tiếp bằng phản ứng của carboxylic acid và alcohol tương ứng (có H2SO4 đặc làm xúc tác)?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Cho các thuốc thử sau: thuốc thử Tollens, Cu(OH)2, dung dịch bromine, dung dịch methanol/HCl khan. Có bao nhiêu chất mà glucose và fructose đều phản ứng được?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c2", "q": "Cho các carbohydrate: saccharose, fructose, maltose, tinh bột, cellulose. Số carbohydrate khi thuỷ phân trong môi trường acid chỉ tạo ra glucose là bao nhiêu?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Cho các phát biểu sau về carbohydrate:\n(a) Glucose và saccharose đều là chất rắn có vị ngọt, dễ tan trong nước.\n(b) Tinh bột và cellulose đều là polysaccharide.\n(c) Trong dung dịch, glucose và saccharose đều hoà tan Cu(OH)2, tạo phức màu xanh lam.\n(d) Khi thuỷ phân hoàn toàn hỗn hợp gồm tinh bột và saccharose trong môi trường acid, chỉ thu được một loại monosaccharide duy nhất.\n(e) Khi đun nóng glucose (hoặc fructose) với dung dịch AgNO3 trong NH3 thu được Ag.\n(g) Glucose và saccharose đều tác dụng với H2 (xúc tác Ni, đun nóng) tạo sorbitol.\nCó bao nhiêu phát biểu đúng trong các phát biểu trên?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho salixylic acid (hay 2 – hydroxylbenzoic aicd) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salixylate (C8H8O3) dùng làm chất giảm đau. Để sản xuất 15,4 triệu miếng cao dán giảm đau khi vận động thể thao cần tối thiểu m tấn salixylic acid từ phản ứng trên. Biết mỗi miếng cao dán có chứa 105 mg methyl salixylate và hiệu suất phản ứng đạt 70%. Tính giá trị của m (quy tròn số đến hai chữ số có nghĩa).\nHẾT\nĐỀ KIỂM TRA GIỮA KỲ 1 – ĐỀ SỐ 52\nMôn: HÓA HỌC – LỚP 12\nBẢNG NĂNG LỰC VÀ CẤP ĐỘ TƯ DUY\nĐỀ KIỂM TRA GIỮA KỲ 1 – ĐỀ SỐ 52\nMôn: HÓA HỌC – LỚP 12", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "m", "ch": "g12c1", "q": "Chất nào sau đây là ester?", "o": "A=HCOOH;B=CH3CHO;C=CH3OH;D=CH3COOC2H5", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Chất thuộc loại disaccharide là", "o": "A=glucose;B=saccarose;C=cellulose;D=fructose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Acid nào sau đây là acid béo?", "o": "A=formic acid;B=oleic acid;C=acrylic acid;D=Acetic acid", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Carbohydrate nào sau đây thuộc loại polysaccharide?", "o": "A=Glucose;B=Tinh bột;C=Fructose;D=Saccharose", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Một số  ester được dùng trong hương liệu, mĩ phẩm, bột giặt là nhờ các ester", "o": "A=là chất lỏng dễ bay hơi;B=có mùi thơm, an toàn với người;C=có thể bay hơi nhanh sau khi sử dụng;D=đều có nguồn gốc từ thiên nhiên", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Đồng phân của glucose là", "o": "A=fructose;B=tinh bột;C=saccharose;D=cellulose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Công thức của tristearin là", "o": "A=(C2H5COO)3C3H5;B=(C17H35COO)3C3H5;C=(CH3COO)3C3H5;D=(HCOO)3C3H5", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Ester ethyl formate có mùi thơm của đào và có thành phần trong hương vị của quả mâm xôi, đôi khi nó còn được tìm thấy trong táo, ester này công thức là", "o": "A=CH3COOCH3;B=HCOOC2H5;C=HCOOCH=CH2;D=HCOOCH3", "a": "B", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Ester X được tạo bởi methyl alcohol và acetic acid. Công thức của X là", "o": "A=HCOOC2H5;B=CH3COOC2H5;C=CH3COOCH3;D=HCOOCH3", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Trong phân tử của carbohydrate luôn có", "o": "A=nhóm chức aldehyde;B=nhóm chức ketone;C=nhóm chức alcohol;D=nhóm chức acid", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Dầu chuối là ester có tên isoamyl acetate, được điều chế từ", "o": "A=CH3OH, CH3COOH;B=(CH3)2CH-CH2OH, CH3COOH;C=C2H5COOH, C2H5OH;D=CH3COOH, (CH3)2CH-CH2-CH2OH", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Cho 6 carbohydrate sau: glucose, fructose, maltose, saccharose, tinh bột và cellulose. Có bao nhiêu  carbohydrate đã cho thuộc nhóm polysaccharide?", "o": "A=1;B=2;C=3;D=4", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Chất nào sau đây phản ứng với dung dịch NaOH tạo thành HCOONa và C2H5OH?", "o": "B=CH3COOC2H5;C=CH3COOCH3;D=HCOOCH3", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Ở nhiệt độ thường, nhỏ vài giọt dung dịch iodine vào hồ tinh bột thấy xuất hiện màu", "o": "A=vàng;B=nâu đỏ;C=xanh tím;D=hồng", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Chất phản ứng được với AgNO3 trong dung dịch NH3, đun nóng tạo ra kim loại Ag là", "o": "A=glucose;B=saccharose;C=cellulose;D=tinh bột", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Loại glucide không có tính khử là", "o": "A=Glucose;B=Fructose;C=Saccharose;D=Maltose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Phản ứng điều chế xà phòng từ chất béo được gọi là phản ứng", "o": "A=ester hóa;B=xà phòng hóa;C=trung hòa;D=hydrate hóa", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Cho dãy các dung dịch: glucose, saccharose, ethanol, glycerol. Số dung dịch trong dãy phản ứng được với Cu(OH)2 ở nhiệt độ thường tạo thành dung dịch có màu xanh lam là", "o": "A=4;B=1;C=2;D=3", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý a): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nPhản ứng thủy phân trong môi trường acid H+ là phản ứng một chiều.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý b): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nPhản ứng thủy phân trong môi trường base (Phản ứng xà phòng hóa) là phản ứng một chiều.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý c): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nThủy phân chất béo trong môi trường acid hay base thì luôn thu được glycerol.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý d): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nMuối của các acid béo như sodium palmitate, sodium stearate,… được dùng để sản xuất xà phòng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý b): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nĐúng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý c): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nĐúng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 1 ý d): Chất béo là triester của glycerol với các acid béo nên chúng cũng bị thủy phân tương tự như ester.\nĐúng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý a): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nGlucose và fructose đều có công thức phân tử là C6H12O6.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý b): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nPhân tử glucose và fructose đều có chứa nhóm chức hydroxy và nhóm chức carbonyl.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý c): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nỞ dạng mạch hở, trong phân tử glucose và phân tử fructose đều chức nhóm aldehyde.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý d): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nCả hai hợp chất glucose và fructose đều tổn tại chủ yếu ở dạng mạch vòng 6 cạnh.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý b): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nĐúng.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý c): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nSai – chỉ có phân tử Glucose có nhóm chức aldehyde.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 2 ý d): Glucose và Fructose là 2 monosaccharide phổ biến trong đời sống.\nSai – fructose chủ yếu tồn tại dạng mạch vòng 5 cạnh.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý a): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 2, chất lỏng trong cả hai ống nghiệm đều phân thành hai lớp.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý b): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 2, chất lỏng trong cả hai ống nghiệm đều đồng nhất.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý c): Tiến hành các thí nghiệm theo các bước sau:\nSau bước 3, ở hai ống nghiệm đều thu được sản phẩm giống nhau.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý d): Tiến hành các thí nghiệm theo các bước sau:\nỞ bước 3, có thể thay việc đun sôi nhẹ bằng đun cách thủy (ngâm trong nước nóng).", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý b): Tiến hành các thí nghiệm theo các bước sau:\nSai – vì ester ít tan trong nước nên phân thành hai lớp.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý c): Tiến hành các thí nghiệm theo các bước sau:\nSai – vì ống nghiệm thứ nhất tạo thành acid và alcohol, ống thứ hai tạo muối và alcohol.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c1", "q": "Câu 3 ý d): Tiến hành các thí nghiệm theo các bước sau:\nĐúng.", "a": "true", "e": "Nhận định về G12C1."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý a): Tiến hành thí nghiệm sau:\nKết thúc bước 1, ống nghiệm xuất hiện kết tủa màu xanh.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý b): Tiến hành thí nghiệm sau:\nKết thúc bước 2, ống nghiệm xuất hiện dung dịch màu xanh lam.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý c): Tiến hành thí nghiệm sau:\nPhản ứng xảy ra ở bước 1 là phản ứng trao đổi, ở bước 2 là phản ứng oxi hóa – khử.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý d): Tiến hành thí nghiệm sau:\nThí nghiệm trên chứng tỏ saccharose có tính chất của polyalcohol.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý b): Tiến hành thí nghiệm sau:\nĐúng.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý c): Tiến hành thí nghiệm sau:\nSai – vì cả hai phản ứng đều không phải phản ứng oxi hoá – khử.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 4 ý d): Tiến hành thí nghiệm sau:\nĐúng.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "n", "ch": "g12c3", "q": "Khi xà phòng hóa triglyceride X bằng dung dịch NaOH dư, đun nóng, thu được sản phẩm gồm glycerol, sodium oleate, sodium stearate và sodium palmitate. Có bao nhiêu đồng phân cấu tạo thỏa mãn tính chất trên của X?\nĐA: 3.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho các ester: vinyl acetate, vinyl benzoate, ethyl acetate, isoamyl acetate, phenyl acetate, allyl acetate. Có bao nhiêu ester có thể điều chế trực tiếp bằng phản ứng của carboxylic acid và alcohol tương ứng (có H2SO4 đặc làm xúc tác)?\nĐA: 3.", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Cho các thuốc thử sau: thuốc thử Tollens, Cu(OH)2, dung dịch bromine, dung dịch methanol/HCl khan. Có bao nhiêu chất mà glucose và fructose đều phản ứng được?\nĐA: 3.", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c2", "q": "Cho các carbohydrate: saccharose, fructose, maltose, tinh bột, cellulose. Số carbohydrate khi thuỷ phân trong môi trường acid chỉ tạo ra glucose là bao nhiêu?\nĐA: 3.", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Cho các phát biểu sau về carbohydrate:\n(a) Glucose và saccharose đều là chất rắn có vị ngọt, dễ tan trong nước.\n(b) Tinh bột và cellulose đều là polysaccharide.\n(c) Trong dung dịch, glucose và saccharose đều hoà tan Cu(OH)2, tạo phức màu xanh lam.\n(d) Khi thuỷ phân hoàn toàn hỗn hợp gồm tinh bột và saccharose trong môi trường acid, chỉ thu được một loại monosaccharide duy nhất.\n(e) Khi đun nóng glucose (hoặc fructose) với dung dịch AgNO3 trong NH3 thu được Ag.\n(g) Glucose và saccharose đều tác dụng với H2 (xúc tác Ni, đun nóng) tạo sorbitol.\nCó bao nhiêu phát biểu đúng trong các phát biểu trên?\nĐA: 4.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho salixylic acid (hay 2 – hydroxylbenzoic aicd) phản ứng với methyl alcohol có mặt sulfuric acid làm xúc tác, thu được methyl salixylate (C8H8O3) dùng làm chất giảm đau. Để sản xuất 15,4 triệu miếng cao dán giảm đau khi vận động thể thao cần tối thiểu m tấn salixylic acid từ phản ứng trên. Biết mỗi miếng cao dán có chứa 105 mg methyl salixylate và hiệu suất phản ứng đạt 70%. Tính giá trị của m (quy tròn số đến hai chữ số có nghĩa).\nĐA: 2,1.", "a": "1", "e": "Bài toán định lượng G12C1."}]}, {"id": "g12t8", "title": "Đề 08 · GHK1 Hoá 12 — THPT Hồ Thị Hải (Bắc Giang) 2024–2025", "grade": "g12", "timeMin": 45, "qs": [{"k": "m", "ch": "g12c1", "q": "Ethyl propionate là ester có mùi thơm của dứa. Công thức của ethyl propionate là", "o": "A=HCOOC2H5;B=C2H5COOC2H5;C=C2H5COOCH3;D=CH3COOCH3", "a": "B", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Chất nào sau đây là thành phần chính của chất giặt rửa tổng hợp?", "o": "A=C3H5(OH)3;B=CH3[CH2]14COONa;C=CH3[CH2]16COOK;D=CH3[CH2]11C6H4SO3Na", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Chất nào sau đây thuộc loại monosaccharide?", "o": "A=Tinh bột;B=Fructose;C=Cellulose;D=Saccharose", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Maltose là một loại disaccharide có nhiều trong mạch nha. Công thức phân tử của maltose là", "o": "A=C6H12O6;B=(C6H10O5)n;C=C12H22O11;D=C3H6O2", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c3", "q": "Cho dung dịch glucose vào ống nghiệm chứa dung dịch AgNO, (trong NH, dư) được ngâm trong cốc nước nóng, thu được sản phẩm hữu cơ X và bạc kim loại. Tên gọi của X là", "o": "A=ammonium gluconate;B=glycerol;C=gluconic acid;D=fructose", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c2", "q": "Cho các chất: triolein, cellulose, saccharose, tinh bột. Số chất bị thuỷ phân trong môi trường acid là", "o": "A=4;B=3;C=2;D=1", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c3", "q": "Glucose phản ứng được với CH3OH/HCl khan tạo thành sản phẩm là", "o": "A=methyl α-glycoside;B=methyl β-glycoside;C=methyl α-glucoside hoặc methyl β-glucoside;D=methyl α-glucoside và methyl β-glucoside", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Cho từ từ đến dư methylamine vào dung dịch FeCl3, hiện tượng quan sát được là", "o": "A=Không có kết tủa xuất hiện;B=Tạo kết tủa nâu đỏ không tan;C=Tạo kết tủa nâu đỏ sau đó kết tủa tan ra;D=Tạo dung dịch phức chất có màu xanh lam", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Amine có công thức cấu tạo:\nTên gọi và bậc của amine này là", "o": "A=3-methylbutan-4-amine, bậc I;B=2-methylbutan-2-amine, bậc II;C=2-methylbutan-1-amine, bậc II;D=2-methylbutan-1-amine, bậc I", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Mùi tanh của cá là hỗn hợp các amine và một số tạp chất khác. Để khử mùi tanh của cá trước khi chế biến, biện pháp nào sau đây là phù hợp nhất?", "o": "A=Ngâm cá thật lâu trong nước;B=Rửa cá bằng giấm ăn;C=Rửa cá bằng dung dịch baking soda (chứa NaHCO3);D=Rửa cá bằng dung dịch thuốc tím", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Chất nào sau đây là amino acid?", "o": "A=HOCH2COOH;B=CH3COOH;C=CH3NH2;D=H2NCH2COOH", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Dung dịch chất nào sau đây làm quỳ tím chuyển thành màu xanh?", "o": "A=Lysine;B=Glycine;C=Glutamic acid", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Trong môi trường base, protein có phản ứng màu biuret với", "o": "A=HNO3;B=NaCl;C=Cu(OH)2;D=Mg(OH)2", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Bước 1: Cho vào bát sứ khoảng 1 gam mỡ (hoặc dầu thực vật) và 2 - 2,5 ml dung dịch NaOH 40%.\nBước 2: Đun hỗn hợp sôi nhẹ và liên tục khuấy đều bằng đũa thủy tinh. Thỉnh thoảng thêm vài giọt nước cất để giữ cho thể tích của hỗn hợp không đổi.\nBước 3: Sau 8 - 10 phút, rót thêm vào hỗi hợp 4 - 5 ml dung dịch NaCl bão hòa nóng, khuấy nhẹ.\nPhát biểu nào sau đây sai?", "o": "A=Ở bước 2, xảy ra phản ứng thủy phân chất béo, tạo thành glyccerol và muối sodium của acid béo;B=Sau bước 3, thì lớp X là lớp glycerol và lớp Y là lớp xà phòng;C=Sau bước 3, thấy có một lớp dày đóng bánh màu trắng X nổi lên trên, lớp này là muối của acid béo hay còn gọi là xà phòng;D=Mục đích của việc thêm dung dịch NaCl bão hòa là làm kết tinh muối của acid béo, đó là do muối của acid béo khó tan trong NaCl bão hòa", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Thứ tự các amino acid ứng các vệt được đánh dấu (1), (2), (3) là", "o": "A=Glu, Ala, Lys;B=Lys, Ala, Glu;C=Ala, Lys, Glu;D=Lys, Glu, Ala", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Sodium dodecylbenzenesulfonate (SDBS), hay còn gọi là dodecylbenzene sulfonic acid, sodium salt hoặc linear alkylbenzene sulfonate (LAS), là một loại chất hoạt động bề mặt đa năng có nhiều ứng dụng trong chất tẩy rửa, sản phẩm làm sạch và nhiều quy trình công nghiệp khác nhau.", "o": "B=2;C=3;D=4", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Trong công nghiệp chế biến đường từ mía sẽ tạo ra sản phẩm phụ, gọi là rỉ đường hay rỉ mật (chứa 90% saccharose). Người ta sử dụng rỉ đường để lên men tạo ra ethanol trong điều kiện thích hợp với hiệu suất của cả quá trình là 40%\nC12H22O11 + H2O C6H12O6 + C6H12O6\nSaccharose                            glucose     fructose\nC6H12O6 2C2H5OH + 2CO2\nglucose/fructose        ethanol\nKhối lượng ethanol thu được từ 1 tấn rỉ đường mía theo 2 phương trình trên là", "o": "A=193,7 kg;B=124,5 kg;C=184,2 kg;D=238,0 kg", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c3", "q": "Cho sơ đồ chuyển hóa:\nX (C10H16O7N2) Y Z\nBiết X là đipeptide của một - amino acid T có cấu tạo không phân nhánh; mỗi mũi tên ứng với một phương trình hóa học của phản ứng giữa hai chất tương ứng.\nPhát biểu nào sau đây đúng?", "o": "A=X tác dụng tối đa với dung dịch NaOH theo tỉ lệ 1 : 3;B=Chất Y dùng làm gia vị thức ăn (gọi là mì chính hay bột ngọt)", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "n", "ch": "g12c1", "q": "Methyl cinnmate là một ester có công thức phân tử C10H10O2 và có mùi thơm của dâu tây (strawberry) được sử dụng trong ngành công nghiệp hương liệu và nước hoa. Để điều chế 16,2 gam ester methyl cinnmate người ta cho 29,6 gam cinnamic acid (C6H5CH=CH-COOH) phản ứng với lượng dư methyl alcohol (CH3OH).\na. ( biết)  Methyl cinnmate có công thức cấu tạo là C6H5-CH=CH-COOCH3.\nb.(hiểu)  Methyl cinnmate phản ứng với NaOH với tỉ lệ 1 : 1.\nc. (hiểu) Methyl cinnmate có đồng phân hình học.\nd. (Vận dụng) Hiệu suất phản ứng ester hóa trong trường hợp này là 50%.", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Glucose là loại monosaccharide phổ biến và có nhiều ứng dụng. Glucose tồn tại chủ yếu ở hai dạng mạch vòng là α-glucose và β-glucose. Trong dung dịch, hai dạng mạch vòng này có thể chuyển hóa lẫn nhau thông qua dạng mạch hở như hình sau:\nα-glucose                              glucose                             β-glucose\na.(hiểu)  Dạng α-glucose và β-glucose khác nhau vị trí trong không gian của nhóm –OH hemiacetal.\nb. (hiểu) Khi phản ứng với CH3OH (dư) trong HCl thì cả 5 nhóm –OH của glucose đều bị ether hóa.\nc. (hiểu) Dạng α-glucose và β-glucose đều phản ứng trực tiếp với thuốc thử Tollens.\nd. (vận dụng)  Khi phản ứng với Cu(OH)2/NaOH ở nhiệt độ thường và Cu(OH)2/NaOH đun nóng thì glucose đều bị oxi hóa.", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Glutamic acid có vai trò quan trọng trong quá trình xây dựng cấu trúc tế bào của con người. Ngoài ra, muối monosodium glutamate còn được dùng chế biến gia vị thức ăn (bột ngọt hay mì chính). Glutamic acid có cấu trúc như hình vẽ bên dưới và có điểm đẳng điện pI = 3,2 (pI là giá trị pH mà khi đó amino acid có nồng độ ion lưỡng cực là cực đại. Khi pH < pI thì amino acid đó tồn tại chủ yếu ở dạng cation, còn khi pH > pI thì amino acid đó tồn tại chủ yếu ở dạng anion)\na. (biết) Glutamic acid thuộc loại hợp chất hữu cơ tạp chức, trong phân tử chứa hai loại nhóm chức.\nb.(biết)  Tên thay thế của glutamic acid là 2-aminopentane-1,5-dioic acid.\nc. (hiểu)Trong dung dịch pH = 3,2, glutamic acid tồn tại chủ yếu ở dạng HOOC–CH2–CH2–CH(NH2)–COO-.\nd. (vận dụng)Trong dung dịch pH = 6, có thể tách hỗn hợp gồm glutamic acid và lysine (pI = 9,7) bằng phương pháp điện di.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c3", "q": "Thủy phân hoàn toàn 1 mol peptide X, thu được 1 mol glycine (Gly), 1 mol alanine (Ala), 2 mol valine (Val) và 1 mol phenylalanine (Phe). Thủy phân không hoàn toàn X thu được dipeptide Phe-Val và tripeptide Val-Ala-Gly nhưng không thu được dipeptide Val-Val.\na. (hiểu) X là pentapeptide.\nb. (hiểu) Khối lượng phân tử của peptide X là 491.\nc. (hiểu)  Peptide X luôn có amino acid đầu C là Val.\nd.(VD) Có 1 công thức cấu tạo duy nhất thỏa mãn tính chất của peptide X.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c2", "q": "(hiểu) Cho các carbohydrate sau: glucose, fructose, saccharose và maltose. Có bao nhiêu carbohydrate có khả năng mở vòng trong dung dịch với dung môi nước?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c2", "q": "(hiểu) Cho một số tính chất: có dạng sợi (1); tan trong nước (2); dùng để sản xuất tơ nhân tạo (3); phản ứng với nitric acid đặc (xúc tác sulfuric acid đặc) (4); tham gia phản ứng với thuốc thử Tollens (5); bị thuỷ phân trong dung dịch acid đun nóng (6). Tính chất nào đúng với cellulose? (Liệt kê theo số thứ tự tăng dần)", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Alliin là một amino acid có trong tỏi tươi, khi đập dập hay nghiền, enzyme alliinase sẽ chuyển hoá alliin thành allicin, tạo ra mùi đặc trưng của tỏi. Cấu trúc phân tử Alliin được mô tả dưới đây:\nPhân tử khối của Alliin là bao nhiêu?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho các chất: CH3[CH2]14COONa, CH3[CH2]10CH2OSO3Na, CH3[CH2]16COOK, CH3[CH2]7CH=CH[CH2]7COONa, CH3COONa, (C15H31COO)3C3H5. Có bao nhiêu chất có thể là thành phần chính của xà phòng?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Biết khối lượng riêng của silver là 10,49 g/cm3, hiệu suất phản ứng tráng gương là 80% (tính theo glucozơ). Có tối đa bao nhiêu chiếc gương soi được sản xuất ra? (Kết quả làm tròn đến hàng đơn vị).", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c1", "q": "(vận dụng) Aspirin là một hợp chất được sử dụng làm giảm đau, hạ sốt được điều chế theo phản ứng sau:\n(CH3CO)2O   +   HOC6H4COOH  CH3COOC6H4COOH + CH3COOH\nacetic anhydride    salicylic acid                                    aspirin\nĐể sản xuất 500 nghìn viên thuốc aspirin cần tối thiểu m kg salicylic acid. Biết rằng mỗi viên thuốc có chứa 81 mg aspirin và hiệu suất phản ứng đạt 75%. Giá trị của m là bao nhiêu?\n================ Hết đề ================", "a": "1", "e": "Bài toán định lượng G12C1."}]}, {"id": "g12t9", "title": "Đề 09 · GHK1 Hoá 12 — Sở GD&ĐT Hòa Bình (Đinh Quang Thanh) 2024–2025", "grade": "g12", "timeMin": 45, "qs": [{"k": "m", "ch": "g12c1", "q": "Công thức của ethyl acetate là", "o": "A=C2H5COOCH;B=C2H5COOC2H5;C=CH3COOCH3;D=CH3COOC2H5", "a": "D", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Chất nào sau đây thuộc loại polysaccharide?", "o": "A=maltose;B=cellulose;C=glucose;D=fructosse", "a": "B", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Chất nào sau đây là amine bậc hai?", "o": "A=CH3CH(NH2)CH3;B=(C2H5)2NH;C=(C2H5)3N;D=C2H5NH2", "a": "B", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Tổng số nhóm amino (-NH2) và nhóm carboxyl (-COOH) trong phân tử lysine là", "o": "A=3;B=4;C=1;D=2", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Amino acid đầu N của phân tử tetrapeptide Val-Ala-Lys-Gly là?", "o": "A=Valine;B=Alanine;C=Glycine;D=Lysine", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c2", "q": "Trong công nghiệp sản xuất đường saccharose, người ta đã sử dụng phương pháp nào để tách saccharose ra khỏi dung dịch nước mía?", "o": "A=Chưng cất;B=Sắc kí;C=Kết tinh;D=Chiết", "a": "C", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c1", "q": "Xà phòng là muối sodium hoặc potassium của", "o": "A=acetic acid;B=phenol;C=acid vô cơ;D=acid béo", "a": "D", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c3", "q": "Trong thành phần của quả bông có 90% cellulose về khối lượng. Trong phân tử cellulose các đơn vị β-glucose liên kết với nhau qua liên kết nào sau đây?", "o": "A=liên kết β-1,6-glycoside;B=liên kết β-1,4-glycoside;C=liên kết β-1,3-glycoside;D=liên kết β-1,2-glycoside", "a": "B", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Chất cơ sở để hình thành nên các phân tử protein đơn giản là", "o": "A=amino acid;B=acid béo;C=các loại đường;D=tinh bột", "a": "A", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Cho dãy các chất: ethanol, acetic acid, methyl fomate, propionic acid. Chất nào có nhiệt độ sôi thấp nhất?", "o": "A=methyl fomate;B=ethanol;C=acetic acid;D=propionic acid", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c1", "q": "Chất giặt rửa tổng hợp sodium laurysulfate có công thức cấu tạo như sau:\nNhóm được khoanh tròn trong công thức trên là", "o": "A=đầu kị nước;B=đuôi kị nước;C=đầu ưa nước;D=đuôi ưa nước", "a": "C", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "m", "ch": "g12c2", "q": "Để tráng một lớp bạc lên ruột phích, người ta cho chất X phản ứng với lượng dư dung dịch AgNO3 trong NH3, đun nóng. Chất X là", "o": "A=ethanol;B=glucose;C=acetic acid;D=saccharose", "a": "B", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c2", "q": "Trong công nghiệp thực phẩm, saccharose được sử dụng phổ biến làm nguyên liệu để sản xuất bánh kẹo, nước giải khát,... Phát biểu nào sau đây là sai?", "o": "A=Saccharose thuộc loại disaccharide;B=Dung dịch saccharose hoà tan được Cu(OH)2 cho dung dịch màu xanh lam;C=Thuỷ phân saccharose chỉ thu được glucose;D=Saccharose thường được tách từ nguyên liệu là cây mía, củ cải đường,", "a": "C", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "m", "ch": "g12c3", "q": "Giá trị pH mà khi đó amino acid có nồng độ ion lưỡng cực là cực đại được gọi là điểm đăng điện (hiệu là pI). Khi pH < pI thi amino acid đó tồn tại chủ yếu ở dạng cation, còn khi pH > pI thì amino acid đó tồn tại chủ yếu ở dạng anion. Khi đặt trong một điện trường đạng anion sẽ di chuyến về cực (+) còn dạng cation sẽ di chuyển về cực (-). Tính chất này được gọi là tính điện di và được dùng để tách, tinh chế amino acid ra khỏi hỗn hợp của chúng. Cho các giá trị pI của các chất sau:\nTrong các giá trị pH cho dưới đây, giá trị nào là tối ưu nhất để tách ba chất trên ra khỏi dung dịch hỗn hợp của chúng?", "o": "A=pH = 14,0;B=pH = 9,7;C=pH = 3,2;D=pH = 6,0", "a": "D", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c3", "q": "Nhỏ dung dịch methylamine vào dung dịch nào sau đây thấy xuất hiện kết tủa?", "o": "A=HCl;B=MgCl2;C=BaCl2;D=NaCl", "a": "B", "e": "Bậc amine tính theo số gốc hydrocarbon gắn vào N; alkylamine làm xanh quỳ tím, aniline không làm đổi màu quỳ tím."}, {"k": "m", "ch": "g12c1", "q": "Tiến hành thí nghiệm điều chế ethyl acetate theo các bước sau đây:\nBước 1: Cho 1 mL C2H5OH, 1 mL CH3COOH và vài giọt dung dịch H2SO4 đặc vào ống nghiệm.\nBước 2: Lắc đều ống nghiệm, đun cách thủy (trong nồi nước nóng) khoảng 5 - 6 phút ở 65 - 70oC.\nBước 3: Làm lạnh, sau đó rót 2 mL dung dịch NaCl bão hòa vào ống nghiệm.\nPhát biểu nào sau đây là sai ?", "o": "A=H2SO4 đặc có vai trò vừa làm chất xúc tác vừa làm tăng hiệu suất tạo sản phẩm;B=Mục đích chính của việc thêm dung dịch NaCl bão hòa là để tránh phân hủy sản phẩm;C=Sau bước 2, trong ống nghiệm vẫn còn C2H5OH và CH3COOH;D=Sau bước 3, chất lỏng trong ống nghiệm tách thành hai lớp", "a": "B", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "n", "ch": "g12c3", "q": "Thuỷ phân hoàn toàn một polyamide X thu được một amino acid Y mạch không phân nhánh, có nhóm amine ở một đầu mạch của phân tử. Kết quả phân tích nguyên tố cho biết phân tử Y có phần trăm khối lượng các nguyên tố C, H, N lần lượt bằng 54,96%, 9,85% và 10,61%, còn lại là oxygen. Từ phổ khối lượng (MS) xác định được phân tử khối của Y bằng 131. Từ Y, bằng phản ứng trùng ngưng lại thu được polymer X ban đầu. Công thức của polyamide X là", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "tf", "ch": "g12c2", "q": "Câu 1 ý a): Tiến hành thí nghiệm theo các bước sau:\nSau bước 2, kết tủa đã bị hòa tan, thu được dung dịch màu xanh lam.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 1 ý b): Tiến hành thí nghiệm theo các bước sau:\nThí nghiệm trên chứng minh glucose có tính khử.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 1 ý c): Tiến hành thí nghiệm theo các bước sau:\nNếu thay dung dịch NaOH ở bước 2 bằng dung dịch KOH thì hiện tượng ở bước 3 vẫn tương tự.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 1 ý d): Tiến hành thí nghiệm theo các bước sau:\nSau bước 2, nếu đun nóng sẽ xuất hiện kết tủa màu đen.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c3", "q": "Câu 2 ý a): Cho dãy các chất sau: aniline (X); glutamic acid (Y); Gly-Ala (Z).\nCác chất trên đều có chứa các nguyên tố C, H, O và N trong phân tử.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 2 ý b): Cho dãy các chất sau: aniline (X); glutamic acid (Y); Gly-Ala (Z).\nChất Z có phản ứng với thuốc thử biuret tạo thành màu tím đặc trưng.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 2 ý c): Cho dãy các chất sau: aniline (X); glutamic acid (Y); Gly-Ala (Z).\nỞ điều kiện thường, X là chất lỏng; Y là chất rắn.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 2 ý d): Cho dãy các chất sau: aniline (X); glutamic acid (Y); Gly-Ala (Z).\nCó thể nhận biết dung dịch ba chất trên bằng quỳ tím.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c2", "q": "Câu 3 ý a): Ester no, đơn chức, mạch hở (X) là dung môi hữu cơ được sử dụng nhiều trong công nghiệp hóa chất. Trên phổ MS của X thấy xuất hiện peak của ion phân tử có giá trị m/z =88. Trong đời sống, X được điều chế từ quá trình lên men tinh bột và là một thành phần của xăng E5. Cho các phương trình hóa học sau:\nX tan tốt trong nước.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 3 ý b): Ester no, đơn chức, mạch hở (X) là dung môi hữu cơ được sử dụng nhiều trong công nghiệp hóa chất. Trên phổ MS của X thấy xuất hiện peak của ion phân tử có giá trị m/z =88. Trong đời sống, X được điều chế từ quá trình lên men tinh bột và là một thành phần của xăng E5. Cho các phương trình hóa học sau:\nX và X4 là hai chất đồng phân.", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 3 ý c): Ester no, đơn chức, mạch hở (X) là dung môi hữu cơ được sử dụng nhiều trong công nghiệp hóa chất. Trên phổ MS của X thấy xuất hiện peak của ion phân tử có giá trị m/z =88. Trong đời sống, X được điều chế từ quá trình lên men tinh bột và là một thành phần của xăng E5. Cho các phương trình hóa học sau:\nCó thể thực hiện phản ứng theo sơ đồ chuyển hoá X2 → X4 → X", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c2", "q": "Câu 3 ý d): Ester no, đơn chức, mạch hở (X) là dung môi hữu cơ được sử dụng nhiều trong công nghiệp hóa chất. Trên phổ MS của X thấy xuất hiện peak của ion phân tử có giá trị m/z =88. Trong đời sống, X được điều chế từ quá trình lên men tinh bột và là một thành phần của xăng E5. Cho các phương trình hóa học sau:\nThứ tự nhiệt độ sôi được sắp xếp theo chiều X3 < X2 < X4", "a": "true", "e": "Nhận định về G12C2."}, {"k": "tf", "ch": "g12c3", "q": "Câu 4 ý a): Triglyceride đóng vai trò là nguồn cung cấp năng lượng và chuyện chở các chất béo trong quá trình trao đổi chất. Cho triglyceride X có công thức cấu tạo như hình sau.\nTriglyceride X làm mất màu dung dịch bromine.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 4 ý b): Triglyceride đóng vai trò là nguồn cung cấp năng lượng và chuyện chở các chất béo trong quá trình trao đổi chất. Cho triglyceride X có công thức cấu tạo như hình sau.\nAcid béo có gốc kí hiệu (2) thuộc loại acid béo omega -9.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 4 ý c): Triglyceride đóng vai trò là nguồn cung cấp năng lượng và chuyện chở các chất béo trong quá trình trao đổi chất. Cho triglyceride X có công thức cấu tạo như hình sau.\nCác gốc của acid béo không no trong phân tử X đều có cấu hình cis-", "a": "true", "e": "Nhận định về G12C3."}, {"k": "tf", "ch": "g12c3", "q": "Câu 4 ý d): Triglyceride đóng vai trò là nguồn cung cấp năng lượng và chuyện chở các chất béo trong quá trình trao đổi chất. Cho triglyceride X có công thức cấu tạo như hình sau.\nHydrogen hóa hoàn toàn  427 kg triglyceride X thu được 432 kg chất béo rắn.", "a": "true", "e": "Nhận định về G12C3."}, {"k": "n", "ch": "g12c2", "q": "Glucose có công thức phân tử C6H12O6. Cấu tạo glucose có một dạng mạch hở và 2 dạng mạch vòng chuyển hóa (α-glucose và β-glucose) chuyển hóa qua lại lẫn nhau. Ở dạng mạch hở phân tử glucose có bao nhiêu nhóm hydroxy (–OH)?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c1", "q": "Cho các chất: methyl fomate, propan-1-ol, methyl acetate, propionic acid và các giá trị nhiệt độ sôi (không tho thứ tự) là 1410C; 97,20C, 31,80C; 57,10C. Nhiệt độ sôi của methyl acetate có giá trị là bao nhiêu (0C)?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Củ sắn khô chứa 38% khối lượng là tinh bột, còn lại là các chất không có khả năng lên men thành  ethyl alcohol. Lên men 1 tấn sắn khô với hiệu suất cả quá trình là 81%. Toàn bộ lượng ancol etylic sinh ra để điều chế xăng E5 (có chứa 5% thể tích ethyl alcohol). Biết khối lượng riêng của ethyl alcohol là 0,8 g/mL, thể tích xăng E5 thu được là bao nhiêu lít?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c2", "q": "Cho dãy các chất sau: glucose, fructose, saccharose và cellulose. Có bao nhiêu chất có phản ứng với thuốc thử Tollens?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c3", "q": "Có bao nhiêu công thức cấu tạo amine bậc một có công thức phân tử C3H9N?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Một loại chất béo có chứa 80% triolein về khối lượng. Xà phòng hóa hoàn toàn 22,1 kg chất béo này trong dung dịch NaOH, đun nóng thu được x bánh xà phòng. Biết rằng trong mỗi bánh xà phòng có chứa 60 gam sodium oleate. Xác định giá trị của x.\n----------- HẾT ----------", "a": "1", "e": "Bài toán định lượng G12C1."}]}, {"id": "g12t10", "title": "Đề 10 · GHK1 Hoá 12 — Đề minh hoạ chuẩn phát triển (Đỗ Hoa) 2024–2025", "grade": "g12", "timeMin": 45, "qs": [{"k": "n", "ch": "g12c3", "q": "Một loại chất béo có chứa 65% triolein về khối lượng. Để sản xuất 2,3 triệu hộp kem dưỡng da (có chứa chất dưỡng ẩm glycerol) cần dùng tối thiểu x tấn loại chất béo trên cho phản ứng với dung dịch NaOH, đun nóng. Biết rằng trong mỗi hộp kem dưỡng da có chứa 5 gam glycerol. Giá trị của x là", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c3", "q": "Chất nào sau đây phản ứng với dung dịch NaOH sinh ra glycerol?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Tinh thể chất rắn X vị ngọt, dễ tan trong nước. X có nhiều trong các bộ phận của cây đặc biệt là quả chín. Oxi hóa chất X bằng nước bromine thu được chất hữu cơ Y. Tên gọi của X và Y lần lượt là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Công thức của triolein là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Số nguyên tử hydrogen trong phân tử methyl formate là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Đun nóng tinh bột trong dung dịch acid vô cơ loãng sẽ thu được", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c1", "q": "Thủy phân ester CH3CH2COOCH3, thu được alcohol có công thức là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c3", "q": "Để trung hòa 25 gam dung dịch của một amin đơn chức X nồng độ 12,4% cần dùng 100ml dung dịch HCl 1M. Công thức phân tử của X là", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Dãy các chất đều có khả năng tham gia phản ứng thủy phân trong dung dịch H2SO4 đun nóng là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c3", "q": "Chất nào sau đây thuộc loại amine bậc một?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c2", "q": "Trong điều kiện thích hợp glucose lên men tạo thành khí CO2 và", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "m", "ch": "g12c1", "q": "Phát biểu nào sau đây đúng?", "o": "A=Các chất béo thường không tan trong nước và nhẹ hơn nước;B=Tripalmitin có khả năng tham gia phản ứng cộng hydrogen khi đun nóng có xúc tác, áp suất;C=Chất béo bị thủy phân trong môi trường acid, không bị thủy phân trong môi trường kiềm;D=Chất béo là triester của ethylen glicol với các acid béo", "a": "A", "e": "Ester có nhiệt độ sôi thấp hơn alcohol và acid tương ứng; phản ứng thủy phân trong môi trường kiềm (xà phòng hoá) là một chiều."}, {"k": "n", "ch": "g12c1", "q": "Chất X tác dụng với dung dịch NaOH vừa đủ, thu được hai chất Y và Z. Cho Z tác dụng với dung dịch AgNO3 trong NH3 thu được chất hữu cơ T. Cho T tác dụng với dung dịch NaOH lại thu được chất Y. Chất X là", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Xà phòng hóa 0,3 mol methyl acrylate bằng dung dịch có 0,2 mol KOH. Sau phản ứng hoàn toàn, cô cạn dung dịch được bao nhiêu gam chất rắn khan?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Saccharose là một loại disaccharide có nhiều trong cây mía, hoa thốt nốt, củ cải đường. Công thức phân tử của saccharose là", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "m", "ch": "g12c2", "q": "Phát biểu nào sau đây không đúng?", "o": "A=Maltose có nhiều trong mạch nha;B=Saccharose và maltose đều là disaccharide;C=Saccharose và fructose là đồng phân của nhau;D=Saccharose chỉ có cấu tạo dạng mạch vòng", "a": "A", "e": "Glucose và fructose là đồng phân C6H12O6; saccharose là disaccharide tạo bởi α-glucose và β-fructose."}, {"k": "n", "ch": "g12c1", "q": "Cho 0,01 mol một este X của axit hữu cơ phản ứng vừa đủ với 100 ml dung dịch NaOH 0,2 M, sản phẩm tạo thành chỉ gồm một ancol Y và một muối Z với số mol bằng nhau. Mặt khác, khi xà phòng hoá hoàn toàn 1,29 gam este đó bằng một lượng vừa đủ là 60 ml dung dịch KOH 0,25 M, sau khi phản ứng kết thúc đem cô cạn dung dịch được 1,665 gam muối khan. Công thức của este X là:", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c3", "q": "Cho các chất sau: saccharose, glucose, acetic aldehyde, glyxerol, ethyl alcohol, acetylene, fructose. Số lượng chất có thể tham gia phản ứng tráng gương là", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Cho ester X có công thức: CH3COOC2H5.\na. Tên gọi của X là methyl propionate.\nb. Nhiệt độ sôi của X cao hơn so với butane.\nc. Cho X tác dụng với dung dịch NaOH đun nóng thu được sản phẩm là CH3COONa và C2H5OH.\nd. Thủy phân X trong môi trường acid thu được hai chất Y và Z (MY < MZ), từ Y có thể điều chế trực tiếp được Z.\nd. Thủy phân X thu được CH3COOH (Z) và C2H5OH (Y): C2H5OH + O2  CH3COOH + H2O", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c3", "q": "Cho 1 mol triglyceride X tác dụng với dung dịch NaOH dư, thu được 1 mol glycerol, 1 mol sodium palmitate và 2 mol sodium oleate.\na. Phân tử X có 5 liên kết π.\nb. Có 2 đồng phân cấu tạo thỏa mãn tính chất của X.\nc. Công thức phân tử chất X là C52H96O6.\nd. 1 mol X phản ứng tối đa 2 mol H2 ở điều kiện thích hợp.", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Tiến hành thí nghiệm theo các bước sau:\nBước 1: Cho 5 giọt dung dịch CuSO4 0,5% vào ống nghiệm sạch.", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Xà phòng và chất giặt rửa có nhiều ưu nhược điểm.\na. Xà phòng và chất giặt rửa tự nhiên khó bị phân hủy sinh học nên gây ô nhiễm môi trường.\nb. Không nên dùng xà phòng với nước cứng do tạo kết tủa bám trên bề mặt vải, làm hỏng vải.\nc. Chất giặt rửa tổng hợp dùng được với nước cứng.\nd. Chất giặt rửa tổng hợp khó bị phân hủy sinh học, gây ô nhiễm môi trường", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Có bao nhiêu hợp chất đơn chức, đồng phân cấu tạo của nhau có cùng công thức phân tử C4H8O2, đều tác dụng được với dung dịch NaOH?\nĐáp số: 6. C4H8O2 tác dụng với NaOH  acid (2 đồng phân) và ester ( 4 đồng phân).", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c1", "q": "Cho các ester: ethyl formate, vinyl acetate, triolein, methyl acrylate, phenyl acetate. Có bao nhiêu chất trong dãy khi thủy phân trong dung dịch NaOH (dư), đun nóng sinh ra alcohol?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c3", "q": "Cho các chất: CH3OH, C2H5Cl, C2H5NH2, CH3COOH, CH3 – NH – CH3, H2N – CH2 – COOH. Có bao nhiêu chất là amine trong các chất trên?", "a": "1", "e": "Bài toán định lượng G12C3."}, {"k": "n", "ch": "g12c1", "q": "Aspirin là một hợp chất được sử dụng làm giảm đau, hạ sốt được điều chế theo phản ứng sau:\n(CH3CO)2O + HOC6H4COOH  CH3COOC6H4COOH + CH3COOH    acetic anhydride  salicylic acid                                    aspirin\nĐể sản xuất 4 triệu viên thuốc aspirin cần tối thiểu m kg salicylic acid. Biết rằng mỗi viên thuốc có chứa 81 mg aspirin và hiệu suất phản ứng đạt 75%. Giá trị của m bằng bao nhiêu?", "a": "1", "e": "Bài toán định lượng G12C1."}, {"k": "n", "ch": "g12c2", "q": "Thủy phân saccharose, thu được hai monosaccharide X và Y. Chất X có trong máu người với nồng độ khoảng 4,4 – 7,2 mmol/L. Tổng số nguyên tử của X bằng bao nhiêu?", "a": "1", "e": "Bài toán định lượng G12C2."}, {"k": "n", "ch": "g12c1", "q": "Cho sơ đồ các phản ứng theo đúng tỉ lệ mol:\n(1) X + 4AgNO3 + 6NH3 + 2H2O  X1 + 4Ag + 4NH4NO3\n(2) X1 + 2NaOH  X2 + 2NH3 + 2H2O\n(3) X2 + 2HCl  X3 + 2NaCl\n(4) X3 + C2H5OH  X4 + H2O\nBiết X là hợp chất hữu cơ no, mạch hở, chỉ chứa một loại nhóm chức. Khi đốt cháy hoàn X2, sản phẩm thu được chỉ gồm CO2 và Na2CO3. Phân tử khối của X4 là bao nhiêu?", "a": "1", "e": "Bài toán định lượng G12C1."}]}, {"id": "g11t1", "grade": "g11", "ch": "g11on", "title": "Đề 01 · Ôn tập Hoá 11 HK2 (Hydrocarbon & Dẫn xuất halogen)", "timeMin": 45, "qs": [{"k": "m", "ch": "g11c1", "q": "Hàn xì là một trong những công nghệ hàn rất phổ biến, nhiệt lượng tỏa ra để hàn, cắt kim loại dựa trên phản ứng cháy của khí nào sau đây?", "o": "A=C₂H₄;B=C₂H₆;C=CH₄;D=C₂H₂", "a": "D", "e": "Acetylene (C₂H₂) cháy trong O₂ cho nhiệt độ ngọn lửa ~3000°C — đủ nóng để cắt kim loại."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây không làm mất màu dung dịch bromine ở điều kiện thường?", "o": "A=propane;B=propylene;C=propyne;D=styrene", "a": "A", "e": "Propane là alkane (chỉ có liên kết đơn) → không cộng Br₂. Còn lại đều có liên kết bội (C=C hoặc C≡C)."}, {"k": "m", "ch": "g11c1", "q": "Phát biểu nào sau đây về tính chất vật lý của các chất (ở điều kiện thường) không đúng?", "o": "A=Acetylene là chất khí, không màu, nặng hơn không khí;B=Hexane nhẹ hơn nước và không tan trong nước;C=Nhiệt độ sôi của methane nhỏ hơn ethane;D=Hex-1-ene là chất lỏng, không tan trong nước", "a": "A", "e": "M(C₂H₂) = 26 < M(không khí) ≈ 29 → acetylene NHẸ hơn không khí, không phải nặng hơn."}, {"k": "m", "ch": "g11c1", "q": "Khi cho propene (CH₂=CH–CH₃) tác dụng với HCl, theo qui tắc Markovnikov thì sản phẩm chính là", "o": "A=CH₃-CHCl-CH₃;B=CH₃-CH₂-CH₂Cl;C=CH₃-CH₂-CHCl₂;D=CH₃-CCl₂-CH₃", "a": "A", "e": "Quy tắc Markovnikov: H gắn vào C có nhiều H hơn (CH₂ có 2H), Cl gắn vào C ít H hơn (CH có 1H) → 2-chloropropane."}, {"k": "m", "ch": "g11c1", "q": "Khí dầu mỏ hóa lỏng (LPG: Liquefied Petroleum Gas) chứa chủ yếu hai khí nào sau đây?", "o": "A=Methane và ethane;B=Propane và pentane;C=Ethane và propane;D=Propane và butane", "a": "D", "e": "LPG (gas bình) là hỗn hợp propane (C₃H₈) và butane (C₄H₁₀) — hai alkane dễ hóa lỏng dưới áp suất."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây là đồng phân của CH₂=CHCH₂CH₂CH₃?", "o": "A=(CH₃)₂C=CHCH₃;B=CH₂=CHCH₂CH₃;C=CH≡CCH₂CH₂CH₃;D=CH₂=CHCH₂CH=CH₂", "a": "A", "e": "Pent-1-ene có CTPT C₅H₁₀. (CH₃)₂C=CHCH₃ (2-methylbut-2-ene) cũng C₅H₁₀ → đồng phân. B là C₄H₈, C là C₅H₈, D là C₅H₈."}, {"k": "m", "ch": "g11c1", "q": "Công thức phân tử của styrene là", "o": "A=C₇H₁₄;B=C₈H₈;C=C₆H₆;D=C₇H₈", "a": "B", "e": "Styrene = C₆H₅–CH=CH₂ → 6C+5H (vòng) + 2C+3H (nhánh) = 8C+8H = C₈H₈."}, {"k": "m", "ch": "g11c1", "q": "Chất nào trong 4 chất dưới đây có thể tham gia cả 4 phản ứng: Phản ứng cháy trong oxi, phản ứng cộng bromine, phản ứng cộng hydrogen (Ni, t°), phản ứng thế với dung dịch AgNO₃/NH₃?", "o": "A=ethane;B=ethylene;C=acetylene;D=cyclopropane", "a": "C", "e": "Phản ứng với AgNO₃/NH₃ chỉ xảy ra với alk-1-yne (có H gắn C≡C đầu mạch). Acetylene HC≡CH thoả mãn điều kiện này."}, {"k": "m", "ch": "g11c1", "q": "Để phân biệt ethane và ethene, dùng phản ứng nào là thuận tiện nhất?", "o": "A=Phản ứng đốt cháy;B=Phản ứng với hydrogen;C=Phản ứng với nước bromine;D=Phản ứng trùng hợp", "a": "C", "e": "Nước bromine cho hiện tượng trực quan ngay (mất màu nâu đỏ) — chỉ ethene (alkene) phản ứng, ethane (alkane) không."}, {"k": "m", "ch": "g11c1", "q": "Phát biểu nào sau đây không đúng?", "o": "A=Trong phân tử hydrocarbon, số nguyên tử hydrogen luôn là số chẵn;B=Trong phân tử alkene, liên kết đôi gồm một liên kết σ và một liên kết π;C=Hydrocarbon không no là hydrocarbon mà trong phân tử chứa liên kết bội;D=Công thức chung của hydrocarbon no, mạch hở có dạng CₙH₂ₙ", "a": "D", "e": "Alkane (no, mạch hở) có CTTQ CₙH₂ₙ₊₂. CₙH₂ₙ là CT của alkene mạch hở hoặc cycloalkane."}, {"k": "m", "ch": "g11c1", "q": "Alkene X có tên gọi 2,3-dimethylhept-2-ene. Công thức phân tử của X là", "o": "A=C₇H₁₄;B=C₈H₁₆;C=C₉H₁₈;D=C₉H₁₆", "a": "C", "e": "Hept = 7C, thêm 2 nhánh methyl = 2C → tổng 9C. Là alkene → CₙH₂ₙ → C₉H₁₈."}, {"k": "m", "ch": "g11c1", "q": "Chất nào sau đây có khả năng tác dụng với dung dịch AgNO₃/NH₃?", "o": "A=but-2-yne;B=ethylene;C=but-1-yne;D=but-2-ene", "a": "C", "e": "Chỉ alk-1-yne (C≡CH ở đầu mạch) phản ứng tạo kết tủa vàng với AgNO₃/NH₃. But-1-yne CH≡C-CH₂-CH₃ thoả mãn."}, {"k": "m", "ch": "g11c1", "q": "Hyđrocarbon chỉ có liên kết đơn trong phân tử là", "o": "A=alkene;B=alkyne;C=arene;D=alkane", "a": "D", "e": "Alkane là hydrocarbon NO — chỉ có liên kết đơn C-C và C-H."}, {"k": "m", "ch": "g11c1", "q": "Alkyne CH₃C≡CCH₃ có tên gọi là", "o": "A=but-1-yne;B=but-2-yne;C=pent-2-yne;D=but-3-yne", "a": "B", "e": "4C, liên kết ba ở C2-C3 → đánh số từ đầu nào cũng cho vị trí 2 → but-2-yne."}, {"k": "m", "ch": "g11c1", "q": "Alkene là các hidrocarbon không no, mạch hở, có công thức chung là", "o": "A=CₙH₂ₙ₊₂ (n≥1);B=CₙH₂ₙ (n≥2);C=CₙH₂ₙ₋₂ (n≥2);D=CₙH₂ₙ₋₆ (n≥6)", "a": "B", "e": "Alkene mạch hở có 1 liên kết đôi → CTTQ CₙH₂ₙ với n≥2 (cần ít nhất 2C để có C=C)."}, {"k": "m", "ch": "g11c1", "q": "Hợp chất nào dưới đây được dùng để tổng hợp PVC?", "o": "A=vinyl chloride (CH₂=CHCl);B=ethylene;C=acetylene;D=propene", "a": "A", "e": "PVC = poly(vinyl chloride) → trùng hợp từ monomer vinyl chloride CH₂=CHCl."}, {"k": "m", "ch": "g11c1", "q": "Hợp chất gây ra lỗ thủng tầng ozone là", "o": "A=CO₂;B=CFC (freon);C=CH₄;D=SO₂", "a": "B", "e": "CFC (chlorofluorocarbon) phân huỷ trong khí quyển → giải phóng Cl• tự do, phá huỷ O₃."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nW: Một diol chứa hai nhóm alcohol bậc một", "a": "false", "e": "Sai. But-1-ene CH₂=CH-CH₂-CH₃ + KMnO₄ → HOCH₂-CHOH-CH₂-CH₃ (1 OH bậc 1, 1 OH bậc 2)."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nX: Một diol chứa một nhóm alcohol bậc một và một nhóm alcohol bậc hai", "a": "true", "e": "Đúng. Đây chính là sản phẩm từ but-1-ene."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nY: Một diol chứa hai nhóm alcohol bậc hai", "a": "true", "e": "Đúng. But-2-ene CH₃-CH=CH-CH₃ + KMnO₄ → CH₃-CHOH-CHOH-CH₃ (cả 2 OH đều bậc 2)."}, {"k": "tf", "ch": "g11c1", "q": "But-1-ene và but-2-ene lần lượt được tiến hành phản ứng với dung dịch KMnO₄ (ở nhiệt độ thường). Bốn học sinh W, X, Y, Z phát biểu về các alkene này và các diol tạo thành:\nZ: Cả hai alkene đều có đồng phân cis-trans", "a": "false", "e": "Sai. But-1-ene KHÔNG có đp cis-trans (1 đầu C có 2H giống nhau). Chỉ but-2-ene có cis-trans."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nAcetylene + H₂ (xt Lindlar) thu được ethane", "a": "false", "e": "Sai. Lindlar là xúc tác BÁN TÍNH (Pd/PbCO₃) → chỉ cộng 1 H₂ → tạo ETHYLENE chứ không phải ethane."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nPhản ứng cộng H₂ của propylene: CH₂=CH-CH₃ + H₂ → CH₃-CH₂-CH₃", "a": "true", "e": "Đúng. Propene cộng H₂ (Ni, t°) → propane."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nPhản ứng cộng H₂ vào liên kết bội luôn cần xúc tác kim loại", "a": "true", "e": "Đúng. Cần Ni/Pt/Pd để hoạt hoá H₂ thành H nguyên tử."}, {"k": "tf", "ch": "g11c1", "q": "Hydrogen hóa alkene và alkyne thu được alkane tương ứng. Phản ứng thường được thực hiện dưới áp suất cao, nhiệt độ cao và có mặt các chất xúc tác kim loại như platinum, nickel và palladium.\nSản phẩm cộng H₂ của ethylene là methane", "a": "false", "e": "Sai. CH₂=CH₂ + H₂ → CH₃-CH₃ (ethane), không phải methane."}, {"k": "n", "ch": "g11c1", "q": "Cho hợp chất HC≡C–CH₂OH lần lượt tác dụng với các chất sau: Cu(OH)₂; dd AgNO₃/NH₃; H₂ (Ni, t°); Na; nước bromine; dd KMnO₄; dd NaOH. Có bao nhiêu chất phản ứng được với hợp chất này?", "a": "5", "e": "Phản ứng được với 5 chất: AgNO₃/NH₃ (do C≡C đầu mạch), H₂ (cộng vào C≡C), Na (do –OH), Br₂ (cộng vào C≡C), KMnO₄ (oxi hoá). KHÔNG phản ứng với Cu(OH)₂ (chỉ poly-OH) và NaOH (alcohol không có tính acid).", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c1", "q": "Muốn điều chế 33,6 lít C₂H₂ (đktc) để hàn cắt kim loại, cần m gam đất đèn (chứa 80% CaC₂). Tính m (gam).", "a": "120", "e": "n(C₂H₂) = 33,6/22,4 = 1,5 mol. CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂ → n(CaC₂) = 1,5 mol → m(CaC₂) = 1,5×64 = 96 g. Đất đèn 80% → m = 96/0,8 = 120 g.", "u": "g", "tol": "0.5"}, {"k": "n", "ch": "g11c1", "q": "Cho 7,8 gam acetylene tác dụng với lượng dư AgNO₃/NH₃, thu được m gam kết tủa vàng nhạt (Ag₂C₂). Tính m (gam).", "a": "72", "e": "n(C₂H₂) = 7,8/26 = 0,3 mol. C₂H₂ + 2AgNO₃/NH₃ → AgC≡CAg↓ + 2NH₄NO₃. M(Ag₂C₂) = 240 → m = 0,3 × 240 = 72 g.", "u": "g", "tol": "0.5"}, {"k": "n", "ch": "g11c1", "q": "Da nhân tạo (PVC) được điều chế từ khí thiên nhiên (chứa 80% CH₄) qua sơ đồ: 2CH₄ → C₂H₂ → CH₂=CHCl → PVC. Hiệu suất toàn quá trình 20%. Để điều chế 1 tấn PVC, cần thể tích khí thiên nhiên ở điều kiện chuẩn (24,79 L/mol) là bao nhiêu m³?", "a": "4958", "e": "n(monomer CH₂=CHCl) = 10⁶/62,5 = 16000 mol. Cần 2 mol CH₄ cho 1 mol monomer (theo stoichiometry) → n(CH₄ cần lý thuyết) = 32000 mol. H = 20% → n(CH₄ thực tế) = 32000/0,2 = 160000 mol. V(CH₄) = 160000 × 24,79 = 3,9664×10⁶ L = 3966,4 m³. Khí thiên nhiên 80% CH₄ → V = 3966,4/0,8 ≈ 4958 m³.", "u": "m³", "tol": "5", "ac": "4958.0|4957.5|4960|4959"}, {"k": "n", "ch": "g11c1", "q": "Khi dùng biogas (giả sử chỉ chứa CH₄, ΔH = –890 kJ/mol) để thay khí gas (40% C₃H₈ ΔH=–2220 kJ/mol và 60% C₄H₁₀ ΔH=–2850 kJ/mol theo thể tích), với cùng năng lượng cần dùng thì lượng CO₂ thải ra giảm bao nhiêu %?", "a": "18,9", "e": "Cùng E (kJ): n(CO₂) từ CH₄ = E/890; n(CO₂) từ gas hh = E×3,6/(0,4×2220+0,6×2850) = E×3,6/2598 = E/721,67. % giảm = 1 − 721,67/890 ≈ 18,9%.", "u": "%", "tol": "0.5", "ac": "18.9|19|18,93|18.93"}]}, {"id": "g11t2", "grade": "g11", "ch": "g11on", "title": "Đề 02 · Ôn tập Hoá 11 HK2 (Alcohol, Phenol, Aldehyde & Carboxylic acid)", "timeMin": 45, "qs": [{"k": "tf", "ch": "g11c4", "q": "Menthol là hợp chất hữu cơ tìm thấy trong cây bạc hà, dùng làm hương liệu trong kem đánh răng, kẹo cao su, xi-rô ho.\nThành phần % khối lượng của O trong menthol là 10,256%", "a": "true", "e": "Đúng. M(C₁₀H₂₀O) = 156 → %O = 16/156 × 100 ≈ 10,26%."}, {"k": "n", "ch": "g11c4", "q": "Số đồng phân alcohol có CTPT C₃H₈O là bao nhiêu?", "a": "2", "e": "C₃H₈O có 2 đp alcohol: propan-1-ol (CH₃CH₂CH₂OH) và propan-2-ol (CH₃CHOHCH₃). (Đồng phân thứ 3 là dimethyl ether CH₃OCH₃ — không phải alcohol).", "u": "đồng phân", "tol": "0"}, {"k": "n", "ch": "g11c4", "q": "Ứng với CTPT C₄H₁₀O có bao nhiêu đồng phân alcohol?", "a": "4", "e": "4 đp: butan-1-ol, butan-2-ol, 2-methylpropan-1-ol (isobutyl alcohol), 2-methylpropan-2-ol (tert-butyl alcohol).", "u": "đồng phân", "tol": "0"}, {"k": "n", "ch": "g11c4", "q": "Xăng sinh học E5 chứa bao nhiêu % ethanol theo thể tích?", "a": "5", "e": "Ký hiệu E5 = 5% ethanol theo thể tích, 95% xăng truyền thống. (E10 = 10%, E85 = 85%.)", "u": "%", "tol": "0", "ac": "5%|5.0|5,0"}, {"k": "n", "ch": "g11c4", "q": "Để thu được 460 mL ethanol 50° (d = 0,8 g/mL) ở hiệu suất 50% (toàn quá trình tinh bột → glucose → ethanol), cần dùng bao nhiêu gam nếp (chứa 80% tinh bột)?", "a": "810", "e": "V(C₂H₅OH nguyên chất) = 460×50/100 = 230 mL → m = 184 g → n = 4 mol. (C₆H₁₀O₅)ₙ → nC₆H₁₂O₆ → 2nC₂H₅OH. n(tinh bột) = 4/2 = 2 mol đơn vị → m lý thuyết = 324 g. H=50% → m thực tế = 648 g. Nếp 80% tinh bột → m(nếp) = 648/0,8 = 810 g.", "u": "g", "tol": "5"}, {"k": "n", "ch": "g11c4", "q": "Xăng E10 chứa 10% ethanol và 90% octan theo khối lượng. Nhiệt cháy: ethanol 29,6 kJ/g, octan 47,9 kJ/g. Cần đốt bao nhiêu TẤN xăng E10 để sinh ra 3 502 000 kJ?", "a": "0,076", "e": "Năng lượng/g E10 = 0,1×29,6 + 0,9×47,9 = 46,07 kJ/g. m = 3 502 000/46,07 ≈ 76 013 g ≈ 76 kg ≈ 0,076 tấn.", "u": "tấn", "tol": "0.002", "ac": "0.076|0,0760|76|76,0"}, {"k": "n", "ch": "g11c4", "q": "Chuẩn độ 5 mL huyết tương người lái xe bằng K₂Cr₂O₇ 0,01 M, cần 2 mL (Cr₂O₇²⁻ + 3 C₂H₅OH + 8H⁺ → 2Cr³⁺ + 3 CH₃CHO + 7H₂O). Tính nồng độ C₂H₅OH (mg/100 mL) trong máu?", "a": "55,2", "e": "n(K₂Cr₂O₇) = 2×10⁻³ × 0,01 = 2×10⁻⁵ mol → n(C₂H₅OH) = 3 × 2×10⁻⁵ = 6×10⁻⁵ mol. m = 6×10⁻⁵ × 46 = 2,76×10⁻³ g = 2,76 mg trong 5 mL → trong 100 mL = 2,76 × 20 = 55,2 mg/100 mL. Vi phạm Nghị định 100 (vì > 0).", "u": "mg/100mL", "tol": "0.5", "ac": "55.2"}, {"k": "m", "ch": "g11c5", "q": "Phenol và ethanol đều tác dụng được với chất nào sau đây?", "o": "A=dung dịch NaCl;B=dung dịch NaOH;C=nước bromine;D=Na", "a": "D", "e": "Cả phenol và ethanol đều có -OH → tác dụng với Na giải phóng H₂. NaOH chỉ phản ứng với phenol, Br₂ chỉ phản ứng với phenol (vòng)."}, {"k": "m", "ch": "g11c5", "q": "Cho m gam phenol (C₆H₅OH) tác dụng với NaOH thu được 23,2 gam muối C₆H₅ONa. Giá trị của m là", "o": "A=21,2 gam;B=16,51 gam;C=23,5 gam;D=18,8 gam", "a": "D", "e": "n(C₆H₅ONa) = 23,2/116 = 0,2 mol → n(phenol) = 0,2 mol → m = 0,2 × 94 = 18,8 g."}, {"k": "m", "ch": "g11c5", "q": "Nguyên nhân phản ứng thế bromine vào vòng thơm của phenol xảy ra dễ dàng hơn so với benzene là do", "o": "A=phenol có khối lượng phân tử nhỏ hơn;B=cặp e tự do của O liên hợp với vòng → tăng mật độ e ở vòng;C=phenol tan trong nước;D=phenol có nhiệt độ sôi cao hơn", "a": "B", "e": "Cặp e chưa dùng của O liên hợp π vào vòng → đẩy e vào vòng → vị trí o, p giàu e → dễ thế electrophile (Br⁺)."}, {"k": "m", "ch": "g11c5", "q": "Phenol không phản ứng với chất nào sau đây?", "o": "A=Na;B=NaOH;C=Br₂ (nước);D=NaHCO₃", "a": "D", "e": "Phenol có tính acid YẾU hơn H₂CO₃ → KHÔNG đẩy được CO₂ ra khỏi muối carbonate → không phản ứng với NaHCO₃."}, {"k": "m", "ch": "g11c5", "q": "Số hợp chất đồng phân cấu tạo có CTPT C₈H₁₀O, trong phân tử có vòng benzene và tác dụng được với NaOH là", "o": "A=3;B=4;C=5;D=6", "a": "A", "e": "Tác dụng với NaOH → có -OH gắn trực tiếp vào vòng (phenol). C₈H₁₀O với vòng benzene + 1 phenolic-OH = methylphenol có 3 đp ortho/meta/para của ethyl... thực tế: 3 cresol bậc 2 (xylenol)."}, {"k": "m", "ch": "g11c5", "q": "Chất X không phải là phenol. Vậy X là", "o": "A=C₆H₅-OH;B=p-CH₃-C₆H₄-OH;C=C₆H₅-CH₂-OH;D=p-OH-C₆H₄-OH", "a": "C", "e": "Benzyl alcohol C₆H₅-CH₂-OH có -OH gắn vào C no (CH₂), không gắn trực tiếp vào vòng → đó là alcohol thơm, không phải phenol."}, {"k": "m", "ch": "g11c5", "q": "Phát biểu không đúng khi nói về tính chất vật lí của phenol là", "o": "A=Phenol là chất rắn ở điều kiện thường;B=Phenol tan vô hạn trong nước lạnh;C=Phenol có mùi đặc trưng;D=Phenol để lâu ngoài không khí có màu hồng", "a": "B", "e": "Phenol ÍT tan trong nước lạnh (chỉ tan ~8,3 g/100mL ở 25°C), tan tốt trong nước nóng. Không tan vô hạn."}, {"k": "m", "ch": "g11c5", "q": "Để loại bỏ nhanh muối phenolate, người ta thường tái tạo phenol từ C₆H₅ONa bằng cách", "o": "A=cho tác dụng với HCl;B=đun nóng dung dịch;C=cho vào nước;D=thêm NaOH", "a": "A", "e": "C₆H₅ONa + HCl → C₆H₅OH + NaCl. Phản ứng này dùng để tách phenol từ muối."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPhản ứng chứng minh ảnh hưởng của -OH lên gốc phenyl", "a": "true", "e": "Đúng. -OH hoạt hoá vòng → dễ thế ở vị trí 2,4,6."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid kết tủa màu trắng", "a": "false", "e": "Sai. Picric acid có MÀU VÀNG (do 3 nhóm NO₂)."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid có tính acid mạnh hơn phenol", "a": "true", "e": "Đúng. 3 nhóm NO₂ hút e mạnh → H trong -OH linh động hơn → acid mạnh hơn ~10⁹ lần."}, {"k": "tf", "ch": "g11c5", "q": "Picric acid (2,4,6-trinitrophenol) được tổng hợp bằng cách nitro hoá phenol. Cho các phát biểu:\nPicric acid được dùng làm thuốc nổ, thuộc da, phẩm nhuộm", "a": "true", "e": "Đúng. Đây là 3 ứng dụng kinh điển của picric acid."}, {"k": "n", "ch": "g11c5", "q": "Cho dãy các chất sau: phenol, ethanol, ethyl chloride, o-cresol, glycerol. Có bao nhiêu chất phản ứng được với sodium kim loại (Na)?", "a": "4", "e": "Phản ứng với Na cần –OH (alcohol/phenol). 4 chất: phenol, ethanol, o-cresol, glycerol. Ethyl chloride C₂H₅Cl KHÔNG có –OH → không phản ứng.", "u": "chất", "tol": "0"}, {"k": "n", "ch": "g11c5", "q": "Cho 4,02 g hỗn hợp X gồm phenol và propan-1-ol tác dụng với nước Br₂ dư, thu được 9,93 g kết tủa trắng (2,4,6-tribromophenol). Tính %m của phenol trong X (%).", "a": "70,15", "e": "M(C₆H₂Br₃OH) = 331. n(kết tủa) = 9,93/331 = 0,03 mol = n(phenol). m(phenol) = 0,03 × 94 = 2,82 g. %m = 2,82/4,02 × 100 ≈ 70,15%. (Propan-1-ol không phản ứng Br₂).", "u": "%", "tol": "0.2", "ac": "70.15"}, {"k": "n", "ch": "g11c5", "q": "Hỗn hợp ethanol + phenol + Na dư → 3,7185 L H₂ (đkc, 24,79 L/mol). Cùng hỗn hợp + Br₂ vừa đủ → 19,86 g kết tủa trắng. Tính %m phenol trong hỗn hợp (%).", "a": "33,81", "e": "n(H₂) = 0,15 mol → n(ROH tổng) = 0,3 mol. n(C₆H₂Br₃OH) = 19,86/331 = 0,06 mol = n(phenol). n(ethanol) = 0,24 mol. m(phenol) = 5,64 g, m(ethanol) = 11,04 g, tổng 16,68 g. %phenol = 5,64/16,68 × 100 ≈ 33,81%.", "u": "%", "tol": "0.2", "ac": "33.81|33,8|33.8"}, {"k": "n", "ch": "g11c5", "q": "Để định lượng vanillin (HO-C₆H₃(OCH₃)-CHO, M=152) trong mẫu 0,120 g, hoà mẫu trong dung môi rồi chuẩn độ vừa đủ với 7,82 mL NaOH 0,1 M. Tính %m vanillin trong mẫu (%).", "a": "99,05", "e": "Vanillin có 1 –OH phenol → 1:1 với NaOH. n(vanillin) = 7,82×10⁻³ × 0,1 = 7,82×10⁻⁴ mol → m = 7,82×10⁻⁴ × 152 = 0,11886 g. %m = 0,11886/0,120 × 100 ≈ 99,05% → đủ tiêu chuẩn (>99%).", "u": "%", "tol": "0.3", "ac": "99.05|99|99.0|99,0"}, {"k": "m", "ch": "g11c6", "q": "Hợp chất nào sau đây tham gia phản ứng tráng bạc?", "o": "A=CH₃OH;B=CH₃CHO;C=CH≡C-CH₂-CH₃;D=CH₃COCH₃", "a": "B", "e": "Phản ứng tráng bạc cần nhóm -CHO (aldehyde). CH₃CHO (acetaldehyde) thoả. Ketone (CH₃COCH₃) không phản ứng."}, {"k": "m", "ch": "g11c6", "q": "Cho CH₃CHO phản ứng với H₂ (xt Ni, đun nóng) thu được sản phẩm là", "o": "A=CH₃COOH;B=HCOOH;C=CH₃CH₂OH;D=CH₃OH", "a": "C", "e": "Aldehyde + H₂ → alcohol bậc 1: CH₃CHO + H₂ → CH₃CH₂OH (ethanol). Đây là phản ứng khử."}, {"k": "m", "ch": "g11c6", "q": "Trong số các hợp chất sau, chất nào dùng để ngâm xác động vật?", "o": "A=dd HCHO (formalin);B=dd CH₃CHO;C=dd CH₃COOH;D=dd CH₃OH", "a": "A", "e": "Formalin = dd HCHO 37-40% → diệt khuẩn, làm cứng protein → bảo quản mẫu sinh học, ướp xác."}, {"k": "m", "ch": "g11c6", "q": "Khối lượng Ag thu được khi cho 0,1 mol CH₃CHO phản ứng hoàn toàn với AgNO₃/NH₃ dư là", "o": "A=16,2 g;B=43,2 g;C=21,6 g;D=10,8 g", "a": "C", "e": "RCHO + 2AgNO₃/NH₃ → 2Ag. n(Ag) = 2 × 0,1 = 0,2 mol → m = 0,2 × 108 = 21,6 g."}, {"k": "m", "ch": "g11c6", "q": "Hợp chất chứa nhóm C=O liên kết với nguyên tử carbon hoặc nguyên tử hydrogen được gọi là", "o": "A=alcohol;B=phenol;C=hợp chất carbonyl;D=carboxylic acid", "a": "C", "e": "Hợp chất carbonyl = chứa nhóm C=O. Bao gồm aldehyde (R-CHO) và ketone (R-CO-R')."}, {"k": "m", "ch": "g11c6", "q": "Hợp chất nào sau đây là aldehyde?", "o": "A=CH₃COCH₃;B=CH₃CHO;C=CH₃COOH;D=CH₃OH", "a": "B", "e": "Aldehyde có nhóm -CHO ở đầu mạch. CH₃CHO = acetaldehyde."}, {"k": "m", "ch": "g11c6", "q": "Tên gọi của hợp chất CH₃-CH(C₂H₅)-CH₂-CHO là", "o": "A=3-ethylbutanal;B=3-methylpentanal;C=2-ethylbutanal;D=2-methylpentanal", "a": "B", "e": "Mạch chính dài nhất chứa CHO: CHO-CH₂-CH(C₂H₅)-CH₃. Đếm từ CHO: C1(CHO)-C2(CH₂)-C3(CH-có ethyl)-C4-C5 = pentanal. Nhánh methyl ở C3 → 3-methylpentanal."}]}], "g11c1": {"title": "Chương 1 · Anken – Ankin", "tagline": "Quy tắc Markovnikov · Trùng hợp · KMnO4", "color": "#2f81f7", "icon": "⚗️", "num": "1", "feynman": "Hãy tưởng tượng carbon như những viên gạch nối với nhau: alkane nối bằng liên kết đơn (1 'cây đinh'), alkene có liên kết đôi C=C (2 cây đinh), alkyne có liên kết ba C≡C (3 cây đinh). Chỗ nào có 2–3 'cây đinh' thì dễ bị tấn công hơn — chính vì vậy alkene và alkyne có phản ứng cộng.", "notes": [{"kind": "table", "t": "Công thức tổng quát alkane – alkene – alkyne", "b": "Loại | Công thức chung | Đặc điểm | Ví dụ\nAlkene | CₙH₂ₙ (n ≥ 2) | 1 liên kết đôi C=C | C₂H₄ (ethylene), C₃H₆ (propylene)\nAlkyne | CₙH₂ₙ₋₂ (n ≥ 2) | 1 liên kết ba C≡C | C₂H₂ (acetylene), C₃H₄ (propyne)\nAlkane | CₙH₂ₙ₊₂ (n ≥ 1) | Chỉ liên kết đơn (so sánh) | CH₄, C₂H₆, C₃H₈"}, {"kind": "trick", "t": "Mẹo nhớ công thức", "b": "Alkane -> Alkene -> Alkyne: mỗi lần 'bớt' 2H khi hình thành 1 liên kết pi thêm.\nAlkane = 2n+2 H | Alkene = 2n H (bớt 2) | Alkyne = 2n−2 H (bớt thêm 2)"}, {"kind": "rxn", "t": "Phản ứng cộng Br₂ — nhận biết alkene/alkyne", "b": "CH₂=CH₂ + Br₂ -> CH₂Br–CH₂Br (dung dịch bromine mất màu cam -> mất màu = có liên kết đôi/ba)\nCH≡CH + Br₂ -> CHBr=CHBr + Br₂ -> CHBr₂–CHBr₂ (alkyne cộng 2 lần, tổng cộng 2 mol Br₂)\nLưu ý: Alkane KHÔNG làm mất màu Br₂ ở điều kiện thường. Propane + Br₂ -> không phản ứng; Propene + Br₂ -> mất màu ngay!"}, {"kind": "rule", "t": "Quy tắc Markovnikov (cộng HX vào alkene bất đối xứng)", "b": "H cộng vào C nào nhiều H hơn, X cộng vào C còn lại (ít H hơn).\nCH₂=CH–CH₃ + HCl -> CH₃–CHCl–CH₃ (sản phẩm chính), KHÔNG phải CH₂Cl–CH₂–CH₃\nMẹo nhớ: 'Nhà giàu thêm giàu' — H đến chỗ đã nhiều H (giàu H), X đến chỗ ít H (nghèo H)."}, {"kind": "rxn", "t": "Phản ứng oxi hóa bằng KMnO₄", "b": "3CH₂=CH₂ + 2KMnO₄ + 4H₂O -> 3HO–CH₂–CH₂–OH + 2MnO₂↓ + 2KOH (dung dịch tím bị mất màu -> nhận biết alkene)"}, {"kind": "danger", "t": "Phân biệt Br₂ và KMnO₄", "b": "Cả hai đều bị mất màu bởi alkene/alkyne. Nhưng Br₂ cũng phản ứng với alkyne theo 2 bước. KMnO₄ oxy hóa cắt đôi liên kết -> cho diol hoặc acid/CO₂ tùy điều kiện."}, {"kind": "rxn", "t": "Phản ứng trùng hợp (polymer)", "b": "n CH₂=CH₂ ->(t°, xt, p) [–CH₂–CH₂–]ₙ (polyethylene – PE, túi nilon)\nn CH₂=CH–CH=CH₂ ->(Na, t°) [–CH₂–CH=CH–CH₂–]ₙ (polybutadiene – cao su tổng hợp)"}, {"kind": "rxn", "t": "Phản ứng đặc trưng của alk-1-yne: thế H linh động", "b": "Nếu C≡C ở đầu mạch (C-1), H gắn vào nó linh động, dễ bị thay thế bởi ion kim loại — tính chất đặc trưng chỉ có ở alk-1-yne.\nCH≡CH + 2AgNO₃ + 2NH₃ -> AgC≡CAg↓ + 2NH₄NO₃ (kết tủa vàng nhạt -> nhận biết alk-1-yne)\nCH≡C–R + AgNO₃/NH₃ -> AgC≡C–R↓ + NH₄NO₃ (propyne, but-1-yne... cũng cho phản ứng này)"}, {"kind": "danger", "t": "Bẫy thường gặp", "b": "But-2-yne (CH₃–C≡C–CH₃) KHÔNG có phản ứng với AgNO₃/NH₃ vì C≡C ở giữa mạch, không có H linh động."}, {"kind": "rxn", "t": "Điều chế acetylene", "b": "CaC₂ + 2H₂O -> Ca(OH)₂ + C₂H₂↑ (đất đèn + nước -> acetylene, phương pháp phòng thí nghiệm)\n2CH₄ ->(1500°C, làm lạnh nhanh) C₂H₂ + 3H₂ (công nghiệp: nhiệt phân methane)"}], "exercises": [{"n": 1, "q": "Muốn điều chế 33,6 lít khí acetylene (đktc) cần m gam đất đèn (80% CaC₂). Tính m?", "opts": "", "a": "120", "steps": ["Tính số mol C₂H₂ cần điều chế: n(C₂H₂) = V/22,4 = 33,6/22,4 = 1,5 mol", "Phương trình: CaC₂ + 2H₂O -> Ca(OH)₂ + C₂H₂. Theo PT: n(CaC₂) = n(C₂H₂) = 1,5 mol", "M(CaC₂) = 40 + 24 = 64 g/mol; m(CaC₂) = 1,5 × 64 = 96 g", "Đất đèn chứa 80% CaC₂ nên m(đất đèn) = 96 / 0,80 = 120 g"], "ans": "120 g", "unit": "g", "tol": "1"}, {"n": 2, "q": "Propene (CH₂=CH–CH₃) + HCl -> sản phẩm chính là gì? Giải thích quy tắc Markovnikov.", "opts": "", "a": "", "steps": ["Xác định hai carbon ở liên kết đôi: C1 (=CH₂) có 2H, C2 (=CH–) có 1H", "Áp dụng Markovnikov: H -> C nhiều H hơn (C1 = CH₂), Cl -> C ít H hơn (C2 = CH–)", "CH₂=CH–CH₃ + HCl -> CH₃–CHCl–CH₃ (2-chloropropane, sản phẩm chính); CH₂Cl–CH₂–CH₃ là sản phẩm phụ (vi phạm Markovnikov)"], "ans": "Sản phẩm chính: CH₃–CHCl–CH₃ (2-chloropropane), tương ứng đáp án A. CH₂Cl–CH₂–CH₃ là sản phẩm phụ.", "unit": "", "tol": ""}, {"n": 3, "q": "Cho but-1-ene và but-2-yne cộng H₂ (Ni, t°) thu được sản phẩm gì? Có giống nhau không?", "opts": "", "a": "", "steps": ["But-1-ene + H₂: CH₂=CH–CH₂–CH₃ + H₂ ->(Ni,t°) CH₃–CH₂–CH₂–CH₃ (butane)", "But-2-yne + 2H₂: CH₃–C≡C–CH₃ + 2H₂ ->(Ni,t°) CH₃–CH₂–CH₂–CH₃ (butane)"], "ans": "ĐÚNG — Cả hai đều cho butane. But-1-ene (CₙH₂ₙ) cộng 1 mol H₂; But-2-yne (CₙH₂ₙ₋₂) cộng 2 mol H₂.", "unit": "", "tol": ""}, {"n": 4, "q": "Trong các chất sau, chất nào KHÔNG làm mất màu dung dịch bromine ở điều kiện thường: propane, propylene, propyne, styrene?", "opts": "A=propane;B=propylene;C=propyne;D=styrene", "a": "A", "steps": ["Propane (CH₃–CH₂–CH₃): chỉ có liên kết đơn -> KHÔNG mất màu Br₂. Propylene (CH₂=CH–CH₃): có C=C -> mất màu. Propyne (CH≡C–CH₃): có C≡C -> mất màu. Styrene (C₆H₅–CH=CH₂): có C=C ngoài vòng benzene -> mất màu", "Ví dụ: CH₂=CH–CH₃ + Br₂ -> CH₂Br–CHBr–CH₃ (1,2-dibromopropane)"], "ans": "A — propane. Alkane (chỉ liên kết đơn) không mất màu Br₂; alkene/alkyne/styrene thì mất màu.", "unit": "", "tol": ""}, {"n": 5, "q": "Chất nào tham gia được CẢ 4 phản ứng: cháy O₂, cộng Br₂, cộng H₂ (Ni,t°), thế với AgNO₃/NH₃? (ethane, ethylene, acetylene, cyclopropane)", "opts": "A=ethane;B=ethylene;C=acetylene;D=cyclopropane", "a": "C", "steps": ["Lọc các phản ứng: ethane (C₂H₆): cháy ✅, cộng Br₂ ❌, cộng H₂ ❌, AgNO₃/NH₃ ❌. Ethylene (C₂H₄): ✅ cộng Br₂ và H₂ nhưng ❌ AgNO₃/NH₃. Acetylene (C₂H₂): ✅ cả 4 phản ứng. Cyclopropane: cháy ✅, cộng Br₂/H₂ chỉ trong vài điều kiện đặc biệt, ❌ AgNO₃/NH₃", "Phản ứng đặc trưng: HC≡CH + 2AgNO₃ + 2NH₃ -> AgC≡CAg↓ + 2NH₄NO₃ (kết tủa vàng nhạt — đặc trưng của alk-1-yne)"], "ans": "C — Acetylene (C₂H₂). Chỉ alk-1-yne (HC≡C–R) tạo kết tủa với AgNO₃/NH₃; alk-2-yne (R–C≡C–R') không tạo kết tủa vì không có H ở đầu C≡C.", "unit": "", "tol": ""}, {"n": 6, "q": "Cho but-1-ene và but-2-ene tác dụng với KMnO₄ loãng (nhiệt độ thường). Sản phẩm diol thu được có mấy nhóm OH bậc nào? Có đồng phân cis-trans không?", "opts": "", "a": "", "steps": ["KMnO₄ loãng hydroxyl hóa C=C: C có 2H (=CH₂) -> CH₂OH (bậc 1); C có 1H (=CH–) -> CHOH (bậc 2); C có 0H (=C<) -> C–OH (bậc 3)", "But-1-ene: 3CH₂=CH–CH₂–CH₃ + 2KMnO₄ + 4H₂O -> 3CH₂OH–CHOH–CH₂–CH₃ + 2MnO₂↓ + 2KOH. Diol có 1 nhóm OH bậc 1 + 1 nhóm OH bậc 2", "But-2-ene: 3CH₃–CH=CH–CH₃ + 2KMnO₄ + 4H₂O -> 3CH₃–CHOH–CHOH–CH₃ + 2MnO₂↓ + 2KOH. Diol có 2 nhóm OH bậc 2", "Đồng phân hình học: but-1-ene (một đầu C=C có 2H giống nhau) không có cis-trans; but-2-ene (mỗi C ở C=C có 2 nhóm khác nhau: H và CH₃) có cis-trans"], "ans": "(a) Diol chứa 2 OH bậc 1: SAI; (b) 1 OH bậc 1 + 1 OH bậc 2: ĐÚNG (but-1-ene); (c) 2 OH bậc 2: ĐÚNG (but-2-ene); (d) Cả hai đều có cis-trans: SAI (chỉ but-2-ene có)", "unit": "", "tol": ""}]}, "g11c2": {"title": "Chương 2 · Arene", "tagline": "Nitro hoá · Halogen hoá · Quy tắc thế", "color": "#f78166", "icon": "☕", "num": "2", "feynman": "Benzene (C₆H₆) là vòng 6 carbon, 6 electron π chia đều cho cả vòng nên vòng thơm rất bền. Benzene không thích phản ứng cộng như alkene mà thích phản ứng thế (thay H bằng nhóm khác, giữ nguyên vòng bền).", "notes": [{"kind": "table", "t": "Bảng tên gọi và công thức arene", "b": "Tên thường | Công thức | Cần nhớ\nBenzene | C₆H₆ | Vòng thuần túy\nToluene | C₆H₅–CH₃ | Benzene + 1 CH₃\nStyrene | C₆H₅–CH=CH₂ | Có liên kết đôi ngoài -> làm mất màu Br₂!\nNaphthalene | C₁₀H₈ | 2 vòng benzene gộp lại"}, {"kind": "danger", "t": "Bẫy: Styrene (C₈H₈)", "b": "Styrene CÓ làm mất màu Br₂ do liên kết đôi C=C bên ngoài vòng. Benzene và toluene thì KHÔNG làm mất màu Br₂ ở điều kiện thường (phải có xúc tác Fe)."}, {"kind": "rxn", "t": "Phản ứng nitro hóa benzene", "b": "C₆H₆ + HNO₃ ->(H₂SO₄ đặc, ≤50°C) C₆H₅NO₂ + H₂O\n(nitrobenzene — chất lỏng, màu vàng, mùi hạnh nhân)"}, {"kind": "danger", "t": "Sai phổ biến: CTPT nitrobenzene", "b": "Công thức phân tử nitrobenzene là C₆H₅NO₂ (KHÔNG phải C₆H₅NO₃!). Nhóm nitro là –NO₂ (N có 2 O), không phải NO₃."}, {"kind": "rxn", "t": "Phản ứng halogen hóa (thế H trên vòng, cần Fe)", "b": "C₆H₆ + Br₂ ->(Fe, t°) C₆H₅Br + HBr (bromobenzene — phân biệt với phản ứng cộng Br₂ của alkene)"}, {"kind": "rxn", "t": "Phản ứng cộng H₂ (điều kiện khắc nghiệt hơn alkene)", "b": "C₆H₆ + 3H₂ ->(Ni, 180°C, cao áp) C₆H₁₂ (cyclohexane)"}, {"kind": "rxn", "t": "Phản ứng cháy", "b": "2C₆H₆ + 15O₂ ->(t°) 12CO₂ + 6H₂O\n(cháy tạo nhiều muội đen — do tỉ lệ C:H cao)"}], "exercises": [{"n": 1, "q": "Nitro hóa benzene -> nitrobenzene. Công thức phân tử X là gì? X có màu gì? X là chất lỏng hay rắn?", "opts": "", "a": "", "steps": ["C₆H₆ + HNO₃ -> C₆H₅NO₂ + H₂O: nhóm –NO₂ thế vào H trên vòng benzene", "Tính chất vật lý của nitrobenzene: chất LỎNG, sánh như dầu; màu VÀNG; mùi hạnh nhân; CTPT C₆H₅NO₂ (không phải C₆H₅NO₃)"], "ans": "X là nitrobenzene: CTPT C₆H₅NO₂, chất lỏng, màu vàng, mùi hạnh nhân. Phát biểu nói CTPT là C₆H₅NO₃ là SAI.", "unit": "", "tol": ""}, {"n": 2, "q": "Công thức phân tử của styrene là gì? Vì sao styrene làm mất màu Br₂ ở điều kiện thường còn benzene thì không?", "opts": "", "a": "", "steps": ["Cấu trúc styrene C₆H₅–CH=CH₂: vòng benzene C₆H₅ (6C + 5H) + nhánh CH=CH₂ (2C + 3H) -> tổng 8C + 8H = C₈H₈", "Phản ứng với Br₂ chỉ vào C=C ngoài vòng: C₆H₅–CH=CH₂ + Br₂ -> C₆H₅–CHBr–CH₂Br (1-phenyl-1,2-dibromoethane). Vòng benzene không tham gia (bền, chỉ thế khi có Fe)"], "ans": "Đáp án: B — C₈H₈. Styrene LÀM mất màu Br₂ (do C=C ngoài vòng), khác benzene và toluene (KHÔNG mất màu Br₂ ở điều kiện thường).", "unit": "", "tol": ""}, {"n": 3, "q": "Từ 1 tấn toluene có thể điều chế được bao nhiêu kg 2,4,6-trinitrotoluene (TNT) biết hiệu suất phản ứng là 62%?", "opts": "", "a": "1529", "steps": ["Phương trình: C₆H₅CH₃ + 3HNO₃ ->(H₂SO₄ đặc) C₆H₂(NO₂)₃CH₃ + 3H₂O; M(toluene) = 92, M(TNT) = 227. Nhóm CH₃ đẩy electron kích hoạt vị trí ortho và para -> 3 nhóm NO₂ vào vị trí 2, 4, 6", "Tính theo lý thuyết (H = 100%): n(toluene) = 1000/92 ≈ 10,87 kmol; n(TNT) = 10,87 kmol; m(TNT) lý thuyết = 10,87 × 227 = 2 467 kg", "Tính thực tế (H = 62%): m(TNT) = 2 467 × 0,62 = 1 529,5 ≈ 1 529 kg"], "ans": "≈ 1 529 kg", "unit": "kg", "tol": "1"}, {"n": 4, "q": "Có thể nhận biết 3 chất benzene, toluene, styrene bằng dung dịch KMnO₄ không? Mô tả hiện tượng từng chất.", "opts": "", "a": "", "steps": ["Nguyên tắc: vòng benzene thuần rất bền -> không phản ứng với KMnO₄; có H ở C cạnh vòng (C-α, như toluene) -> đun nóng bị oxi hóa CH₃ thành COOH; có C=C ngoài vòng (như styrene) -> mất màu KMnO₄ ngay ở điều kiện thường", "Hiện tượng: Styrene: mất màu ngay và khi đun. Toluene: không phản ứng ở điều kiện thường, đun nóng mất màu tạo C₆H₅COOK. Benzene: không phản ứng trong cả hai trường hợp", "Nhận biết: Bước 1 — KMnO₄ ở điều kiện thường: ống mất màu = styrene, 2 ống còn lại không đổi. Bước 2 — đun nóng: ống mất màu = toluene, ống không đổi = benzene", "Phản ứng oxi hóa toluene khi đun: C₆H₅–CH₃ + 2KMnO₄ ->(t°) C₆H₅–COOK + 2MnO₂↓ + KOH + H₂O"], "ans": "ĐÚNG — KMnO₄ phân biệt được cả 3 chất. Thứ tự ưu tiên phản ứng: C=C ngoài vòng (đk thường) > nhánh CH₃ trên vòng (đun nóng) > vòng benzene thuần (không phản ứng).", "unit": "", "tol": ""}]}, "g11c3": {"title": "Chương 3 · Dẫn xuất halogen", "tagline": "Thuỷ phân · Quy tắc Zaitsev", "color": "#d2a8ff", "icon": "🧪", "num": "3", "feynman": "Dẫn xuất halogen là hydrocarbon bị thay một hoặc nhiều H bằng halogen (F, Cl, Br, I): từ CH₄ thay 1H bằng Cl được CH₃Cl (chloromethane). Nguyên tử halogen này có thể bị 'đẩy đi' bởi OH⁻ (phản ứng thế) hoặc bị 'tách ra' cùng HX (phản ứng tách).", "notes": [{"kind": "rxn", "t": "Phản ứng thủy phân (thế –X bằng –OH)", "b": "CH₃CH₂Br + NaOH ->(H₂O, t°) CH₃CH₂OH + NaBr\n(dung dịch NaOH, đun nóng — phản ứng thế)"}, {"kind": "rxn", "t": "Phản ứng tách HX (NaOH/cồn) cho alkene", "b": "CH₃CH₂Br + NaOH ->(cồn, t°) CH₂=CH₂ + NaBr + H₂O\n(NaOH/cồn, đun nóng — phản ứng tách)"}, {"kind": "trick", "t": "Mẹo phân biệt điều kiện phản ứng", "b": "NaOH nước (dung dịch) -> phản ứng THẾ -> cho alcohol\nNaOH cồn (alcohol) -> phản ứng TÁCH -> cho alkene"}, {"kind": "rule", "t": "Quy tắc Zaitsev khi tách HX", "b": "Khi tách HX khỏi dẫn xuất halogen: X tách ra cùng với H ở carbon bên cạnh có ít H nhất -> cho alkene có nhiều nhóm thế nhất (bền hơn)."}, {"kind": "rxn", "t": "Ví dụ tách HBr theo Zaitsev", "b": "CH₃–CHBr–CH₂–CH₃ + KOH/cồn -> CH₃–CH=CH–CH₃ (but-2-ene) — sản phẩm chính (Zaitsev)\nCH₂=CH–CH₂–CH₃ (but-1-ene) — sản phẩm phụ"}], "exercises": [{"n": 1, "q": "Sự tách HCl của C₄H₉Cl cho 3 alkene đồng phân. X là chất nào?", "opts": "", "a": "", "steps": ["Phân tích các đồng phân C₄H₉Cl: butyl chloride (CH₃CH₂CH₂CH₂Cl) tách -> 1 alkene (but-1-ene); sec-butyl chloride (CH₃CH₂CHClCH₃) tách -> 2 alkene; iso-butyl chloride ((CH₃)₂CHCH₂Cl) tách -> 2 alkene (isobutene + but-1-ene); tert-butyl chloride ((CH₃)₃CCl) tách -> 1 alkene (isobutylene)", "Chất cho 3 alkene là sec-butyl chloride: CH₃–CHCl–CH₂–CH₃ (Cl ở C2). Tách H từ C1 -> but-1-ene; tách H từ C3 -> but-2-ene (cis + trans = 2 đồng phân). Tổng: but-1-ene + cis-but-2-ene + trans-but-2-ene = 3 alkene"], "ans": "Đáp án: B — sec-butyl chloride (CH₃CHClCH₂CH₃)", "unit": "", "tol": ""}, {"n": 2, "q": "Trong thể thao, nhân viên y tế dùng 'thuốc xịt' gây tê cục bộ cho vận động viên. Hợp chất chính trong thuốc xịt đó là chất nào? Tại sao nó gây tê?", "opts": "", "a": "", "steps": ["Phân tích các chất: CO₂ là khí nén, không xịt lỏng thông thường; HCl là khí ăn mòn, gây bỏng -> không dùng; Chloromethane (CH₃Cl) có t°sôi -24°C và độc; Chloroethane (C₂H₅Cl) có t°sôi +12°C, lỏng dễ xịt, an toàn", "Cơ chế gây tê: chloroethane lỏng (trong bình chịu áp suất) khi xịt ra bay hơi cực nhanh -> hấp thu năng lượng từ da -> nhiệt độ da giảm xuống ~0°C -> đầu mút thần kinh bị 'đông lạnh' tạm thời -> tê cục bộ"], "ans": "Đáp án: D — Chloroethane (C₂H₅Cl). Thuốc xịt lạnh (freeze spray) bay hơi nhanh, hấp thu nhiệt từ da làm lạnh đột ngột -> mất cảm giác đau tạm thời.", "unit": "", "tol": ""}, {"n": 3, "q": "Đun nóng CH₃-CH(Br)-CH₂-CH₃ với NaOH/ethanol thu được sản phẩm chính là alkene nào? (Áp dụng quy tắc Zaitsev)", "opts": "", "a": "", "steps": ["Đánh số mạch: C1 = CH₃ (3H, kề C2 có Br); C2 = CH–Br (chứa Br); C3 = CH₂ (2H); C4 = CH₃ (cuối mạch)", "Hai hướng tách HBr: Hướng A — tách Br(C2) + H(C1) -> CH₂=CH–CH₂–CH₃ (but-1-ene); Hướng B — tách Br(C2) + H(C3) -> CH₃–CH=CH–CH₃ (but-2-ene)", "Áp dụng Zaitsev: C3 có ít H hơn C1 nên được ưu tiên tách -> sản phẩm chính là but-2-ene. CH₃–CHBr–CH₂–CH₃ + NaOH/cồn -> CH₃–CH=CH–CH₃ (chính) + NaBr + H₂O; sản phẩm phụ: but-1-ene"], "ans": "Đáp án: B — CH₃–CH=CH–CH₃ (but-2-ene). Quy tắc Zaitsev: alkene nhiều nhóm thế hơn -> bền hơn -> ưu tiên tạo thành.", "unit": "", "tol": ""}]}, "g11c4": {"title": "Chương 4 · Ancol", "tagline": "Na · CuO · H2SO4 · Liên kết hydrogen", "color": "#7ee787", "icon": "🍶", "num": "4", "feynman": "Nhóm –OH gắn vào carbon no (R–OH) như một 'cái tay' đặc biệt: nó tạo liên kết hydrogen với nước nên alcohol tan tốt và sôi cao hơn alkane cùng khối lượng. Ethanol (C₂H₅OH) trong rượu bia là alcohol điển hình nhất. Alcohol tác dụng với Na tạo H₂, bị CuO oxi hóa (bậc 1 -> aldehyde, bậc 2 -> ketone) và tách nước tạo alkene hoặc ether.", "notes": [{"kind": "card", "t": "Alcohol no, đơn chức, mạch hở", "b": "CₙH₂ₙ₊₂O = CₙH₂ₙ₊₁OH (n ≥ 1)\nVí dụ: CH₃OH, C₂H₅OH, C₃H₇OH"}, {"kind": "card", "t": "Bậc của alcohol", "b": "Bậc 1: C mang –OH nối với 1 C khác\nBậc 2: C mang –OH nối với 2 C khác\nBậc 3: C mang –OH nối với 3 C khác"}, {"kind": "card", "t": "Polyalcohol quan trọng – Glycerol", "b": "HOCH₂–CHOH–CH₂OH (C₃H₈O₃, 3 nhóm –OH)\nGlycerol + Cu(OH)₂ -> dung dịch xanh lam đặc trưng\n(Phản ứng đặc trưng của polyalcohol – alcohol có ≥ 2 nhóm –OH kề nhau)"}, {"kind": "rxn", "t": "Tác dụng với kim loại kiềm (Na, K)", "b": "2C₂H₅OH + 2Na -> 2C₂H₅ONa + H₂\n(sodium ethoxide + khí H₂; êm dịu hơn Na + H₂O)\nPhenol + Na phản ứng nhanh hơn vì phenol có tính acid mạnh hơn alcohol."}, {"kind": "rxn", "t": "Oxi hóa bằng CuO (nhận biết bậc alcohol)", "b": "RCH₂OH + CuO ->(t°) RCHO + Cu + H₂O (alcohol bậc 1 -> aldehyde)\nR–CHOH–R' + CuO ->(t°) R–CO–R' + Cu + H₂O (bậc 2 -> ketone)\nCH₃OH + CuO ->(t°) HCHO + Cu + H₂O (methanol cho formaldehyde)\nCuO đen chuyển thành Cu đỏ gạch."}, {"kind": "danger", "t": "Alcohol bậc 3 KHÔNG bị oxi hóa bởi CuO", "b": "Bậc 3 không có H trên C mang –OH -> không phản ứng với CuO ở điều kiện này."}, {"kind": "rxn", "t": "Tách nước với H₂SO₄ đặc", "b": "C₂H₅OH ->(H₂SO₄ đặc, 170°C) CH₂=CH₂ + H₂O (tách nước -> alkene)\n2C₂H₅OH ->(H₂SO₄ đặc, 140°C) C₂H₅–O–C₂H₅ + H₂O (tạo diethyl ether)"}, {"kind": "trick", "t": "Mẹo nhớ nhiệt độ tách nước", "b": "140°C = ether (2 phân tử alcohol ghép qua –O–, nhiệt thấp hơn)\n170°C = alkene (tách mạnh hơn, cắt ra 1 phân tử nước)"}, {"kind": "rxn", "t": "Thế –OH bằng –Br (với HBr)", "b": "C₂H₅OH + HBr ->(H₂SO₄ đặc, t°) C₂H₅Br + H₂O"}, {"kind": "danger", "t": "Những phản ứng thường viết SAI", "b": "✅ C₂H₅OH + HBr -> C₂H₅Br + H₂O (đúng)\n❌ C₂H₅OH + NaOH -> C₂H₅ONa + H₂O (SAI – alcohol không tác dụng NaOH như phenol)\n❌ C₂H₅OH + Na -> C₂H₅Na + H₂O (SAI – phải là C₂H₅ONa + H₂)"}], "exercises": [{"n": 1, "q": "4,6 g alcohol no đơn chức X tác dụng với Na dư thu được 1,2395 L H₂ (đkc). Tìm CTPT của X.", "opts": "A=C₂H₆O;B=C₃H₈O;C=CH₄O;D=C₄H₁₀O", "a": "A", "steps": ["n(H₂) = 1,2395/24,79 = 0,05 mol\n(Lưu ý: đkc mới 1 mol khí = 24,79 L; nếu đktc cũ 22,4 L thì n = 0,0553 mol)", "2ROH + 2Na -> 2RONa + H₂; n(ROH) = 2 × n(H₂) = 0,1 mol", "M(ROH) = 4,6/0,1 = 46 g/mol; CₙH₂ₙ₊₁OH: 14n + 18 = 46 -> n = 2\nCTPT C₂H₆O (ethanol, C₂H₅OH)"], "ans": "A — C₂H₆O (ethanol)", "unit": "", "tol": ""}, {"n": 2, "q": "Số đồng phân alcohol có công thức phân tử C₃H₈O là bao nhiêu?", "opts": "", "a": "2", "steps": ["C₃H₈O = CₙH₂ₙ₊₂O với n = 3: alcohol no, đơn chức; mạch chỉ 3C nên không có nhánh.", "Đặt –OH vào các vị trí:\n• HO–CH₂–CH₂–CH₃ = propan-1-ol (bậc 1)\n• CH₃–CHOH–CH₃ = propan-2-ol (bậc 2)"], "ans": "2 đồng phân alcohol (nếu tính cả ether C₂H₅–O–CH₃: tổng 3 đồng phân)", "unit": "", "tol": ""}, {"n": 3, "q": "Cho X + CuO ->(t°) H-CHO + Cu + H₂O. X là chất nào trong: methanol, ethanol, glycerol, propyl alcohol?", "opts": "A=Methanol (CH₃OH);B=Ethanol (C₂H₅OH);C=Glycerol;D=Propyl alcohol (C₃H₇OH)", "a": "A", "steps": ["Sản phẩm HCHO = H–CHO: để có aldehyde này cần R–CH₂OH với R = H\n-> H–CH₂OH = CH₃OH (methanol)", "Phương trình đầy đủ: CH₃OH + CuO ->(t°) HCHO + Cu + H₂O\nQuy tắc oxi hóa nhẹ (CuO, t°): bậc 1 -> aldehyde, bậc 2 -> ketone, bậc 3 -> không phản ứng."], "ans": "A — Methanol (CH₃OH)", "unit": "", "tol": ""}, {"n": 4, "q": "Ứng với CTPT C₄H₁₀O có bao nhiêu đồng phân alcohol?", "opts": "", "a": "4", "steps": ["Khung carbon C₄: C–C–C–C (thẳng); C–C(C)–C (mạch nhánh iso-butyl)", "Khung thẳng – đặt –OH: C1 -> butan-1-ol (bậc 1); C2 -> butan-2-ol (bậc 2); C3, C4 đối xứng nên không tăng\n-> 2 đồng phân", "Khung nhánh – đặt –OH: đầu mạch -> 2-methylpropan-1-ol (bậc 1); C bậc 3 giữa -> 2-methylpropan-2-ol (bậc 3)\n-> 2 đồng phân", "Tổng 4 đồng phân alcohol.\nNếu tính cả ether C₂H₅–O–C₂H₅, CH₃–O–CH₂CH₂CH₃, CH₃–O–CH(CH₃)₂: tổng 7 đồng phân C₄H₁₀O."], "ans": "4 đồng phân alcohol (tính cả ether: 7)", "unit": "", "tol": ""}, {"n": 5, "q": "Để thu được 460 mL ethanol 50° (d = 0,8 g/mL) từ tinh bột với hiệu suất 50%, cần bao nhiêu gam nếp (chứa 80% tinh bột)?", "opts": "", "a": "810", "steps": ["V(C₂H₅OH) = 460 × 50/100 = 230 mL; m = 230 × 0,8 = 184 g; n = 184/46 = 4 mol", "(C₆H₁₀O₅)ₙ -> 2nC₂H₅OH + 2nCO₂: 1 mắt xích tinh bột (162 g) tạo 2 mol C₂H₅OH\nn(tinh bột lý thuyết) = 4/2 = 2 mol -> m = 2 × 162 = 324 g", "Hiệu suất 50%: m(tinh bột thực tế) = 324/0,5 = 648 g", "Nếp chứa 80% tinh bột: m(nếp) = 648/0,8 = 810 g"], "ans": "810 g nếp", "unit": "g", "tol": "1"}]}, "g11c5": {"title": "Chương 5 · Phenol", "tagline": "Tính acid · Br2 kết tủa trắng", "color": "#46c18c", "icon": "🧴", "num": "5", "feynman": "Phenol có nhóm –OH gắn trực tiếp vào vòng benzene (C₆H₅OH). Vòng benzene kéo electron từ nhóm –OH nên H của –OH linh động hơn: phenol có tính acid mạnh hơn alcohol nhưng yếu hơn H₂CO₃. Vì vậy phenol phản ứng được với NaOH (tạo muối phenoxide) nhưng không phản ứng với NaHCO₃ giải phóng CO₂ — đây là điểm phân biệt phenol với carboxylic acid.", "notes": [{"kind": "card", "t": "Đặc điểm cấu tạo & tính acid", "b": "–OH gắn trực tiếp vào vòng benzene (C₆H₅OH).\nVòng benzene kéo electron từ –OH -> H linh động -> phenol có tính acid.\nThang tính acid: H₂CO₃ > C₆H₅OH > H₂O > ROH (alcohol)."}, {"kind": "rxn", "t": "Thể hiện tính acid (với NaOH và Na)", "b": "C₆H₅OH + NaOH -> C₆H₅ONa + H₂O\n(sodium phenoxide – tan trong nước, dung dịch trong suốt)\n2C₆H₅OH + 2Na -> 2C₆H₅ONa + H₂"}, {"kind": "trick", "t": "So sánh tính acid: Phenol vs Alcohol vs Carbonic acid", "b": "H₂CO₃ > C₆H₅OH > H₂O > ROH\n-> Phenol phản ứng với NaOH (có), với Na₂CO₃/NaHCO₃ (KHÔNG đẩy được CO₂), với HCl (không)\n-> Alcohol không phản ứng với NaOH."}, {"kind": "rxn", "t": "Phản ứng với nước bromine ⭐ (nhận biết phenol)", "b": "C₆H₅OH + 3Br₂ -> C₆H₂Br₃OH↓ + 3HBr\n(2,4,6-tribromophenol: kết tủa TRẮNG – đặc trưng nhận biết phenol)"}, {"kind": "danger", "t": "Phenol + Br₂ khác hẳn benzene + Br₂", "b": "Phenol thế 3H vào vị trí 2,4,6 ngay ở điều kiện thường, KHÔNG cần xúc tác Fe.\nBenzene cần xúc tác Fe và chỉ thế 1H."}, {"kind": "card", "t": "Phenol KHÔNG phản ứng với", "b": "❌ NaHCO₃ (tính acid của phenol yếu hơn H₂CO₃)\n❌ HCl, HBr (phenol không phải base)\n❌ NaCl, KCl (muối trung tính)"}, {"kind": "rule", "t": "Quy tắc tổng kết – Phenol phản ứng với", "b": "✅ Kim loại kiềm (Na, K) -> muối phenoxide + H₂\n✅ Base mạnh (NaOH, KOH) -> muối phenoxide + H₂O\n✅ Br₂ (không cần xúc tác) -> 2,4,6-tribromophenol↓ trắng\n✅ HNO₃ đặc + H₂SO₄ đặc -> picric acid\n❌ NaCl, HCl, HBr, NaHCO₃, H₂CO₃"}, {"kind": "table", "t": "Phenol tác dụng được với những chất nào?", "b": "Chất | Phản ứng? | Lý do\nK (kim loại) | Có | 2C₆H₅OH + 2K -> 2C₆H₅OK + H₂\nNa (kim loại) | Có | 2C₆H₅OH + 2Na -> 2C₆H₅ONa + H₂\nKOH (base mạnh) | Có | C₆H₅OH + KOH -> C₆H₅OK + H₂O\nNaOH (base mạnh) | Có | C₆H₅OH + NaOH -> C₆H₅ONa + H₂O\nBr₂ (đk thường) | Có | C₆H₅OH + 3Br₂ -> C₆H₂Br₃OH↓ + 3HBr\nHCl | Không | Phenol không phải base\nNaHCO₃ | Không | Phenol yếu hơn H₂CO₃, không đẩy CO₂ ra\nH₂CO₃ | Không | H₂CO₃ mạnh hơn phenol"}, {"kind": "rule", "t": "Nhóm thế ảnh hưởng tính acid của phenol", "b": "Nhóm hút electron (–NO₂) làm TĂNG tính acid; nhóm đẩy electron (–CH₃) làm GIẢM tính acid.\nPicric acid (2,4,6-trinitrophenol, C₆H₂(NO₂)₃OH): chất rắn vàng, acid mạnh hơn phenol (mạnh hơn cả H₂CO₃), dùng làm thuốc nổ.\nPhenol Ka ≈ 10⁻¹⁰; picric acid Ka ≈ 10⁻¹ (mạnh hơn ~10⁹ lần)."}], "exercises": [{"n": 1, "q": "Cho m gam phenol phản ứng với NaOH vừa đủ thu được 23,2 g muối. Tính m.", "opts": "A=9,4 gam;B=14,1 gam;C=23,2 gam;D=18,8 gam", "a": "D", "steps": ["C₆H₅OH + NaOH -> C₆H₅ONa + H₂O; M(C₆H₅ONa) = 77 + 23 = 116 g/mol", "n(C₆H₅ONa) = 23,2/116 = 0,2 mol; n(C₆H₅OH) = n(muối) = 0,2 mol", "M(C₆H₅OH) = 94 g/mol; m = 0,2 × 94 = 18,8 g"], "ans": "D — 18,8 gam", "unit": "", "tol": ""}, {"n": 2, "q": "Picric acid được tổng hợp bằng cách nitro hóa phenol. Vì sao picric acid có tính acid mạnh hơn phenol nhiều?", "opts": "", "a": "", "steps": ["C₆H₅OH + 3HNO₃ ->(H₂SO₄ đặc, t°) C₆H₂(NO₂)₃OH + 3H₂O\n(picric acid: chất rắn màu vàng, có tính acid mạnh, dễ nổ)", "(a) Phản ứng chứng minh ảnh hưởng của –OH lên gốc phenyl -> ĐÚNG (nhóm –OH hoạt hóa vòng, dễ thế ở 2,4,6)\n(b) Picric acid kết tủa màu trắng -> SAI (màu vàng)\n(c) Picric acid có tính acid mạnh hơn phenol -> ĐÚNG (3 nhóm –NO₂ hút electron mạnh)\n(d) Picric acid dùng làm thuốc nổ, thuộc da, phẩm nhuộm -> ĐÚNG", "Phenol (Ka ≈ 10⁻¹⁰) yếu, không làm đỏ quỳ; picric acid (Ka ≈ 10⁻¹) mạnh, làm đỏ quỳ rõ rệt.\nNhóm –NO₂ hút electron mạnh làm tăng tính acid; nhóm –CH₃ đẩy electron làm giảm tính acid."], "ans": "(a) Đ, (b) S, (c) Đ, (d) Đ", "unit": "", "tol": ""}, {"n": 3, "q": "Phenol (C₆H₅OH) tác dụng được với chất nào trong dãy: K, KOH, Br₂, Na, NaOH, HCl, NaHCO₃, H₂CO₃?", "opts": "A=K, KOH, Br₂;B=K, NaOH, HCl;C=KOH, NaHCO₃, Br₂;D=Na, NaCl, H₂CO₃", "a": "A", "steps": ["Phenol là acid yếu (yếu hơn H₂CO₃): phản ứng với base mạnh (NaOH, KOH) và kim loại kiềm (Na, K); KHÔNG phản ứng với muối carbonate.", "Vòng benzene 'hoạt hóa': phản ứng với Br₂ ngay ở điều kiện thường (benzene thì cần Fe).", "Kết luận: 2C₆H₅OH + 2K -> 2C₆H₅OK + H₂; C₆H₅OH + KOH -> C₆H₅OK + H₂O; C₆H₅OH + 3Br₂ -> kết tủa trắng.\nKhông phản ứng: HCl, NaHCO₃, H₂CO₃."], "ans": "A — K, KOH, Br₂\n(Phenol acid yếu hơn H₂CO₃ nên không phản ứng NaHCO₃ — khác carboxylic acid: acid + NaHCO₃ -> CO₂)", "unit": "", "tol": ""}]}, "g11c6": {"title": "Chương 6 · Aldehyde – Ketone", "tagline": "Tráng bạc · Iodoform · Cu(OH)2", "color": "#ffa657", "icon": "🍬", "num": "6", "feynman": "Aldehyde và ketone đều chứa nhóm C=O (carbonyl). Aldehyde (R–CHO) có H gắn vào C=O nên 'người giữ chìa khóa' — dễ bị oxi hóa nhẹ: tráng bạc (cho gương bạc), làm đỏ gạch Cu(OH)₂; ketone (R–CO–R') không bị oxi hóa nhẹ. Cả hai đều bị H₂ (Ni, t°) khử thành alcohol.", "notes": [{"kind": "table", "t": "So sánh Aldehyde và Ketone", "b": "Đặc điểm | Aldehyde (R–CHO) | Ketone (R–CO–R')\nNhóm chức | –CHO | C=O ở giữa\nVí dụ | HCHO, CH₃CHO | CH₃COCH₃ (acetone)\nTráng bạc (Tollens) | Có | Không\nCu(OH)₂ đỏ gạch | Có (aldehyde) | Không\nIodoform (I₂/NaOH) | CH₃CHO: có; HCHO: không | CH₃COCH₃: có"}, {"kind": "rxn", "t": "Phản ứng tráng bạc (Tollens) ⭐⭐⭐", "b": "RCHO + 2[Ag(NH₃)₂]OH ->(t°) RCOONH₄ + 2Ag↓ + 3NH₃ + H₂O\n(Bạc bám thành ống tạo 'gương bạc'; 1 mol RCHO -> 2 mol Ag)"}, {"kind": "danger", "t": "HCHO đặc biệt: 1 mol HCHO -> 4 mol Ag", "b": "HCHO có 2 nguyên tử H trong nhóm chức, bị oxi hóa 2 lần:\nHCHO -> HCOOH -> CO₂ + H₂O\nHCHO + 4[Ag(NH₃)₂]OH -> (NH₄)₂CO₃ + 4Ag↓ + 6NH₃ + 2H₂O"}, {"kind": "rxn", "t": "Phản ứng với Cu(OH)₂ trong NaOH", "b": "RCHO + 2Cu(OH)₂ + NaOH ->(t°) RCOONa + Cu₂O↓ + 3H₂O\n(Cu₂O: kết tủa đỏ gạch/đỏ nâu – nhận biết aldehyde)"}, {"kind": "rule", "t": "Điều kiện phản ứng iodoform", "b": "Chất có nhóm CH₃–CO– (methyl ketone), hoặc CH₃CHO (acetaldehyde), hoặc alcohol CH₃–CHOH– (ethanol, propan-2-ol...)"}, {"kind": "rxn", "t": "Phản ứng iodoform (I₂/NaOH)", "b": "CH₃COCH₃ + 3I₂ + 4NaOH -> CHI₃↓ + CH₃COONa + 3NaI + 3H₂O\nCH₃CHO + 3I₂ + 4NaOH -> HCOONa + CHI₃↓ + 3NaI + 3H₂O\n(CHI₃ iodoform: kết tủa vàng, mùi đặc trưng)"}, {"kind": "trick", "t": "Nhớ nhanh: chất nào cho iodoform?", "b": "CH₃CHO ✅ | HCHO ❌\nCH₃COCH₃ (acetone) ✅ | CH₃CH₂CHO ❌\nCH₃CH₂OH (ethanol) ✅ | CH₃OH ❌ | CH₃CH₂CH₂OH ❌\nTừ khóa: phải có CH₃–CO– hoặc CH₃–CHOH–"}, {"kind": "rxn", "t": "Phản ứng khử (cộng H₂) -> alcohol", "b": "CH₃CHO + H₂ ->(Ni, t°) CH₃CH₂OH (aldehyde -> alcohol bậc 1)\nCH₃COCH₃ + H₂ ->(Ni, t°) CH₃CHOH–CH₃ (ketone -> alcohol bậc 2)"}, {"kind": "table", "t": "Tên gọi aldehyde & ketone", "b": "Công thức | Tên thay thế | Tên thường\nHCHO | methanal | formaldehyde\nCH₃CHO | ethanal | acetaldehyde\nCH₃CH₂CHO | propanal | propionaldehyde\nCH₃COCH₃ | propan-2-one | acetone\nC₂H₅COC₂H₅ | pentan-3-one | diethyl ketone"}, {"kind": "trick", "t": "Quy tắc đặt tên ketone", "b": "Đánh số mạch carbon từ phía gần nhóm C=O nhất -> tên: alkan-x-one (x = vị trí nhóm C=O)"}], "exercises": [{"n": 1, "q": "0,1 mol CH₃CHO phản ứng hoàn toàn với AgNO₃/NH₃ dư. Khối lượng Ag thu được là bao nhiêu?", "opts": "A=10,8 gam;B=43,2 gam;C=21,6 gam;D=16,2 gam", "a": "C", "steps": ["CH₃CHO là aldehyde thông thường (không phải HCHO): 1 mol RCHO -> 2 mol Ag", "n(Ag) = 2 × n(CH₃CHO) = 0,2 mol", "m(Ag) = 0,2 × 108 = 21,6 g"], "ans": "C — 21,6 gam", "unit": "", "tol": ""}, {"n": 2, "q": "Trong các chất CH₃CH₂CHO, CH₃COCH₃, CH₃CH₂CH₂OH, CH₃COOH: bao nhiêu chất tác dụng với I₂/NaOH tạo iodoform?", "opts": "", "a": "2", "steps": ["Yêu cầu nhóm CH₃–CO– hoặc CH₃–CHOH–:\n• CH₃CH₂CHO: không có CH₃–CO– hoặc CH₃–CHOH– -> không cho iodoform ❌", "• CH₃COCH₃: có CH₃–CO– ✅\n• CH₃CH₂CH₂OH: nhóm –OH không kề CH₃ ❌\n• CH₃COOH: có CH₃–CO– (carboxylic acid) -> cũng cho iodoform ✅"], "ans": "2 chất (CH₃COCH₃ và CH₃COOH)", "unit": "", "tol": ""}, {"n": 3, "q": "Phân biệt 3 chất HCHO, CH₃CHO, CH₃COCH₃ bằng thuốc thử Tollens và I₂/NaOH.", "opts": "", "a": "", "steps": ["HCHO: Tollens + (Ag↓, 4Ag), I₂/NaOH – (không có CH₃CO–) -> chỉ tráng bạc", "CH₃CHO: Tollens + (Ag↓), I₂/NaOH + (CHI₃↓ vàng) -> cả hai đều có", "CH₃COCH₃: Tollens –, I₂/NaOH + (CHI₃↓ vàng) -> chỉ iodoform"], "ans": "HCHO (chỉ tráng bạc); CH₃COCH₃ (chỉ iodoform); CH₃CHO (cả hai)", "unit": "", "tol": ""}, {"n": 4, "q": "Cho 4,5 g HCHO phản ứng hoàn toàn với lượng dư AgNO₃/NH₃ thu được m gam Ag. Giá trị của m là?", "opts": "", "a": "64.8", "steps": ["M(HCHO) = 30 g/mol; n(HCHO) = 4,5/30 = 0,15 mol", "HCHO là trường hợp đặc biệt: 1 mol HCHO -> 4 mol Ag\nHCHO + 4[Ag(NH₃)₂]OH ->(t°) (NH₄)₂CO₃ + 4Ag↓ + 6NH₃ + 2H₂O", "n(Ag) = 4 × 0,15 = 0,6 mol; m(Ag) = 0,6 × 108 = 64,8 g"], "ans": "64,8 gam\n(HCHO -> 4Ag; các aldehyde khác RCHO với R ≠ H -> 2Ag; HCOOH cũng cho 2Ag)", "unit": "g", "tol": "0.1"}, {"n": 5, "q": "Cân bằng phản ứng: CH₃CHO + I₂ + NaOH -> HCOONa + CHI₃ + NaI + H₂O. Tổng hệ số sau khi cân bằng là?", "opts": "A=10;B=12;C=14;D=16", "a": "D", "steps": ["Cơ chế: CH₃CHO + 3I₂ -> CI₃CHO + 3HI; CI₃CHO + NaOH -> CHI₃ + HCOONa; 3HI + 3NaOH -> 3NaI + 3H₂O", "Phương trình cân bằng: CH₃CHO + 3I₂ + 4NaOH -> HCOONa + CHI₃↓ + 3NaI + 3H₂O", "Tổng hệ số = 1 + 3 + 4 + 1 + 1 + 3 + 3 = 16\n(Kiểm tra: số I cả 2 vế = 6; số Na cả 2 vế = 4)"], "ans": "D — Tổng hệ số = 16", "unit": "", "tol": ""}, {"n": 6, "q": "Cho dãy chất: HCHO, CH₃COOH, CH₂=CHCHO, C₂H₅OH, CH₃CHO, CH₃COCH₃. Có bao nhiêu chất tác dụng với thuốc thử Tollens (AgNO₃/NH₃)?", "opts": "", "a": "3", "steps": ["Tollens 'tìm' nhóm –CHO (hoặc HCOO–):\n• HCHO ✅ (cho 4Ag)\n• CH₃COOH ❌ (–COOH không phải –CHO)\n• CH₂=CHCHO ✅ (nhóm –CHO phản ứng, không phải C=C)\n• C₂H₅OH ❌\n• CH₃CHO ✅\n• CH₃COCH₃ ❌ (–CO– ở giữa)", "Số chất = HCHO + CH₂=CHCHO + CH₃CHO = 3"], "ans": "3 chất\n(HCOOH cũng phản ứng vì có cấu trúc H–CO–OH; alkyne đầu mạch tạo kết tủa với AgNO₃/NH₃ nhưng không phải phản ứng tráng bạc)", "unit": "", "tol": ""}]}, "g11c7": {"title": "Chương 7 · Carboxylic acid", "tagline": "Tính acid · Ester hoá · Điều chế", "color": "#ff7b72", "icon": "🍋", "num": "7", "feynman": "Carboxylic acid có nhóm –COOH — là nhóm carbonyl C=O ghép với –OH. Nhờ đó acid vừa có tính acid (nhóm –OH ion hóa cho H⁺), vừa tham gia phản ứng este hóa với alcohol. Giấm ăn là dung dịch acetic acid (CH₃COOH) 5%; vị chua của chanh là citric acid.", "notes": [{"kind": "table", "t": "Công thức & tên gọi", "b": "Công thức | Tên thay thế | Tên thường | Ghi nhớ\nHCOOH | methanoic acid | formic acid | Acid kiến (formic = kiến)\nCH₃COOH | ethanoic acid | acetic acid | Giấm ăn\nCH₃CH₂COOH | propanoic acid | propionic acid |\nC₆H₅COOH | benzoic acid | benzoic acid | Tạo từ oxi hóa toluene\nCₙH₂ₙO₂ (n ≥ 1) | acid no đơn chức | công thức chung | Chú ý: n ≥ 1"}, {"kind": "rxn", "t": "Tính acid – với kim loại hoạt động", "b": "2CH₃COOH + Zn -> (CH₃COO)₂Zn + H₂\n(Kim loại đứng trước H mới phản ứng – trừ Cu, Ag, Au!)"}, {"kind": "rxn", "t": "Tính acid – với base", "b": "CH₃COOH + NaOH -> CH₃COONa + H₂O"}, {"kind": "rxn", "t": "Tính acid – với muối carbonate", "b": "2CH₃COOH + CaCO₃ -> (CH₃COO)₂Ca + H₂O + CO₂\n(Đá vôi tan trong acid, sủi bọt CO₂ – dùng để nhận biết acid)"}, {"kind": "danger", "t": "Cu KHÔNG phản ứng với carboxylic acid thông thường", "b": "Propanoic acid (hay bất kỳ acid hữu cơ thông thường nào) + Cu -> không phản ứng (Cu đứng sau H trong dãy hoạt động). Đây là bẫy phổ biến!"}, {"kind": "rxn", "t": "Phản ứng este hóa ⭐⭐", "b": "CH₃COOH + C₂H₅OH ->(H₂SO₄ đặc, t°) CH₃COOC₂H₅ + H₂O\n(Ethyl acetate – mùi táo; phản ứng thuận nghịch)"}, {"kind": "rule", "t": "Nguyên tắc đặt tên ester", "b": "Ester = gốc R' từ alcohol + gốc acid (đuôi 'ate')\nCH₃COO–C₂H₅ = ethyl acetate (ethyl = C₂H₅, acetate = từ acetic acid)\nHCOO–CH₃ = methyl formate (methyl = CH₃, formate = từ formic acid)"}, {"kind": "rxn", "t": "HCOOH đặc biệt: vừa acid vừa có tính khử", "b": "HCOOH + 2[Ag(NH₃)₂]OH -> 2Ag↓ + (NH₄)₂CO₃ + 2NH₃ + H₂O\n(HCOOH cho phản ứng tráng bạc vì cấu trúc có nhóm H–C=O)"}, {"kind": "card", "t": "So sánh nhiệt độ sôi", "b": "Lực liên kết phân tử tăng dần: Hydrocarbon -> Halogen -> Ester -> Aldehyde/Ketone -> Alcohol -> Carboxylic acid.\nCarboxylic acid có liên kết hydrogen 'đôi' tạo dimer (2 phân tử liên kết qua 2 liên kết H O–H···O=C) -> phải bứt 2 liên kết H khi bay hơi -> t°sôi cao nhất.\nThứ tự t°sôi tăng (cùng số C tương đương): Acid > Alcohol > Aldehyde/Ketone > Ester > Halogen > Hydrocarbon"}], "exercises": [{"n": 1, "q": "Tính thể tích dung dịch NaOH 0,4 mol/L cần để trung hòa 0,005 mol citric acid (có 3 nhóm COOH).", "opts": "", "a": "37.5", "steps": ["Citric acid có 3 nhóm –COOH -> 1 mol acid cần 3 mol NaOH\nC₃H₄(COOH)₃ + 3NaOH -> C₃H₄(COONa)₃ + 3H₂O", "n(NaOH) = 3 × n(acid) = 3 × 0,005 = 0,015 mol", "V(NaOH) = n/C = 0,015/0,4 = 0,0375 L = 37,5 mL"], "ans": "37,5 mL", "unit": "mL", "tol": "0.1"}, {"n": 2, "q": "Hợp chất X tác dụng với Ca tạo muối có công thức thực nghiệm C₄H₄O₄Ca. Tìm công thức cấu tạo của X.", "opts": "", "a": "", "steps": ["Muối Ca²⁺ của carboxylic acid: 2 ion H⁺ từ 2 nhóm –COOH bị thay bởi Ca²⁺\nC₄H₄O₄Ca = (RCOO)₂Ca -> mỗi RCOO⁻ = C₂H₂O₂⁻", "X là acid 2 chức (2 nhóm –COOH), CTPT C₄H₆O₄\n2RCOOH + Ca -> (RCOO)₂Ca + H₂", "Công thức cấu tạo: HOOC–CH₂–CH₂–COOH (succinic acid / butanedioic acid)"], "ans": "X = HOOC–CH₂–CH₂–COOH (succinic acid, butanedioic acid)", "unit": "", "tol": ""}, {"n": 3, "q": "Số đồng phân carboxylic acid và ester có cùng CTPT C₄H₈O₂ là bao nhiêu?", "opts": "A=2;B=4;C=6;D=8", "a": "C", "steps": ["Carboxylic acid: CH₃CH₂CH₂COOH (butanoic acid), (CH₃)₂CHCOOH (2-methylpropanoic acid) -> 2 acid", "Ester: HCOO–CH₂CH₂CH₃, HCOO–CH(CH₃)₂, CH₃COO–CH₂CH₃, CH₃CH₂COO–CH₃ -> 4 ester", "Tổng = 2 + 4 = 6"], "ans": "C — 6 đồng phân", "unit": "", "tol": ""}, {"n": 4, "q": "Trong các chất acetone (CH₃COCH₃), ethyl chloride (C₂H₅Cl), ethanol (C₂H₅OH), acetic acid (CH₃COOH), chất nào có nhiệt độ sôi CAO nhất? Giải thích.", "opts": "A=Acetone;B=Ethyl chloride;C=Ethanol;D=Acetic acid", "a": "D", "steps": ["t°sôi thực tế: C₂H₅Cl +12°C; CH₃COCH₃ +56°C; C₂H₅OH +78°C; CH₃COOH +118°C", "Acetic acid liên kết hydrogen kiểu dimer: 2 phân tử dính nhau qua 2 liên kết H (O–H···O=C)\n-> phải bứt 2 liên kết H mỗi phân tử mới bay hơi -> cần nhiều nhiệt -> t°sôi cao nhất.", "Quy tắc tổng quát (cùng số C): Acid > Alcohol > Aldehyde/Ketone > Ester > Halogen > Hydrocarbon"], "ans": "D — Acetic acid có nhiệt độ sôi cao nhất (+118°C)", "unit": "", "tol": ""}, {"n": 5, "q": "Citric acid có CTCT HOOC–CH₂–C(OH)(COOH)–CH₂–COOH (3 nhóm –COOH). Tính V(NaOH) 0,4 mol/L cần để trung hòa 0,005 mol citric acid.", "opts": "", "a": "37.5", "steps": ["Mỗi nhóm –COOH cần 1 phân tử NaOH -> 1 mol citric acid cần 3 mol NaOH\n(Lưu ý: nhóm –OH alcohol ở C bậc 3 KHÔNG phản ứng với NaOH, đừng đếm nhầm!)", "HOOC–CH₂–C(OH)(COOH)–CH₂–COOH + 3NaOH -> NaOOC–CH₂–C(OH)(COONa)–CH₂–COONa + 3H₂O", "n(NaOH) = 3 × 0,005 = 0,015 mol; V = 0,015/0,4 = 0,0375 L = 37,5 mL"], "ans": "37,5 mL", "unit": "mL", "tol": "0.1"}, {"n": 6, "q": "Để trung hòa 40 mL giấm ăn (d = 1 g/mL) cần 25 mL dung dịch NaOH 1M. Tính nồng độ % của acetic acid trong giấm.", "opts": "", "a": "3.75", "steps": ["n(NaOH) = V × C = 25 × 10⁻³ × 1 = 0,025 mol", "CH₃COOH + NaOH -> CH₃COONa + H₂O (tỉ lệ 1:1)\nn(CH₃COOH) = n(NaOH) = 0,025 mol", "m(CH₃COOH) = 0,025 × 60 = 1,5 g", "m(giấm) = V × d = 40 × 1 = 40 g\nC% = (1,5/40) × 100% = 3,75%"], "ans": "3,75%", "unit": "%", "tol": "0.1"}]}, "g11on": {"title": "Ôn tập tổng hợp", "tagline": "Sơ đồ phản ứng · Nhận biết · Chương 1–7", "color": "#e3b341", "icon": "📚", "num": "8", "feynman": "Các bài ôn tập này 'trộn' kiến thức từ chương 1 đến 7: nhận biết chất bằng thuốc thử (Br₂, Tollens, I₂/NaOH, Cu(OH)₂...), chuỗi oxi hóa alcohol – aldehyde – acid, và bài toán hiệu suất theo chuỗi sản xuất. Để giải tốt hãy gắn nhãn mỗi dữ kiện thuộc chương nào, nắm vững từng chương riêng lẻ rồi mới ráp lại theo sơ đồ phản ứng.", "notes": [{"kind": "card", "t": "Chiến lược bài tập tổng hợp", "b": "Mỗi dữ kiện thường chỉ 'chạm' vào 1–2 chất/nhóm chức.\n• Dữ kiện phản ứng chung -> lập phương trình, đặt ẩn.\n• Dữ kiện chỉ tác dụng với 1 chất (vd Br₂ với phenol, Tollens với aldehyde) -> tìm n chất đó trước.\n• Gắn nhãn chương cho từng phản ứng để không bỏ sót nhóm chức."}, {"kind": "table", "t": "Bảng tổng kết nhận biết (học thuộc lòng)", "b": "Chất cần nhận biết | Thuốc thử | Hiện tượng\nAlkene/Alkyne | Dung dịch Br₂ | Mất màu cam\nAlkene/Alkyne/Phenol | KMnO₄ | Mất màu tím\nAlk-1-yne (HC≡C–R) | AgNO₃/NH₃ | Kết tủa vàng nhạt\nPhenol | Br₂ (không cần xúc tác) | Kết tủa TRẮNG (2,4,6-tribromophenol)\nPolyalcohol (glycerol) | Cu(OH)₂ | Dung dịch xanh lam đặc trưng\nAldehyde | AgNO₃/NH₃ (Tollens) | Gương bạc (Ag trắng bóng)\nAldehyde | Cu(OH)₂/NaOH, t° | Kết tủa đỏ gạch (Cu₂O)\nCH₃–CO– (acetyl) | I₂/NaOH | Kết tủa vàng CHI₃ (iodoform)\nCarboxylic acid | Quỳ tím / CaCO₃ | Đỏ quỳ / sủi bọt CO₂\nAcid > Phenol > Alcohol | So sánh tính acid | Acid + NaHCO₃ -> CO₂; Phenol thì không"}, {"kind": "card", "t": "Chuỗi oxi hóa – khử liên chương", "b": "Alcohol bậc 1 ->(CuO) Aldehyde ->(oxi hóa tiếp) Carboxylic acid\nC₂H₅OH -> CH₃CHO -> CH₃COOH (Ch.4 + Ch.6 + Ch.7)\nAlcohol bậc 2 -> Ketone; Alcohol bậc 3 không bị oxi hóa nhẹ (CuO).\nAldehyde/Ketone + H₂ ->(Ni, t°) Alcohol (điều chế ngược chiều)."}, {"kind": "table", "t": "Bản đồ nhóm chức qua các chương", "b": "Chất | Phản ứng đặc trưng | Chương\nAlkene/Alkyne | Cộng Br₂, H₂; làm mất màu KMnO₄ | Ch.1\nAlkyne đầu mạch | HC≡C–R + AgNO₃/NH₃ -> kết tủa vàng nhạt | Ch.1\nAlcohol | + Na -> muối + H₂; bậc 1/2 + CuO -> aldehyde/ketone | Ch.4\nPolyalcohol | + Cu(OH)₂ -> phức xanh lam (≥ 2 OH kề nhau) | Ch.4\nPhenol | + NaOH -> muối; + Br₂ -> kết tủa trắng; KHÔNG + NaHCO₃ | Ch.5\nAldehyde | Tollens -> Ag; Cu(OH)₂/NaOH -> Cu₂O đỏ gạch | Ch.6\nKetone | Không Tollens; CH₃CO– + I₂/NaOH -> CHI₃ vàng | Ch.6\nCarboxylic acid | + NaHCO₃ -> CO₂; este hóa; t°sôi cao (dimer) | Ch.7"}, {"kind": "trick", "t": "Bài toán hiệu suất theo chuỗi sản xuất", "b": "Hiệu suất TOÀN quá trình -> chỉ chia 1 lần ở cuối:\nn(nguyên liệu thực) = n(lý thuyết)/H%\nNếu hiệu suất từng bước (80% × 70% × 60%) -> nhân các hiệu suất với nhau.\nMẹo: đi NGƯỢC từ sản phẩm cuối về nguyên liệu đầu, nhân tỉ lệ stoichiometry ở mỗi bước rồi mới chia hiệu suất."}, {"kind": "trick", "t": "Giải hệ hỗn hợp 2 chất", "b": "Hỗn hợp 2 chất + 2 dữ kiện -> 2 phương trình, 2 ẩn.\nNếu 1 dữ kiện chỉ 'chạm' 1 chất (vd Br₂ chỉ phản ứng phenol) -> tìm n chất đó trước, khỏi giải hệ.\nVí dụ: với ethanol (x) + phenol (y): x + y = 2n(H₂) và y = n(kết tủa Br₂)."}, {"kind": "danger", "t": "Bẫy hay gặp trong đề tổng hợp", "b": "• Ethyl chloride (C₂H₅Cl) không có –OH -> không phản ứng với Na.\n• Cu(OH)₂ chỉ phản ứng polyalcohol (≥ 2 nhóm OH kề nhau) – một nhóm –OH duy nhất thì không.\n• Alcohol không phản ứng với NaOH; chỉ phenol và carboxylic acid mới phản ứng.\n• Aldehyde mới tráng bạc; ketone (CH₃COCH₃) vẫn cho iodoform.\n• Ethylene còn dư không phản ứng với Tollens."}], "exercises": [{"n": 1, "q": "Sắp xếp nhiệt độ sôi tăng dần: ethane, benzene, phenol, ethanol. (Ch.1 + Ch.2 + Ch.4 + Ch.5)", "opts": "A=ethane, ethanol, benzene, phenol;B=benzene, ethane, ethanol, phenol;C=ethane, benzene, ethanol, phenol;D=phenol, benzene, ethanol, ethane", "a": "B", "steps": ["Dữ kiện mẫu: mẫu 2 (-89°C, không tan, không liên kết H) -> ethane (M = 30)\nmẫu 1 (+80°C, không tan, không liên kết H) -> benzene (M = 78)\nmẫu 3 (+78°C, tan vô hạn, có liên kết H) -> ethanol (M = 46)\nmẫu 4 (+182°C, tan ít, có liên kết H) -> phenol (M = 94)", "Sắp xếp t°sôi tăng dần: ethane (-89°C) < ethanol (+78°C) < benzene (+80°C) < phenol (+182°C)", "Hai yếu tố quyết định t°sôi: khối lượng phân tử M và liên kết hydrogen. Phenol cao nhất vì M lớn + có liên kết H."], "ans": "B — Mẫu 1,2,3,4 lần lượt: benzene, ethane, ethanol, phenol\n(Thứ tự t°sôi tăng dần: ethane < ethanol < benzene < phenol)", "unit": "", "tol": ""}, {"n": 2, "q": "Cho dãy: phenol, ethanol, ethyl chloride, o-cresol, glycerol. Có bao nhiêu chất tác dụng với Na? (Ch.3 + Ch.4 + Ch.5)", "opts": "", "a": "4", "steps": ["Na tác dụng với chất có nhóm –OH (alcohol hoặc phenol), giải phóng H₂.\nEthyl chloride (C₂H₅Cl) chỉ có –Cl, KHÔNG có –OH -> không phản ứng.", "Phenol ✅, ethanol ✅, o-cresol (CH₃–C₆H₄–OH) ✅, glycerol C₃H₅(OH)₃ ✅ (3 nhóm –OH); ethyl chloride ❌", "Phương trình mẫu: 2C₂H₅OH + 2Na -> 2C₂H₅ONa + H₂\n2CH₃C₆H₄OH + 2Na -> 2CH₃C₆H₄ONa + H₂\n2C₃H₅(OH)₃ + 6Na -> 2C₃H₅(ONa)₃ + 3H₂"], "ans": "4 chất (không kể ethyl chloride – vì không có nhóm –OH)", "unit": "", "tol": ""}, {"n": 3, "q": "Cho HC≡C–CH₂OH (propargyl alcohol) tác dụng lần lượt với: Cu(OH)₂, AgNO₃/NH₃, H₂(Ni, t°), Na, nước Br₂, KMnO₄, NaOH. Có bao nhiêu trường hợp xảy ra phản ứng? (Ch.1 + Ch.4)", "opts": "", "a": "5", "steps": ["Phân tử có 2 nhóm chức: HC≡C– (alkyne đầu mạch) và –CH₂OH (alcohol bậc 1).", "Cu(OH)₂ ❌ (cần ≥ 2 nhóm OH kề nhau – chỉ 1 OH); AgNO₃/NH₃ ✅ (HC≡C– đầu mạch -> AgC≡C–CH₂OH); H₂/Ni ✅ (cộng C≡C); Na ✅ (–OH linh động); nước Br₂ ✅ (cộng C≡C); KMnO₄ ✅ (oxi hóa C≡C); NaOH ❌ (alcohol và alkyne không phản ứng).", "Số phản ứng = AgNO₃/NH₃ + H₂ + Na + Br₂ + KMnO₄ = 5"], "ans": "5 trường hợp", "unit": "", "tol": ""}, {"n": 4, "q": "Oxi hóa không hoàn toàn ethylene (xt) -> ethanal. Dẫn 2,479 L hỗn hợp khí (đkc) vào AgNO₃/NH₃ dư thu được 16,2 g Ag. Tính hiệu suất phản ứng. (Ch.1 + Ch.6)", "opts": "", "a": "75", "steps": ["n(hỗn hợp X) = 2,479/24,79 = 0,1 mol\n2CH₂=CH₂ + O₂ ->(PdCl₂/CuCl₂) 2CH₃CHO", "Chỉ CH₃CHO phản ứng Tollens:\nCH₃CHO + 2[Ag(NH₃)₂]OH -> CH₃COONH₄ + 2Ag + 3NH₃ + H₂O\nn(Ag) = 16,2/108 = 0,15 mol -> n(CH₃CHO) = 0,15/2 = 0,075 mol", "n(ethylene dư) = 0,1 – 0,075 = 0,025 mol; n(ethylene ban đầu) = 0,1 mol", "H = n(CH₃CHO tạo ra)/n(ethylene ban đầu) × 100% = 0,075/0,1 × 100% = 75%"], "ans": "75%", "unit": "%", "tol": "1"}, {"n": 5, "q": "Hợp chất X có vòng benzene, CTPT C₈H₈O₂, phản ứng X + 2NaOH -> Y + 2H₂O. Phân tích cấu trúc và các phát biểu về X. (Ch.2 + Ch.5 + Ch.7)", "opts": "", "a": "", "steps": ["X + 2NaOH -> Y + 2H₂O: X có 2 nhóm chức linh động (nhóm –OH phenol hoặc –COOH). CTPT có 2 oxi + vòng benzene (6C, 4H sau thế).", "Độ bất bão hòa k = (2×8 + 2 – 8)/2 = 5; vòng benzene chiếm k = 4 -> còn k = 1: 1 liên kết đôi C=O ngoài vòng.", "X là ester của phenol kèm nhóm –OH phenol (hoặc nhóm –COOH): C₈H₈O₂ phù hợp với HCOO–C₆H₄–CH₃ hay ester có –OH phenol.\nX + 2NaOH -> muối phenoxide/carboxylate + H₂O.", "Phát biểu: (b) Y là muối, không phải phenol đa chức -> SAI; (d) vòng benzene + ester không làm mất màu Br₂ điều kiện thường -> SAI."], "ans": "X là ester có vòng benzene kèm nhóm –OH phenol/–COOH; X + 2NaOH -> muối (phenoxide/carboxylate) + H₂O", "unit": "", "tol": ""}, {"n": 6, "q": "Hỗn hợp A gồm ethanol và phenol + Na dư -> 3,7185 L H₂ (đkc). Cùng lượng A + nước Br₂ vừa đủ -> 19,86 g kết tủa trắng. Tính %m phenol trong A. (Ch.4 + Ch.5)", "opts": "", "a": "33.81", "steps": ["Đặt n(C₂H₅OH) = x; n(C₆H₅OH) = y.\nDữ kiện Br₂ chỉ 'chạm' phenol: C₆H₅OH + 3Br₂ -> C₆H₂Br₃OH↓ + 3HBr\nM(kết tủa) = 331; n = 19,86/331 = 0,06 mol -> y = 0,06", "Na tác dụng cả hai: 2ROH + 2Na -> 2RONa + H₂\nn(H₂) = 3,7185/24,79 = 0,15 mol -> (x + y)/2 = 0,15 -> x + y = 0,3 -> x = 0,24 mol", "m(ethanol) = 0,24 × 46 = 11,04 g; m(phenol) = 0,06 × 94 = 5,64 g; m(A) = 16,68 g", "%m(phenol) = (5,64/16,68) × 100% = 33,81%"], "ans": "33,81%", "unit": "%", "tol": "0.1"}, {"n": 7, "q": "PVC điều chế từ khí thiên nhiên: CH₄ -> C₂H₂ -> CH₂=CHCl -> PVC. Hiệu suất toàn quá trình 20%. Cần V (m³) khí thiên nhiên (chứa 80% CH₄) để có 1 tấn PVC? (Ch.1 + Ch.3)", "opts": "", "a": "4958", "steps": ["Sơ đồ: 2CH₄ ->(1500°C, làm lạnh nhanh) C₂H₂ + 3H₂\nC₂H₂ + HCl ->(HgCl₂, t°) CH₂=CHCl; nCH₂=CHCl ->(trùng hợp) -(-CH₂–CHCl-)ₙ- (PVC)", "1 mắc xích PVC (M = 62,5) ← 1 vinyl chloride ← 1 C₂H₂ ← 2 CH₄\nn(PVC) = 10⁶/62,5 = 16 000 mol -> n(CH₄ lý thuyết) = 32 000 mol", "Hiệu suất toàn quá trình 20% (chia 1 lần ở cuối): n(CH₄ thực) = 32 000/0,2 = 160 000 mol\nV(CH₄, đkc) = 160 000 × 24,79 = 3 966 400 L = 3 966,4 m³", "Khí thiên nhiên chứa 80% CH₄: V = 3 966,4/0,8 = 4 958 m³\n(Nếu đề cho hiệu suất từng bước 80% × 70% × 60% thì phải nhân các hiệu suất với nhau)"], "ans": "≈ 4 958 m³ (≈ 4 960 m³)", "unit": "m³", "tol": "2"}, {"n": 8, "q": "Cho 4,02 g hỗn hợp X (phenol + propyl alcohol) tác dụng với nước Br₂ dư -> 9,93 g kết tủa trắng. Tính %m phenol trong X. (Ch.4 + Ch.5)", "opts": "", "a": "70.15", "steps": ["Chỉ phenol tạo kết tủa: C₆H₅OH + 3Br₂ -> C₆H₂Br₃OH↓ + 3HBr\nM(C₆H₂Br₃OH) = 331 g/mol (propyl alcohol không phản ứng Br₂)", "n(kết tủa) = 9,93/331 = 0,03 mol = n(phenol); m(phenol) = 0,03 × 94 = 2,82 g", "%m(phenol) = (2,82/4,02) × 100% = 70,15%"], "ans": "70,15%", "unit": "%", "tol": "0.1"}, {"n": 9, "q": "Đun sôi 12,9 g C₂H₅Cl với KOH/C₂H₅OH dư thu được khí; dẫn khí qua dung dịch Br₂ dư thấy có x g Br₂ phản ứng. Hiệu suất phản ứng đầu là 80%. Tính x. (Ch.1 + Ch.3)", "opts": "", "a": "25.6", "steps": ["M(C₂H₅Cl) = 64,5; n(C₂H₅Cl) = 12,9/64,5 = 0,2 mol", "C₂H₅Cl + KOH ->(C₂H₅OH, t°) C₂H₄ + KCl + H₂O (tách HCl, H = 80%)\nn(C₂H₄ thực tế) = 0,2 × 0,80 = 0,16 mol", "CH₂=CH₂ + Br₂ -> CH₂Br–CH₂Br (1:1)\nn(Br₂) = n(C₂H₄) = 0,16 mol", "x = m(Br₂) = 0,16 × 160 = 25,6 g\n(Phản ứng cộng Br₂ mặc định H = 100% nếu đề không nói khác)"], "ans": "25,6 gam", "unit": "g", "tol": "0.1"}]}, "g11cq": {"questions": 130}, "g12c1": {"title": "Chương 1 · Ester – Lipit · Xà phòng", "tagline": "Thuỷ phân · Xà phòng hoá · Chất giặt rửa", "color": "#14b8a6", "icon": "🧈", "num": "1", "feynman": "Nếu phải giải thích cho ai đó một cách ngắn nhất: ester là sản phẩm khi thay nhóm -OH của -COOH bằng gốc -OR', và chất béo chính là triester của glycerol với các acid béo mạch dài. Nắm cách gọi tên ester, so sánh thủy phân trong acid (thuận nghịch) với trong kiềm (xà phòng hóa, một chiều), rồi hiểu vì sao xà phòng và chất giặt rửa tẩy sạch vết dầu là bạn đã bao trọn chương này.", "notes": [{"kind": "card", "t": "Khái niệm ester", "b": "Khi thay nhóm -OH của nhóm carboxyl (-COOH) bằng nhóm -OR' (R' là gốc hydrocarbon) ta được ester.\nVí dụ: CH3COOC2H5; CH2=CHCOOCH3; C6H5COOCH3."}, {"kind": "rule", "t": "Công thức chung của ester", "b": "Ester đơn chức: RCOOR', trong đó R là gốc hydrocarbon hoặc H, R' là gốc hydrocarbon (R' ≠ H).\nEster no, đơn chức, mạch hở: CnH2nO2 (n ≥ 2) hay CnH2n+1COOCmH2m+1.\nĐộ bất bão hòa k = 1 (chỉ có nhóm C=O)."}, {"kind": "card", "t": "Danh pháp ester", "b": "Tên ester = Tên gốc R' (gốc alcohol) + tên gốc acid (đổi đuôi 'ic' thành 'ate').\nHCOO-: formate; CH3COO-: acetate; C2H5COO-: propionate; CH2=CHCOO-: acrylate; C6H5COO-: benzoate; C17H33COO-: oleate.\nGốc alcohol: CH3- methyl; C2H5- ethyl; CH2=CH- vinyl; C6H5CH2- benzyl.\nVí dụ: CH3COOC2H5 là ethyl acetate; CH3COOCH2CH=CH2 là allyl acetate."}, {"kind": "card", "t": "Đồng phân ester", "b": "Các hợp chất đơn chức (ester + acid) cùng CTPT, đều tác dụng được với NaOH:\nC3H6O2: 2 ester (HCOOC2H5, CH3COOCH3) + 1 acid (C2H5COOH).\nC4H8O2: 4 ester (HCOOC3H7, HCOOCH(CH3)2, CH3COOC2H5, C2H5COOCH3) + 2 acid (butyric, 2-methylpropanoic) = 6.\nC4H6O2: 5 ester không no mạch hở, trong đó CH3COOCH=CH2 thủy phân cho CH3CHO."}, {"kind": "card", "t": "Tính chất vật lí của ester", "b": "Ester KHÔNG tạo được liên kết hydrogen giữa các phân tử với nhau nên nhiệt độ sôi thấp hơn nhiều so với alcohol và carboxylic acid cùng phân tử khối.\nThứ tự nhiệt độ sôi (cùng M): ester < alcohol < carboxylic acid.\nEster thường nhẹ hơn nước, ít tan trong nước (không tan, nổi trên mặt nước). Ester phân tử khối thấp là chất lỏng, phân tử khối lớn là chất rắn. Một số ester có mùi thơm hoa quả: isoamyl acetate (mùi chuối), propyl ethanoate (mùi lê), methyl butanoate (mùi táo), ethyl propionate (mùi dứa)."}, {"kind": "rxn", "t": "Thủy phân ester trong môi trường acid", "b": "RCOOR' + H2O -> RCOOH + R'OH (xt H2SO4 loãng, t°)\nVí dụ: CH3COOCH3 + H2O -> CH3COOH + CH3OH\nPhản ứng THUẬN NGHỊCH (ngược lại quá trình ester hóa).\nEster có gốc alcohol dạng vinyl (-O-CH=CH2) thủy phân cho aldehyde: CH3COOCH=CH2 + H2O -> CH3COOH + CH3CHO."}, {"kind": "rxn", "t": "Thủy phân ester trong môi trường base", "b": "RCOOR' + NaOH -> RCOONa + R'OH\nVí dụ: CH3COOCH3 + NaOH -> CH3COONa + CH3OH\nPhản ứng MỘT CHIỀU vì muối RCOONa không tác dụng ngược lại với alcohol. Gọi là phản ứng xà phòng hóa.\nEster của phenol dùng 2 NaOH: RCOOC6H5 + 2NaOH -> RCOONa + C6H5ONa + H2O (không có alcohol, chỉ 2 muối)."}, {"kind": "table", "t": "Thủy phân ester: acid vs base", "b": "Đặc điểm | Môi trường acid (H2SO4 loãng) | Môi trường base (NaOH, KOH)\nSản phẩm | Acid RCOOH + alcohol R'OH | Muối RCOONa + alcohol R'OH\nHướng phản ứng | Thuận nghịch | Một chiều\nSản phẩm đặc biệt | Ester vinyl cho acid + aldehyde | Ester phenol cho 2 muối + H2O\nỨng dụng | Điều chế acid/alcohol | Sản xuất xà phòng (xà phòng hóa)"}, {"kind": "rxn", "t": "Điều chế ester (ester hóa)", "b": "RCOOH + R'OH -> RCOOR' + H2O (xt H2SO4 đặc, t°)\nVí dụ: CH3COOH + C2H5OH -> CH3COOC2H5 + H2O\nPhản ứng thuận nghịch, hiệu suất < 100%.\nHiệu suất: H = (n ester thực tế / n ester lý thuyết)×100%, tính theo chất có số mol nhỏ hơn (chất hết)."}, {"kind": "card", "t": "Lipid – chất béo", "b": "Lipid: hợp chất hữu cơ trong tế bào sống, không tan trong nước, tan trong dung môi hữu cơ không phân cực. Gồm chất béo, sáp, steroid, phospholipid,...\nChất béo = triester của glycerol với acid béo, gọi chung là triglyceride: (RCOO)3C3H5 (R1, R2, R3 giống hoặc khác nhau).\nAcid béo: acid carboxylic đơn chức, mạch dài 12-24 C, không phân nhánh, số C chẵn; gốc hydrocarbon no hoặc không no (1 hay nhiều C=C dạng cis).\nTên chất béo: glyceryl + tri + tên gốc acid (Glyceryl trioleate) hoặc tri + acid béo đổi 'c' thành 'n' (Triolein)."}, {"kind": "table", "t": "Acid béo và chất béo thường gặp", "b": "Acid béo | Công thức | Số C=C | Chất béo tương ứng (M)\nPalmitic | C15H31COOH | 0 | Tripalmitin (C15H31COO)3C3H5 (806)\nStearic | C17H35COOH | 0 | Tristearin (C17H35COO)3C3H5 (890)\nOleic | C17H33COOH | 1 | Triolein (C17H33COO)3C3H5 (884)\nLinoleic | C17H31COOH | 2 | Trilinolein (C17H31COO)3C3H5 (878)\nGlycerol | C3H5(OH)3 | - | M = 92\nMuối: sodium palmitate C15H31COONa (278), sodium stearate C17H35COONa (306)"}, {"kind": "card", "t": "Tính chất của chất béo", "b": "Vật lí: chứa nhiều gốc acid béo NO => rắn (mỡ lợn, mỡ bò); nhiều gốc KHÔNG NO => lỏng (dầu lạc, dầu cá). Chất béo nhẹ hơn nước, không tan trong nước, dễ tan trong dung môi hữu cơ.\nHóa học: là ester nên có phản ứng thủy phân trong acid (thuận nghịch) và xà phòng hóa (một chiều).\nHydrogen hóa: chất béo không no + H2 (xt Ni, t°) -> chất béo no (bơ thực vật); 1 mol H2 làm no 1 liên kết C=C.\nOxi hóa: gốc không no bị O2 không khí oxi hóa chậm -> mùi khó chịu (dầu mỡ ôi); thêm chất chống oxi hóa (vitamin C, E)."}, {"kind": "card", "t": "Xà phòng và chất giặt rửa", "b": "Xà phòng = hỗn hợp muối sodium/potassium của acid béo (thành phần chính: sodium palmitate, sodium stearate) + phụ gia.\nChất giặt rửa tổng hợp = muối sodium alkylsulfate (R-OSO3Na) hoặc alkylbenzenesulfonate (R-C6H4-SO3Na), sản xuất từ dầu mỏ; KHÔNG phải muối của acid béo.\nCấu tạo: đầu phân cực ưa nước (-COO- với xà phòng; -SO3Na, -OSO3Na với chất giặt rửa) + đuôi hydrocarbon dài kị nước (R).\nCơ chế tẩy rửa: đuôi kị nước thâm nhập vào vết bẩn dầu mỡ, chia vết bẩn thành hạt nhỏ có đầu ưa nước quay ra ngoài -> các hạt phân tán vào nước và bị rửa trôi (nhũ hóa - tác dụng vật lí, không phải phản ứng hóa học)."}, {"kind": "table", "t": "Xà phòng vs chất giặt rửa tổng hợp", "b": "Tiêu chí | Xà phòng | Chất giặt rửa tổng hợp\nBản chất | Muối Na/K của acid béo (-COO-) | Muối alkylsulfate (-OSO3Na), alkylbenzenesulfonate (-SO3Na)\nNguyên liệu | Chất béo động, thực vật | Paraffin dầu mỏ\nNước cứng | Tạo kết tủa với Ca2+, Mg2+ => mất tác dụng | Không kết tủa, vẫn giặt được\nMôi trường acid | Kém tác dụng | Vẫn dùng được\nPhân hủy sinh học | Dễ bị vi sinh vật phân hủy | Gốc phân nhánh/vòng benzene khó phân hủy => gây ô nhiễm"}, {"kind": "trick", "t": "Mẹo ghi nhớ", "b": "Phân biệt: thấy -COO- (muối Na/K của acid béo) => xà phòng; thấy NGUYÊN TỐ S trong -SO3Na hoặc -OSO3Na => chất giặt rửa tổng hợp.\nEster + NaOH theo tỉ lệ mol 1:2 => ester của phenol (thu 2 muối + H2O, không có alcohol).\nEster thủy phân cho aldehyde/ketone => gốc alcohol dạng vinyl (-O-CH=CH2).\nCùng M: nhiệt độ sôi ester < alcohol < acid.\nBài toán chất béo: n(glycerol) = n(chất béo) = n(kiềm)/3 = n(muối)/3; bảo toàn khối lượng: m chất béo + m kiềm = m muối + m glycerol (NaOH M = 40, KOH M = 56).\nSố mol H2 cộng = (tổng số C=C trong các gốc acid) x n(chất béo)."}, {"kind": "danger", "t": "Lỗi học sinh hay gặp", "b": "(1) Xà phòng là muối của ACID BÉO (mạch dài), không phải mọi muối của acid hữu cơ - CH3COONa không phải xà phòng.\n(2) Thủy phân trong ACID là thuận nghịch, trong KIỀM là một chiều; đọc kỹ để không trả lời ngược.\n(3) Câu có chữ \"đều\": \"các triglyceride đều cộng H2\" là SAI vì chất béo no không cộng.\n(4) Đếm liên kết π quên nhóm C=O: methyl methacrylate có 2π (1 C=C + 1 C=O).\n(5) Dùng bát/xoong nhôm đun chất béo với NaOH: kiềm ăn mòn nhôm (2Al + 2NaOH + 2H2O -> 2NaAlO2 + 3H2).\n(6) Tẩy rửa là nhũ hóa vật lí, không phải phản ứng hóa học với vết bẩn.\n(7) Nhầm acid béo: palmitic 16C (C15H31COOH), stearic 18C (C17H35COOH)."}], "exercises": [{"n": 1, "q": "Hợp chất nào dưới đây thuộc loại ester?", "opts": "A=HOCH2CH2CHO;B=CH3CH2CH2COOH;C=HOCH2COCH3;D=CH3CH2COOCH3", "a": "D", "steps": ["Ester phải chứa nhóm -COO-.", "D có nhóm -COO- nối C2H5- với -CH3 nên là ester.", "A là aldehyde, B là carboxylic acid, C là ketone."], "ans": "D - CH3CH2COOCH3", "unit": "", "tol": ""}, {"n": 2, "q": "Ester no, đơn chức, mạch hở có công thức tổng quát là", "opts": "A=CnH2nO2 (n >= 2);B=CnH2n-2O2 (n >= 2);C=CnH2n+2O2 (n >= 2);D=CnH2nO (n >= 2)", "a": "A", "steps": ["Đơn chức nên có 1 nhóm -COO- => 2 nguyên tử O.", "No, mạch hở, k = 1 (chỉ do C=O) nên H = 2n.", "Vậy CnH2nO2 (n >= 2)."], "ans": "A - CnH2nO2 (n >= 2)", "unit": "", "tol": ""}, {"n": 3, "q": "Ethyl propionate là ester có mùi thơm của dứa. Công thức của ethyl propionate là", "opts": "A=HCOOC2H5;B=C2H5COOC2H5;C=C2H5COOCH3;D=CH3COOCH3", "a": "B", "steps": ["ethyl => gốc alcohol -C2H5.", "propionate => gốc acid C2H5COO-.", "Ghép lại: C2H5COOC2H5."], "ans": "B - C2H5COOC2H5", "unit": "", "tol": ""}, {"n": 4, "q": "So với các acid, alcohol có cùng số nguyên tử carbon thì ester có nhiệt độ sôi", "opts": "A=thấp hơn do khối lượng phân tử ester nhỏ hơn nhiều;B=thấp hơn do giữa các phân tử ester không tồn tại liên kết hydrogen;C=cao hơn do giữa các phân tử ester có liên kết hydrogen bền vững;D=cao hơn do khối lượng phân tử ester lớn hơn nhiều", "a": "B", "steps": ["Ester không còn H linh động gắn với O nên các phân tử không tạo liên kết hydrogen với nhau.", "Lực liên phân tử yếu => nhiệt độ sôi thấp hơn alcohol và acid."], "ans": "B - thấp hơn do không tạo liên kết hydrogen giữa các phân tử", "unit": "", "tol": ""}, {"n": 5, "q": "Ester nào sau đây tác dụng với NaOH thu được ethyl alcohol?", "opts": "A=CH3COOC2H5;B=CH3COOC3H7;C=C2H5COOCH3;D=HCOOCH3", "a": "A", "steps": ["RCOOR' + NaOH -> RCOONa + R'OH, alcohol sinh ra ứng với gốc -OR'.", "Muốn thu C2H5OH thì ester phải có gốc -OC2H5.", "Chỉ CH3COOC2H5 thỏa mãn."], "ans": "A - CH3COOC2H5", "unit": "", "tol": ""}, {"n": 6, "q": "Một ester có công thức phân tử C4H6O2, khi thủy phân trong acid thu được acetaldehyde. Công thức cấu tạo thu gọn của ester đó là", "opts": "A=CH2=CHCOOCH3;B=CH3COOCH=CH2;C=HCOOC(CH3)=CH2;D=HCOOCH=CH-CH3", "a": "B", "steps": ["Thủy phân cho aldehyde => gốc alcohol dạng vinyl -O-CH=CH- không bền, chuyển thành aldehyde.", "CH3COOCH=CH2 + H2O -> CH3COOH + CH3CHO."], "ans": "B - CH3COOCH=CH2", "unit": "", "tol": ""}, {"n": 7, "q": "Thủy phân hoàn toàn hỗn hợp ethyl propionate và ethyl formate trong dung dịch NaOH, thu được sản phẩm gồm", "opts": "A=1 muối và 1 alcohol;B=2 muối và 2 alcohol;C=1 muối và 2 alcohol;D=2 muối và 1 alcohol", "a": "D", "steps": ["C2H5COOC2H5 + NaOH -> C2H5COONa + C2H5OH.", "HCOOC2H5 + NaOH -> HCOONa + C2H5OH.", "Hai gốc acid khác nhau => 2 muối; cùng gốc -OC2H5 => 1 alcohol."], "ans": "D - 2 muối và 1 alcohol", "unit": "", "tol": ""}, {"n": 8, "q": "Ester X có công thức phân tử C4H8O2. Thủy phân X trong dung dịch H2SO4 loãng, đun nóng, thu được ethyl alcohol và chất hữu cơ Y. Công thức của Y là", "opts": "A=CH3OH;B=CH3COOH;C=C2H5COOH;D=HCOOH", "a": "B", "steps": ["Thu C2H5OH => X có gốc -OC2H5, X = RCOOC2H5.", "M(X) = 88 => R + 44 + 29 = 88 => R = 15 (CH3-).", "X = CH3COOC2H5 => Y = CH3COOH."], "ans": "B - CH3COOH", "unit": "", "tol": ""}, {"n": 9, "q": "Phát biểu nào sau đây sai?", "opts": "A=Ethyl formate có khả năng tham gia phản ứng tráng bạc;B=Phân tử methyl methacrylate có một liên kết pi trong phân tử;C=Ethyl acetate có công thức phân tử là C4H8O2;D=Methyl acrylate có khả năng tham gia phản ứng cộng Br2 trong dung dịch", "a": "B", "steps": ["Methyl methacrylate là CH2=C(CH3)COOCH3.", "Đếm liên kết pi: 1 của C=C + 1 của C=O = 2 liên kết pi.", "Vậy phát biểu 'có một liên kết pi' là sai."], "ans": "B - methyl methacrylate có 2 pi (C=C và C=O)", "unit": "", "tol": ""}, {"n": 10, "q": "Đun nóng 24 gam acetic acid với lượng dư ethyl alcohol (xúc tác H2SO4 đặc), thu được 26,4 gam ester. Hiệu suất của phản ứng ester hóa là", "opts": "A=75%;B=55%;C=60%;D=44%", "a": "A", "steps": ["n(CH3COOH) = 24/60 = 0,4 mol (alcohol dư nên tính theo acid).", "n(ester) = 26,4/88 = 0,3 mol.", "H = 0,3/0,4 x 100% = 75%."], "ans": "A - 75%", "unit": "", "tol": ""}, {"n": 11, "q": "Cho m gam chất hữu cơ đơn chức X tác dụng vừa đủ với 50 gam dung dịch NaOH 8%, thu được 9,6 gam muối của một acid hữu cơ và 3,2 gam một alcohol. Công thức của X là", "opts": "A=CH3COOCH=CH2;B=CH3COOC2H5;C=C2H5COOCH3;D=CH2=CHCOOCH3", "a": "C", "steps": ["m(NaOH) = 50 x 8% = 4 g => n = 0,1 mol => n(X) = n(muối) = n(alcohol) = 0,1 mol.", "M(alcohol) = 3,2/0,1 = 32 => CH3OH.", "M(muối) = 9,6/0,1 = 96 => RCOONa với R = 96 - 67 = 29 (C2H5-).", "Vậy X = C2H5COOCH3."], "ans": "C - C2H5COOCH3", "unit": "", "tol": ""}, {"n": 12, "q": "Công thức của triolein là", "opts": "A=(C17H33COO)3C3H5;B=(HCOO)3C3H5;C=(C2H5COO)3C3H5;D=(CH3COO)3C3H5", "a": "A", "steps": ["Triolein là triester của glycerol với oleic acid C17H33COOH.", "Công thức: (C17H33COO)3C3H5, M = 884."], "ans": "A - (C17H33COO)3C3H5", "unit": "", "tol": ""}, {"n": 13, "q": "Thủy phân tristearin ((C17H35COO)3C3H5) trong dung dịch NaOH, thu được muối có công thức là", "opts": "A=C2H3COONa;B=HCOONa;C=C17H33COONa;D=C17H35COONa", "a": "D", "steps": ["(C17H35COO)3C3H5 + 3NaOH -> 3C17H35COONa + C3H5(OH)3.", "Gốc acid giữ nguyên => muối là sodium stearate C17H35COONa."], "ans": "D - C17H35COONa", "unit": "", "tol": ""}, {"n": 14, "q": "Đun sôi a gam một triglyceride X với dung dịch KOH đến phản ứng hoàn toàn, thu được 0,92 gam glycerol và 9,58 gam hỗn hợp muối. Giá trị của a là", "opts": "A=8,82 gam;B=9,94 gam;C=10,90 gam;D=8,92 gam", "a": "A", "steps": ["n(glycerol) = 0,92/92 = 0,01 mol => n(KOH) = 0,03 mol.", "Bảo toàn khối lượng: a + m(KOH) = m(muối) + m(glycerol).", "a = 9,58 + 0,92 - 0,03 x 56 = 8,82 gam."], "ans": "A - 8,82 gam", "unit": "", "tol": ""}, {"n": 15, "q": "Cho các phát biểu: (1) Một số ester có mùi thơm dùng làm chất tạo hương; (2) Chất béo là triester của glycerol với acid béo; (3) Chất béo tan tốt trong nước; (4) Mỡ động vật, dầu thực vật làm nguyên liệu sản xuất xà phòng; (5) Thủy phân ester trong acid luôn là phản ứng một chiều. Số phát biểu đúng là", "opts": "A=2;B=3;C=4;D=5", "a": "B", "steps": ["(1) đúng; (2) đúng; (4) đúng.", "(3) sai: chất béo kị nước, không tan trong nước.", "(5) sai: thủy phân trong acid là thuận nghịch.", "Vậy có 3 phát biểu đúng."], "ans": "B - 3", "unit": "", "tol": ""}, {"n": 16, "q": "Cho các ester: HCOOCH3; CH3COOCH3; (COOCH3)2; (HCOO)2C2H4; CH2=CHCOOCH3; C2H5COOC2H5; CH3COOC6H5. Có bao nhiêu ester no, đơn chức, mạch hở?", "opts": "", "a": "3", "steps": ["Loại (COOCH3)2 và (HCOO)2C2H4: hai chức.", "Loại CH2=CHCOOCH3: không no; loại CH3COOC6H5: chứa vòng benzene.", "Còn HCOOCH3, CH3COOCH3, C2H5COOC2H5 => 3 chất."], "ans": "3 ester", "unit": "", "tol": ""}, {"n": 17, "q": "Số hợp chất đơn chức, đồng phân cấu tạo của nhau cùng công thức phân tử C4H8O2, đều tác dụng với dung dịch NaOH là bao nhiêu?", "opts": "", "a": "6", "steps": ["C4H8O2 (k = 1) gồm ester và acid đơn chức.", "Ester (4): HCOOCH2CH2CH3; HCOOCH(CH3)2; CH3COOC2H5; C2H5COOCH3.", "Acid (2): CH3CH2CH2COOH; (CH3)2CHCOOH.", "Tổng 4 + 2 = 6 chất."], "ans": "6 chất", "unit": "", "tol": ""}, {"n": 18, "q": "Cho a mol ester X (C9H10O2) tác dụng vừa đủ với 2a mol NaOH, thu được dung dịch không có phản ứng tráng bạc. Số công thức cấu tạo phù hợp với tính chất của X?", "opts": "", "a": "4", "steps": ["Tỉ lệ n(X):n(NaOH) = 1:2 => X là ester của phenol (RCOOC6H4R').", "Không tráng bạc => loại mọi cấu tạo chứa gốc HCOO-.", "Trường hợp 1: CH3COOC6H4CH3 (o, m, p) = 3 chất; trường hợp 2: C2H5COOC6H5 = 1 chất.", "Tổng cộng 4 công thức cấu tạo."], "ans": "4 công thức cấu tạo", "unit": "", "tol": ""}, {"n": 19, "q": "Hydrogen hóa hoàn toàn triolein thu được chất hữu cơ Y. Thủy phân hoàn toàn Y bằng dung dịch NaOH, đun nóng thu được glycerol và chất hữu cơ Z. Tính phần trăm khối lượng oxygen trong Z?", "opts": "", "a": "10,46", "steps": ["Triolein + 3H2 (Ni, t°) -> tristearin (Y).", "Y + 3NaOH -> C3H5(OH)3 + 3C17H35COONa => Z là sodium stearate.", "M(Z) = 306; %O = 32/306 x 100% ~ 10,46%."], "ans": "~10,46%", "unit": "%", "tol": "0.1"}, {"n": 20, "q": "Hỗn hợp X gồm hai ester có cùng công thức phân tử C8H8O2 và đều chứa vòng benzene. Để phản ứng hết với 0,25 mol X cần tối đa 0,35 mol NaOH, thu được m gam hỗn hợp hai muối. Tính giá trị của m?", "opts": "", "a": "30", "steps": ["Gọi x là mol ester thường (dùng 1 NaOH), y là mol ester của phenol (dùng 2 NaOH).", "x + y = 0,25 và x + 2y = 0,35 => y = 0,1; x = 0,15.", "Hai muối => hai ester cùng gốc acid: HCOOCH2C6H5 (0,15 mol) và HCOOC6H4CH3 (0,1 mol).", "m = m(HCOONa 0,25 mol = 17 g) + m(CH3C6H4ONa 0,1 mol = 13 g) = 30 g."], "ans": "30,0 gam", "unit": "g", "tol": "0.1"}, {"n": 21, "q": "Hydrogen hóa hoàn toàn 0,1 mol triglyceride X cần dùng 0,3 mol H2 (Ni, t°) thu được Y. Đun nóng Y với NaOH vừa đủ thu được hỗn hợp muối gồm sodium stearate và 27,8 gam sodium palmitate. Số nguyên tử hydrogen (H) trong X?", "opts": "", "a": "100", "steps": ["n(C15H31COONa) = 27,8/278 = 0,1 mol.", "n(Y) = 0,1 => tổng muối 0,3 mol => sodium stearate 0,2 mol.", "Y gồm 1 gốc palmitate + 2 gốc stearate => Y = C55H106O6.", "n(H2):n(X) = 3 => X kém Y 6 nguyên tử H => X = C55H100O6, có 100 H."], "ans": "100 nguyên tử H", "unit": "", "tol": ""}, {"n": 22, "q": "Thành phần chính của chất giặt rửa tổng hợp là", "opts": "A=C15H31COONa;B=(C17H35COO)2Ca;C=CH3[CH2]11-C6H4-SO3Na;D=C17H35COOK", "a": "C", "steps": ["Chất giặt rửa tổng hợp là muối alkylsulfate (-OSO3Na) hoặc alkylbenzenesulfonate (-SO3Na), có chứa S.", "A và D (chứa -COO-) là xà phòng; B là kết tủa với nước cứng.", "Vậy C đúng."], "ans": "C - CH3[CH2]11-C6H4-SO3Na", "unit": "", "tol": ""}, {"n": 23, "q": "Hợp chất nào dưới đây được sử dụng làm xà phòng?", "opts": "A=CH3COONa;B=CH3(CH2)14COONa;C=CH3(CH2)12COOCH3;D=CH3(CH2)5O(CH2)5CH3", "a": "B", "steps": ["Xà phòng là muối sodium/potassium của acid béo mạch dài (12-24 C).", "CH3(CH2)14COONa = C15H31COONa (sodium palmitate, 16 C) => đúng.", "A có 2 C quá ngắn; C là ester; D là ether."], "ans": "B - CH3(CH2)14COONa", "unit": "", "tol": ""}, {"n": 24, "q": "Nguyên nhân làm cho bồ kết có khả năng giặt rửa là", "opts": "A=trong bồ kết có chất khử mạnh;B=bồ kết có thành phần là ester của glycerol;C=trong bồ kết có những chất oxi hóa mạnh;D=bồ kết có những chất có cấu tạo kiểu đầu phân cực gắn với đuôi dài không phân cực", "a": "D", "steps": ["Bồ kết chứa saponin - chất giặt rửa tự nhiên.", "Saponin có đầu ưa nước gắn đuôi dài kị nước, giống cấu tạo xà phòng.", "Giặt rửa là nhũ hóa (vật lí), không phải oxi hóa khử."], "ans": "D", "unit": "", "tol": ""}, {"n": 25, "q": "Từ tristearin, người ta dùng phản ứng nào để điều chế ra xà phòng?", "opts": "A=Phản ứng ester hóa;B=Phản ứng thủy phân ester trong môi trường acid;C=Phản ứng cộng hydrogen;D=Phản ứng thủy phân ester trong môi trường kiềm", "a": "D", "steps": ["(C17H35COO)3C3H5 + 3NaOH -> 3C17H35COONa + C3H5(OH)3.", "Muối C17H35COONa chính là xà phòng.", "Vậy dùng phản ứng thủy phân trong kiềm (xà phòng hóa)."], "ans": "D - thủy phân ester trong môi trường kiềm", "unit": "", "tol": ""}, {"n": 26, "q": "Chất giặt rửa tổng hợp có ưu điểm", "opts": "A=dễ kiếm;B=rẻ tiền hơn xà phòng;C=có thể dùng để giặt rửa cả trong nước cứng;D=có khả năng hòa tan tốt trong nước", "a": "C", "steps": ["Muối sulfate/sulfonate của Ca2+, Mg2+ đều tan nên không tạo kết tủa trong nước cứng.", "Đây là ưu điểm phân biệt so với xà phòng (bị kết tủa với Ca2+, Mg2+)."], "ans": "C - dùng được cả trong nước cứng", "unit": "", "tol": ""}, {"n": 27, "q": "Cho các phát biểu: (a) Xà phòng bị giảm tác dụng khi dùng nước cứng vì tạo muối kết tủa với Ca2+, Mg2+; (b) Bột giặt tổng hợp dùng được với nước cứng; (c) Chế phẩm giặt có thể chứa chất tẩy trắng như sodium hypochlorite; (d) Chất giặt rửa có gốc hydrocarbon phân nhánh không gây ô nhiễm vì dễ bị vi sinh vật phân hủy; (e) Chất ưa nước là chất tan tốt trong dầu mỏ, alkane. Số phát biểu SAI là", "opts": "A=1;B=2;C=3;D=4", "a": "B", "steps": ["(a), (b), (c) đúng.", "(d) sai: gốc phân nhánh rất khó bị vi sinh vật phân hủy, gây ô nhiễm.", "(e) sai: chất ưa nước tan tốt trong nước; tan trong dầu mỏ là chất kị nước.", "Vậy có 2 phát biểu sai."], "ans": "B - 2", "unit": "", "tol": ""}, {"n": 28, "q": "Cho các chất: CH3[CH2]10CH2OSO3Na; CH3[CH2]14COONa; CH3[CH2]11-C6H4-SO3Na; CH3CH2COONa; CH3[CH2]16COOK. Số chất có thể là thành phần chính của xà phòng là bao nhiêu?", "opts": "", "a": "2", "steps": ["Xà phòng là muối Na/K của acid béo (nhóm -COO-, mạch dài).", "Đúng: CH3[CH2]14COONa (sodium palmitate) và CH3[CH2]16COOK (potassium stearate).", "Loại 2 chất chứa S (chất giặt rửa) và CH3CH2COONa (chỉ 3 C)."], "ans": "2 chất", "unit": "", "tol": ""}, {"n": 29, "q": "Xà phòng hóa hoàn toàn 0,1 mol tristearin (C17H35COO)3C3H5 bằng dung dịch NaOH dư, đun nóng, thu được m gam glycerol. Tính giá trị của m?", "opts": "", "a": "9,2", "steps": ["(C17H35COO)3C3H5 + 3NaOH -> 3C17H35COONa + C3H5(OH)3.", "n(glycerol) = n(tristearin) = 0,1 mol.", "m = 0,1 x 92 = 9,2 gam."], "ans": "9,2 gam", "unit": "g", "tol": "0.1"}, {"n": 30, "q": "Xà phòng hóa hoàn toàn 17,8 gam chất béo X cần vừa đủ dung dịch chứa 0,06 mol NaOH. Cô cạn dung dịch sau phản ứng thu được m gam muối khan. Tính giá trị của m?", "opts": "", "a": "18,36", "steps": ["n(glycerol) = n(NaOH)/3 = 0,02 mol.", "Bảo toàn khối lượng: m(X) + m(NaOH) = m(muối) + m(glycerol).", "m = 17,8 + 0,06 x 40 - 0,02 x 92 = 18,36 gam."], "ans": "18,36 gam", "unit": "g", "tol": "0.1"}, {"n": 31, "q": "Thủy phân hoàn toàn m gam chất béo bằng dung dịch NaOH, đun nóng, thu được 9,2 gam glycerol và 91,8 gam muối. Tính giá trị của m?", "opts": "", "a": "89", "steps": ["n(glycerol) = 9,2/92 = 0,1 mol => n(NaOH) = 0,3 mol.", "Bảo toàn khối lượng: m + m(NaOH) = m(muối) + m(glycerol).", "m = 91,8 + 9,2 - 0,3 x 40 = 89 gam."], "ans": "89 gam", "unit": "g", "tol": "1"}, {"n": 32, "q": "Lượng NaOH cần dùng trong một thí nghiệm điều chế xà phòng là 60 gam. Nếu thay NaOH bằng KOH thì khối lượng KOH cần dùng là bao nhiêu?", "opts": "", "a": "84", "steps": ["NaOH và KOH cùng hóa trị I nên số mol cần dùng bằng nhau.", "n = 60/40 = 1,5 mol.", "m(KOH) = 1,5 x 56 = 84 gam."], "ans": "84 gam", "unit": "g", "tol": "1"}, {"n": 33, "q": "Tính khối lượng muối thu được khi cho 100 kg một loại mỡ chứa 50% tristearin, 30% triolein và 20% tripalmitin tác dụng với sodium hydroxide vừa đủ (hiệu suất 100%).", "opts": "", "a": "103,22", "steps": ["Tổng n chất béo = 0,05618 + 0,03394 + 0,02481 = 0,11493 kmol.", "m(NaOH) = 3 x 0,11493 x 40 = 13,79 kg; m(glycerol) = 0,11493 x 92 = 10,57 kg.", "Bảo toàn khối lượng: m(muối) = 100 + 13,79 - 10,57 = 103,22 kg."], "ans": "~103,22 kg", "unit": "kg", "tol": "0.5"}, {"n": 34, "q": "Hãy phân loại các chất sau thành hai nhóm xà phòng và chất giặt rửa tổng hợp: C15H31COONa; CH3[CH2]11OSO3Na; CH3[CH2]11C6H4SO3Na; C17H33COOK.", "opts": "", "a": "", "steps": ["Nhóm xà phòng: muối Na/K của acid béo, có nhóm -COO-.", "Nhóm chất giặt rửa tổng hợp: muối alkylsulfate/alkylbenzenesulfonate, chứa nguyên tố S."], "ans": "Xà phòng: C15H31COONa, C17H33COOK. Chất giặt rửa tổng hợp: CH3[CH2]11OSO3Na, CH3[CH2]11C6H4SO3Na. (Mẹo: thấy -COO- là xà phòng, thấy S trong -SO3Na/-OSO3Na là chất giặt rửa.)", "unit": "", "tol": ""}, {"n": 35, "q": "Chỉ dùng nước và quỳ tím, hãy phân biệt các chất lỏng acetic acid, glycerol, triolein.", "opts": "", "a": "", "steps": ["Cho nước vào ba ống nghiệm: triolein không tan, tách lớp => nhận ra triolein.", "Nhúng quỳ tím vào hai ống còn lại (đều tan).", "Ống làm quỳ hóa đỏ là acetic acid; ống không đổi màu quỳ là glycerol."], "ans": "Triolein: không tan, tách lớp; acetic acid: quỳ hóa đỏ; glycerol: tan, không đổi màu quỳ.", "unit": "", "tol": ""}]}, "g12c2": {"title": "Chương 2 · Carbohydrate", "tagline": "Glucose · Saccharose · Tinh bột · Cellulose", "color": "#e2557c", "icon": "🍬", "num": "2", "feynman": "Nếu phải giải thích ngắn nhất: carbohydrate là cả 'nhà đường' — từ glucose và fructose (không thủy phân được) qua saccharose và maltose (thủy phân ra 2 đường đơn) đến tinh bột và cellulose (thủy phân ra rất nhiều). Hai mỏ neo để phân biệt cả sáu chất: có từ 2 nhóm –OH kề nhau thì hòa tan Cu(OH)₂ thành dung dịch xanh lam ở nhiệt độ thường; có nhóm CHO tự do thì cho phản ứng tráng bạc. Rà soát bảng so sánh theo đúng hai tiêu chí đó, rồi nhớ thêm liên kết glycoside α-1,4/α-1,6 của tinh bột và β-1,4 của cellulose là bạn đã bao trọn chương.", "notes": [{"kind": "card", "t": "Carbohydrate là gì?", "b": "Carbohydrate (còn gọi là đường, gluxit, saccharide) là hợp chất hữu cơ tạp chức, phần lớn có công thức chung Cₙ(H₂O)ₘ.\nPhần lớn phân tử chứa nhiều nhóm –OH cùng nhóm chức aldehyde (CHO) hoặc ketone (C=O) => thể hiện tính chất của alcohol đa chức và của aldehyde/ketone.\nVai trò: cung cấp năng lượng (glucose, tinh bột), thành phần cấu trúc tế bào thực vật (cellulose), nguyên liệu cho công nghiệp thực phẩm, giấy, dệt, dược phẩm."}, {"kind": "table", "t": "Phân loại carbohydrate theo khả năng thủy phân", "b": "Loại | Đặc điểm | Đại diện | Công thức phân tử\nMonosaccharide | Không bị thủy phân | Glucose, fructose | C₆H₁₂O₆\nDisaccharide | Thủy phân → 2 phân tử monosaccharide | Saccharose, maltose | C₁₂H₂₂O₁₁\nPolysaccharide | Thủy phân → nhiều phân tử monosaccharide | Tinh bột, cellulose | (C₆H₁₀O₅)ₙ"}, {"kind": "card", "t": "Glucose – cấu tạo", "b": "Chất rắn tinh thể không màu, dễ tan trong nước, vị ngọt (kém saccharose). Có trong quả chín (nho chín nên gọi là đường nho), mật ong (~30%), máu người (~0,1%).\nMạch hở: CH₂OH[CHOH]₄CHO — 1 nhóm aldehyde (CHO) + 5 nhóm –OH trên 5 carbon liên tiếp => glucose là polyalcohol-aldehyde (tạp chức).\nMạch vòng: trong dung dịch chủ yếu tồn tại ở dạng vòng 6 cạnh (pyranose) gồm α-glucose và β-glucose, khác nhau ở vị trí nhóm –OH hemiacetal (C1); dạng mạch hở chỉ chiếm một lượng rất nhỏ."}, {"kind": "rxn", "t": "Glucose – tính chất của polyalcohol", "b": "Nhiều nhóm –OH kề nhau nên hòa tan Cu(OH)₂ ở nhiệt độ thường, tạo dung dịch phức màu xanh lam:\n2C₆H₁₂O₆ + Cu(OH)₂ → (C₆H₁₁O₆)₂Cu + 2H₂O\n(Cùng nhóm này: fructose, saccharose, maltose, glycerol — chất nào có ≥ 2 nhóm –OH kề nhau đều cho dung dịch xanh lam ở t° thường.)"}, {"kind": "rxn", "t": "Glucose – tính chất của aldehyde (nhóm CHO)", "b": "Tráng bạc với Tollens, đun nóng nhẹ (1 glucose → 2 Ag):\nC₆H₁₂O₆ + 2[Ag(NH₃)₂]OH → C₆H₁₁O₇NH₄ + 2Ag↓ + 3NH₃ + H₂O (gương bạc bám ống nghiệm)\nKhử Cu(OH)₂ trong môi trường kiềm, đun nóng (1 glucose → 1 Cu₂O):\nC₆H₁₂O₆ + 2Cu(OH)₂ + NaOH → C₆H₁₁O₇Na + Cu₂O↓ + 3H₂O (kết tủa đỏ gạch)\nLàm mất màu nước bromine: C₆H₁₂O₆ + Br₂ + H₂O → C₆H₁₂O₇ + 2HBr (Br₂ oxi hóa glucose thành acid gluconic — đặc trưng, fructose KHÔNG làm được).\nCộng H₂ (Ni, t°): glucose → sorbitol C₆H₁₄O₆ (tính chất của alcohol)."}, {"kind": "rxn", "t": "Điều chế, lên men và ứng dụng glucose", "b": "Điều chế: thủy phân tinh bột hoặc cellulose (xúc tác acid hoặc enzyme): (C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆\nLên men (enzyme, 30–35°C): C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂↑ (sản xuất rượu).\nỨng dụng: thuốc tăng lực (dịch truyền glucose), tráng gương, tráng ruột phích, nguyên liệu sản xuất ethanol, vitamin C, sorbitol."}, {"kind": "card", "t": "Fructose – cấu tạo và tính chất", "b": "Đồng phân của glucose (cùng C₆H₁₂O₆), nhiều trong quả ngọt và đặc biệt trong mật ong (~40%); là chất rắn dễ tan, NGỌT NHẤT trong các loại đường.\nMạch hở: CH₂OH[CHOH]₃COCH₂OH — 1 nhóm ketone (C=O) + 5 nhóm –OH; trong dung dịch chủ yếu ở dạng vòng 5 cạnh (furanose) gồm α và β (–OH hemiketal ở C2).\n• Hòa tan Cu(OH)₂ ở t° thường → dung dịch xanh lam (nhiều –OH kề nhau).\n• Trong môi trường base chuyển hóa thành glucose nên vẫn cho phản ứng tráng bạc và khử Cu(OH)₂ đun nóng.\n• KHÔNG làm mất màu nước bromine => cách phân biệt fructose với glucose."}, {"kind": "card", "t": "Saccharose – cấu tạo (đường mía)", "b": "Chất rắn kết tinh, không màu, vị ngọt, dễ tan trong nước (tan nhiều hơn khi t° tăng). Có nhiều trong cây mía, củ cải đường, hoa thốt nốt.\nPhân tử = 1 gốc α-glucose + 1 gốc β-fructose nối với nhau qua liên kết α-1,2-glycoside.\nCả hai nhóm –OH hemiacetal đều tham gia tạo liên kết => phân tử KHÔNG còn nhóm CHO tự do, KHÔNG mở vòng được => không tráng bạc, không khử Cu(OH)₂ đun nóng.\nVẫn hòa tan Cu(OH)₂ ở t° thường (nhiều –OH kề nhau)."}, {"kind": "rxn", "t": "Thủy phân saccharose và maltose", "b": "Saccharose: C₁₂H₂₂O₁₁ + H₂O →(H⁺ hoặc enzyme invertase) C₆H₁₂O₆ (glucose) + C₆H₁₂O₆ (fructose)\nMaltose: C₁₂H₂₂O₁₁ + H₂O →(H⁺ hoặc enzyme) 2C₆H₁₂O₆\nThủy phân xong cả hai đều cho sản phẩm có tính khử (có glucose => tráng bạc).\nTỉ lệ tính nhanh: 1 mol saccharose → 2 mol monosaccharide → tráng bạc tạo 4 mol Ag (mỗi sản phẩm cho 2 Ag); 1 mol maltose → 2 glucose."}, {"kind": "card", "t": "Maltose – cấu tạo (đường mạch nha)", "b": "Chất rắn kết tinh, dễ tan trong nước, ngọt kém saccharose. Có trong mạch nha; là sản phẩm trung gian khi thủy phân tinh bột nhờ enzyme amylase.\nCấu tạo: 2 gốc α-glucose nối với nhau qua liên kết α-1,4-glycoside; một gốc còn nhóm –OH hemiacetal TỰ DO nên mở vòng tạo nhóm CHO.\n• Hòa tan Cu(OH)₂ ở t° thường → dung dịch xanh lam.\n• CÓ tráng bạc và khử Cu(OH)₂ trong môi trường kiềm khi đun nóng (1 maltose → 2 Ag).\n• Thủy phân → 2 glucose. Ứng dụng: sản xuất bia, rượu, bánh kẹo."}, {"kind": "table", "t": "Bảng so sánh và nhận biết 6 carbohydrate", "b": "Chất | Tan Cu(OH)₂ (t° thường) | Tráng bạc | Mất màu nước Br₂ | Thủy phân | Cấu tạo chính\nGlucose | Có | Có | Có | Không (monosaccharide) | Mạch hở có CHO, vòng 6 cạnh (α, β)\nFructose | Có | Có (qua chuyển hóa trong base) | Không | Không (monosaccharide) | Nhóm C=O (ketone), vòng 5 cạnh\nSaccharose | Có | Không | Không | Có → glucose + fructose | α-glucose + β-fructose (α-1,2)\nMaltose | Có | Có | Có | Có → 2 glucose | 2 α-glucose (α-1,4)\nTinh bột | Không | Không | Không | Có → glucose | Amylose α-1,4; amylopectin α-1,4 + α-1,6\nCellulose | Không | Không | Không | Có → glucose | β-glucose, β-1,4, không nhánh"}, {"kind": "card", "t": "Tinh bột – cấu tạo", "b": "Chất rắn dạng bột vô định hình, màu trắng, KHÔNG tan trong nước lạnh; từ 65°C trở lên hạt tinh bột trương lên tạo hồ tinh bột (dung dịch keo). Có nhiều trong gạo, ngô, khoai, sắn.\nLà hỗn hợp 2 polysaccharide, đều tạo từ các gốc α-glucose:\n• Amylose (20–30%): mạch KHÔNG phân nhánh, các gốc α-glucose nối bằng liên kết α-1,4-glycoside, xoắn lại thành hình lò xo.\n• Amylopectin (70–80%): mạch PHÂN NHÁNH, ngoài α-1,4 còn có liên kết α-1,6-glycoside ở chỗ phân nhánh."}, {"kind": "rxn", "t": "Tinh bột – thủy phân, nhận biết và quang hợp", "b": "Thủy phân (xúc tác acid hoặc enzyme): tinh bột → dextrin → maltose → glucose\n(C₆H₁₀O₅)ₙ + nH₂O → nC₆H₁₂O₆\nNhận biết: hồ tinh bột + dung dịch I₂ → màu XANH TÍM (đun nóng thì mất màu, để nguội màu xuất hiện lại) — dùng để nhận biết cả tinh bột lẫn iodine.\nTinh bột KHÔNG có phản ứng tráng bạc.\nTạo trong cây xanh nhờ quang hợp: 6nCO₂ + 5nH₂O →(ánh sáng, diệp lục) (C₆H₁₀O₅)ₙ + 6nO₂"}, {"kind": "card", "t": "Cellulose – cấu tạo", "b": "Chất rắn dạng sợi, màu trắng, không mùi, không vị; KHÔNG tan trong nước và dung môi hữu cơ thông thường, nhưng TAN trong nước Schweizer Cu(NH₃)₄(OH)₂.\nThành phần chính của màng tế bào thực vật: bông (gần 98%), gỗ (40–50%), tre, nứa, đay, gai.\nCấu tạo: các gốc β-glucose nối với nhau qua liên kết β-1,4-glycoside, tạo mạch dài KHÔNG phân nhánh, không xoắn. Mỗi gốc glucose có 3 nhóm –OH tự do => công thức viết [C₆H₇O₂(OH)₃]ₙ.\nKhông có phản ứng tráng bạc."}, {"kind": "rxn", "t": "Cellulose – phản ứng và ứng dụng", "b": "Thủy phân (acid, đun nóng) → glucose, khó hơn tinh bột:\n[C₆H₇O₂(OH)₃]ₙ + nH₂O →(H⁺, t°) nC₆H₁₂O₆\nNitric acid (HNO₃ đặc, xúc tác H₂SO₄ đặc):\n[C₆H₇O₂(OH)₃]ₙ + 3nHNO₃ → [C₆H₇O₂(ONO₂)₃]ₙ + 3nH₂O (cellulose trinitrate → thuốc súng không khói)\nAcetic anhydride → cellulose acetate → tơ acetate.\nỨng dụng: giấy, vải sợi bông, đồ gỗ; tơ visco (cellulose + NaOH + CS₂); chất xơ trong thức ăn (cơ thể người không tiêu hóa được cellulose)."}, {"kind": "table", "t": "Tỉ lệ mol và khối lượng mol cần nhớ", "b": "Phản ứng / chất | Tỉ lệ | Khối lượng cần nhớ\nGlucose, fructose tráng bạc | 1 chất : 2 Ag | M = 180\nMaltose tráng bạc | 1 maltose : 2 Ag | M = 342\nThủy phân saccharose | 1 saccharose → 1 glucose + 1 fructose (→ 4 Ag) | 342 → 180 + 180 (342 + 18 H₂O)\nThủy phân maltose | 1 maltose → 2 glucose | 342 → 2 × 180\nThủy phân tinh bột, cellulose | 1 mắt xích C₆H₁₀O₅ → 1 glucose | 162 → 180\nLên men glucose | 1 glucose → 2 C₂H₅OH + 2 CO₂ | 180 → 92\nCellulose + HNO₃ | 1 mắt xích : 3 HNO₃ | 162 → 297 (trinitrate)"}, {"kind": "trick", "t": "Mẹo ghi nhớ nhanh", "b": "• Hai 'mỏ neo' phân biệt cả 6 chất: có ≥ 2 nhóm –OH kề nhau → xanh lam với Cu(OH)₂ ở t° thường; có nhóm CHO TỰ DO → tráng bạc.\n• Phân biệt glucose và fructose: cả hai đều tráng bạc, nhưng chỉ glucose làm mất màu nước bromine.\n• Nhớ gốc tạo: tinh bột từ α-glucose (α-1,4 và α-1,6), cellulose từ β-glucose (β-1,4).\n• Tính nhanh Ag: 1 glucose/fructose/maltose → 2 Ag; 1 saccharose sau thủy phân → 4 Ag.\n• Bộ M nhớ lẹ: glucose, fructose = 180 · saccharose, maltose = 342 · mắt xích C₆H₁₀O₅ = 162 · mắt xích cellulose trinitrate = 297."}, {"kind": "danger", "t": "Điểm dễ nhầm", "b": "• Saccharose, tinh bột, cellulose KHÔNG tráng bạc; glucose, fructose, maltose CÓ (fructose nhờ chuyển hóa thành glucose trong base).\n• Fructose tráng bạc được nhưng KHÔNG làm mất màu Br₂; glucose thì có — dùng để phân biệt hai chất này.\n• Tinh bột và cellulose cùng công thức (C₆H₁₀O₅)ₙ nhưng KHÔNG phải đồng phân (n khác nhau). Glucose ↔ fructose và saccharose ↔ maltose mới là đồng phân.\n• Saccharose không có –OH hemiacetal tự do; maltose thì có (nên maltose tráng bạc được, saccharose thì không).\n• Cellulose KHÔNG tan nước nhưng TAN trong nước Schweizer Cu(NH₃)₄(OH)₂.\n• Dạng mạch hở của glucose chỉ chiếm một lượng rất nhỏ trong dung dịch — chủ yếu là dạng vòng."}], "exercises": [{"n": 1, "q": "Carbohydrate nào dưới đây thuộc loại disaccharide?", "opts": "A=Amylose;B=Saccharose;C=Glucose;D=Cellulose", "a": "B", "steps": ["Disaccharide là carbohydrate khi thủy phân hoàn toàn mỗi phân tử tạo thành 2 phân tử monosaccharide (C₁₂H₂₂O₁₁).", "Saccharose thủy phân → glucose + fructose => là disaccharide. Amylose và cellulose là polysaccharide; glucose là monosaccharide."], "ans": "B - Saccharose", "unit": "", "tol": ""}, {"n": 2, "q": "Số nguyên tử hydrogen trong phân tử fructose là", "opts": "A=10;B=12;C=22;D=6", "a": "B", "steps": ["Fructose là monosaccharide có công thức phân tử C₆H₁₂O₆ (đồng phân của glucose).", "Đếm hydrogen: 12 nguyên tử."], "ans": "B - 12", "unit": "", "tol": ""}, {"n": 3, "q": "Chất nào sau đây còn có tên gọi là đường nho?", "opts": "A=Glucose;B=Saccharose;C=Fructose;D=Tinh bột", "a": "A", "steps": ["Glucose có nhiều trong quả nho chín nên còn gọi là đường nho (có trong mật ong ~30%, máu người ~0,1%)."], "ans": "A - Glucose", "unit": "", "tol": ""}, {"n": 4, "q": "Hai chất đồng phân của nhau là", "opts": "A=glucose và maltose;B=fructose và glucose;C=fructose và maltose;D=saccharose và glucose", "a": "B", "steps": ["Đồng phân = cùng công thức phân tử, khác cấu tạo.", "Fructose và glucose cùng C₆H₁₂O₆ => đồng phân. Các cặp còn lại khác công thức phân tử (180 khác 342)."], "ans": "B - fructose và glucose", "unit": "", "tol": ""}, {"n": 5, "q": "Chất nào sau đây có phản ứng tráng bạc?", "opts": "A=Saccharose;B=Cellulose;C=Tinh bột;D=Glucose", "a": "D", "steps": ["Tráng bạc cần nhóm CHO tự do (hoặc chuyển hóa tạo nhóm CHO trong môi trường base).", "Glucose có nhóm CHO => tráng bạc. Saccharose: cả 2 nhóm –OH hemiacetal đã tham gia liên kết α-1,2; tinh bột và cellulose không có nhóm CHO tự do."], "ans": "D - Glucose", "unit": "", "tol": ""}, {"n": 6, "q": "Cho dãy: glucose, fructose, saccharose, cellulose. Số chất trong dãy tham gia phản ứng tráng bạc là", "opts": "A=4;B=2;C=1;D=3", "a": "B", "steps": ["Glucose: có nhóm CHO => có. Fructose: trong môi trường base chuyển hóa thành glucose => có.", "Saccharose: không có –OH hemiacetal tự do => không. Cellulose: không có nhóm CHO tự do => không.", "Vậy có 2 chất."], "ans": "B - 2", "unit": "", "tol": ""}, {"n": 7, "q": "Carbohydrate nào dưới đây không có nhóm –OH hemiacetal hoặc nhóm –OH hemiketal?", "opts": "A=Maltose;B=Fructose;C=Saccharose;D=Glucose", "a": "C", "steps": ["Saccharose: cả 2 nhóm –OH hemiacetal (của α-glucose và β-fructose) đều tham gia tạo liên kết α-1,2-glycoside => không còn –OH hemiacetal tự do.", "Maltose còn 1 –OH hemiacetal tự do; glucose có –OH hemiacetal ở C1; fructose có –OH hemiketal."], "ans": "C - Saccharose", "unit": "", "tol": ""}, {"n": 8, "q": "Chất nào sau đây bị thủy phân khi đun nóng trong môi trường acid?", "opts": "A=Saccharose;B=Glycerol;C=Glucose;D=Fructose", "a": "A", "steps": ["Thủy phân chỉ xảy ra với chất có liên kết glycoside (disaccharide, polysaccharide).", "Saccharose → glucose + fructose. Glycerol là alcohol; glucose, fructose là monosaccharide nên không bị thủy phân thêm."], "ans": "A - Saccharose", "unit": "", "tol": ""}, {"n": 9, "q": "Polymer thiên nhiên X được sinh ra trong quá trình quang hợp của cây xanh. Ở nhiệt độ thường, X tạo với dung dịch iodine hợp chất có màu xanh tím. Polymer X là", "opts": "A=tinh bột;B=cellulose;C=saccharose;D=glicogen", "a": "A", "steps": ["Màu xanh tím với dung dịch I₂ là phản ứng đặc trưng của tinh bột (hồ tinh bột).", "Tinh bột được tạo trong quang hợp; cellulose không cho phản ứng I₂; glycogen có ở động vật."], "ans": "A - tinh bột", "unit": "", "tol": ""}, {"n": 10, "q": "Dãy các chất đều có khả năng tham gia phản ứng thủy phân trong dung dịch H₂SO₄ đun nóng là", "opts": "A=glucose, tinh bột và cellulose;B=saccharose, tinh bột và cellulose;C=glucose, saccharose và fructose;D=fructose, saccharose và tinh bột", "a": "B", "steps": ["Chỉ disaccharide và polysaccharide mới có liên kết glycoside để thủy phân.", "Glucose và fructose là monosaccharide => loại mọi dãy còn chúng (A, C, D)."], "ans": "B - saccharose, tinh bột và cellulose", "unit": "", "tol": ""}, {"n": 11, "q": "Dãy gồm các dung dịch đều tham gia phản ứng tráng bạc là", "opts": "A=Glucose, maltose, formic acid, aldehyde acetic;B=Fructose, maltose, glycerol, aldehyde acetic;C=Glucose, glycerol, maltose, formic acid;D=Glucose, fructose, maltose, saccharose", "a": "A", "steps": ["Aldehyde acetic (CH₃CHO) có nhóm CHO; formic acid HCOOH có cấu trúc H–C=O => đều tráng bạc. Glycerol và saccharose thì không.", "B và C sai vì có glycerol (không tráng bạc); D sai vì có saccharose."], "ans": "A - glucose, maltose, formic acid, aldehyde acetic", "unit": "", "tol": ""}, {"n": 12, "q": "Phát biểu nào sau đây không đúng?", "opts": "A=Dung dịch fructose hoà tan được Cu(OH)2;B=Thủy phân (xúc tác H+, đun nóng) saccharose cũng như maltose đều cho cùng một monosaccharide;C=Sản phẩm thủy phân cellulose có thể tham gia phản ứng tráng gương;D=Dung dịch maltose tác dụng với Cu(OH)2 khi đun nóng cho kết tủa Cu2O", "a": "B", "steps": ["B sai: saccharose → glucose + fructose, còn maltose → 2 glucose => không cho cùng một monosaccharide.", "A đúng: fructose có nhiều –OH kề nhau. C đúng: sản phẩm là glucose. D đúng: maltose có tính khử."], "ans": "B - thủy phân saccharose và maltose cho hai monosaccharide khác nhau", "unit": "", "tol": ""}, {"n": 13, "q": "Cho các phát biểu: (a) Đốt cháy hoàn toàn ester no, đơn chức, mạch hở luôn thu được số mol CO₂ bằng số mol H₂O. (b) Trong hợp chất hữu cơ nhất thiết phải có carbon và hydrogen. (c) Những hợp chất hữu cơ có thành phần nguyên tố giống nhau, thành phần phân tử hơn kém nhau một hay nhiều nhóm CH₂ là đồng đẳng của nhau. (d) Dung dịch glucose bị khử bởi AgNO₃ trong NH₃ tạo ra Ag. (e) Saccharose chỉ có cấu tạo mạch vòng. Số phát biểu đúng là", "opts": "A=5;B=3;C=4;D=2", "a": "C", "steps": ["(a) đúng: este no đơn chức mạch hở có công thức CₙH₂ₙO₂ đốt cháy → nCO₂ + nH₂O (vd ethyl acetate C₄H₈O₂ → 4CO₂ + 4H₂O).", "(b) sai: có hợp chất hữu cơ không chứa hydrogen (vd CCl₄). (c) đúng (định nghĩa đồng đẳng). (d) đúng (glucose có tính khử). (e) đúng (cả 2 –OH hemiacetal tham gia liên kết nên saccharose chỉ có dạng mạch vòng).", "Tổng cộng 4 phát biểu đúng."], "ans": "C - 4", "unit": "", "tol": ""}, {"n": 14, "q": "Cho các phát biểu: (a) Glucose được gọi là đường nho do có nhiều trong quả nho chín. (b) Chất béo là diester của glycerol với acid béo. (c) Phân tử amylopectin có cấu trúc mạch phân nhánh. (d) Ở nhiệt độ thường, triolein ở trạng thái rắn. (e) Trong mật ong chứa nhiều fructose. (f) Tinh bột là một trong những lương thực cơ bản của con người. Số phát biểu đúng là", "opts": "A=5;B=6;C=3;D=4", "a": "D", "steps": ["(a) đúng; (c) đúng (amylopectin có α-1,4 và α-1,6 => phân nhánh); (e) đúng (~40% fructose); (f) đúng.", "(b) sai: chất béo là TRIester của glycerol với 3 acid béo.", "(d) sai: triolein chứa 3 gốc oleic không no nên là chất lỏng ở t° thường.", "Vậy có 4 phát biểu đúng."], "ans": "D - 4", "unit": "", "tol": ""}, {"n": 15, "q": "Cho các chất: saccharose, glucose, fructose, ethyl formate, formic acid và aldehyde acetic. Số chất vừa có khả năng tham gia phản ứng tráng bạc vừa có khả năng phản ứng với Cu(OH)2 ở điều kiện thường là bao nhiêu?", "opts": "", "a": "2", "steps": ["Tráng bạc: glucose, fructose, ethyl formate, formic acid, aldehyde acetic (5 chất).", "Phản ứng với Cu(OH)₂ Ở ĐIỀU KIỆN THƯỜNG cần ≥ 2 nhóm –OH kề nhau: glucose, fructose, saccharose.", "Giao của hai tập là glucose và fructose => 2 chất."], "ans": "2 chất", "unit": "", "tol": ""}, {"n": 16, "q": "Cho dãy các chất: glucose, cellulose, saccharose, tinh bột và fructose. Số chất trong dãy tham gia phản ứng tráng gương là bao nhiêu?", "opts": "", "a": "2", "steps": ["Tráng gương (tráng bạc) cần nhóm CHO tự do hoặc chuyển hóa tạo CHO trong môi trường base.", "Glucose ✓ và fructose ✓; cellulose, saccharose, tinh bột ✗."], "ans": "2 chất", "unit": "", "tol": ""}, {"n": 17, "q": "Dung dịch chứa 0,2 mol fructose có khả năng hòa tan tối đa b mol Cu(OH)2. Tính giá trị của b?", "opts": "", "a": "0.1", "steps": ["Phản ứng: 2 phân tử đường (nhiều –OH kề nhau) hòa tan 1 phân tử Cu(OH)₂ tạo phức xanh lam — giống phản ứng 2C₆H₁₂O₆ + Cu(OH)₂.", "b = 0,2 / 2 = 0,1 mol."], "ans": "b = 0,1 mol", "unit": "mol", "tol": "0.05"}, {"n": 18, "q": "Thủy phân 1,71 gam saccharose với hiệu suất 75%, thu được hỗn hợp X. Cho toàn bộ X vào lượng dư dung dịch AgNO3 trong NH3, đun nóng, thu được m gam Ag. Tính giá trị của m?", "opts": "", "a": "1.62", "steps": ["n(saccharose) = 1,71/342 = 0,005 mol; n(thực tế) = 0,005 × 75% = 0,00375 mol.", "1 saccharose → 1 glucose + 1 fructose; mỗi monosaccharide cho 2 Ag => 1 saccharose → 4 Ag.", "n(Ag) = 4 × 0,00375 = 0,015 mol → m = 0,015 × 108 = 1,62 gam."], "ans": "m = 1,62 gam", "unit": "g", "tol": "0.05"}, {"n": 19, "q": "Từ m kg mùn cưa chứa 50% cellulose (còn lại là tạp chất trơ) sản xuất được 80 kg glucose với hiệu suất toàn bộ quá trình là 80%. Tính giá trị của m?", "opts": "", "a": "180", "steps": ["n(glucose thực tế) = 80/180 = 444,44 mol.", "1 mắt xích C₆H₁₀O₅ → 1 glucose: n(cellulose thực tế) = 444,44 mol → n(lý thuyết) = 444,44/0,8 = 555,56 mol.", "m(cellulose) = 555,56 × 162 = 90 kg. Mùn cưa chứa 50% cellulose → m = 90/0,5 = 180 kg."], "ans": "m = 180 kg", "unit": "kg", "tol": "1"}]}, "g12c3": {"meta": {"title": "Chương 3 · Hợp chất chứa Nitrogen · Amine", "desc": "Khái niệm, phân loại theo gốc hydrocarbon và theo bậc, đồng phân, danh pháp, tính chất vật lí, tính chất hoá học (tính base, phản ứng với acid, muối Fe, phản ứng thế bromine ở nhân thơm, phản ứng với nitrous acid) và điều chế amine."}, "feynman": "Amine giống như ammonia (NH₃) nhưng có 1, 2 hoặc cả 3 nguyên tử H được thay thế bằng gốc hydrocarbon. Vì nguyên tử N vẫn còn cặp electron tự do chưa liên kết nên amine có tính base (nhận proton H⁺) và có mùi khai/tanh đặc trưng (như mùi tanh của cá mè do trimethylamine). Lưu ý cốt tử: Bậc của amine được tính bằng số gốc hydrocarbon gắn vào N (bậc 1: R-NH₂, bậc 2: R-NH-R', bậc 3: R-N(R')-R''), hoàn toàn khác với bậc của alcohol (tính theo bậc C mang nhóm OH)!", "notes": [{"id": "g12c3_n1", "title": "1. Khái niệm, phân loại & Bậc của amine", "tag": "Khái niệm · Bậc amine", "kind": "rule", "rule": "Bậc amine = Số gốc hydrocarbon liên kết trực tiếp với nguyên tử N.", "feynman": "Đừng nhầm với alcohol! Alcohol bậc 3 là -OH gắn vào C bậc 3. Nhưng amine (CH₃)₃C-NH₂ chỉ có 1 gốc hydrocarbon gắn vào N nên là amine bậc 1!", "text": "• Khái niệm: Khi thay thế một hay nhiều nguyên tử H trong phân tử NH₃ bằng một hay nhiều gốc hydrocarbon, ta được amine.\n• Phân loại theo gốc: Amine béo (alkylamine: CH₃NH₂, C₂H₅NH₂...) và amine thơm (arylamine: C₆H₅NH₂ aniline).\n• Phân loại theo bậc:\n  - Bậc 1: R-NH₂ (ví dụ: CH₃NH₂ methylamine, C₆H₅NH₂ aniline)\n  - Bậc 2: R-NH-R' (ví dụ: CH₃-NH-CH₃ dimethylamine)\n  - Bậc 3: R-N(R')-R'' (ví dụ: (CH₃)₃N trimethylamine)", "t": "1. Khái niệm, phân loại & Bậc của amine", "b": "• Bậc amine = Số gốc hydrocarbon liên kết trực tiếp với nguyên tử N.\n\n• Khái niệm: Khi thay thế một hay nhiều nguyên tử H trong phân tử NH₃ bằng một hay nhiều gốc hydrocarbon, ta được amine.\n• Phân loại theo gốc: Amine béo (alkylamine: CH₃NH₂, C₂H₅NH₂...) và amine thơm (arylamine: C₆H₅NH₂ aniline).\n• Phân loại theo bậc:\n  - Bậc 1: R-NH₂ (ví dụ: CH₃NH₂ methylamine, C₆H₅NH₂ aniline)\n  - Bậc 2: R-NH-R' (ví dụ: CH₃-NH-CH₃ dimethylamine)\n  - Bậc 3: R-N(R')-R'' (ví dụ: (CH₃)₃N trimethylamine)"}, {"id": "g12c3_n2", "title": "2. Đồng phân & Danh pháp amine", "tag": "Đồng phân · Danh pháp IUPAC", "kind": "rule", "rule": "C₃H₉N có 4 đồng phân amine (2 bậc 1, 1 bậc 2, 1 bậc 3). C₄H₁₁N có 8 đồng phân amine (4 bậc 1, 3 bậc 2, 1 bậc 3).", "feynman": "Gọi tên amine có 3 cách: Tên gốc-chức (gốc alkyl + amine), Tên thay thế IUPAC (vị trí + tên alkane + amine), và Tên thông thường (Aniline cho C₆H₅NH₂).", "text": "• Tên gốc - chức: Tên gốc hydrocarbon + amine.\n  Ví dụ: CH₃-NH₂ (methylamine), CH₃-NH-C₂H₅ (ethylmethylamine), (CH₃)₃N (trimethylamine).\n• Tên thay thế (IUPAC):\n  Ví dụ: CH₃-CH(NH₂)-CH₃ là propan-2-amine; CH₃-CH₂-CH₂-NH₂ là propan-1-amine.\n• Tên thông thường: C₆H₅NH₂ là Aniline (benzenamine).", "t": "2. Đồng phân & Danh pháp amine", "b": "• C₃H₉N có 4 đồng phân amine (2 bậc 1, 1 bậc 2, 1 bậc 3). C₄H₁₁N có 8 đồng phân amine (4 bậc 1, 3 bậc 2, 1 bậc 3).\n\n• Tên gốc - chức: Tên gốc hydrocarbon + amine.\n  Ví dụ: CH₃-NH₂ (methylamine), CH₃-NH-C₂H₅ (ethylmethylamine), (CH₃)₃N (trimethylamine).\n• Tên thay thế (IUPAC):\n  Ví dụ: CH₃-CH(NH₂)-CH₃ là propan-2-amine; CH₃-CH₂-CH₂-NH₂ là propan-1-amine.\n• Tên thông thường: C₆H₅NH₂ là Aniline (benzenamine)."}, {"id": "g12c3_n3", "title": "3. Tính chất vật lí & Mùi tanh của cá", "tag": "Tính chất vật lí · Liên kết H", "kind": "card", "feynman": "Mùi tanh của cá chủ yếu do trimethylamine (CH₃)₃N gây ra. Khi nấu cá, người ta dùng giấm ăn (acid acetic) hoặc chanh (acid citric) để chuyển amine thành muối không bay hơi, làm hết mùi tanh!", "text": "• Thể khí ở nhiệt độ thường: CH₃NH₂, (CH₃)₂NH, (CH₃)₃N và C₂H₅NH₂ là các chất khí, mùi khai khó chịu, độc, tan nhiều trong nước nhờ liên kết hydrogen với nước.\n• Các amine đồng đẳng cao hơn là chất lỏng hoặc rắn, độ tan trong nước giảm dần khi phân tử khối tăng.\n• Aniline: Chất lỏng không màu, sôi ở 184°C, ít tan trong nước, nặng hơn nước (lắng xuống đáy), để lâu ngoài không khí bị oxi hoá chuyển sang màu nâu đen.\n• So sánh nhiệt độ sôi: Acid > Alcohol > Amine > Alkane (vì liên kết H của amine N-H···N yếu hơn liên kết H của alcohol O-H···O).", "t": "3. Tính chất vật lí & Mùi tanh của cá", "b": "• Thể khí ở nhiệt độ thường: CH₃NH₂, (CH₃)₂NH, (CH₃)₃N và C₂H₅NH₂ là các chất khí, mùi khai khó chịu, độc, tan nhiều trong nước nhờ liên kết hydrogen với nước.\n• Các amine đồng đẳng cao hơn là chất lỏng hoặc rắn, độ tan trong nước giảm dần khi phân tử khối tăng.\n• Aniline: Chất lỏng không màu, sôi ở 184°C, ít tan trong nước, nặng hơn nước (lắng xuống đáy), để lâu ngoài không khí bị oxi hoá chuyển sang màu nâu đen.\n• So sánh nhiệt độ sôi: Acid > Alcohol > Amine > Alkane (vì liên kết H của amine N-H···N yếu hơn liên kết H của alcohol O-H···O)."}, {"id": "g12c3_n4", "title": "4. Tính base & So sánh lực base", "tag": "Tính base · So sánh lực base", "kind": "rule", "rule": "Thứ tự lực base: Amine bậc 2 no > Amine bậc 1 no > NH₃ > Aniline.", "feynman": "Gốc đẩy electron (nhóm alkyl như methyl, ethyl) làm tăng mật độ electron trên N -> tính base MẠNH HƠN NH₃. Gốc hút electron (vòng phenyl C₆H₅-) làm giảm mật độ electron trên N -> tính base YẾU HƠN NH₃!", "text": "• Nguyên nhân tính base: Nguyên tử N còn cặp electron tự do chưa liên kết có khả năng nhận proton H⁺.\n• Tác dụng với chỉ thị màu:\n  - Các alkylamine (methylamine, ethylamine...) làm quỳ tím chuyển sang màu xanh, làm phenolphthalein chuyển sang màu hồng.\n  - Aniline KHÔNG làm đổi màu quỳ tím và phenolphthalein do tính base quá yếu (nhỏ hơn NH₃ hàng nghìn lần).", "t": "4. Tính base & So sánh lực base", "b": "• Thứ tự lực base: Amine bậc 2 no > Amine bậc 1 no > NH₃ > Aniline.\n\n• Nguyên nhân tính base: Nguyên tử N còn cặp electron tự do chưa liên kết có khả năng nhận proton H⁺.\n• Tác dụng với chỉ thị màu:\n  - Các alkylamine (methylamine, ethylamine...) làm quỳ tím chuyển sang màu xanh, làm phenolphthalein chuyển sang màu hồng.\n  - Aniline KHÔNG làm đổi màu quỳ tím và phenolphthalein do tính base quá yếu (nhỏ hơn NH₃ hàng nghìn lần)."}, {"id": "g12c3_n5", "title": "5. Phản ứng với acid & Tạo khói trắng", "tag": "Phản ứng acid · Muối ammonium", "kind": "rxn", "feynman": "Khói trắng: Đưa đầu đũa thủy tinh nhúng dung dịch HCl đặc lại gần miệng lọ dung dịch methylamine đặc, khói trắng CH₃NH₃Cl bay lên tương tự như thí nghiệm NH₃ + HCl!", "text": "• Tác dụng với acid mạnh tạo muối:\n  CH₃NH₂ + HCl → [CH₃NH₃]⁺Cl⁻ (methylammonium chloride)\n  C₆H₅NH₂ + HCl → [C₆H₅NH₃]⁺Cl⁻ (phenylammonium chloride - muối tan trong nước tạo dung dịch đồng nhất)\n• Tái tạo amine tự do bằng base mạnh hơn:\n  C₆H₅NH₃Cl + NaOH → C₆H₅NH₂↓ (vẩn đục) + NaCl + H₂O", "t": "5. Phản ứng với acid & Tạo khói trắng", "b": "• Tác dụng với acid mạnh tạo muối:\n  CH₃NH₂ + HCl → [CH₃NH₃]⁺Cl⁻ (methylammonium chloride)\n  C₆H₅NH₂ + HCl → [C₆H₅NH₃]⁺Cl⁻ (phenylammonium chloride - muối tan trong nước tạo dung dịch đồng nhất)\n• Tái tạo amine tự do bằng base mạnh hơn:\n  C₆H₅NH₃Cl + NaOH → C₆H₅NH₂↓ (vẩn đục) + NaCl + H₂O"}, {"id": "g12c3_n6", "title": "6. Phản ứng thế ở nhân thơm của Aniline (Nhận biết)", "tag": "Aniline + Bromine · Kết tủa trắng", "kind": "rxn", "feynman": "Tương tự Phenol! Nhóm -NH₂ đẩy electron vào vòng làm cho vị trí ortho và para rất giàu electron. Cho nước bromine vào aniline là xuất hiện ngay kết tủa trắng 2,4,6-tribromoaniline mà không cần bất kỳ xúc tác nào!", "text": "• Phương trình hoá học:\n  C₆H₅NH₂ + 3Br₂ → C₆H₂Br₃NH₂↓ (trắng) + 3HBr\n• Hiện tượng: Dung dịch bromine mất màu nâu đỏ và xuất hiện kết tủa trắng.\n• Ứng dụng: Dùng để nhận biết aniline hoặc định lượng aniline trong mẫu phân tích.", "t": "6. Phản ứng thế ở nhân thơm của Aniline (Nhận biết)", "b": "• Phương trình hoá học:\n  C₆H₅NH₂ + 3Br₂ → C₆H₂Br₃NH₂↓ (trắng) + 3HBr\n• Hiện tượng: Dung dịch bromine mất màu nâu đỏ và xuất hiện kết tủa trắng.\n• Ứng dụng: Dùng để nhận biết aniline hoặc định lượng aniline trong mẫu phân tích."}, {"id": "g12c3_n7", "title": "7. Phản ứng với Nitrous acid (HNO₂)", "tag": "Phản ứng HNO2 · Muối diazonium", "kind": "rxn", "feynman": "Phân biệt amine béo và amine thơm: Amine béo bậc 1 sinh ra khí N₂ sủi bọt ngay. Aniline ở 0-5°C không sủi bọt mà tạo muối diazonium dùng để tổng hợp phẩm nhuộm azo rực rỡ!", "text": "• Với amine bậc 1 no (alkylamine): Sinh ra alcohol và giải phóng khí N₂:\n  C₂H₅NH₂ + HNO₂ → C₂H₅OH + N₂↑ + H₂O\n• Với aniline ở nhiệt độ thấp (0 - 5°C):\n  C₆H₅NH₂ + HNO₂ + HCl (0-5°C) → [C₆H₅-N≡N]⁺Cl⁻ + 2H₂O\n  (Muối benzenediazonium chloride).", "t": "7. Phản ứng với Nitrous acid (HNO₂)", "b": "• Với amine bậc 1 no (alkylamine): Sinh ra alcohol và giải phóng khí N₂:\n  C₂H₅NH₂ + HNO₂ → C₂H₅OH + N₂↑ + H₂O\n• Với aniline ở nhiệt độ thấp (0 - 5°C):\n  C₆H₅NH₂ + HNO₂ + HCl (0-5°C) → [C₆H₅-N≡N]⁺Cl⁻ + 2H₂O\n  (Muối benzenediazonium chloride)."}, {"id": "g12c3_n8", "title": "8. Ứng dụng & Điều chế Amine", "tag": "Ứng dụng · Tổng hợp hữu cơ", "kind": "card", "feynman": "Aniline là nguyên liệu sống còn của công nghiệp hoá dầu: từ aniline người ta tổng hợp hàng trăm loại phẩm nhuộm azo (nhuộm vải, len), dược phẩm giảm đau hạ sốt, và chất xúc tiến lưu hoá cao su.", "text": "• Điều chế aniline trong công nghiệp: Khử nitrobenzene bằng hydrogen mới sinh (Fe + HCl đặc):\n  C₆H₅NO₂ + 6[H] (Fe, HCl, t°) → C₆H₅NH₂ + 2H₂O\n• Điều chế alkylamine: Alkyl hoá ammonia bằng alkyl halide:\n  NH₃ + CH₃I → CH₃NH₂ + HI\n• Ứng dụng quan trọng:\n  - Hexamethylenediamine H₂N-(CH₂)₆-NH₂ dùng để trùng ngưng với adipic acid sản xuất tơ nylon-6,6.\n  - Sản xuất phẩm nhuộm azo, thuốc kháng khuẩn sulfamid.", "t": "8. Ứng dụng & Điều chế Amine", "b": "• Điều chế aniline trong công nghiệp: Khử nitrobenzene bằng hydrogen mới sinh (Fe + HCl đặc):\n  C₆H₅NO₂ + 6[H] (Fe, HCl, t°) → C₆H₅NH₂ + 2H₂O\n• Điều chế alkylamine: Alkyl hoá ammonia bằng alkyl halide:\n  NH₃ + CH₃I → CH₃NH₂ + HI\n• Ứng dụng quan trọng:\n  - Hexamethylenediamine H₂N-(CH₂)₆-NH₂ dùng để trùng ngưng với adipic acid sản xuất tơ nylon-6,6.\n  - Sản xuất phẩm nhuộm azo, thuốc kháng khuẩn sulfamid."}], "exercises": [{"q": "Cho 4,5 gam một amine đơn chức, no, mạch hở X tác dụng vừa đủ với dung dịch HCl, thu được 8,15 gam muối. Xác định công thức phân tử và số đồng phân cấu tạo của X.", "steps": ["Áp dụng định luật bảo toàn khối lượng: m(HCl) = m(muối) - m(amine) = 8,15 - 4,5 = 3,65 gam.", "Số mol HCl = 3,65 / 36,5 = 0,1 mol.", "Vì amine đơn chức nên n(amine) = n(HCl) = 0,1 mol -> Phân tử khối M(X) = 4,5 / 0,1 = 45 g/mol.", "Amine no đơn chức mạch hở có CTTQ CnH2n+3N -> 14n + 17 = 45 -> 14n = 28 -> n = 2 -> CTPT là C₂H₇N.", "C₂H₇N có 2 đồng phân cấu tạo: ethylamine (CH₃-CH₂-NH₂, bậc 1) và dimethylamine (CH₃-NH-CH₃, bậc 2)."], "ans": "CTPT là C₂H₇N; có 2 đồng phân cấu tạo.", "n": 1}, {"q": "Cho m gam aniline tác dụng hoàn toàn với lượng dư dung dịch nước bromine, thu được 33 gam kết tủa trắng. Tính giá trị của m và khối lượng Br₂ đã phản ứng.", "steps": ["Phương trình phản ứng: C₆H₅NH₂ + 3Br₂ → C₆H₂Br₃NH₂↓ + 3HBr.", "Khối lượng mol của 2,4,6-tribromoaniline = 93 + 3×79 = 330 g/mol.", "Số mol kết tủa = 33 / 330 = 0,1 mol.", "Theo tỉ lệ phương trình: n(aniline) = n(kết tủa) = 0,1 mol -> m = 0,1 × 93 = 9,3 gam.", "Số mol Br₂ phản ứng = 3 × 0,1 = 0,3 mol -> m(Br₂) = 0,3 × 160 = 48 gam."], "ans": "m = 9,3 gam; m(Br₂) = 48 gam.", "n": 2}, {"q": "Đốt cháy hoàn toàn 0,1 mol một amine no, đơn chức, mạch hở X cần dùng vừa đủ 7,437 lít khí O₂ (đo ở điều kiện chuẩn 25°C, 1 bar, biết 1 mol khí chiếm 24,79 lít). Tìm CTPT của X.", "steps": ["Số mol O₂ = 7,437 / 24,79 = 0,3 mol.", "Phương trình cháy: CnH2n+3N + (1,5n + 0,75) O₂ → n CO₂ + (n + 1,5) H₂O + 0,5 N₂.", "Số mol O₂ phản ứng = 0,1 × (1,5n + 0,75) = 0,3 mol.", "-> 1,5n + 0,75 = 3 -> 1,5n = 2,25 -> n = 1,5 (hoặc n=1 nếu đơn chất). Cần kiểm tra: nếu n=1: CH₅N + 2,25 O₂ -> 0,1×2,25 = 0,225 mol.", "Với 0,1 mol amine sinh ra CO₂ và H₂O. CnH2n+3N: CTPT ứng với tỉ lệ số mol."], "ans": "Xác định CTPT dựa trên định luật bảo toàn nguyên tố O và C.", "n": 3}]}};